window.HT = window.HT || {}; HT.CDF = HT.CDF || {};
HT.CDF["G15"] = {"bang":[{"i":0,"tieu_de_bang":"Việt Bắc – An toàn khu","tieu_de":"Chín năm “thủ đô” không tên giữa rừng cọ, đồi chè Việt Bắc","sapo":"Tháng 5 năm 1947, một đoàn người lặng lẽ băng rừng, lội suối, dừng chân giữa một thung lũng nhỏ ở Định Hóa, Thái Nguyên. Không cờ hoa, không dinh thự nghênh đón, chỉ có vài mái lán nứa vừa dựng vội bên sườn đồi. Thế nhưng chính từ những mái lán đơn sơ ấy, suốt chín năm ròng, một dân tộc đã điều hành cuộc kháng chiến giữ nước của mình, và chiến thắng Điện Biên Phủ lừng lẫy năm châu đã được thai nghén. Bước vào gian trưng bày này, bạn sẽ đi vào không gian sống và làm việc giản dị đến bất ngờ của Chủ tịch Hồ Chí Minh giữa núi rừng Việt Bắc.","bia":{"src":"textures/bai/G15_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Đêm chia tay Hà Nội, mở đầu một hành trình","text":"Đêm 19 tháng 12 năm 1946, tại làng Vạn Phúc (nay thuộc Hà Đông, Hà Nội), Chủ tịch Hồ Chí Minh viết Lời kêu gọi toàn quốc kháng chiến, với những câu chữ mà nhiều thế hệ người Việt còn thuộc lòng: “Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới... Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ”. Ngay trong đêm ấy, cả nước bước vào cuộc kháng chiến trường kỳ.\n\nTheo kế hoạch đã tính trước, các cơ quan Trung ương lần lượt rời Hà Nội, ngược lên vùng trung du rồi tiến sâu vào miền núi phía Bắc để bảo toàn lực lượng cho một cuộc chiến được xác định sẽ còn kéo dài chưa biết đến bao giờ. Đoàn người mang theo tài liệu, máy in, máy chữ, vượt qua nhiều chặng đường gian nan giữa vòng vây theo dõi của địch. Phải mất gần nửa năm ròng rã, đến tháng 5 năm 1947, Chủ tịch Hồ Chí Minh mới đặt chân tới Định Hóa (Thái Nguyên), bắt đầu một chặng đường sống và làm việc kéo dài suốt bảy năm sau đó giữa vùng An toàn khu Việt Bắc.","doc":1},{"loai":"anh","src":"textures/bang_w/G15_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Việt Bắc – An toàn khu”, nhìn từ xa."},{"loai":"doan","tieu_de":"Vì sao là Việt Bắc","text":"Việt Bắc không phải một cái tên xa lạ đối với cách mạng Việt Nam. Trước đó, ngày 28 tháng 1 năm 1941, sau ba mươi năm bôn ba nước ngoài, Người đã về nước qua cột mốc 108 và sống, làm việc tại hang Pác Bó (Cao Bằng); tháng 8 năm 1945, Tân Trào (Tuyên Quang) từng là nơi họp Quốc dân Đại hội, phát lệnh Tổng khởi nghĩa. Chọn trở lại vùng đất này để đặt An toàn khu năm 1947 vì thế không phải chuyện ngẫu nhiên, mà là sự tiếp nối một mối duyên đã có từ trước.\n\nVề địa thế, Định Hóa, Sơn Dương, Chiêm Hóa, Đại Từ, Yên Sơn... là vùng núi non hiểm trở, đường sá khó đi với người lạ nhưng thông thuộc với người quen thổ nhưỡng — điều kiện lý tưởng để di chuyển, ẩn náu và giữ bí mật cho một cơ quan lãnh đạo phải hoạt động ngay trong tầm với của các cuộc càn quét. Quan trọng không kém là con người: đồng bào các dân tộc Tày, Nùng, Dao, Kinh ở đây một lòng che chở, nuôi giấu cán bộ, giữ bí mật tuyệt đối về nơi ở của Bác và các cơ quan Trung ương suốt nhiều năm liền, dù đối phương treo thưởng rất cao cho ai chỉ điểm.\n\nMột lý do khác ít được nhắc tới là vị trí trung chuyển của Việt Bắc: từ đây, đường liên lạc có thể vươn tới biên giới phía Bắc, xuống đồng bằng Bắc Bộ, sang cả Lào và Liên khu Việt Bắc mở rộng, giúp Trung ương vừa chỉ đạo kháng chiến trên cả nước, vừa giữ được mạch giao thông với các nước bạn khi thời cơ đến. Chính vì hội đủ ba yếu tố — địa hình, lòng dân và vị trí chiến lược — Việt Bắc mới có thể gánh vác vai trò một căn cứ địa suốt gần một thập kỷ mà không một lần bị đánh sập.","doc":2},{"loai":"ban_co_biet","text":"Suốt chín năm, dù thực dân Pháp treo giải thưởng lớn cho ai chỉ điểm nơi ở của Chủ tịch Hồ Chí Minh, không một người dân nào ở An toàn khu tiết lộ bí mật. Nhiều gia đình đồng bào Tày, Nùng từng nhiều lần được giao dựng lán, canh gác, tiếp tế lương thực mà không hề biết vị khách mình đang bảo vệ chính là Chủ tịch nước.","nguon_ten":"Khu di tích lịch sử ATK Định Hóa; Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":3},{"loai":"doan","tieu_de":"Một chính phủ giấu mình giữa núi rừng","text":"Nhìn trên bản đồ những năm 1947–1954, sẽ không thấy địa danh nào được gọi là “thủ đô kháng chiến”. Nhưng trên thực tế, cả bộ máy lãnh đạo cao nhất của đất nước — Trung ương Đảng, Chính phủ, Quốc hội, Bộ Tổng tư lệnh — đều đóng phân tán trong các thung lũng, xóm bản của An toàn khu, mỗi cơ quan một khu vực riêng, cách nhau vài giờ đi bộ, vừa liên lạc được với nhau vừa tránh bị phát hiện, tiêu diệt cùng lúc nếu chẳng may lộ bí mật.\n\nGiữa núi rừng ấy, đời sống chính trị, văn hóa, báo chí của cả nước vẫn không ngừng vận hành. Ngày 11 tháng 3 năm 1951, giữa những ngày họp Đại hội II của Đảng, Báo Nhân Dân — cơ quan ngôn luận của Đảng — ra số đầu tiên ngay tại An toàn khu, kế tục sự nghiệp của tờ Sự Thật trước đó. Trường lớp huấn luyện cán bộ, xưởng in, xưởng quân giới, kho tàng, bệnh xá dã chiến... cũng lần lượt mọc lên trong rừng sâu. Tất cả tạo thành một “thủ đô” không tên trên bản đồ nhưng đủ sức điều hành một cuộc kháng chiến toàn dân, toàn diện suốt gần một thập kỷ.\n\nĐiều đáng nói là bộ máy ấy vận hành không phải nhờ những tòa nhà kiên cố hay phương tiện hiện đại, mà chủ yếu dựa vào đôi chân người giao liên, những chuyến thư hỏa tốc luồn rừng vượt suối, và ý thức giữ bí mật gần như tuyệt đối của từng cán bộ, từng người dân. Một bức điện từ An toàn khu có khi phải qua tay nhiều trạm giao liên mới tới được chiến trường xa, nhưng guồng máy ấy hiếm khi đứt mạch, kể cả trong những ngày Việt Bắc bị vây ráp gắt gao nhất.","doc":4},{"loai":"anh","src":"textures/bang_w/G15_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Việt Bắc – An toàn khu”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một ngày của Người giữa Việt Bắc","text":"Nếp sống của Chủ tịch Hồ Chí Minh ở Việt Bắc giản dị đến mức nhiều cán bộ phục vụ bên cạnh sau này vẫn nhắc lại như một bài học lớn. Người dậy sớm tập thể dục, rồi làm việc bên chiếc bàn tre kê sát cửa lán, nơi ánh sáng ban ngày lọt vào đủ để đọc công văn, viết bài, dịch tài liệu. Buổi tối, dưới ánh đèn dầu, Người vẫn ngồi bên chiếc máy chữ xách tay để tự tay soạn thảo chỉ thị, thư từ, bài báo, có khi làm việc tới khuya.\n\nKhông chỉ ngồi một chỗ, Người thường xuyên đi bộ hàng chục cây số đường rừng để đến thăm các đơn vị bộ đội, lớp huấn luyện cán bộ, hay đơn giản là một gia đình đồng bào địa phương. Giữa hai buổi làm việc, Người vẫn dành thời gian tăng gia: một khoảnh vườn rau nhỏ, vài luống rau cải, đôi khi thêm một hai con gà — vừa để cải thiện bữa ăn giữa những năm thiếu thốn, vừa làm gương cho cán bộ, chiến sĩ về tinh thần tự lực cánh sinh. Cứ sau một thời gian ngắn, cả “văn phòng” ấy — người, tài liệu, chiếc máy chữ — lại lặng lẽ chuyển sang một lán khác, giữ cho bí mật luôn được an toàn tuyệt đối.","doc":5},{"loai":"trich","text":"Tiếng suối trong như tiếng hát xa, Trăng lồng cổ thụ bóng lồng hoa. Cảnh khuya như vẽ người chưa ngủ, Chưa ngủ vì lo nỗi nước nhà.","nguoi":"Hồ Chí Minh, bài thơ “Cảnh khuya”, sáng tác tại Việt Bắc năm 1947","nguon_ten":"Hồ Chí Minh Toàn tập; sách giáo khoa Ngữ văn phổ thông","doc":6},{"loai":"doan","tieu_de":"Thử lửa giữa núi rừng","text":"An toàn khu non trẻ phải trải qua thử thách đầu tiên chỉ vài tháng sau khi vừa hình thành. Tháng 10 năm 1947, thực dân Pháp huy động một lực lượng lớn, gồm cả quân nhảy dù, đường bộ và đường thủy, đồng loạt đánh vào Việt Bắc với tham vọng tiêu diệt cơ quan đầu não kháng chiến trong một đòn duy nhất. Suốt 75 ngày đêm, quân và dân ta chiến đấu trên khắp các mặt trận, từ Bắc Kạn đến sông Lô, đường số 4, buộc đối phương phải rút chạy vào cuối năm đó, để lại đằng sau một An toàn khu vẫn đứng vững (xem thêm chuyên đề “Thu – đông 1947: đòn đánh vào chiến khu thất bại”).\n\nBa năm sau, tháng 9 năm 1950, từ chính những mái lán này, Chủ tịch Hồ Chí Minh trực tiếp ra mặt trận Biên giới, theo dõi trận đánh mở màn tại Đông Khê — lần duy nhất trong cuộc đời hoạt động cách mạng Người trực tiếp có mặt tại một mặt trận để theo dõi một chiến dịch quân sự. Chiến dịch Biên giới thắng lợi, khai thông tuyến biên giới Việt – Trung, nối liền hậu phương Việt Bắc với các nước xã hội chủ nghĩa, mở ra một giai đoạn phát triển mới cho cuộc kháng chiến.","doc":7},{"loai":"ban_co_biet","text":"Tháng 10 năm 1947, ngay giữa những ngày An toàn khu vừa trải qua cuộc tấn công của quân Pháp, Chủ tịch Hồ Chí Minh vẫn hoàn thành tác phẩm “Sửa đổi lối làm việc”, ký bút danh X.Y.Z — một trong những tác phẩm quan trọng về xây dựng Đảng, được viết ngay giữa hoàn cảnh chiến tranh ác liệt.","nguon_ten":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","doc":8},{"loai":"doan","tieu_de":"Nơi ra đời những quyết sách lớn","text":"Không chỉ là nơi trú ẩn, An toàn khu Việt Bắc còn là nơi ra đời những quyết định làm thay đổi cục diện cuộc kháng chiến. Tháng 2 năm 1951, giữa núi rừng Chiêm Hóa (Tuyên Quang), Đại hội đại biểu toàn quốc lần thứ II của Đảng được triệu tập — sự kiện đưa Đảng ra hoạt động công khai trở lại sau nhiều năm phải rút vào bí mật, với tên gọi mới: Đảng Lao động Việt Nam. Chủ tịch Hồ Chí Minh được Đại hội bầu làm Chủ tịch Đảng.\n\nGần ba năm sau, cũng chính giữa vùng đất này, tại lán Tỉn Keo dưới chân đèo De, một quyết định còn lớn hơn đã được đưa ra: đêm 6 tháng 12 năm 1953, Bộ Chính trị do Người chủ trì quyết định mở Chiến dịch Điện Biên Phủ — trận quyết chiến chiến lược khép lại toàn bộ cuộc kháng chiến chín năm (xem thêm chuyên đề “Từ Tỉn Keo đến Điện Biên Phủ”). Cứ như vậy, từ những căn lán nhỏ tưởng chừng chỉ đủ chỗ cho vài người ngồi họp, những quyết sách tầm quốc gia, thậm chí làm chấn động dư luận quốc tế, đã lần lượt ra đời.","doc":9},{"loai":"anh","src":"textures/ht/ht_anh_dai_hoi_dai_bieu_toan_quoc_lan_thu_hai_dang_cong.jpg","chu_thich":"Đại hội đại biểu toàn quốc lần thứ II của Đảng, họp tại Chiêm Hóa, Tuyên Quang, tháng 2/1951 — sự kiện đưa Đảng ra hoạt động công khai.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Chín năm, một hành trình khép lại","text":"Chiến thắng Điện Biên Phủ ngày 7 tháng 5 năm 1954 buộc thực dân Pháp phải ngồi vào bàn đàm phán. Ngày 21 tháng 7 năm 1954, Hiệp định Genève về Đông Dương được ký kết, chấm dứt chiến tranh, lập lại hòa bình trên cơ sở tôn trọng độc lập, chủ quyền của Việt Nam. Ngày 10 tháng 10 năm 1954, Thủ đô Hà Nội được giải phóng; cũng trong tháng 10 năm ấy, Chủ tịch Hồ Chí Minh cùng Trung ương Đảng, Chính phủ rời Việt Bắc, trở về Hà Nội sau đúng chín năm.\n\nTrên đường về, ngày 19 tháng 9 năm 1954, dừng chân tại Đền Giếng thuộc Khu di tích Đền Hùng (Phú Thọ), Người căn dặn cán bộ, chiến sĩ Đại đoàn Quân Tiên phong trước khi vào tiếp quản Thủ đô một câu nói trở thành lời thề của bao thế hệ: “Các vua Hùng đã có công dựng nước, Bác cháu ta phải cùng nhau giữ lấy nước”. Chín năm kháng chiến, chín năm những mái lán nứa giữa rừng cọ, đồi chè đã hoàn thành sứ mệnh lịch sử của mình.","doc":10},{"loai":"anh","src":"textures/bang_w/G15_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Việt Bắc – An toàn khu”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Những mái lán nứa năm xưa nay không còn nguyên vẹn — vật liệu tre nứa không thể chống chọi với thời gian và khí hậu miền núi — nhưng dấu tích và ký ức về chúng vẫn được gìn giữ cẩn trọng. Ngày 10 tháng 5 năm 2012, Thủ tướng Chính phủ ra quyết định số 548/QĐ-TTg, xếp hạng Khu di tích lịch sử An toàn khu (ATK) Định Hóa là Di tích quốc gia đặc biệt, ghi nhận đây là một trong những quần thể di tích cách mạng quan trọng bậc nhất của đất nước trong thế kỷ XX.\n\nNgày nay, du khách đến Định Hóa có thể tận mắt thấy nền lán Tỉn Keo, lán Khuôn Tát được phục dựng, đi qua những con đường mòn xuyên rừng cọ, đồi chè mà đoàn cán bộ kháng chiến từng qua lại, và đứng trước tấm bia ghi lại quyết định lịch sử đêm 6 tháng 12 năm 1953. Gian trưng bày này, với các bảng bên cạnh, mời bạn đi sâu vào từng lát cắt nhỏ của chín năm ấy: một trận đánh, một quyết định, một khoảnh khắc đời thường của một vị Chủ tịch nước sống giữa dân, giữa núi rừng.","doc":11},{"loai":"anh","src":"textures/ht/ht_anh_atk_dinh_hoa.jpg","chu_thich":"An toàn khu Định Hóa, Thái Nguyên ngày nay — nơi lưu giữ dấu tích chín năm kháng chiến, được xếp hạng Di tích quốc gia đặc biệt năm 2012.","credit":"Ảnh: Viethavvh at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Khu di tích ATK Định Hóa ngày nay gồm hàng chục điểm di tích trải khắp nhiều xã của huyện Định Hóa, trong đó cụm di tích Tỉn Keo – Phú Đình là nơi tập trung nhiều dấu tích gắn liền với Chủ tịch Hồ Chí Minh nhất, được xem là một trong những quần thể di tích cách mạng quan trọng bậc nhất của Việt Nam trong thế kỷ XX.","nguon_ten":"Cơ sở dữ liệu di sản văn hóa Việt Nam (dsvh.gov.vn); Khu di tích lịch sử ATK Định Hóa","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh (hochiminh.vn)","Khu di tích lịch sử ATK Định Hóa (Thái Nguyên)","Cơ sở dữ liệu di sản văn hóa Việt Nam (dsvh.gov.vn) — Quyết định số 548/QĐ-TTg ngày 10/5/2012"],"doc":[{"t":"Chín năm “thủ đô” không tên giữa rừng cọ, đồi chè Việt Bắc. Tháng 5 năm 1947, một đoàn người lặng lẽ băng rừng, lội suối, dừng chân giữa một thung lũng nhỏ ở Định Hóa, Thái Nguyên. Không cờ hoa, không dinh thự nghênh đón, chỉ có vài mái lán nứa vừa dựng vội bên sườn đồi. Thế nhưng chính từ những mái lán đơn sơ ấy, suốt chín năm ròng, một dân tộc đã điều hành cuộc kháng chiến giữ nước của mình, và chiến thắng Điện Biên Phủ lừng lẫy năm châu đã được thai nghén. Bước vào gian trưng bày này, bạn sẽ đi vào không gian sống và làm việc giản dị đến bất ngờ của Chủ tịch Hồ Chí Minh giữa núi rừng Việt Bắc."},{"t":"Đêm chia tay Hà Nội, mở đầu một hành trình. Đêm 19 tháng 12 năm 1946, tại làng Vạn Phúc (nay thuộc Hà Đông, Hà Nội), Chủ tịch Hồ Chí Minh viết Lời kêu gọi toàn quốc kháng chiến, với những câu chữ mà nhiều thế hệ người Việt còn thuộc lòng: “Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới... Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ”. Ngay trong đêm ấy, cả nước bước vào cuộc kháng chiến trường kỳ. Theo kế hoạch đã tính trước, các cơ quan Trung ương lần lượt rời Hà Nội, ngược lên vùng trung du rồi tiến sâu vào miền núi phía Bắc để bảo toàn lực lượng cho một cuộc chiến được xác định sẽ còn kéo dài chưa biết đến bao giờ. Đoàn người mang theo tài liệu, máy in, máy chữ, vượt qua nhiều chặng đường gian nan giữa vòng vây theo dõi của địch. Phải mất gần nửa năm ròng rã, đến tháng 5 năm 1947, Chủ tịch Hồ Chí Minh mới đặt chân tới Định Hóa (Thái Nguyên), bắt đầu một chặng đường sống và làm việc kéo dài suốt bảy năm sau đó giữa vùng An toàn khu Việt Bắc."},{"t":"Vì sao là Việt Bắc. Việt Bắc không phải một cái tên xa lạ đối với cách mạng Việt Nam. Trước đó, ngày 28 tháng 1 năm 1941, sau ba mươi năm bôn ba nước ngoài, Người đã về nước qua cột mốc 108 và sống, làm việc tại hang Pác Bó (Cao Bằng); tháng 8 năm 1945, Tân Trào (Tuyên Quang) từng là nơi họp Quốc dân Đại hội, phát lệnh Tổng khởi nghĩa. Chọn trở lại vùng đất này để đặt An toàn khu năm 1947 vì thế không phải chuyện ngẫu nhiên, mà là sự tiếp nối một mối duyên đã có từ trước. Về địa thế, Định Hóa, Sơn Dương, Chiêm Hóa, Đại Từ, Yên Sơn... là vùng núi non hiểm trở, đường sá khó đi với người lạ nhưng thông thuộc với người quen thổ nhưỡng — điều kiện lý tưởng để di chuyển, ẩn náu và giữ bí mật cho một cơ quan lãnh đạo phải hoạt động ngay trong tầm với của các cuộc càn quét. Quan trọng không kém là con người: đồng bào các dân tộc Tày, Nùng, Dao, Kinh ở đây một lòng che chở, nuôi giấu cán bộ, giữ bí mật tuyệt đối về nơi ở của Bác và các cơ quan Trung ương suốt nhiều năm liền, dù đối phương treo thưởng rất cao cho ai chỉ điểm. Một lý do khác ít được nhắc tới là vị trí trung chuyển của Việt Bắc: từ đây, đường liên lạc có thể vươn tới biên giới phía Bắc, xuống đồng bằng Bắc Bộ, sang cả Lào và Liên khu Việt Bắc mở rộng, giúp Trung ương vừa chỉ đạo kháng chiến trên cả nước, vừa giữ được mạch giao thông với các nước bạn khi thời cơ đến. Chính vì hội đủ ba yếu tố — địa hình, lòng dân và vị trí chiến lược — Việt Bắc mới có thể gánh vác vai trò một căn cứ địa suốt gần một thập kỷ mà không một lần bị đánh sập."},{"t":"Bạn có biết? Suốt chín năm, dù thực dân Pháp treo giải thưởng lớn cho ai chỉ điểm nơi ở của Chủ tịch Hồ Chí Minh, không một người dân nào ở An toàn khu tiết lộ bí mật. Nhiều gia đình đồng bào Tày, Nùng từng nhiều lần được giao dựng lán, canh gác, tiếp tế lương thực mà không hề biết vị khách mình đang bảo vệ chính là Chủ tịch nước."},{"t":"Một chính phủ giấu mình giữa núi rừng. Nhìn trên bản đồ những năm 1947–1954, sẽ không thấy địa danh nào được gọi là “thủ đô kháng chiến”. Nhưng trên thực tế, cả bộ máy lãnh đạo cao nhất của đất nước — Trung ương Đảng, Chính phủ, Quốc hội, Bộ Tổng tư lệnh — đều đóng phân tán trong các thung lũng, xóm bản của An toàn khu, mỗi cơ quan một khu vực riêng, cách nhau vài giờ đi bộ, vừa liên lạc được với nhau vừa tránh bị phát hiện, tiêu diệt cùng lúc nếu chẳng may lộ bí mật. Giữa núi rừng ấy, đời sống chính trị, văn hóa, báo chí của cả nước vẫn không ngừng vận hành. Ngày 11 tháng 3 năm 1951, giữa những ngày họp Đại hội II của Đảng, Báo Nhân Dân — cơ quan ngôn luận của Đảng — ra số đầu tiên ngay tại An toàn khu, kế tục sự nghiệp của tờ Sự Thật trước đó. Trường lớp huấn luyện cán bộ, xưởng in, xưởng quân giới, kho tàng, bệnh xá dã chiến... cũng lần lượt mọc lên trong rừng sâu. Tất cả tạo thành một “thủ đô” không tên trên bản đồ nhưng đủ sức điều hành một cuộc kháng chiến toàn dân, toàn diện suốt gần một thập kỷ. Điều đáng nói là bộ máy ấy vận hành không phải nhờ những tòa nhà kiên cố hay phương tiện hiện đại, mà chủ yếu dựa vào đôi chân người giao liên, những chuyến thư hỏa tốc luồn rừng vượt suối, và ý thức giữ bí mật gần như tuyệt đối của từng cán bộ, từng người dân. Một bức điện từ An toàn khu có khi phải qua tay nhiều trạm giao liên mới tới được chiến trường xa, nhưng guồng máy ấy hiếm khi đứt mạch, kể cả trong những ngày Việt Bắc bị vây ráp gắt gao nhất."},{"t":"Một ngày của Người giữa Việt Bắc. Nếp sống của Chủ tịch Hồ Chí Minh ở Việt Bắc giản dị đến mức nhiều cán bộ phục vụ bên cạnh sau này vẫn nhắc lại như một bài học lớn. Người dậy sớm tập thể dục, rồi làm việc bên chiếc bàn tre kê sát cửa lán, nơi ánh sáng ban ngày lọt vào đủ để đọc công văn, viết bài, dịch tài liệu. Buổi tối, dưới ánh đèn dầu, Người vẫn ngồi bên chiếc máy chữ xách tay để tự tay soạn thảo chỉ thị, thư từ, bài báo, có khi làm việc tới khuya. Không chỉ ngồi một chỗ, Người thường xuyên đi bộ hàng chục cây số đường rừng để đến thăm các đơn vị bộ đội, lớp huấn luyện cán bộ, hay đơn giản là một gia đình đồng bào địa phương. Giữa hai buổi làm việc, Người vẫn dành thời gian tăng gia: một khoảnh vườn rau nhỏ, vài luống rau cải, đôi khi thêm một hai con gà — vừa để cải thiện bữa ăn giữa những năm thiếu thốn, vừa làm gương cho cán bộ, chiến sĩ về tinh thần tự lực cánh sinh. Cứ sau một thời gian ngắn, cả “văn phòng” ấy — người, tài liệu, chiếc máy chữ — lại lặng lẽ chuyển sang một lán khác, giữ cho bí mật luôn được an toàn tuyệt đối."},{"t":"Tiếng suối trong như tiếng hát xa, Trăng lồng cổ thụ bóng lồng hoa. Cảnh khuya như vẽ người chưa ngủ, Chưa ngủ vì lo nỗi nước nhà. — Hồ Chí Minh, bài thơ “Cảnh khuya”, sáng tác tại Việt Bắc năm 1947"},{"t":"Thử lửa giữa núi rừng. An toàn khu non trẻ phải trải qua thử thách đầu tiên chỉ vài tháng sau khi vừa hình thành. Tháng 10 năm 1947, thực dân Pháp huy động một lực lượng lớn, gồm cả quân nhảy dù, đường bộ và đường thủy, đồng loạt đánh vào Việt Bắc với tham vọng tiêu diệt cơ quan đầu não kháng chiến trong một đòn duy nhất. Suốt 75 ngày đêm, quân và dân ta chiến đấu trên khắp các mặt trận, từ Bắc Kạn đến sông Lô, đường số 4, buộc đối phương phải rút chạy vào cuối năm đó, để lại đằng sau một An toàn khu vẫn đứng vững (xem thêm chuyên đề “Thu – đông 1947: đòn đánh vào chiến khu thất bại”). Ba năm sau, tháng 9 năm 1950, từ chính những mái lán này, Chủ tịch Hồ Chí Minh trực tiếp ra mặt trận Biên giới, theo dõi trận đánh mở màn tại Đông Khê — lần duy nhất trong cuộc đời hoạt động cách mạng Người trực tiếp có mặt tại một mặt trận để theo dõi một chiến dịch quân sự. Chiến dịch Biên giới thắng lợi, khai thông tuyến biên giới Việt – Trung, nối liền hậu phương Việt Bắc với các nước xã hội chủ nghĩa, mở ra một giai đoạn phát triển mới cho cuộc kháng chiến."},{"t":"Bạn có biết? Tháng 10 năm 1947, ngay giữa những ngày An toàn khu vừa trải qua cuộc tấn công của quân Pháp, Chủ tịch Hồ Chí Minh vẫn hoàn thành tác phẩm “Sửa đổi lối làm việc”, ký bút danh X.Y.Z — một trong những tác phẩm quan trọng về xây dựng Đảng, được viết ngay giữa hoàn cảnh chiến tranh ác liệt."},{"t":"Nơi ra đời những quyết sách lớn. Không chỉ là nơi trú ẩn, An toàn khu Việt Bắc còn là nơi ra đời những quyết định làm thay đổi cục diện cuộc kháng chiến. Tháng 2 năm 1951, giữa núi rừng Chiêm Hóa (Tuyên Quang), Đại hội đại biểu toàn quốc lần thứ II của Đảng được triệu tập — sự kiện đưa Đảng ra hoạt động công khai trở lại sau nhiều năm phải rút vào bí mật, với tên gọi mới: Đảng Lao động Việt Nam. Chủ tịch Hồ Chí Minh được Đại hội bầu làm Chủ tịch Đảng. Gần ba năm sau, cũng chính giữa vùng đất này, tại lán Tỉn Keo dưới chân đèo De, một quyết định còn lớn hơn đã được đưa ra: đêm 6 tháng 12 năm 1953, Bộ Chính trị do Người chủ trì quyết định mở Chiến dịch Điện Biên Phủ — trận quyết chiến chiến lược khép lại toàn bộ cuộc kháng chiến chín năm (xem thêm chuyên đề “Từ Tỉn Keo đến Điện Biên Phủ”). Cứ như vậy, từ những căn lán nhỏ tưởng chừng chỉ đủ chỗ cho vài người ngồi họp, những quyết sách tầm quốc gia, thậm chí làm chấn động dư luận quốc tế, đã lần lượt ra đời."},{"t":"Chín năm, một hành trình khép lại. Chiến thắng Điện Biên Phủ ngày 7 tháng 5 năm 1954 buộc thực dân Pháp phải ngồi vào bàn đàm phán. Ngày 21 tháng 7 năm 1954, Hiệp định Genève về Đông Dương được ký kết, chấm dứt chiến tranh, lập lại hòa bình trên cơ sở tôn trọng độc lập, chủ quyền của Việt Nam. Ngày 10 tháng 10 năm 1954, Thủ đô Hà Nội được giải phóng; cũng trong tháng 10 năm ấy, Chủ tịch Hồ Chí Minh cùng Trung ương Đảng, Chính phủ rời Việt Bắc, trở về Hà Nội sau đúng chín năm. Trên đường về, ngày 19 tháng 9 năm 1954, dừng chân tại Đền Giếng thuộc Khu di tích Đền Hùng (Phú Thọ), Người căn dặn cán bộ, chiến sĩ Đại đoàn Quân Tiên phong trước khi vào tiếp quản Thủ đô một câu nói trở thành lời thề của bao thế hệ: “Các vua Hùng đã có công dựng nước, Bác cháu ta phải cùng nhau giữ lấy nước”. Chín năm kháng chiến, chín năm những mái lán nứa giữa rừng cọ, đồi chè đã hoàn thành sứ mệnh lịch sử của mình."},{"t":"Dấu tích hôm nay. Những mái lán nứa năm xưa nay không còn nguyên vẹn — vật liệu tre nứa không thể chống chọi với thời gian và khí hậu miền núi — nhưng dấu tích và ký ức về chúng vẫn được gìn giữ cẩn trọng. Ngày 10 tháng 5 năm 2012, Thủ tướng Chính phủ ra quyết định số 548/QĐ-TTg, xếp hạng Khu di tích lịch sử An toàn khu (ATK) Định Hóa là Di tích quốc gia đặc biệt, ghi nhận đây là một trong những quần thể di tích cách mạng quan trọng bậc nhất của đất nước trong thế kỷ XX. Ngày nay, du khách đến Định Hóa có thể tận mắt thấy nền lán Tỉn Keo, lán Khuôn Tát được phục dựng, đi qua những con đường mòn xuyên rừng cọ, đồi chè mà đoàn cán bộ kháng chiến từng qua lại, và đứng trước tấm bia ghi lại quyết định lịch sử đêm 6 tháng 12 năm 1953. Gian trưng bày này, với các bảng bên cạnh, mời bạn đi sâu vào từng lát cắt nhỏ của chín năm ấy: một trận đánh, một quyết định, một khoảnh khắc đời thường của một vị Chủ tịch nước sống giữa dân, giữa núi rừng."},{"t":"Bạn có biết? Khu di tích ATK Định Hóa ngày nay gồm hàng chục điểm di tích trải khắp nhiều xã của huyện Định Hóa, trong đó cụm di tích Tỉn Keo – Phú Đình là nơi tập trung nhiều dấu tích gắn liền với Chủ tịch Hồ Chí Minh nhất, được xem là một trong những quần thể di tích cách mạng quan trọng bậc nhất của Việt Nam trong thế kỷ XX."}],"so_chu":2281},{"i":1,"tieu_de_bang":"Thu – đông 1947: đòn đánh vào chiến khu thất bại","tieu_de":"75 ngày đêm: khi quân dù Pháp nhảy xuống Bắc Kạn hòng bắt gọn cơ quan đầu não","sapo":"Một buổi sáng tháng 10 năm 1947, tiếng động cơ máy bay gầm rú trên bầu trời Bắc Kạn, những chiếc dù trắng bung ra giữa không trung. Thực dân Pháp tin rằng chỉ cần một đòn bất ngờ, chúng có thể bắt gọn cả cơ quan đầu não kháng chiến, kết thúc cuộc chiến trong vài tuần. Bảy mươi lăm ngày đêm sau, chính đội quân ấy phải rút chạy khỏi Việt Bắc.","bia":{"src":"textures/bai/G15_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Ván bài “đánh nhanh, thắng nhanh”","text":"Chỉ năm tháng sau khi Trung ương và Chủ tịch Hồ Chí Minh đặt chân tới Định Hóa, căn cứ địa non trẻ đã phải đối mặt với thử thách sống còn đầu tiên. Sau hơn một năm giao tranh ở các đô thị và vùng đồng bằng mà không dứt điểm được cuộc chiến, Bộ Chỉ huy quân viễn chinh Pháp tại Đông Dương tin rằng chìa khóa để kết thúc nhanh cuộc chiến nằm ở việc đánh thẳng vào bộ não của kháng chiến: tiêu diệt cơ quan lãnh đạo, bắt sống hoặc buộc Chính phủ kháng chiến phải đầu hàng, đồng thời tiêu diệt bộ đội chủ lực còn non trẻ của ta ngay tại căn cứ.\n\nKế hoạch được vạch ra công phu: dùng một lực lượng hỗn hợp gồm quân nhảy dù, bộ binh và cả tàu chiến, hình thành hai gọng kìm siết chặt quanh Việt Bắc, đồng thời khóa chặt biên giới Việt – Trung để cô lập hoàn toàn cuộc kháng chiến với bên ngoài. Nếu thành công, đây sẽ là đòn kết liễu khiến cuộc kháng chiến toàn quốc chưa kịp trưởng thành đã phải kết thúc.","doc":1},{"loai":"anh","src":"textures/bang_w/G15_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thu – đông 1947: đòn đánh vào chiến khu thất bại”, nhìn từ xa."},{"loai":"doan","tieu_de":"Ngày 7 tháng 10 năm 1947","text":"Sáng ngày 7 tháng 10 năm 1947, hàng loạt máy bay vận tải quân sự xuất hiện trên bầu trời Bắc Kạn. Quân Pháp cho lính dù đổ xuống ngay thị xã Bắc Kạn, đồng thời rải quân xuống Chợ Mới, Chợ Đồn — những vị trí được tính toán để bao vây nhanh nhất khu vực được cho là nơi đóng cơ quan đầu não kháng chiến. Cùng lúc đó, một binh đoàn bộ binh xuất phát từ Lạng Sơn, theo đường số 4 tiến lên Cao Bằng rồi vòng xuống Bắc Kạn khép gọng kìm phía đông; một binh đoàn hỗn hợp khác ngược sông Hồng, sông Lô từ Hà Nội tiến lên Tuyên Quang, khép gọng kìm phía tây.\n\nĐòn tấn công bất ngờ từ trên không đặt cơ quan đầu não kháng chiến trước nguy cơ lớn chưa từng có kể từ ngày rời Hà Nội. Có những thời điểm, lính dù Pháp đổ xuống chỉ cách nơi làm việc của một số cơ quan Trung ương một khoảng không xa, nhưng nhờ hệ thống giao liên, cảnh giới và tinh thần bí mật đã được rèn luyện suốt nhiều tháng trước đó, các cơ quan kịp thời sơ tán an toàn.","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_chu_tich_ho_chi_minh_trao_doi_cong_viec_voi_dong.jpg","chu_thich":"Chủ tịch Hồ Chí Minh trao đổi công việc với cụ Tôn Đức Thắng và Hoàng Quốc Việt tại An toàn khu, năm 1947 — giữa những ngày Việt Bắc đang bị vây ráp.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Cuộc hành quân mang tên Léa","text":"Cuộc tấn công tháng 10 năm 1947 nằm trong một kế hoạch quân sự được phía Pháp đặt tên là cuộc hành quân Léa, do tướng Jean-Étienne Valluy, Tổng chỉ huy quân viễn chinh Pháp ở Đông Dương, trực tiếp vạch ra và chỉ huy, diễn ra từ ngày 7 tháng 10 đến đầu tháng 11 năm 1947. Ý đồ của cuộc hành quân rất rõ ràng: dùng lực lượng nhảy dù đánh úp bất ngờ vào nơi được tình báo Pháp phỏng đoán là sở chỉ huy của Việt Minh, kết hợp với các cánh quân bộ binh siết chặt vòng vây từ nhiều hướng để không cho đối phương kịp thoát.\n\nTrên thực tế, có những thời điểm mũi nhảy dù của Pháp tiến sát đến mức suýt chạm được vào khu vực nơi Chủ tịch Hồ Chí Minh và Đại tướng Võ Nguyên Giáp đang trú đóng, nhưng nhờ mạng lưới giao liên cảnh giới từ xa và quyết định sơ tán kịp thời, các cơ quan đầu não đã kịp luồn qua giữa các mũi tiến quân để thoát khỏi vòng vây. Không đạt được mục tiêu chính sau hơn ba tuần, tướng Valluy tiếp tục phát động một cuộc hành quân thứ hai, mang tên Ceinture, vào tháng 11 năm 1947, nhưng kết quả cũng không khác gì cuộc hành quân trước đó.\n\nGiới nghiên cứu quân sự phương Tây sau này nhìn nhận Léa là một kế hoạch được chuẩn bị bài bản, kết hợp nhiều binh chủng theo kiểu tác chiến hiện đại hiếm thấy ở chiến trường Đông Dương thời điểm đó, nhưng lại vấp phải một trở ngại mà mọi phương tiện quân sự không thể khắc phục: địa hình rừng núi hiểm trở khiến quân nhảy dù khó hợp đồng tác chiến đúng kế hoạch, còn mạng lưới do thám của đối phương gần như tê liệt trước một dân cư luôn giữ im lặng tuyệt đối về mọi hành tung của cán bộ kháng chiến.","doc":3},{"loai":"ban_co_biet","text":"Theo các tư liệu quân sự phương Tây về cuộc hành quân Léa, có thời điểm lực lượng nhảy dù Pháp đã tiến rất gần khu vực trú đóng của cơ quan đầu não kháng chiến, khiến chiến dịch này được xem là một trong những lần Chủ tịch Hồ Chí Minh và Đại tướng Võ Nguyên Giáp ở gần nguy cơ bị đối phương bắt giữ nhất trong suốt cuộc kháng chiến chống Pháp.","nguon_ten":"Tư liệu quân sự phương Tây về Chiến dịch Việt Bắc 1947 (Operation Léa); Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","doc":4},{"loai":"doan","tieu_de":"“Phải phá tan cuộc tấn công mùa đông của giặc Pháp”","text":"Ngày 15 tháng 10 năm 1947, Ban Thường vụ Trung ương Đảng ra chỉ thị mang tên “Phải phá tan cuộc tấn công mùa đông của giặc Pháp”, xác định rõ: đây là cơ hội để quân đội ta trưởng thành qua thử lửa, đồng thời bảo vệ bằng được cơ quan đầu não. Trong khi Chủ tịch Hồ Chí Minh cùng phần lớn cơ quan Trung ương lặng lẽ di chuyển sâu hơn vào rừng, giữ liên lạc chỉ đạo qua giao liên và điện đài, quân và dân Việt Bắc bước vào một cuộc chiến đấu trên nhiều mặt trận cùng lúc.\n\nỞ mặt trận Bắc Kạn, bộ đội và dân quân bao vây, tập kích liên tục vào các vị trí quân Pháp vừa chiếm đóng, khiến đối phương không thể mở rộng vùng kiểm soát như dự tính. Trên đường số 4 — con đường huyết mạch nối Cao Bằng, Lạng Sơn — bộ đội ta tổ chức hàng loạt trận phục kích đánh vào các đoàn xe cơ giới, đỉnh điểm là chiến thắng Đèo Bông Lau ngày 30 tháng 10 năm 1947, một trong những trận phục kích lớn nhất của quân ta trên tuyến đường này, phá hủy nhiều xe quân sự và gây thiệt hại nặng cho đối phương.","doc":5},{"loai":"ban_co_biet","text":"Sau chiến thắng Đèo Bông Lau và hàng loạt trận phục kích khác, đường số 4 trở thành nỗi ám ảnh đến mức binh lính Pháp gọi đây là “con đường chết”. Đài chiến thắng Bông Lau – Lũng Phầy sau này được xếp hạng di tích cấp quốc gia, ghi dấu một trong những chiến công tiêu biểu của chiến dịch Việt Bắc thu – đông.","nguon_ten":"Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam; tư liệu Bộ Văn hóa, Thể thao và Du lịch","doc":6},{"loai":"doan","tieu_de":"Trận địa trên sông Lô","text":"Không chỉ trên bộ, mặt trận sông Lô cũng trở thành nơi diễn ra những trận đánh quyết định. Đoàn tàu chiến, ca nô của Pháp ngược sông Lô để tiếp ứng cho cánh quân đường thủy đã lọt vào các trận địa phục kích của bộ đội ta tại khu vực Đoan Hùng, Khoan Bộ, Khe Lau (giáp ranh Phú Thọ, Tuyên Quang). Nhiều tàu chiến, ca nô bị bắn chìm hoặc hư hỏng nặng, buộc đối phương phải từ bỏ ý định dùng đường sông làm tuyến tiếp vận chủ lực lên Việt Bắc.\n\nChiến thắng trên sông Lô về sau còn đi vào âm nhạc qua bản trường ca nổi tiếng của nhạc sĩ Văn Cao, trở thành một trong những biểu tượng văn hóa gắn liền với chiến dịch Việt Bắc thu – đông 1947. Trong khi các mặt trận sôi động khắp Bắc Kạn, đường số 4 và sông Lô, Chủ tịch Hồ Chí Minh cùng các cơ quan Trung ương vẫn ở lại ngay giữa vùng chiến sự, được bộ đội và nhân dân bảo vệ an toàn tuyệt đối, tiếp tục chỉ đạo cuộc chiến đấu qua từng bức điện.\n\nTrong những ngày tháng gay go ấy, việc giữ vững liên lạc giữa các cơ quan Trung ương với những mặt trận đang chiến đấu ác liệt cách nhau hàng chục, hàng trăm cây số đường rừng là cả một kỳ công thầm lặng. Đội ngũ giao liên phải luồn qua vùng địch kiểm soát, có khi đi cả ngày lẫn đêm để kịp chuyển một bức điện chỉ đạo hay một chỉ thị khẩn, trong khi hệ thống thông tin vô tuyến còn rất thô sơ và luôn đứng trước nguy cơ bị đối phương dò sóng, phát hiện vị trí đóng quân.","doc":7},{"loai":"anh","src":"textures/bang_w/G15_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thu – đông 1947: đòn đánh vào chiến khu thất bại”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Khi kẻ tấn công phải rút lui","text":"Sau hơn hai tháng bị đánh trả quyết liệt trên khắp các hướng, không đạt được mục tiêu tiêu diệt cơ quan đầu não hay bộ đội chủ lực, lại chịu tổn thất ngày càng nặng, quân Pháp buộc phải tính đến việc rút lui. Đến cuối tháng 12 năm 1947, sau 75 ngày đêm, phần lớn lực lượng tấn công đã phải rời khỏi Việt Bắc, để lại một chiến trường mà đối phương không thể kiểm soát nổi.\n\nĐây là chiến thắng quân sự có ý nghĩa chiến lược đầu tiên của cuộc kháng chiến toàn quốc. Kế hoạch “đánh nhanh, thắng nhanh” — vốn được coi là con bài chiến lược của thực dân Pháp — hoàn toàn phá sản. Từ đây, cuộc chiến buộc phải chuyển sang một hình thái mới: chiến tranh kéo dài, mà ưu thế về thời gian, về lòng dân dần nghiêng về phía những người kháng chiến.","doc":8},{"loai":"ban_co_biet","text":"Chiến thắng Việt Bắc thu – đông 1947 không chỉ bảo toàn được cơ quan đầu não và bộ đội chủ lực, mà còn giúp quân đội ta trưởng thành vượt bậc qua thực chiến: từ một lực lượng chủ yếu đánh du kích, bộ đội chủ lực bắt đầu tổ chức được những trận đánh tập trung quy mô cấp trung đoàn, đặt nền móng cho các chiến dịch lớn hơn những năm sau, trong đó có Chiến dịch Biên giới năm 1950.","nguon_ten":"Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","doc":9},{"loai":"doan","tieu_de":"Bài học của một chiến khu không bị đánh sập","text":"Nhìn lại 75 ngày đêm ấy, điều đáng chú ý không chỉ nằm ở những trận đánh, mà còn ở cách cả một hệ thống — từ cơ quan lãnh đạo đến từng người dân — đã cùng vận hành nhịp nhàng để bảo vệ bí mật tuyệt đối. Không một tài liệu, không một nhân chứng nào ghi nhận việc quân Pháp phát hiện được nơi ở chính xác của Chủ tịch Hồ Chí Minh trong suốt chiến dịch, dù các mũi tấn công nhiều lúc chỉ cách khu vực An toàn khu không xa.\n\nChiến thắng Việt Bắc thu – đông 1947 vì vậy không chỉ là chiến thắng quân sự, mà còn là bằng chứng sống động cho sự vững chắc của mối quan hệ giữa Đảng, Chính phủ với nhân dân các dân tộc Việt Bắc — nền tảng để An toàn khu tiếp tục đứng vững thêm bảy năm nữa, cho đến ngày toàn thắng ở Điện Biên Phủ (xem thêm chuyên đề “Từ Tỉn Keo đến Điện Biên Phủ”).\n\nVề sau, khi tổng kết lại chiến dịch này, nhiều nhà nghiên cứu quân sự trong và ngoài nước đều coi thất bại của cuộc hành quân Léa và Ceinture là dấu mốc cho thấy một đội quân nhà nghề, được trang bị hiện đại, vẫn có thể bị đánh bại bởi một lực lượng non trẻ hơn nếu thiếu đi sự ủng hộ của dân chúng bản địa — bài học mà nước Pháp sẽ còn phải trả giá thêm nhiều lần nữa trước khi cuộc chiến kết thúc ở Điện Biên Phủ bảy năm sau đó.","doc":10},{"loai":"anh","src":"textures/bang_w/G15_1_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thu – đông 1947: đòn đánh vào chiến khu thất bại”, nhìn từ trên cao."}],"nguon":["Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh (hochiminh.vn)","Tư liệu Bộ Văn hóa, Thể thao và Du lịch về Di tích Đài chiến thắng Bông Lau – Lũng Phầy"],"doc":[{"t":"75 ngày đêm: khi quân dù Pháp nhảy xuống Bắc Kạn hòng bắt gọn cơ quan đầu não. Một buổi sáng tháng 10 năm 1947, tiếng động cơ máy bay gầm rú trên bầu trời Bắc Kạn, những chiếc dù trắng bung ra giữa không trung. Thực dân Pháp tin rằng chỉ cần một đòn bất ngờ, chúng có thể bắt gọn cả cơ quan đầu não kháng chiến, kết thúc cuộc chiến trong vài tuần. Bảy mươi lăm ngày đêm sau, chính đội quân ấy phải rút chạy khỏi Việt Bắc."},{"t":"Ván bài “đánh nhanh, thắng nhanh”. Chỉ năm tháng sau khi Trung ương và Chủ tịch Hồ Chí Minh đặt chân tới Định Hóa, căn cứ địa non trẻ đã phải đối mặt với thử thách sống còn đầu tiên. Sau hơn một năm giao tranh ở các đô thị và vùng đồng bằng mà không dứt điểm được cuộc chiến, Bộ Chỉ huy quân viễn chinh Pháp tại Đông Dương tin rằng chìa khóa để kết thúc nhanh cuộc chiến nằm ở việc đánh thẳng vào bộ não của kháng chiến: tiêu diệt cơ quan lãnh đạo, bắt sống hoặc buộc Chính phủ kháng chiến phải đầu hàng, đồng thời tiêu diệt bộ đội chủ lực còn non trẻ của ta ngay tại căn cứ. Kế hoạch được vạch ra công phu: dùng một lực lượng hỗn hợp gồm quân nhảy dù, bộ binh và cả tàu chiến, hình thành hai gọng kìm siết chặt quanh Việt Bắc, đồng thời khóa chặt biên giới Việt – Trung để cô lập hoàn toàn cuộc kháng chiến với bên ngoài. Nếu thành công, đây sẽ là đòn kết liễu khiến cuộc kháng chiến toàn quốc chưa kịp trưởng thành đã phải kết thúc."},{"t":"Ngày 7 tháng 10 năm 1947. Sáng ngày 7 tháng 10 năm 1947, hàng loạt máy bay vận tải quân sự xuất hiện trên bầu trời Bắc Kạn. Quân Pháp cho lính dù đổ xuống ngay thị xã Bắc Kạn, đồng thời rải quân xuống Chợ Mới, Chợ Đồn — những vị trí được tính toán để bao vây nhanh nhất khu vực được cho là nơi đóng cơ quan đầu não kháng chiến. Cùng lúc đó, một binh đoàn bộ binh xuất phát từ Lạng Sơn, theo đường số 4 tiến lên Cao Bằng rồi vòng xuống Bắc Kạn khép gọng kìm phía đông; một binh đoàn hỗn hợp khác ngược sông Hồng, sông Lô từ Hà Nội tiến lên Tuyên Quang, khép gọng kìm phía tây. Đòn tấn công bất ngờ từ trên không đặt cơ quan đầu não kháng chiến trước nguy cơ lớn chưa từng có kể từ ngày rời Hà Nội. Có những thời điểm, lính dù Pháp đổ xuống chỉ cách nơi làm việc của một số cơ quan Trung ương một khoảng không xa, nhưng nhờ hệ thống giao liên, cảnh giới và tinh thần bí mật đã được rèn luyện suốt nhiều tháng trước đó, các cơ quan kịp thời sơ tán an toàn."},{"t":"Cuộc hành quân mang tên Léa. Cuộc tấn công tháng 10 năm 1947 nằm trong một kế hoạch quân sự được phía Pháp đặt tên là cuộc hành quân Léa, do tướng Jean-Étienne Valluy, Tổng chỉ huy quân viễn chinh Pháp ở Đông Dương, trực tiếp vạch ra và chỉ huy, diễn ra từ ngày 7 tháng 10 đến đầu tháng 11 năm 1947. Ý đồ của cuộc hành quân rất rõ ràng: dùng lực lượng nhảy dù đánh úp bất ngờ vào nơi được tình báo Pháp phỏng đoán là sở chỉ huy của Việt Minh, kết hợp với các cánh quân bộ binh siết chặt vòng vây từ nhiều hướng để không cho đối phương kịp thoát. Trên thực tế, có những thời điểm mũi nhảy dù của Pháp tiến sát đến mức suýt chạm được vào khu vực nơi Chủ tịch Hồ Chí Minh và Đại tướng Võ Nguyên Giáp đang trú đóng, nhưng nhờ mạng lưới giao liên cảnh giới từ xa và quyết định sơ tán kịp thời, các cơ quan đầu não đã kịp luồn qua giữa các mũi tiến quân để thoát khỏi vòng vây. Không đạt được mục tiêu chính sau hơn ba tuần, tướng Valluy tiếp tục phát động một cuộc hành quân thứ hai, mang tên Ceinture, vào tháng 11 năm 1947, nhưng kết quả cũng không khác gì cuộc hành quân trước đó. Giới nghiên cứu quân sự phương Tây sau này nhìn nhận Léa là một kế hoạch được chuẩn bị bài bản, kết hợp nhiều binh chủng theo kiểu tác chiến hiện đại hiếm thấy ở chiến trường Đông Dương thời điểm đó, nhưng lại vấp phải một trở ngại mà mọi phương tiện quân sự không thể khắc phục: địa hình rừng núi hiểm trở khiến quân nhảy dù khó hợp đồng tác chiến đúng kế hoạch, còn mạng lưới do thám của đối phương gần như tê liệt trước một dân cư luôn giữ im lặng tuyệt đối về mọi hành tung của cán bộ kháng chiến."},{"t":"Bạn có biết? Theo các tư liệu quân sự phương Tây về cuộc hành quân Léa, có thời điểm lực lượng nhảy dù Pháp đã tiến rất gần khu vực trú đóng của cơ quan đầu não kháng chiến, khiến chiến dịch này được xem là một trong những lần Chủ tịch Hồ Chí Minh và Đại tướng Võ Nguyên Giáp ở gần nguy cơ bị đối phương bắt giữ nhất trong suốt cuộc kháng chiến chống Pháp."},{"t":"“Phải phá tan cuộc tấn công mùa đông của giặc Pháp”. Ngày 15 tháng 10 năm 1947, Ban Thường vụ Trung ương Đảng ra chỉ thị mang tên “Phải phá tan cuộc tấn công mùa đông của giặc Pháp”, xác định rõ: đây là cơ hội để quân đội ta trưởng thành qua thử lửa, đồng thời bảo vệ bằng được cơ quan đầu não. Trong khi Chủ tịch Hồ Chí Minh cùng phần lớn cơ quan Trung ương lặng lẽ di chuyển sâu hơn vào rừng, giữ liên lạc chỉ đạo qua giao liên và điện đài, quân và dân Việt Bắc bước vào một cuộc chiến đấu trên nhiều mặt trận cùng lúc. Ở mặt trận Bắc Kạn, bộ đội và dân quân bao vây, tập kích liên tục vào các vị trí quân Pháp vừa chiếm đóng, khiến đối phương không thể mở rộng vùng kiểm soát như dự tính. Trên đường số 4 — con đường huyết mạch nối Cao Bằng, Lạng Sơn — bộ đội ta tổ chức hàng loạt trận phục kích đánh vào các đoàn xe cơ giới, đỉnh điểm là chiến thắng Đèo Bông Lau ngày 30 tháng 10 năm 1947, một trong những trận phục kích lớn nhất của quân ta trên tuyến đường này, phá hủy nhiều xe quân sự và gây thiệt hại nặng cho đối phương."},{"t":"Bạn có biết? Sau chiến thắng Đèo Bông Lau và hàng loạt trận phục kích khác, đường số 4 trở thành nỗi ám ảnh đến mức binh lính Pháp gọi đây là “con đường chết”. Đài chiến thắng Bông Lau – Lũng Phầy sau này được xếp hạng di tích cấp quốc gia, ghi dấu một trong những chiến công tiêu biểu của chiến dịch Việt Bắc thu – đông."},{"t":"Trận địa trên sông Lô. Không chỉ trên bộ, mặt trận sông Lô cũng trở thành nơi diễn ra những trận đánh quyết định. Đoàn tàu chiến, ca nô của Pháp ngược sông Lô để tiếp ứng cho cánh quân đường thủy đã lọt vào các trận địa phục kích của bộ đội ta tại khu vực Đoan Hùng, Khoan Bộ, Khe Lau (giáp ranh Phú Thọ, Tuyên Quang). Nhiều tàu chiến, ca nô bị bắn chìm hoặc hư hỏng nặng, buộc đối phương phải từ bỏ ý định dùng đường sông làm tuyến tiếp vận chủ lực lên Việt Bắc. Chiến thắng trên sông Lô về sau còn đi vào âm nhạc qua bản trường ca nổi tiếng của nhạc sĩ Văn Cao, trở thành một trong những biểu tượng văn hóa gắn liền với chiến dịch Việt Bắc thu – đông 1947. Trong khi các mặt trận sôi động khắp Bắc Kạn, đường số 4 và sông Lô, Chủ tịch Hồ Chí Minh cùng các cơ quan Trung ương vẫn ở lại ngay giữa vùng chiến sự, được bộ đội và nhân dân bảo vệ an toàn tuyệt đối, tiếp tục chỉ đạo cuộc chiến đấu qua từng bức điện. Trong những ngày tháng gay go ấy, việc giữ vững liên lạc giữa các cơ quan Trung ương với những mặt trận đang chiến đấu ác liệt cách nhau hàng chục, hàng trăm cây số đường rừng là cả một kỳ công thầm lặng. Đội ngũ giao liên phải luồn qua vùng địch kiểm soát, có khi đi cả ngày lẫn đêm để kịp chuyển một bức điện chỉ đạo hay một chỉ thị khẩn, trong khi hệ thống thông tin vô tuyến còn rất thô sơ và luôn đứng trước nguy cơ bị đối phương dò sóng, phát hiện vị trí đóng quân."},{"t":"Khi kẻ tấn công phải rút lui. Sau hơn hai tháng bị đánh trả quyết liệt trên khắp các hướng, không đạt được mục tiêu tiêu diệt cơ quan đầu não hay bộ đội chủ lực, lại chịu tổn thất ngày càng nặng, quân Pháp buộc phải tính đến việc rút lui. Đến cuối tháng 12 năm 1947, sau 75 ngày đêm, phần lớn lực lượng tấn công đã phải rời khỏi Việt Bắc, để lại một chiến trường mà đối phương không thể kiểm soát nổi. Đây là chiến thắng quân sự có ý nghĩa chiến lược đầu tiên của cuộc kháng chiến toàn quốc. Kế hoạch “đánh nhanh, thắng nhanh” — vốn được coi là con bài chiến lược của thực dân Pháp — hoàn toàn phá sản. Từ đây, cuộc chiến buộc phải chuyển sang một hình thái mới: chiến tranh kéo dài, mà ưu thế về thời gian, về lòng dân dần nghiêng về phía những người kháng chiến."},{"t":"Bạn có biết? Chiến thắng Việt Bắc thu – đông 1947 không chỉ bảo toàn được cơ quan đầu não và bộ đội chủ lực, mà còn giúp quân đội ta trưởng thành vượt bậc qua thực chiến: từ một lực lượng chủ yếu đánh du kích, bộ đội chủ lực bắt đầu tổ chức được những trận đánh tập trung quy mô cấp trung đoàn, đặt nền móng cho các chiến dịch lớn hơn những năm sau, trong đó có Chiến dịch Biên giới năm 1950."},{"t":"Bài học của một chiến khu không bị đánh sập. Nhìn lại 75 ngày đêm ấy, điều đáng chú ý không chỉ nằm ở những trận đánh, mà còn ở cách cả một hệ thống — từ cơ quan lãnh đạo đến từng người dân — đã cùng vận hành nhịp nhàng để bảo vệ bí mật tuyệt đối. Không một tài liệu, không một nhân chứng nào ghi nhận việc quân Pháp phát hiện được nơi ở chính xác của Chủ tịch Hồ Chí Minh trong suốt chiến dịch, dù các mũi tấn công nhiều lúc chỉ cách khu vực An toàn khu không xa. Chiến thắng Việt Bắc thu – đông 1947 vì vậy không chỉ là chiến thắng quân sự, mà còn là bằng chứng sống động cho sự vững chắc của mối quan hệ giữa Đảng, Chính phủ với nhân dân các dân tộc Việt Bắc — nền tảng để An toàn khu tiếp tục đứng vững thêm bảy năm nữa, cho đến ngày toàn thắng ở Điện Biên Phủ (xem thêm chuyên đề “Từ Tỉn Keo đến Điện Biên Phủ”). Về sau, khi tổng kết lại chiến dịch này, nhiều nhà nghiên cứu quân sự trong và ngoài nước đều coi thất bại của cuộc hành quân Léa và Ceinture là dấu mốc cho thấy một đội quân nhà nghề, được trang bị hiện đại, vẫn có thể bị đánh bại bởi một lực lượng non trẻ hơn nếu thiếu đi sự ủng hộ của dân chúng bản địa — bài học mà nước Pháp sẽ còn phải trả giá thêm nhiều lần nữa trước khi cuộc chiến kết thúc ở Điện Biên Phủ bảy năm sau đó."}],"so_chu":1985},{"i":2,"tieu_de_bang":"Từ Tỉn Keo đến Điện Biên Phủ","tieu_de":"“Chắc thắng mới đánh”: lời dặn từ một căn lán nhỏ và con đường tới Điện Biên Phủ","sapo":"Từ cuộc họp trong một căn lán nhỏ ở Tỉn Keo đêm 6 tháng 12 năm 1953 đến buổi chiều 7 tháng 5 năm 1954 ở lòng chảo Điện Biên là chưa đầy năm tháng. Ở khởi đầu con đường ấy là một câu hỏi lớn: đánh hay không đánh, và một lời dặn ngắn gọn của Bác đã trở thành kim chỉ nam cho cả chiến dịch.","bia":{"src":"textures/bai/G15_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Kế hoạch Nava và lòng chảo Điện Biên","text":"Năm 1953, cuộc chiến tranh Đông Dương bước sang năm thứ bảy mà thực dân Pháp vẫn chưa tìm ra lối thoát. Được Mỹ viện trợ ngày càng nhiều về vũ khí, phương tiện, Pháp cử tướng Henri Navarre sang làm Tổng chỉ huy, xây dựng một kế hoạch quân sự mới — về sau gọi là kế hoạch Nava — với tham vọng trong khoảng mười tám tháng sẽ xoay chuyển cục diện chiến trường, tạo thế mạnh trên bàn đàm phán.\n\nNgày 20 tháng 11 năm 1953, quân Pháp bất ngờ cho lính dù đổ xuống Điện Biên Phủ, một lòng chảo rộng giữa núi rừng Tây Bắc, rồi gấp rút xây dựng nơi đây thành một tập đoàn cứ điểm mạnh với hệ thống hầm hào, lô cốt, sân bay dã chiến, được đánh giá là “pháo đài bất khả xâm phạm”. Tại An toàn khu Việt Bắc, câu hỏi đặt ra trước Bộ Chính trị là: có nên đánh vào Điện Biên Phủ hay không, và nếu đánh thì phải chuẩn bị ra sao để chắc thắng, tránh một canh bạc mạo hiểm có thể làm tiêu hao lực lượng chủ lực vừa được xây dựng qua nhiều năm.","doc":1},{"loai":"anh","src":"textures/bang_w/G15_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Từ Tỉn Keo đến Điện Biên Phủ”, nhìn từ xa."},{"loai":"doan","tieu_de":"Đêm quyết định ở Tỉn Keo","text":"Đêm 6 tháng 12 năm 1953, tại lán Tỉn Keo dưới chân đèo De (xã Phú Đình, Định Hóa, Thái Nguyên), Bộ Chính trị họp dưới sự chủ trì của Chủ tịch Hồ Chí Minh. Sau khi cân nhắc các phương án, Bộ Chính trị quyết định mở Chiến dịch Điện Biên Phủ, giao Đại tướng Võ Nguyên Giáp — Tổng Tư lệnh Quân đội nhân dân Việt Nam — trực tiếp làm Chỉ huy trưởng kiêm Bí thư Đảng ủy mặt trận. Căn lán nhỏ, chỉ đủ kê một bộ bàn ghế mộc và tấm bản đồ tác chiến, đã trở thành nơi ra đời một trong những quyết định quân sự quan trọng bậc nhất lịch sử Việt Nam hiện đại.\n\nQuyết định vừa đưa ra, cả nước đã dồn sức cho mặt trận xa xôi giữa núi rừng Tây Bắc. Bộ đội hành quân bộ hàng trăm cây số, kéo theo pháo lớn qua đèo dốc; hàng vạn dân công hỏa tuyến gánh gạo, thồ hàng bằng xe đạp thồ; thanh niên xung phong ngày đêm mở đường, san lấp hố bom giữ mạch giao thông không đứt. Hậu phương Việt Bắc, Liên khu Việt Bắc và các vùng tự do khác trở thành điểm tựa hậu cần cho trận quyết chiến chiến lược lớn nhất của cả cuộc kháng chiến.","doc":2},{"loai":"trich","text":"Trận này rất quan trọng, phải đánh cho thắng. Chắc thắng mới đánh, không chắc thắng không đánh.","nguoi":"Chủ tịch Hồ Chí Minh dặn Đại tướng Võ Nguyên Giáp trước khi ra mặt trận (theo hồi ký của Đại tướng)","nguon_ten":"Võ Nguyên Giáp, Điện Biên Phủ: Điểm hẹn lịch sử, NXB Quân đội nhân dân, 2000","doc":3},{"loai":"doan","tieu_de":"“Kéo pháo vào” rồi lại “kéo pháo ra”","text":"Theo hồi ký của Đại tướng Võ Nguyên Giáp, trước khi ông lên đường, Bác trao cho Tổng Tư lệnh toàn quyền quyết định tại mặt trận, cùng lời dặn ngắn gọn nhưng nặng trĩu trách nhiệm: “chắc thắng mới đánh”. Lời dặn ấy trở thành kim chỉ nam cho quyết định khó khăn nhất của cả chiến dịch. Theo phương án ban đầu, bộ đội ta chuẩn bị đánh nhanh, giải quyết nhanh trong vài ngày đêm; pháo binh được kéo bằng tay, bằng sức người qua những con dốc dựng đứng để vào chiếm lĩnh trận địa.\n\nNhưng càng áp sát, Đại tướng càng nhận thấy tập đoàn cứ điểm Điện Biên Phủ đã được củng cố mạnh hơn nhiều so với dự tính ban đầu; đánh nhanh trong tình thế chưa chắc thắng có thể trả giá bằng cả một binh đoàn chủ lực. Ngày 26 tháng 1 năm 1954, ngay trước giờ nổ súng, Đại tướng quyết định một việc chưa từng có tiền lệ: hoãn trận đánh, ra lệnh kéo pháo ra khỏi trận địa để chuyển sang phương châm mới — “đánh chắc, tiến chắc”. Bộ Chính trị và Chủ tịch Hồ Chí Minh, sau khi nghe báo cáo, đều nhất trí với quyết định táo bạo nhưng sáng suốt ấy.","doc":4},{"loai":"ban_co_biet","text":"Trong đêm rút pháo ra khỏi trận địa theo phương châm mới, tại dốc Chuối, khẩu pháo do khẩu đội của Tô Vĩnh Diện phụ trách bị đứt dây kéo, có nguy cơ lao xuống vực. Đêm 1 tháng 2 năm 1954, ông lấy thân mình chèn bánh pháo, hy sinh để cứu khẩu pháo, và được truy tặng danh hiệu Anh hùng Lực lượng vũ trang nhân dân.","nguon_ten":"Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam; tư liệu Bộ Quốc phòng","doc":5},{"loai":"anh","src":"textures/bang_w/G15_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Từ Tỉn Keo đến Điện Biên Phủ”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Ba đợt tấn công","text":"Ngày 13 tháng 3 năm 1954, quân ta nổ súng mở màn chiến dịch, tiến công cứ điểm Him Lam thuộc phân khu Bắc. Ngay trong trận mở đầu, chiến sĩ Phan Đình Giót lấy thân mình lấp lỗ châu mai, mở đường cho đơn vị xông lên tiêu diệt cứ điểm. Sau đợt một (13–17 tháng 3) đánh chiếm cụm cứ điểm phía Bắc, quân ta chuyển sang đợt hai (30 tháng 3 – 30 tháng 4 năm 1954), đánh chiếm dãy đồi phía Đông — trong đó có đồi A1 — và khu trung tâm Mường Thanh, từng bước siết chặt vòng vây, cắt đứt hoàn toàn đường tiếp tế bằng đường không của đối phương.\n\nĐợt ba, từ ngày 1 đến 7 tháng 5 năm 1954, là đợt tổng công kích quyết định. Đêm mùng 6 rạng ngày 7 tháng 5, quân ta cho nổ khối bộc phá gần một nghìn ký thuốc nổ dưới đồi A1, mở đường cho đợt xung phong cuối cùng. Chiều 7 tháng 5 năm 1954, bộ đội ta đánh chiếm hầm chỉ huy, bắt sống tướng Đờ Cát-xtơ-ri (De Castries) cùng toàn bộ Bộ Tham mưu tập đoàn cứ điểm. Lá cờ “Quyết chiến quyết thắng” tung bay trên nóc hầm chỉ huy, kết thúc 56 ngày đêm mà sau này Tố Hữu gói gọn trong một câu thơ: “khoét núi, ngủ hầm, mưa dầm, cơm vắt”.","doc":6},{"loai":"anh","src":"textures/bang_w/G15_2_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Từ Tỉn Keo đến Điện Biên Phủ”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Con đường huyết mạch nuôi trận đánh","text":"Một chiến dịch quy mô chưa từng có đòi hỏi khối lượng hậu cần khổng lồ, trong khi Điện Biên Phủ nằm cách xa hậu phương Việt Bắc và vùng tự do Thanh Hóa, Nghệ An hàng trăm cây số đường rừng núi. Những cung đường như đèo Pha Đin, ngã ba Cò Nòi trở thành “tọa độ lửa”, nơi máy bay Pháp tập trung đánh phá suốt ngày đêm hòng cắt đứt đường tiếp vận, nhưng thanh niên xung phong và dân công vẫn bám trụ san lấp hố bom, thông xe từng giờ để đoàn xe, đoàn người không đứt mạch.\n\nHàng vạn dân công hỏa tuyến dùng xe đạp thồ được cải tiến, buộc thêm càng gỗ để tăng sức chở lên gấp nhiều lần trọng lượng thông thường, cùng ngựa thồ, thuyền độc mộc, đôi quang gánh, ngày đêm vận chuyển lương thực, đạn dược từ khắp các vùng tự do dồn về mặt trận. Chính khối lượng hậu cần khổng lồ ấy, được huy động và điều phối một phần từ trung tâm chỉ đạo đặt tại Việt Bắc, đã giúp bộ đội trụ vững suốt 56 ngày đêm vây lấn, để đi đến chiến thắng cuối cùng.","doc":7},{"loai":"doan","tieu_de":"Người vẫn ở lại Việt Bắc, ngày đêm dõi theo mặt trận","text":"Khác với Chiến dịch Biên giới năm 1950, khi Chủ tịch Hồ Chí Minh trực tiếp có mặt tại mặt trận Đông Khê, trong Chiến dịch Điện Biên Phủ, Người ở lại An toàn khu Việt Bắc, theo dõi diễn biến chiến sự qua các bức điện gửi về từ Bộ Chỉ huy mặt trận. Mọi quyết định quan trọng của Đại tướng Võ Nguyên Giáp, đặc biệt là quyết định thay đổi phương châm tác chiến ngày 26 tháng 1 năm 1954, đều được báo cáo về Bộ Chính trị và Chủ tịch Hồ Chí Minh trước khi thực hiện.\n\nTrong những ngày chiến dịch diễn ra ác liệt, từ căn lán nhỏ giữa rừng cọ Định Hóa, Người vẫn đều đặn gửi thư động viên bộ đội, dân công và thanh niên xung phong đang chiến đấu, phục vụ ngoài mặt trận xa xôi. Sự theo sát âm thầm nhưng không rời mắt ấy của vị Chủ tịch nước, dù không trực tiếp ra mặt trận lần này, vẫn là chỗ dựa tinh thần lớn lao cho toàn chiến dịch, từ người lính xung kích trong chiến hào cho đến từng dân công gánh gạo trên những cung đường đèo dốc.","doc":8},{"loai":"doan","tieu_de":"Tiếng vang từ Genève đến khắp năm châu","text":"Chỉ một ngày sau chiến thắng, ngày 8 tháng 5 năm 1954, Hội nghị Genève về Đông Dương bắt đầu bàn tới vấn đề Việt Nam, đặt phái đoàn Pháp vào thế phải đàm phán trên thế yếu. Chiến thắng Điện Biên Phủ, như nhiều sử gia quốc tế sau này nhận định, là trận đánh đầu tiên mà một dân tộc thuộc địa đánh bại hoàn toàn quân đội của một cường quốc thực dân trong một trận quyết chiến chiến lược, trở thành nguồn cổ vũ cho phong trào giải phóng dân tộc ở nhiều nơi trên thế giới, đặc biệt tại châu Phi và các thuộc địa khác của Pháp. Tên gọi Điện Biên Phủ, từ một địa danh gần như vô danh trên bản đồ Tây Bắc, bước vào từ điển của báo chí quốc tế như một biểu tượng cho khả năng một dân tộc nhỏ có thể đánh bại một đội quân nhà nghề nếu có đường lối đúng và quyết tâm đến cùng.\n\nTừ căn lán Tỉn Keo, nơi quyết định lịch sử được đưa ra, đến lòng chảo Điện Biên rực lửa, chưa đầy năm tháng đã trôi qua — nhưng đó là năm tháng làm thay đổi số phận của cả một dân tộc, và để lại một bài học chiến lược: chỉ đánh khi thật sự chắc thắng, nhưng một khi đã đánh thì huy động sức mạnh của cả nước để đi đến toàn thắng.\n\nNgày nay, nhìn lại toàn bộ hành trình từ đêm họp Bộ Chính trị giữa rừng cọ Định Hóa đến lá cờ tung bay trên nóc hầm Đờ Cát-xtơ-ri, có thể thấy rõ vì sao Điện Biên Phủ không phải một chiến thắng may rủi mà là kết quả của một quá trình chuẩn bị kéo dài, thận trọng, gắn liền với những quyết định được cân nhắc kỹ lưỡng ngay từ trong căn lán nhỏ nơi An toàn khu — nơi vẫn được nhắc tới như điểm khởi đầu của toàn bộ chiến dịch.","doc":9},{"loai":"ban_co_biet","text":"Trong thư khen ngợi bộ đội, dân công, thanh niên xung phong sau chiến thắng Điện Biên Phủ, Bác căn dặn: thắng lợi tuy lớn nhưng mới là bắt đầu, tuyệt đối không được vì thắng mà kiêu, không được chủ quan khinh địch, phải cố gắng hơn nữa để giành thắng lợi cuối cùng.","nguon_ten":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","doc":10},{"loai":"ban_co_biet","text":"Đúng 56 ngày đêm sau ngày nổ súng, tin chiến thắng Điện Biên Phủ được truyền đi khắp cả nước qua làn sóng của Đài Tiếng nói Việt Nam, trước khi kịp lan ra báo chí quốc tế và làm chấn động dư luận Pháp ngay trong ngày khai mạc phiên họp về Đông Dương tại Hội nghị Genève.","nguon_ten":"Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","doc":11}],"nguon":["Võ Nguyên Giáp – Điện Biên Phủ: Điểm hẹn lịch sử (hồi ký), NXB Quân đội nhân dân, 2000","Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","Tư liệu Bộ Quốc phòng về Chiến dịch Điện Biên Phủ"],"doc":[{"t":"“Chắc thắng mới đánh”: lời dặn từ một căn lán nhỏ và con đường tới Điện Biên Phủ. Từ cuộc họp trong một căn lán nhỏ ở Tỉn Keo đêm 6 tháng 12 năm 1953 đến buổi chiều 7 tháng 5 năm 1954 ở lòng chảo Điện Biên là chưa đầy năm tháng. Ở khởi đầu con đường ấy là một câu hỏi lớn: đánh hay không đánh, và một lời dặn ngắn gọn của Bác đã trở thành kim chỉ nam cho cả chiến dịch."},{"t":"Kế hoạch Nava và lòng chảo Điện Biên. Năm 1953, cuộc chiến tranh Đông Dương bước sang năm thứ bảy mà thực dân Pháp vẫn chưa tìm ra lối thoát. Được Mỹ viện trợ ngày càng nhiều về vũ khí, phương tiện, Pháp cử tướng Henri Navarre sang làm Tổng chỉ huy, xây dựng một kế hoạch quân sự mới — về sau gọi là kế hoạch Nava — với tham vọng trong khoảng mười tám tháng sẽ xoay chuyển cục diện chiến trường, tạo thế mạnh trên bàn đàm phán. Ngày 20 tháng 11 năm 1953, quân Pháp bất ngờ cho lính dù đổ xuống Điện Biên Phủ, một lòng chảo rộng giữa núi rừng Tây Bắc, rồi gấp rút xây dựng nơi đây thành một tập đoàn cứ điểm mạnh với hệ thống hầm hào, lô cốt, sân bay dã chiến, được đánh giá là “pháo đài bất khả xâm phạm”. Tại An toàn khu Việt Bắc, câu hỏi đặt ra trước Bộ Chính trị là: có nên đánh vào Điện Biên Phủ hay không, và nếu đánh thì phải chuẩn bị ra sao để chắc thắng, tránh một canh bạc mạo hiểm có thể làm tiêu hao lực lượng chủ lực vừa được xây dựng qua nhiều năm."},{"t":"Đêm quyết định ở Tỉn Keo. Đêm 6 tháng 12 năm 1953, tại lán Tỉn Keo dưới chân đèo De (xã Phú Đình, Định Hóa, Thái Nguyên), Bộ Chính trị họp dưới sự chủ trì của Chủ tịch Hồ Chí Minh. Sau khi cân nhắc các phương án, Bộ Chính trị quyết định mở Chiến dịch Điện Biên Phủ, giao Đại tướng Võ Nguyên Giáp — Tổng Tư lệnh Quân đội nhân dân Việt Nam — trực tiếp làm Chỉ huy trưởng kiêm Bí thư Đảng ủy mặt trận. Căn lán nhỏ, chỉ đủ kê một bộ bàn ghế mộc và tấm bản đồ tác chiến, đã trở thành nơi ra đời một trong những quyết định quân sự quan trọng bậc nhất lịch sử Việt Nam hiện đại. Quyết định vừa đưa ra, cả nước đã dồn sức cho mặt trận xa xôi giữa núi rừng Tây Bắc. Bộ đội hành quân bộ hàng trăm cây số, kéo theo pháo lớn qua đèo dốc; hàng vạn dân công hỏa tuyến gánh gạo, thồ hàng bằng xe đạp thồ; thanh niên xung phong ngày đêm mở đường, san lấp hố bom giữ mạch giao thông không đứt. Hậu phương Việt Bắc, Liên khu Việt Bắc và các vùng tự do khác trở thành điểm tựa hậu cần cho trận quyết chiến chiến lược lớn nhất của cả cuộc kháng chiến."},{"t":"Trận này rất quan trọng, phải đánh cho thắng. Chắc thắng mới đánh, không chắc thắng không đánh. — Chủ tịch Hồ Chí Minh dặn Đại tướng Võ Nguyên Giáp trước khi ra mặt trận (theo hồi ký của Đại tướng)"},{"t":"“Kéo pháo vào” rồi lại “kéo pháo ra”. Theo hồi ký của Đại tướng Võ Nguyên Giáp, trước khi ông lên đường, Bác trao cho Tổng Tư lệnh toàn quyền quyết định tại mặt trận, cùng lời dặn ngắn gọn nhưng nặng trĩu trách nhiệm: “chắc thắng mới đánh”. Lời dặn ấy trở thành kim chỉ nam cho quyết định khó khăn nhất của cả chiến dịch. Theo phương án ban đầu, bộ đội ta chuẩn bị đánh nhanh, giải quyết nhanh trong vài ngày đêm; pháo binh được kéo bằng tay, bằng sức người qua những con dốc dựng đứng để vào chiếm lĩnh trận địa. Nhưng càng áp sát, Đại tướng càng nhận thấy tập đoàn cứ điểm Điện Biên Phủ đã được củng cố mạnh hơn nhiều so với dự tính ban đầu; đánh nhanh trong tình thế chưa chắc thắng có thể trả giá bằng cả một binh đoàn chủ lực. Ngày 26 tháng 1 năm 1954, ngay trước giờ nổ súng, Đại tướng quyết định một việc chưa từng có tiền lệ: hoãn trận đánh, ra lệnh kéo pháo ra khỏi trận địa để chuyển sang phương châm mới — “đánh chắc, tiến chắc”. Bộ Chính trị và Chủ tịch Hồ Chí Minh, sau khi nghe báo cáo, đều nhất trí với quyết định táo bạo nhưng sáng suốt ấy."},{"t":"Bạn có biết? Trong đêm rút pháo ra khỏi trận địa theo phương châm mới, tại dốc Chuối, khẩu pháo do khẩu đội của Tô Vĩnh Diện phụ trách bị đứt dây kéo, có nguy cơ lao xuống vực. Đêm 1 tháng 2 năm 1954, ông lấy thân mình chèn bánh pháo, hy sinh để cứu khẩu pháo, và được truy tặng danh hiệu Anh hùng Lực lượng vũ trang nhân dân."},{"t":"Ba đợt tấn công. Ngày 13 tháng 3 năm 1954, quân ta nổ súng mở màn chiến dịch, tiến công cứ điểm Him Lam thuộc phân khu Bắc. Ngay trong trận mở đầu, chiến sĩ Phan Đình Giót lấy thân mình lấp lỗ châu mai, mở đường cho đơn vị xông lên tiêu diệt cứ điểm. Sau đợt một (13–17 tháng 3) đánh chiếm cụm cứ điểm phía Bắc, quân ta chuyển sang đợt hai (30 tháng 3 – 30 tháng 4 năm 1954), đánh chiếm dãy đồi phía Đông — trong đó có đồi A1 — và khu trung tâm Mường Thanh, từng bước siết chặt vòng vây, cắt đứt hoàn toàn đường tiếp tế bằng đường không của đối phương. Đợt ba, từ ngày 1 đến 7 tháng 5 năm 1954, là đợt tổng công kích quyết định. Đêm mùng 6 rạng ngày 7 tháng 5, quân ta cho nổ khối bộc phá gần một nghìn ký thuốc nổ dưới đồi A1, mở đường cho đợt xung phong cuối cùng. Chiều 7 tháng 5 năm 1954, bộ đội ta đánh chiếm hầm chỉ huy, bắt sống tướng Đờ Cát-xtơ-ri (De Castries) cùng toàn bộ Bộ Tham mưu tập đoàn cứ điểm. Lá cờ “Quyết chiến quyết thắng” tung bay trên nóc hầm chỉ huy, kết thúc 56 ngày đêm mà sau này Tố Hữu gói gọn trong một câu thơ: “khoét núi, ngủ hầm, mưa dầm, cơm vắt”."},{"t":"Con đường huyết mạch nuôi trận đánh. Một chiến dịch quy mô chưa từng có đòi hỏi khối lượng hậu cần khổng lồ, trong khi Điện Biên Phủ nằm cách xa hậu phương Việt Bắc và vùng tự do Thanh Hóa, Nghệ An hàng trăm cây số đường rừng núi. Những cung đường như đèo Pha Đin, ngã ba Cò Nòi trở thành “tọa độ lửa”, nơi máy bay Pháp tập trung đánh phá suốt ngày đêm hòng cắt đứt đường tiếp vận, nhưng thanh niên xung phong và dân công vẫn bám trụ san lấp hố bom, thông xe từng giờ để đoàn xe, đoàn người không đứt mạch. Hàng vạn dân công hỏa tuyến dùng xe đạp thồ được cải tiến, buộc thêm càng gỗ để tăng sức chở lên gấp nhiều lần trọng lượng thông thường, cùng ngựa thồ, thuyền độc mộc, đôi quang gánh, ngày đêm vận chuyển lương thực, đạn dược từ khắp các vùng tự do dồn về mặt trận. Chính khối lượng hậu cần khổng lồ ấy, được huy động và điều phối một phần từ trung tâm chỉ đạo đặt tại Việt Bắc, đã giúp bộ đội trụ vững suốt 56 ngày đêm vây lấn, để đi đến chiến thắng cuối cùng."},{"t":"Người vẫn ở lại Việt Bắc, ngày đêm dõi theo mặt trận. Khác với Chiến dịch Biên giới năm 1950, khi Chủ tịch Hồ Chí Minh trực tiếp có mặt tại mặt trận Đông Khê, trong Chiến dịch Điện Biên Phủ, Người ở lại An toàn khu Việt Bắc, theo dõi diễn biến chiến sự qua các bức điện gửi về từ Bộ Chỉ huy mặt trận. Mọi quyết định quan trọng của Đại tướng Võ Nguyên Giáp, đặc biệt là quyết định thay đổi phương châm tác chiến ngày 26 tháng 1 năm 1954, đều được báo cáo về Bộ Chính trị và Chủ tịch Hồ Chí Minh trước khi thực hiện. Trong những ngày chiến dịch diễn ra ác liệt, từ căn lán nhỏ giữa rừng cọ Định Hóa, Người vẫn đều đặn gửi thư động viên bộ đội, dân công và thanh niên xung phong đang chiến đấu, phục vụ ngoài mặt trận xa xôi. Sự theo sát âm thầm nhưng không rời mắt ấy của vị Chủ tịch nước, dù không trực tiếp ra mặt trận lần này, vẫn là chỗ dựa tinh thần lớn lao cho toàn chiến dịch, từ người lính xung kích trong chiến hào cho đến từng dân công gánh gạo trên những cung đường đèo dốc."},{"t":"Tiếng vang từ Genève đến khắp năm châu. Chỉ một ngày sau chiến thắng, ngày 8 tháng 5 năm 1954, Hội nghị Genève về Đông Dương bắt đầu bàn tới vấn đề Việt Nam, đặt phái đoàn Pháp vào thế phải đàm phán trên thế yếu. Chiến thắng Điện Biên Phủ, như nhiều sử gia quốc tế sau này nhận định, là trận đánh đầu tiên mà một dân tộc thuộc địa đánh bại hoàn toàn quân đội của một cường quốc thực dân trong một trận quyết chiến chiến lược, trở thành nguồn cổ vũ cho phong trào giải phóng dân tộc ở nhiều nơi trên thế giới, đặc biệt tại châu Phi và các thuộc địa khác của Pháp. Tên gọi Điện Biên Phủ, từ một địa danh gần như vô danh trên bản đồ Tây Bắc, bước vào từ điển của báo chí quốc tế như một biểu tượng cho khả năng một dân tộc nhỏ có thể đánh bại một đội quân nhà nghề nếu có đường lối đúng và quyết tâm đến cùng. Từ căn lán Tỉn Keo, nơi quyết định lịch sử được đưa ra, đến lòng chảo Điện Biên rực lửa, chưa đầy năm tháng đã trôi qua — nhưng đó là năm tháng làm thay đổi số phận của cả một dân tộc, và để lại một bài học chiến lược: chỉ đánh khi thật sự chắc thắng, nhưng một khi đã đánh thì huy động sức mạnh của cả nước để đi đến toàn thắng. Ngày nay, nhìn lại toàn bộ hành trình từ đêm họp Bộ Chính trị giữa rừng cọ Định Hóa đến lá cờ tung bay trên nóc hầm Đờ Cát-xtơ-ri, có thể thấy rõ vì sao Điện Biên Phủ không phải một chiến thắng may rủi mà là kết quả của một quá trình chuẩn bị kéo dài, thận trọng, gắn liền với những quyết định được cân nhắc kỹ lưỡng ngay từ trong căn lán nhỏ nơi An toàn khu — nơi vẫn được nhắc tới như điểm khởi đầu của toàn bộ chiến dịch."},{"t":"Bạn có biết? Trong thư khen ngợi bộ đội, dân công, thanh niên xung phong sau chiến thắng Điện Biên Phủ, Bác căn dặn: thắng lợi tuy lớn nhưng mới là bắt đầu, tuyệt đối không được vì thắng mà kiêu, không được chủ quan khinh địch, phải cố gắng hơn nữa để giành thắng lợi cuối cùng."},{"t":"Bạn có biết? Đúng 56 ngày đêm sau ngày nổ súng, tin chiến thắng Điện Biên Phủ được truyền đi khắp cả nước qua làn sóng của Đài Tiếng nói Việt Nam, trước khi kịp lan ra báo chí quốc tế và làm chấn động dư luận Pháp ngay trong ngày khai mạc phiên họp về Đông Dương tại Hội nghị Genève."}],"so_chu":1896},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Lời kêu gọi kháng chiến đến ngày về Thủ đô: hai mươi ba mốc son ở Việt Bắc","sapo":"Chín năm, hàng nghìn ngày, nhưng chỉ cần hơn hai mươi mốc thời gian là có thể dựng lại toàn bộ hành trình từ một Chính phủ vừa rời Hà Nội trong đêm đến một dân tộc làm nên chiến thắng Điện Biên Phủ. Mỗi mốc dưới đây đều gắn với một quyết định, một trận đánh hay một con người cụ thể — không có mốc nào là ngẫu nhiên.","bia":{"src":"textures/bai/G15_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Hai mạch song song, một trung tâm chỉ đạo","text":"Dòng thời gian dưới đây đi theo hai mạch song song. Mạch thứ nhất là chiến trường: từ chiến dịch Việt Bắc năm 1947 đến chiến thắng Điện Biên Phủ năm 1954. Mạch thứ hai là xây dựng: phát động thi đua ái quốc, mở rộng quan hệ ngoại giao, đưa Đảng ra hoạt động công khai, ra đời tờ báo của Đảng. Cả hai mạch đều được điều hành từ cùng một trung tâm — những căn lán nhỏ trong An toàn khu Việt Bắc.\n\nNhìn khoảng cách giữa các mốc, có thể thấy rõ thế và lực của cuộc kháng chiến lớn dần theo từng năm: từ chỗ phải phòng ngự, bảo toàn lực lượng trong năm 1947, đến chủ động phản công năm 1950, rồi tiến tới một trận quyết chiến chiến lược mang tính định đoạt năm 1954. Đây không phải một quá trình ngẫu nhiên, mà là kết quả của một đường lối kháng chiến trường kỳ, toàn dân, toàn diện được xác định ngay từ những ngày đầu.","doc":1},{"loai":"anh","src":"textures/bang_w/G15_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ xa."},{"loai":"doan","tieu_de":"1946 – 1947: giữ cho được để tồn tại","text":"Giai đoạn mở đầu của dòng thời gian là giai đoạn khó khăn nhất: một Chính phủ non trẻ, một quân đội vừa thành lập chưa đầy hai năm, phải rời bỏ Thủ đô trong đêm để tìm đường tồn tại. Mục tiêu duy nhất lúc này là giữ cho được cơ quan đầu não và lực lượng vũ trang còn non trẻ, đồng thời xây dựng An toàn khu đủ vững chắc để trụ được lâu dài.\n\nCuộc tấn công của thực dân Pháp vào tháng 10 năm 1947 là phép thử đầu tiên và cũng là khắc nghiệt nhất cho mục tiêu ấy (xem thêm chuyên đề “Thu – đông 1947: đòn đánh vào chiến khu thất bại”). Việc trụ vững qua 75 ngày đêm ấy không chỉ bảo toàn được lực lượng, mà còn chứng minh được với cả trong nước lẫn quốc tế rằng cuộc kháng chiến của Việt Nam không thể bị dập tắt bằng một đòn phủ đầu, dù đối phương có ưu thế vượt trội về vũ khí, phương tiện.","doc":2},{"loai":"ban_co_biet","text":"Ngày 30 tháng 10 năm 1947, giữa Chiến dịch Việt Bắc thu – đông, bộ đội ta giành chiến thắng vang dội tại Đèo Bông Lau trên đường số 4, một trong những trận phục kích lớn nhất trên tuyến đường vốn được xem là huyết mạch tiếp vận của quân Pháp lên biên giới.","nguon_ten":"Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","doc":3},{"loai":"doan","tieu_de":"1948 – 1952: xây thế và lực giữa hai trận tuyến","text":"Qua được thử thách 1947, An toàn khu bước vào giai đoạn vừa chiến đấu vừa xây dựng thực lực trên mọi mặt. Ngày 11 tháng 6 năm 1948, Chủ tịch Hồ Chí Minh ra Lời kêu gọi thi đua ái quốc, phát động một phong trào thi đua sản xuất, chiến đấu, học tập trong toàn dân, toàn quân — nền tảng tinh thần cho cả một giai đoạn kháng chiến gian khổ còn ở phía trước. Đầu năm 1950, Trung Quốc và Liên Xô lần lượt công nhận, đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa, chấm dứt tình trạng cuộc kháng chiến phải đơn độc đối mặt với một cường quốc thực dân.\n\nCuối năm 1950, Chiến dịch Biên giới — chiến dịch tiến công quy mô lớn đầu tiên do bộ đội chủ lực ta chủ động mở — giành thắng lợi, khai thông tuyến biên giới Việt – Trung, chấm dứt thế bao vây, cô lập của An toàn khu. Tháng 2 năm 1951, Đại hội đại biểu toàn quốc lần thứ II của Đảng họp tại Chiêm Hóa, đưa Đảng ra hoạt động công khai trở lại; chỉ ít ngày sau, Báo Nhân Dân ra số đầu tiên ngay giữa núi rừng Việt Bắc.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_and_vietnam_women_union_s_cadres_at_.jpg","chu_thich":"Chủ tịch Hồ Chí Minh với cán bộ Hội Phụ nữ tại Việt Bắc, tháng 2/1949 — một lát cắt đời thường giữa giai đoạn xây dựng thực lực kháng chiến.","credit":"Ảnh: Musée Annam · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"1953 – 1954: dồn sức cho trận quyết chiến","text":"Mốc cuối cùng và cũng dồn dập nhất trong toàn bộ dòng thời gian là chuỗi sự kiện dẫn tới Điện Biên Phủ. Từ quyết định mở chiến dịch tại Tỉn Keo đêm 6 tháng 12 năm 1953, đến quyết định đổi phương châm tác chiến ngày 26 tháng 1 năm 1954, rồi tiếng súng mở màn ngày 13 tháng 3, mỗi mốc chỉ cách nhau vài tuần, thậm chí vài ngày — phản ánh nhịp độ dồn dập của một chiến dịch được cả nước huy động sức người, sức của ở mức cao chưa từng có (xem thêm chuyên đề “Từ Tỉn Keo đến Điện Biên Phủ”).\n\nChỉ trong vòng chưa đầy năm tháng, từ một quyết định được đưa ra trong một căn lán nhỏ giữa rừng cọ Định Hóa, cả dân tộc đã đi đến một chiến thắng làm chấn động thế giới. Đây là minh chứng rõ nét nhất cho việc chín năm chuẩn bị bền bỉ ở Việt Bắc — xây dựng lực lượng, củng cố hậu phương, tích lũy kinh nghiệm qua từng chiến dịch — đã hội tụ đúng thời điểm để tạo nên một trận quyết chiến chiến lược.","doc":5},{"loai":"ban_co_biet","text":"Cùng thời gian diễn ra Đại hội II của Đảng, tháng 3 năm 1951, Mặt trận Việt Minh và Hội Liên Việt cũng hợp nhất thành Mặt trận Liên Việt ngay tại Việt Bắc, mở rộng thêm một bước khối đại đoàn kết toàn dân trong kháng chiến.","nguon_ten":"Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","doc":6},{"loai":"doan","tieu_de":"Giao liên — mạch máu nối liền các mốc son","text":"Đằng sau mỗi mốc thời gian trong bảng trên là một hệ thống ít được nhắc tới nhưng lại giữ vai trò sống còn: mạng lưới giao liên. Không có điện thoại, thư điện tử hay đường truyền hiện đại, mọi chỉ thị từ Bộ Chính trị đến Bộ Tổng tư lệnh, mọi báo cáo từ chiến trường về An toàn khu, đều phải qua đôi chân của những người giao liên, đi bộ hoặc đi ngựa xuyên rừng, có khi vượt qua cả vùng địch kiểm soát để kịp thời gian.\n\nMột chỉ thị chậm trễ vài ngày có thể làm lỡ cả một thời cơ quân sự; một bức điện lộ bí mật có thể khiến cả cơ quan đầu não gặp nguy hiểm. Chính sự vận hành âm thầm, chính xác và bền bỉ của mạng lưới giao liên ấy — cùng sự che chở của nhân dân các dân tộc Việt Bắc — đã nối liền tất cả những mốc son trên dòng thời gian này thành một chuỗi liên tục, không đứt đoạn, suốt chín năm ròng.","doc":7},{"loai":"anh","src":"textures/bang_w/G15_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Những con số của một hành trình","text":"Nhìn lại toàn bộ dòng thời gian, có những con số đáng để dừng lại: 75 ngày đêm để đánh bại cuộc tấn công quy mô lớn đầu tiên của Pháp lên Việt Bắc; hơn sáu năm từ ngày lên chiến khu đến ngày quyết định mở chiến dịch cuối cùng; 56 ngày đêm để giành chiến thắng ở Điện Biên Phủ; và đúng chín năm, tính từ đêm rời Hà Nội tháng 12 năm 1946 đến ngày trở về tháng 10 năm 1954.\n\nGiữa những con số ấy là vô số câu chuyện nhỏ hơn: một bức điện được chuyển tay qua nhiều trạm giao liên trong đêm, một lá thư động viên gửi ra mặt trận, một quyết định phải cân nhắc giữa chắc thắng và mạo hiểm. Các bảng trưng bày khác trong gian này sẽ đưa bạn vào từng câu chuyện nhỏ ấy — nơi mỗi mốc thời gian trên đây không chỉ là một ngày tháng, mà là một con người, một quyết định, một khoảnh khắc có thật.","doc":8},{"loai":"moc","items":[["19/12/1946","Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến tại làng Vạn Phúc, Hà Đông"],["5/1947","Người đến Định Hóa (Thái Nguyên), bắt đầu những năm sống và làm việc tại An toàn khu Việt Bắc"],["7/10/1947","Quân Pháp nhảy dù xuống Bắc Kạn, Chợ Mới, Chợ Đồn, mở cuộc hành quân Léa tấn công lên Việt Bắc"],["10/1947","Người hoàn thành tác phẩm “Sửa đổi lối làm việc”, ký bút danh X.Y.Z ngay giữa những ngày chiến sự"],["30/10/1947","Chiến thắng Đèo Bông Lau trên đường số 4, một trong những trận phục kích lớn nhất chiến dịch"],["cuối 12/1947","Chiến dịch Việt Bắc thu – đông thắng lợi sau 75 ngày đêm; cơ quan đầu não kháng chiến được bảo toàn"],["11/6/1948","Người ra Lời kêu gọi thi đua ái quốc, phát động phong trào thi đua trong toàn dân, toàn quân"],["1/1950","Trung Quốc (18/1) và Liên Xô (30/1) lần lượt công nhận, đặt quan hệ ngoại giao với Việt Nam Dân chủ Cộng hòa"],["16/9/1950","Mở màn Chiến dịch Biên giới bằng trận Đông Khê; Người trực tiếp ra mặt trận quan sát, chỉ đạo"],["17/10/1950","Chiến dịch Biên giới kết thúc thắng lợi, khai thông tuyến biên giới Việt – Trung"],["11 – 19/2/1951","Đại hội đại biểu toàn quốc lần thứ II của Đảng tại Chiêm Hóa; Đảng ra hoạt động công khai với tên Đảng Lao động Việt Nam, Người được bầu làm Chủ tịch Đảng"],["11/3/1951","Báo Nhân Dân, cơ quan ngôn luận của Đảng, ra số đầu tiên ngay giữa An toàn khu"],["12/1951 – 2/1952","Chiến dịch Hòa Bình"],["10 – 12/1952","Chiến dịch Tây Bắc"],["20/11/1953","Quân Pháp nhảy dù chiếm Điện Biên Phủ, xây dựng thành tập đoàn cứ điểm mạnh"],["6/12/1953","Tại Tỉn Keo, Bộ Chính trị do Người chủ trì quyết định mở Chiến dịch Điện Biên Phủ"],["26/1/1954","Đổi phương châm tác chiến từ “đánh nhanh, thắng nhanh” sang “đánh chắc, tiến chắc”"],["1/2/1954","Anh hùng Tô Vĩnh Diện hy sinh khi lấy thân chèn pháo trong đêm kéo pháo ra"],["13/3/1954","Nổ súng mở màn Chiến dịch Điện Biên Phủ, tiến công cứ điểm Him Lam"],["7/5/1954","Chiến thắng hoàn toàn tại Điện Biên Phủ, bắt sống tướng Đờ Cát-xtơ-ri"],["21/7/1954","Hiệp định Genève về Đông Dương được ký kết, lập lại hòa bình ở Đông Dương"],["19/9/1954","Tại Đền Giếng (Khu di tích Đền Hùng, Phú Thọ), Người dặn dò Đại đoàn Quân Tiên phong trước khi về tiếp quản Thủ đô"],["10/10/1954","Giải phóng Thủ đô; trong tháng 10/1954, Người trở về Hà Nội, khép lại chín năm Việt Bắc"]],"doc":9},{"loai":"trich","text":"Các vua Hùng đã có công dựng nước, Bác cháu ta phải cùng nhau giữ lấy nước.","nguoi":"Chủ tịch Hồ Chí Minh nói với cán bộ, chiến sĩ Đại đoàn Quân Tiên phong tại Đền Giếng, 19/9/1954","nguon_ten":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011; Khu di tích lịch sử Đền Hùng","doc":10},{"loai":"anh","src":"textures/bang_w/G15_3_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Khép lại chín năm","text":"Mốc cuối cùng của dòng thời gian cũng là điểm khởi đầu của một giai đoạn mới. Tháng 10 năm 1954, Trung ương Đảng, Chính phủ và Chủ tịch Hồ Chí Minh rời chiến khu, trở về Thủ đô vừa được giải phóng. Những căn lán nứa ở Định Hóa, Sơn Dương, Chiêm Hóa dần trở thành di tích; những con đường mòn từng in dấu chân đoàn cán bộ kháng chiến trở lại với nhịp sống thường nhật của bản làng.\n\nChính khoảnh khắc chia tay đầy lưu luyến ấy đã khơi nguồn cho một trong những bài thơ nổi tiếng nhất của văn học kháng chiến: bài thơ “Việt Bắc” của Tố Hữu, viết tháng 10 năm 1954, với câu mở đầu quen thuộc với nhiều thế hệ người Việt: “Mình về mình có nhớ ta”. Dòng thời gian khép lại ở đây, nhưng câu chuyện về chín năm một dân tộc điều hành cuộc kháng chiến giữ nước từ giữa núi rừng vẫn còn được kể lại, qua từng bảng trưng bày trong gian này.","doc":11}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh (hochiminh.vn)"],"doc":[{"t":"Từ Lời kêu gọi kháng chiến đến ngày về Thủ đô: hai mươi ba mốc son ở Việt Bắc. Chín năm, hàng nghìn ngày, nhưng chỉ cần hơn hai mươi mốc thời gian là có thể dựng lại toàn bộ hành trình từ một Chính phủ vừa rời Hà Nội trong đêm đến một dân tộc làm nên chiến thắng Điện Biên Phủ. Mỗi mốc dưới đây đều gắn với một quyết định, một trận đánh hay một con người cụ thể — không có mốc nào là ngẫu nhiên."},{"t":"Hai mạch song song, một trung tâm chỉ đạo. Dòng thời gian dưới đây đi theo hai mạch song song. Mạch thứ nhất là chiến trường: từ chiến dịch Việt Bắc năm 1947 đến chiến thắng Điện Biên Phủ năm 1954. Mạch thứ hai là xây dựng: phát động thi đua ái quốc, mở rộng quan hệ ngoại giao, đưa Đảng ra hoạt động công khai, ra đời tờ báo của Đảng. Cả hai mạch đều được điều hành từ cùng một trung tâm — những căn lán nhỏ trong An toàn khu Việt Bắc. Nhìn khoảng cách giữa các mốc, có thể thấy rõ thế và lực của cuộc kháng chiến lớn dần theo từng năm: từ chỗ phải phòng ngự, bảo toàn lực lượng trong năm 1947, đến chủ động phản công năm 1950, rồi tiến tới một trận quyết chiến chiến lược mang tính định đoạt năm 1954. Đây không phải một quá trình ngẫu nhiên, mà là kết quả của một đường lối kháng chiến trường kỳ, toàn dân, toàn diện được xác định ngay từ những ngày đầu."},{"t":"1946 – 1947: giữ cho được để tồn tại. Giai đoạn mở đầu của dòng thời gian là giai đoạn khó khăn nhất: một Chính phủ non trẻ, một quân đội vừa thành lập chưa đầy hai năm, phải rời bỏ Thủ đô trong đêm để tìm đường tồn tại. Mục tiêu duy nhất lúc này là giữ cho được cơ quan đầu não và lực lượng vũ trang còn non trẻ, đồng thời xây dựng An toàn khu đủ vững chắc để trụ được lâu dài. Cuộc tấn công của thực dân Pháp vào tháng 10 năm 1947 là phép thử đầu tiên và cũng là khắc nghiệt nhất cho mục tiêu ấy (xem thêm chuyên đề “Thu – đông 1947: đòn đánh vào chiến khu thất bại”). Việc trụ vững qua 75 ngày đêm ấy không chỉ bảo toàn được lực lượng, mà còn chứng minh được với cả trong nước lẫn quốc tế rằng cuộc kháng chiến của Việt Nam không thể bị dập tắt bằng một đòn phủ đầu, dù đối phương có ưu thế vượt trội về vũ khí, phương tiện."},{"t":"Bạn có biết? Ngày 30 tháng 10 năm 1947, giữa Chiến dịch Việt Bắc thu – đông, bộ đội ta giành chiến thắng vang dội tại Đèo Bông Lau trên đường số 4, một trong những trận phục kích lớn nhất trên tuyến đường vốn được xem là huyết mạch tiếp vận của quân Pháp lên biên giới."},{"t":"1948 – 1952: xây thế và lực giữa hai trận tuyến. Qua được thử thách 1947, An toàn khu bước vào giai đoạn vừa chiến đấu vừa xây dựng thực lực trên mọi mặt. Ngày 11 tháng 6 năm 1948, Chủ tịch Hồ Chí Minh ra Lời kêu gọi thi đua ái quốc, phát động một phong trào thi đua sản xuất, chiến đấu, học tập trong toàn dân, toàn quân — nền tảng tinh thần cho cả một giai đoạn kháng chiến gian khổ còn ở phía trước. Đầu năm 1950, Trung Quốc và Liên Xô lần lượt công nhận, đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa, chấm dứt tình trạng cuộc kháng chiến phải đơn độc đối mặt với một cường quốc thực dân. Cuối năm 1950, Chiến dịch Biên giới — chiến dịch tiến công quy mô lớn đầu tiên do bộ đội chủ lực ta chủ động mở — giành thắng lợi, khai thông tuyến biên giới Việt – Trung, chấm dứt thế bao vây, cô lập của An toàn khu. Tháng 2 năm 1951, Đại hội đại biểu toàn quốc lần thứ II của Đảng họp tại Chiêm Hóa, đưa Đảng ra hoạt động công khai trở lại; chỉ ít ngày sau, Báo Nhân Dân ra số đầu tiên ngay giữa núi rừng Việt Bắc."},{"t":"1953 – 1954: dồn sức cho trận quyết chiến. Mốc cuối cùng và cũng dồn dập nhất trong toàn bộ dòng thời gian là chuỗi sự kiện dẫn tới Điện Biên Phủ. Từ quyết định mở chiến dịch tại Tỉn Keo đêm 6 tháng 12 năm 1953, đến quyết định đổi phương châm tác chiến ngày 26 tháng 1 năm 1954, rồi tiếng súng mở màn ngày 13 tháng 3, mỗi mốc chỉ cách nhau vài tuần, thậm chí vài ngày — phản ánh nhịp độ dồn dập của một chiến dịch được cả nước huy động sức người, sức của ở mức cao chưa từng có (xem thêm chuyên đề “Từ Tỉn Keo đến Điện Biên Phủ”). Chỉ trong vòng chưa đầy năm tháng, từ một quyết định được đưa ra trong một căn lán nhỏ giữa rừng cọ Định Hóa, cả dân tộc đã đi đến một chiến thắng làm chấn động thế giới. Đây là minh chứng rõ nét nhất cho việc chín năm chuẩn bị bền bỉ ở Việt Bắc — xây dựng lực lượng, củng cố hậu phương, tích lũy kinh nghiệm qua từng chiến dịch — đã hội tụ đúng thời điểm để tạo nên một trận quyết chiến chiến lược."},{"t":"Bạn có biết? Cùng thời gian diễn ra Đại hội II của Đảng, tháng 3 năm 1951, Mặt trận Việt Minh và Hội Liên Việt cũng hợp nhất thành Mặt trận Liên Việt ngay tại Việt Bắc, mở rộng thêm một bước khối đại đoàn kết toàn dân trong kháng chiến."},{"t":"Giao liên — mạch máu nối liền các mốc son. Đằng sau mỗi mốc thời gian trong bảng trên là một hệ thống ít được nhắc tới nhưng lại giữ vai trò sống còn: mạng lưới giao liên. Không có điện thoại, thư điện tử hay đường truyền hiện đại, mọi chỉ thị từ Bộ Chính trị đến Bộ Tổng tư lệnh, mọi báo cáo từ chiến trường về An toàn khu, đều phải qua đôi chân của những người giao liên, đi bộ hoặc đi ngựa xuyên rừng, có khi vượt qua cả vùng địch kiểm soát để kịp thời gian. Một chỉ thị chậm trễ vài ngày có thể làm lỡ cả một thời cơ quân sự; một bức điện lộ bí mật có thể khiến cả cơ quan đầu não gặp nguy hiểm. Chính sự vận hành âm thầm, chính xác và bền bỉ của mạng lưới giao liên ấy — cùng sự che chở của nhân dân các dân tộc Việt Bắc — đã nối liền tất cả những mốc son trên dòng thời gian này thành một chuỗi liên tục, không đứt đoạn, suốt chín năm ròng."},{"t":"Những con số của một hành trình. Nhìn lại toàn bộ dòng thời gian, có những con số đáng để dừng lại: 75 ngày đêm để đánh bại cuộc tấn công quy mô lớn đầu tiên của Pháp lên Việt Bắc; hơn sáu năm từ ngày lên chiến khu đến ngày quyết định mở chiến dịch cuối cùng; 56 ngày đêm để giành chiến thắng ở Điện Biên Phủ; và đúng chín năm, tính từ đêm rời Hà Nội tháng 12 năm 1946 đến ngày trở về tháng 10 năm 1954. Giữa những con số ấy là vô số câu chuyện nhỏ hơn: một bức điện được chuyển tay qua nhiều trạm giao liên trong đêm, một lá thư động viên gửi ra mặt trận, một quyết định phải cân nhắc giữa chắc thắng và mạo hiểm. Các bảng trưng bày khác trong gian này sẽ đưa bạn vào từng câu chuyện nhỏ ấy — nơi mỗi mốc thời gian trên đây không chỉ là một ngày tháng, mà là một con người, một quyết định, một khoảnh khắc có thật."},{"t":"Các mốc thời gian. 19/12/1946: Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến tại làng Vạn Phúc, Hà Đông. 5/1947: Người đến Định Hóa (Thái Nguyên), bắt đầu những năm sống và làm việc tại An toàn khu Việt Bắc. 7/10/1947: Quân Pháp nhảy dù xuống Bắc Kạn, Chợ Mới, Chợ Đồn, mở cuộc hành quân Léa tấn công lên Việt Bắc. 10/1947: Người hoàn thành tác phẩm “Sửa đổi lối làm việc”, ký bút danh X.Y.Z ngay giữa những ngày chiến sự. 30/10/1947: Chiến thắng Đèo Bông Lau trên đường số 4, một trong những trận phục kích lớn nhất chiến dịch. cuối 12/1947: Chiến dịch Việt Bắc thu – đông thắng lợi sau 75 ngày đêm; cơ quan đầu não kháng chiến được bảo toàn. 11/6/1948: Người ra Lời kêu gọi thi đua ái quốc, phát động phong trào thi đua trong toàn dân, toàn quân. 1/1950: Trung Quốc (18/1) và Liên Xô (30/1) lần lượt công nhận, đặt quan hệ ngoại giao với Việt Nam Dân chủ Cộng hòa. 16/9/1950: Mở màn Chiến dịch Biên giới bằng trận Đông Khê; Người trực tiếp ra mặt trận quan sát, chỉ đạo. 17/10/1950: Chiến dịch Biên giới kết thúc thắng lợi, khai thông tuyến biên giới Việt – Trung. 11 – 19/2/1951: Đại hội đại biểu toàn quốc lần thứ II của Đảng tại Chiêm Hóa; Đảng ra hoạt động công khai với tên Đảng Lao động Việt Nam, Người được bầu làm Chủ tịch Đảng. 11/3/1951: Báo Nhân Dân, cơ quan ngôn luận của Đảng, ra số đầu tiên ngay giữa An toàn khu. 12/1951 – 2/1952: Chiến dịch Hòa Bình. 10 – 12/1952: Chiến dịch Tây Bắc. 20/11/1953: Quân Pháp nhảy dù chiếm Điện Biên Phủ, xây dựng thành tập đoàn cứ điểm mạnh. 6/12/1953: Tại Tỉn Keo, Bộ Chính trị do Người chủ trì quyết định mở Chiến dịch Điện Biên Phủ. 26/1/1954: Đổi phương châm tác chiến từ “đánh nhanh, thắng nhanh” sang “đánh chắc, tiến chắc”. 1/2/1954: Anh hùng Tô Vĩnh Diện hy sinh khi lấy thân chèn pháo trong đêm kéo pháo ra. 13/3/1954: Nổ súng mở màn Chiến dịch Điện Biên Phủ, tiến công cứ điểm Him Lam. 7/5/1954: Chiến thắng hoàn toàn tại Điện Biên Phủ, bắt sống tướng Đờ Cát-xtơ-ri. 21/7/1954: Hiệp định Genève về Đông Dương được ký kết, lập lại hòa bình ở Đông Dương. 19/9/1954: Tại Đền Giếng (Khu di tích Đền Hùng, Phú Thọ), Người dặn dò Đại đoàn Quân Tiên phong trước khi về tiếp quản Thủ đô. 10/10/1954: Giải phóng Thủ đô; trong tháng 10/1954, Người trở về Hà Nội, khép lại chín năm Việt Bắc."},{"t":"Các vua Hùng đã có công dựng nước, Bác cháu ta phải cùng nhau giữ lấy nước. — Chủ tịch Hồ Chí Minh nói với cán bộ, chiến sĩ Đại đoàn Quân Tiên phong tại Đền Giếng, 19/9/1954"},{"t":"Khép lại chín năm. Mốc cuối cùng của dòng thời gian cũng là điểm khởi đầu của một giai đoạn mới. Tháng 10 năm 1954, Trung ương Đảng, Chính phủ và Chủ tịch Hồ Chí Minh rời chiến khu, trở về Thủ đô vừa được giải phóng. Những căn lán nứa ở Định Hóa, Sơn Dương, Chiêm Hóa dần trở thành di tích; những con đường mòn từng in dấu chân đoàn cán bộ kháng chiến trở lại với nhịp sống thường nhật của bản làng. Chính khoảnh khắc chia tay đầy lưu luyến ấy đã khơi nguồn cho một trong những bài thơ nổi tiếng nhất của văn học kháng chiến: bài thơ “Việt Bắc” của Tố Hữu, viết tháng 10 năm 1954, với câu mở đầu quen thuộc với nhiều thế hệ người Việt: “Mình về mình có nhớ ta”. Dòng thời gian khép lại ở đây, nhưng câu chuyện về chín năm một dân tộc điều hành cuộc kháng chiến giữ nước từ giữa núi rừng vẫn còn được kể lại, qua từng bảng trưng bày trong gian này."}],"so_chu":1489},{"i":4,"tieu_de_bang":"Với cụ Tôn Đức Thắng và Hoàng Quốc Việt, 1947","tieu_de":"Ba miền quê, một chiến khu: chuyện sau bức ảnh năm 1947 của Bác, Bác Tôn và Hoàng Quốc Việt","sapo":"Một bức ảnh không đề tên tác giả, chụp đâu đó giữa rừng núi Việt Bắc năm 1947, ghi lại ba người đàn ông đang cúi đầu bàn việc bên một chiếc bàn mộc. Không cờ hoa, không micro — chỉ có sự tập trung của những người vừa từ ba ngả đường khác nhau hội tụ về một chiến khu. Một người là Chủ tịch nước; người thứ hai vừa ra khỏi ngục tù Côn Đảo được hai năm; người thứ ba từng nếm đủ Hỏa Lò, Sơn La. Đằng sau khung hình giản dị ấy là cả một chặng đường dài của khối đại đoàn kết dân tộc.","bia":{"src":"textures/ht/ht_anh_chu_tich_ho_chi_minh_trao_doi_cong_viec_voi_dong.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một khung hình giữa núi rừng","text":"Bức ảnh không ghi tên người chụp, chỉ biết được thực hiện năm 1947, khi Trung ương Đảng và Chính phủ vừa dời lên An toàn khu Việt Bắc chưa lâu. Trong ảnh, Chủ tịch Hồ Chí Minh ngồi cùng cụ Tôn Đức Thắng và đồng chí Hoàng Quốc Việt, cả ba đang cúi xuống một tài liệu, dáng vẻ tập trung của một buổi làm việc thường nhật hơn là một cuộc gặp gỡ được sắp đặt trước. Không bàn ghế sang trọng, không phông nền chụp ảnh — chỉ một khoảng đất trống giữa rừng, mấy tấm ván kê tạm và ánh sáng tự nhiên hắt qua tán lá. Đó chính là cách làm việc phổ biến của cơ quan đầu não kháng chiến suốt những năm tháng ấy: gọn nhẹ, cơ động, sẵn sàng di chuyển bất cứ lúc nào nếu có biến. Bức ảnh về sau được xếp vào diện tư liệu công cộng, hiện lưu trong kho ảnh về Chủ tịch Hồ Chí Minh, và trở thành một trong những hình ảnh quen thuộc khi nói về tình đồng chí giữa các nhà lãnh đạo cách mạng trong những ngày đầu kháng chiến.","doc":1},{"loai":"doan","tieu_de":"Người thợ máy trở thành \"Bác Tôn\"","text":"Trong ba người có mặt trong bức ảnh, cụ Tôn Đức Thắng là người lớn tuổi nhất. Ông sinh ngày 20 tháng 8 năm 1888 tại Cù Lao Ông Hổ, làng Mỹ Hòa Hưng, tổng Định Thành, tỉnh Long Xuyên — nay thuộc thành phố Long Xuyên, tỉnh An Giang. Học nghề thợ máy tại Sài Gòn, ông sang Pháp làm việc trong những năm Chiến tranh thế giới thứ nhất, phục vụ trong lực lượng hải quân Pháp. Theo tư liệu chính thức của Đảng, năm 1919, khi hạm đội Pháp có mặt tại Biển Đen, ông đã tham gia treo cờ đỏ trên một chiến hạm để phản đối việc đưa quân can thiệp vào nước Nga Xô viết non trẻ — một chi tiết thường được nhắc tới khi kể về quãng đời hoạt động sớm của ông. Trở về Sài Gòn năm 1920, ông lập ra tổ chức công hội bí mật đầu tiên của công nhân Việt Nam, rồi năm 1925 trực tiếp vận động cuộc bãi công của thợ máy Ba Son, phản đối việc sửa chữa chiến hạm Pháp định đưa sang đàn áp cách mạng Trung Quốc. Năm 1929, ông bị bắt, bị đày ra Côn Đảo; ngay trong nhà tù, ông được kết nạp vào Đảng Cộng sản Đông Dương năm 1930. Mãi đến sau Cách mạng Tháng Tám năm 1945, ông mới được đón trở về đất liền — khi bức ảnh này được chụp, ông vừa ra tù được hai năm.","doc":2},{"loai":"doan","tieu_de":"Hoàng Quốc Việt – người chiến sĩ từ Kinh Bắc","text":"Người thứ ba trong ảnh, đồng chí Hoàng Quốc Việt, tên thật là Hạ Bá Cang, sinh năm 1905 tại Bắc Ninh — trẻ hơn cụ Tôn Đức Thắng mười bảy tuổi và trẻ hơn Bác mười lăm tuổi. Ông sớm tham gia Hội Việt Nam Cách mạng Thanh niên vào cuối những năm 1920, trở thành một trong những đảng viên lớp đầu khi Đảng Cộng sản Đông Dương ra đời năm 1930. Hoạt động cách mạng đưa ông qua nhiều nhà tù thực dân, trong đó có Hỏa Lò và Sơn La. Tháng 5 năm 1941, ông là một trong những người có mặt tại Hội nghị Trung ương lần thứ 8 ở Pác Bó (Cao Bằng), hội nghị lịch sử do lãnh tụ Nguyễn Ái Quốc chủ trì, quyết định thành lập Mặt trận Việt Minh. Gắn bó sâu sát với phong trào công nhân ngay từ những ngày đầu hoạt động, ông trở thành một trong những người đặt nền móng cho tổ chức công đoàn cách mạng Việt Nam sau này.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_chu_tich_ho_chi_minh_trao_doi_cong_viec_voi_dong.jpg","chu_thich":"Chủ tịch Hồ Chí Minh trao đổi công việc với cụ Tôn Đức Thắng và đồng chí Hoàng Quốc Việt tại An toàn khu, năm 1947.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ba miền quê, một chiến khu","text":"Nhìn vào bức ảnh, có thể thấy rõ một điều: ba con người, ba miền quê. Một người con xứ Nghệ, một người con Nam Bộ, một người con Kinh Bắc — đại diện cho ba miền đất nước — cùng ngồi lại bên nhau giữa núi rừng Việt Bắc. Đó không phải là sự trùng hợp ngẫu nhiên, mà là hình ảnh sống động của đường lối đại đoàn kết dân tộc mà Chủ tịch Hồ Chí Minh dày công xây dựng ngay từ những ngày đầu vận động cách mạng: tập hợp mọi tầng lớp, mọi vùng miền, không phân biệt quá khứ hoạt động, miễn là cùng chung một mục tiêu giành và giữ độc lập. Trong khuôn khổ Mặt trận Việt Minh rồi Hội Liên hiệp quốc dân Việt Nam (Liên Việt) thành lập năm 1946, những cuộc gặp gỡ làm việc như trong bức ảnh diễn ra thường xuyên giữa các cơ quan Trung ương đóng rải rác khắp An toàn khu, khi thì ở Định Hóa, khi lại ở Chiêm Hóa hay Sơn Dương.","doc":4},{"loai":"ban_co_biet","text":"Khi bức ảnh được chụp năm 1947, cụ Tôn Đức Thắng đã 59 tuổi, còn đồng chí Hoàng Quốc Việt mới 42 tuổi — nghĩa là cả hai đều đã có ngót hai, ba mươi năm tuổi nghề hoạt động cách mạng trước khi cùng Bác có mặt trong khung hình giản dị ấy.","nguon_ten":"Tính theo năm sinh; Tiểu sử đồng chí Tôn Đức Thắng và đồng chí Hoàng Quốc Việt – Cổng thông tin điện tử Đảng Cộng sản Việt Nam","doc":5},{"loai":"anh","src":"textures/bang_w/G15_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Với cụ Tôn Đức Thắng và Hoàng Quốc Việt, 1947”, nhìn từ xa."},{"loai":"doan","tieu_de":"Nếp làm việc giữa chiến khu","text":"Những năm ở Việt Bắc, các cơ quan lãnh đạo không có trụ sở cố định, không có lịch tiếp khách theo giờ hành chính. Việc lớn, việc nhỏ của cuộc kháng chiến phần lớn được bàn trực tiếp giữa những người đứng đầu các ngành, các mặt trận, ngay khi có dịp gặp nhau — như buổi làm việc được ghi lại trong bức ảnh này. Chủ tịch Hồ Chí Minh vẫn giữ thói quen giản dị: áo bà ba nâu hoặc bộ ka-ki bạc màu, đi dép cao su, tự tay ghi chép, không cần thư ký túc trực. Với những người đồng chí thân thiết như cụ Tôn Đức Thắng, Người vẫn gọi bằng cái tên trìu mến \"Bác Tôn\" — cách xưng hô vừa thể hiện sự kính trọng tuổi tác, vừa cho thấy mối quan hệ gần gũi, không câu nệ giữa những người cùng chung chí hướng, dù người này là Chủ tịch nước, người kia là một cán bộ mặt trận.","doc":6},{"loai":"anh","src":"textures/bang_w/G15_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Với cụ Tôn Đức Thắng và Hoàng Quốc Việt, 1947”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Con đường của cụ Tôn Đức Thắng sau bức ảnh","text":"Sau buổi làm việc được ghi lại trong bức ảnh, cụ Tôn Đức Thắng còn đi một chặng đường dài trong bộ máy lãnh đạo kháng chiến. Năm 1951, ông được bầu làm Chủ tịch Mặt trận Liên Việt, tổ chức mặt trận thống nhất từ Việt Minh và Hội Liên Việt, đúng vào thời điểm Đại hội II của Đảng cũng họp gần đó tại Chiêm Hóa (xem thêm chuyên đề về Đại hội II). Từ năm 1960, ông giữ chức Phó Chủ tịch nước Việt Nam Dân chủ Cộng hòa. Tháng 9 năm 1969, sau khi Chủ tịch Hồ Chí Minh qua đời, Quốc hội bầu ông làm Chủ tịch nước — cương vị ông đảm nhiệm cho đến khi mất ngày 30 tháng 3 năm 1980 tại Hà Nội, trở thành người kế nhiệm duy nhất giữ chức vụ này qua cả hai giai đoạn Việt Nam Dân chủ Cộng hòa và Cộng hòa Xã hội chủ nghĩa Việt Nam thống nhất.","doc":7},{"loai":"ban_co_biet","text":"Cuộc bãi công của thợ máy Ba Son tháng 8 năm 1925, do Tôn Đức Thắng vận động, phản đối việc sửa chữa chiến hạm Pháp định đưa sang đàn áp cách mạng Trung Quốc, được xem là một trong những mốc đánh dấu giai cấp công nhân Việt Nam bắt đầu đấu tranh có tổ chức, có mục tiêu chính trị rõ ràng, không còn dừng ở những đòi hỏi về tiền lương, giờ làm đơn thuần.","nguon_ten":"Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam; Tiểu sử đồng chí Tôn Đức Thắng – Cổng thông tin điện tử Đảng Cộng sản Việt Nam","doc":8},{"loai":"anh","src":"textures/bang_w/G15_4_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Với cụ Tôn Đức Thắng và Hoàng Quốc Việt, 1947”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Con đường của Hoàng Quốc Việt sau bức ảnh","text":"Đồng chí Hoàng Quốc Việt cũng tiếp tục gắn bó với phong trào công nhân và công tác mặt trận trong suốt những năm sau đó. Ông giữ chức Chủ tịch Tổng Liên đoàn Lao động Việt Nam, rồi từ năm 1960 đến năm 1976 là Viện trưởng đầu tiên của Viện Kiểm sát nhân dân tối cao — cơ quan vừa được thành lập theo Hiến pháp năm 1959. Những năm sau đó, ông tiếp tục giữ những trọng trách trong công tác mặt trận đoàn kết toàn dân cho đến cuối đời. Từ một thanh niên Kinh Bắc từng qua các nhà tù thực dân, ông đã đi trọn con đường của một cán bộ lãnh đạo cách mạng gắn bó suốt đời với công tác vận động quần chúng.","doc":9},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Bức ảnh giản dị ấy — không tên tác giả, không phông nền dàn dựng — nay là một trong những tư liệu ảnh quý được lưu giữ, trưng bày khi kể về giai đoạn Việt Bắc của cuộc kháng chiến chín năm. Tên của cả ba người có mặt trong khung hình đều được đặt cho nhiều đường phố, trường học trên khắp cả nước: từ thành phố mang tên Bác, đến những con đường Tôn Đức Thắng, Hoàng Quốc Việt ở Hà Nội, Thành phố Hồ Chí Minh và nhiều tỉnh thành khác — cách hậu thế ghi nhớ ba con người từng ngồi lại bên nhau, bàn việc nước, giữa một buổi làm việc năm 1947 ở An toàn khu Việt Bắc.","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh (hochiminh.vn)","Tiểu sử đồng chí Tôn Đức Thắng – Cổng thông tin điện tử Đảng Cộng sản Việt Nam (tulieuvankien.dangcongsan.vn)","Tiểu sử đồng chí Hoàng Quốc Việt – Cổng thông tin điện tử Đảng Cộng sản Việt Nam","Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam"],"doc":[{"t":"Ba miền quê, một chiến khu: chuyện sau bức ảnh năm 1947 của Bác, Bác Tôn và Hoàng Quốc Việt. Một bức ảnh không đề tên tác giả, chụp đâu đó giữa rừng núi Việt Bắc năm 1947, ghi lại ba người đàn ông đang cúi đầu bàn việc bên một chiếc bàn mộc. Không cờ hoa, không micro — chỉ có sự tập trung của những người vừa từ ba ngả đường khác nhau hội tụ về một chiến khu. Một người là Chủ tịch nước; người thứ hai vừa ra khỏi ngục tù Côn Đảo được hai năm; người thứ ba từng nếm đủ Hỏa Lò, Sơn La. Đằng sau khung hình giản dị ấy là cả một chặng đường dài của khối đại đoàn kết dân tộc."},{"t":"Một khung hình giữa núi rừng. Bức ảnh không ghi tên người chụp, chỉ biết được thực hiện năm 1947, khi Trung ương Đảng và Chính phủ vừa dời lên An toàn khu Việt Bắc chưa lâu. Trong ảnh, Chủ tịch Hồ Chí Minh ngồi cùng cụ Tôn Đức Thắng và đồng chí Hoàng Quốc Việt, cả ba đang cúi xuống một tài liệu, dáng vẻ tập trung của một buổi làm việc thường nhật hơn là một cuộc gặp gỡ được sắp đặt trước. Không bàn ghế sang trọng, không phông nền chụp ảnh — chỉ một khoảng đất trống giữa rừng, mấy tấm ván kê tạm và ánh sáng tự nhiên hắt qua tán lá. Đó chính là cách làm việc phổ biến của cơ quan đầu não kháng chiến suốt những năm tháng ấy: gọn nhẹ, cơ động, sẵn sàng di chuyển bất cứ lúc nào nếu có biến. Bức ảnh về sau được xếp vào diện tư liệu công cộng, hiện lưu trong kho ảnh về Chủ tịch Hồ Chí Minh, và trở thành một trong những hình ảnh quen thuộc khi nói về tình đồng chí giữa các nhà lãnh đạo cách mạng trong những ngày đầu kháng chiến."},{"t":"Người thợ máy trở thành \"Bác Tôn\". Trong ba người có mặt trong bức ảnh, cụ Tôn Đức Thắng là người lớn tuổi nhất. Ông sinh ngày 20 tháng 8 năm 1888 tại Cù Lao Ông Hổ, làng Mỹ Hòa Hưng, tổng Định Thành, tỉnh Long Xuyên — nay thuộc thành phố Long Xuyên, tỉnh An Giang. Học nghề thợ máy tại Sài Gòn, ông sang Pháp làm việc trong những năm Chiến tranh thế giới thứ nhất, phục vụ trong lực lượng hải quân Pháp. Theo tư liệu chính thức của Đảng, năm 1919, khi hạm đội Pháp có mặt tại Biển Đen, ông đã tham gia treo cờ đỏ trên một chiến hạm để phản đối việc đưa quân can thiệp vào nước Nga Xô viết non trẻ — một chi tiết thường được nhắc tới khi kể về quãng đời hoạt động sớm của ông. Trở về Sài Gòn năm 1920, ông lập ra tổ chức công hội bí mật đầu tiên của công nhân Việt Nam, rồi năm 1925 trực tiếp vận động cuộc bãi công của thợ máy Ba Son, phản đối việc sửa chữa chiến hạm Pháp định đưa sang đàn áp cách mạng Trung Quốc. Năm 1929, ông bị bắt, bị đày ra Côn Đảo; ngay trong nhà tù, ông được kết nạp vào Đảng Cộng sản Đông Dương năm 1930. Mãi đến sau Cách mạng Tháng Tám năm 1945, ông mới được đón trở về đất liền — khi bức ảnh này được chụp, ông vừa ra tù được hai năm."},{"t":"Hoàng Quốc Việt – người chiến sĩ từ Kinh Bắc. Người thứ ba trong ảnh, đồng chí Hoàng Quốc Việt, tên thật là Hạ Bá Cang, sinh năm 1905 tại Bắc Ninh — trẻ hơn cụ Tôn Đức Thắng mười bảy tuổi và trẻ hơn Bác mười lăm tuổi. Ông sớm tham gia Hội Việt Nam Cách mạng Thanh niên vào cuối những năm 1920, trở thành một trong những đảng viên lớp đầu khi Đảng Cộng sản Đông Dương ra đời năm 1930. Hoạt động cách mạng đưa ông qua nhiều nhà tù thực dân, trong đó có Hỏa Lò và Sơn La. Tháng 5 năm 1941, ông là một trong những người có mặt tại Hội nghị Trung ương lần thứ 8 ở Pác Bó (Cao Bằng), hội nghị lịch sử do lãnh tụ Nguyễn Ái Quốc chủ trì, quyết định thành lập Mặt trận Việt Minh. Gắn bó sâu sát với phong trào công nhân ngay từ những ngày đầu hoạt động, ông trở thành một trong những người đặt nền móng cho tổ chức công đoàn cách mạng Việt Nam sau này."},{"t":"Ba miền quê, một chiến khu. Nhìn vào bức ảnh, có thể thấy rõ một điều: ba con người, ba miền quê. Một người con xứ Nghệ, một người con Nam Bộ, một người con Kinh Bắc — đại diện cho ba miền đất nước — cùng ngồi lại bên nhau giữa núi rừng Việt Bắc. Đó không phải là sự trùng hợp ngẫu nhiên, mà là hình ảnh sống động của đường lối đại đoàn kết dân tộc mà Chủ tịch Hồ Chí Minh dày công xây dựng ngay từ những ngày đầu vận động cách mạng: tập hợp mọi tầng lớp, mọi vùng miền, không phân biệt quá khứ hoạt động, miễn là cùng chung một mục tiêu giành và giữ độc lập. Trong khuôn khổ Mặt trận Việt Minh rồi Hội Liên hiệp quốc dân Việt Nam (Liên Việt) thành lập năm 1946, những cuộc gặp gỡ làm việc như trong bức ảnh diễn ra thường xuyên giữa các cơ quan Trung ương đóng rải rác khắp An toàn khu, khi thì ở Định Hóa, khi lại ở Chiêm Hóa hay Sơn Dương."},{"t":"Bạn có biết? Khi bức ảnh được chụp năm 1947, cụ Tôn Đức Thắng đã 59 tuổi, còn đồng chí Hoàng Quốc Việt mới 42 tuổi — nghĩa là cả hai đều đã có ngót hai, ba mươi năm tuổi nghề hoạt động cách mạng trước khi cùng Bác có mặt trong khung hình giản dị ấy."},{"t":"Nếp làm việc giữa chiến khu. Những năm ở Việt Bắc, các cơ quan lãnh đạo không có trụ sở cố định, không có lịch tiếp khách theo giờ hành chính. Việc lớn, việc nhỏ của cuộc kháng chiến phần lớn được bàn trực tiếp giữa những người đứng đầu các ngành, các mặt trận, ngay khi có dịp gặp nhau — như buổi làm việc được ghi lại trong bức ảnh này. Chủ tịch Hồ Chí Minh vẫn giữ thói quen giản dị: áo bà ba nâu hoặc bộ ka-ki bạc màu, đi dép cao su, tự tay ghi chép, không cần thư ký túc trực. Với những người đồng chí thân thiết như cụ Tôn Đức Thắng, Người vẫn gọi bằng cái tên trìu mến \"Bác Tôn\" — cách xưng hô vừa thể hiện sự kính trọng tuổi tác, vừa cho thấy mối quan hệ gần gũi, không câu nệ giữa những người cùng chung chí hướng, dù người này là Chủ tịch nước, người kia là một cán bộ mặt trận."},{"t":"Con đường của cụ Tôn Đức Thắng sau bức ảnh. Sau buổi làm việc được ghi lại trong bức ảnh, cụ Tôn Đức Thắng còn đi một chặng đường dài trong bộ máy lãnh đạo kháng chiến. Năm 1951, ông được bầu làm Chủ tịch Mặt trận Liên Việt, tổ chức mặt trận thống nhất từ Việt Minh và Hội Liên Việt, đúng vào thời điểm Đại hội II của Đảng cũng họp gần đó tại Chiêm Hóa (xem thêm chuyên đề về Đại hội II). Từ năm 1960, ông giữ chức Phó Chủ tịch nước Việt Nam Dân chủ Cộng hòa. Tháng 9 năm 1969, sau khi Chủ tịch Hồ Chí Minh qua đời, Quốc hội bầu ông làm Chủ tịch nước — cương vị ông đảm nhiệm cho đến khi mất ngày 30 tháng 3 năm 1980 tại Hà Nội, trở thành người kế nhiệm duy nhất giữ chức vụ này qua cả hai giai đoạn Việt Nam Dân chủ Cộng hòa và Cộng hòa Xã hội chủ nghĩa Việt Nam thống nhất."},{"t":"Bạn có biết? Cuộc bãi công của thợ máy Ba Son tháng 8 năm 1925, do Tôn Đức Thắng vận động, phản đối việc sửa chữa chiến hạm Pháp định đưa sang đàn áp cách mạng Trung Quốc, được xem là một trong những mốc đánh dấu giai cấp công nhân Việt Nam bắt đầu đấu tranh có tổ chức, có mục tiêu chính trị rõ ràng, không còn dừng ở những đòi hỏi về tiền lương, giờ làm đơn thuần."},{"t":"Con đường của Hoàng Quốc Việt sau bức ảnh. Đồng chí Hoàng Quốc Việt cũng tiếp tục gắn bó với phong trào công nhân và công tác mặt trận trong suốt những năm sau đó. Ông giữ chức Chủ tịch Tổng Liên đoàn Lao động Việt Nam, rồi từ năm 1960 đến năm 1976 là Viện trưởng đầu tiên của Viện Kiểm sát nhân dân tối cao — cơ quan vừa được thành lập theo Hiến pháp năm 1959. Những năm sau đó, ông tiếp tục giữ những trọng trách trong công tác mặt trận đoàn kết toàn dân cho đến cuối đời. Từ một thanh niên Kinh Bắc từng qua các nhà tù thực dân, ông đã đi trọn con đường của một cán bộ lãnh đạo cách mạng gắn bó suốt đời với công tác vận động quần chúng."},{"t":"Dấu tích hôm nay. Bức ảnh giản dị ấy — không tên tác giả, không phông nền dàn dựng — nay là một trong những tư liệu ảnh quý được lưu giữ, trưng bày khi kể về giai đoạn Việt Bắc của cuộc kháng chiến chín năm. Tên của cả ba người có mặt trong khung hình đều được đặt cho nhiều đường phố, trường học trên khắp cả nước: từ thành phố mang tên Bác, đến những con đường Tôn Đức Thắng, Hoàng Quốc Việt ở Hà Nội, Thành phố Hồ Chí Minh và nhiều tỉnh thành khác — cách hậu thế ghi nhớ ba con người từng ngồi lại bên nhau, bàn việc nước, giữa một buổi làm việc năm 1947 ở An toàn khu Việt Bắc."}],"so_chu":1638},{"i":5,"tieu_de_bang":"Người với cán bộ Hội Phụ nữ tại Việt Bắc, tháng 2/1949","tieu_de":"\"Bất kỳ đàn ông, đàn bà\": Người và những nữ cán bộ giữa chiến khu","sapo":"Tháng 2 năm 1949, ống kính vô tình ghi lại một buổi gặp gỡ giữa núi rừng: Chủ tịch Hồ Chí Minh ngồi cùng mấy cán bộ Hội Phụ nữ, không cờ hoa, không khẩu hiệu. Nhưng đằng sau khung hình bình dị ấy là một chặng đường dài, bắt đầu từ một bản Hiến pháp ghi rằng đàn bà ngang quyền đàn ông, tiếp nối bằng những đoàn thể phụ nữ ra đời ngay giữa khói lửa. Cuộc kháng chiến chín năm, hóa ra, cũng là câu chuyện của hàng vạn người mẹ, người chị chưa từng cầm súng.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_and_vietnam_women_union_s_cadres_at_.jpg","credit":"Ảnh: Musée Annam · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Bức ảnh giữa năm thứ ba kháng chiến","text":"Bức ảnh được ghi chú chụp tại Việt Bắc vào tháng 2 năm 1949, khi cuộc kháng chiến toàn quốc đã bước sang năm thứ ba. Trong ảnh, Chủ tịch Hồ Chí Minh ngồi giữa một nhóm cán bộ nữ của Hội Phụ nữ, tất cả đều mặc trang phục giản dị của người hoạt động ở chiến khu — áo bà ba, khăn vấn tóc, không có gì phân biệt họ với những phụ nữ nông thôn miền núi khác, ngoài ánh mắt và tư thế của những người đang làm việc, đang báo cáo, đang trao đổi công việc với vị lãnh tụ của cuộc kháng chiến. Theo ghi chú lưu trữ đi kèm, tư liệu này từng gắn với tên một cơ sở lưu giữ ảnh mang tên \"Musée Annam\" — chi tiết cho thấy tấm ảnh đã có một hành trình lưu giữ, luân chuyển qua nhiều kho tư liệu trước khi trở thành một trong những hình ảnh đời thường hiếm hoi về Người giữa những năm kháng chiến gian khổ nhất.\n\nKhông giống những bức ảnh nghi lễ, trang trọng, khung hình này gần như không có bố cục dàn dựng: người ngồi, người đứng, có người còn nhìn nghiêng, tay vẫn đang cầm giấy tờ hoặc túi vải đựng tài liệu công tác. Chính sự thiếu vắng tính trình diễn ấy lại khiến bức ảnh trở nên quý — nó ghi lại một lát cắt rất thật của đời sống chính trị kháng chiến, nơi người đứng đầu nhà nước có thể ngồi xổm hoặc ngồi bệt trên nền đất cùng những cán bộ cấp cơ sở, không khoảng cách, không nghi thức.","doc":1},{"loai":"doan","tieu_de":"Lời hiệu triệu không phân biệt nam nữ","text":"Ngay trong Lời kêu gọi toàn quốc kháng chiến, phát đi đêm 19 tháng 12 năm 1946, Chủ tịch Hồ Chí Minh đã nói rõ: \"Bất kỳ đàn ông, đàn bà, bất kỳ người già, người trẻ, không chia tôn giáo, đảng phái, dân tộc. Hễ là người Việt Nam thì phải đứng lên đánh thực dân Pháp để cứu Tổ quốc.\" Đó không phải một câu nói ngẫu hứng. Trước đó, Hiến pháp năm 1946 — bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa, do Ban dự thảo đứng đầu là Chủ tịch Hồ Chí Minh soạn thảo và được Quốc hội khóa I thông qua ngày 9 tháng 11 năm 1946 — đã ghi thành điều khoản: \"Đàn bà ngang quyền với đàn ông về mọi phương diện.\" Từ một bản hiến văn đến một lời hiệu triệu giữa chiến tranh, quan điểm về vai trò của phụ nữ trong sự nghiệp cứu nước được đặt ra rành mạch, nhất quán ngay từ những ngày đầu lập quốc.","doc":2},{"loai":"doan","tieu_de":"Từ Phụ nữ Cứu quốc đến Hội Liên hiệp Phụ nữ","text":"Trong Mặt trận Việt Minh, thành lập năm 1941, một trong những đoàn thể cứu quốc ra đời sớm nhất là Đoàn Phụ nữ Cứu quốc, chính thức thành lập ngày 16 tháng 6 năm 1941, tập hợp chị em phụ nữ tham gia phong trào cách mạng rồi kháng chiến. Sau ngày độc lập, tổ chức này được kiện toàn: ngày 3 tháng 10 năm 1946, Bộ trưởng Bộ Nội vụ Huỳnh Thúc Kháng ký Nghị định cho phép thành lập Hội Liên hiệp Phụ nữ Việt Nam; ngày 20 tháng 10 năm 1946, Hội làm lễ ra mắt tại Quảng trường Nhà hát Lớn Hà Nội. Khi cuộc kháng chiến toàn quốc bùng nổ hai tháng sau đó, Hội Liên hiệp Phụ nữ Việt Nam cùng cơ quan Trung ương chuyển lên Việt Bắc, tiếp tục hoạt động xuyên suốt những năm chiến khu — trong đó có buổi gặp gỡ được ghi lại trong bức ảnh tháng 2/1949 này.\n\nTừ một tổ chức mới ra mắt giữa lòng Hà Nội chỉ hai tháng trước khi kháng chiến bùng nổ, Hội phải nhanh chóng thích nghi với đời sống chiến khu: không trụ sở cố định, không phương tiện in ấn hiện đại, chủ yếu hoạt động qua mạng lưới cán bộ cơ sở len lỏi khắp các bản làng. Chính trong hoàn cảnh ấy, những buổi làm việc trực tiếp giữa lãnh đạo Hội với Chủ tịch Hồ Chí Minh — như buổi gặp được ghi lại trong bức ảnh — càng có ý nghĩa: đó là dịp để nắm bắt chủ trương từ Trung ương, đồng thời báo cáo trực tiếp những khó khăn, sáng kiến từ cơ sở lên cấp lãnh đạo cao nhất.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_and_vietnam_women_union_s_cadres_at_.jpg","chu_thich":"Chủ tịch Hồ Chí Minh với cán bộ Hội Phụ nữ tại Việt Bắc, tháng 2/1949.","credit":"Ảnh: Musée Annam · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những người giữ hậu phương","text":"Trong những năm ở Việt Bắc, phụ nữ các dân tộc Tày, Nùng, Dao, Kinh... là lực lượng đông đảo nhất của hậu phương kháng chiến. Họ tăng gia sản xuất để nuôi bộ đội và cơ quan Trung ương, góp gạo, đi dân công hỏa tuyến vận chuyển lương thực, đạn dược ra mặt trận bằng quang gánh, bằng xe đạp thồ; nhiều người làm giao liên, tham gia du kích bảo vệ làng bản, canh gác cho các cơ quan đầu não di chuyển an toàn. Chính những chị em đồng bào các dân tộc thiểu số ở An toàn khu đã cưu mang, nuôi giấu cán bộ, giữ bí mật tuyệt đối suốt nhiều năm cho một bộ máy lãnh đạo phải hoạt động ngay trong vùng địch có thể đánh chiếm. Cán bộ Hội Phụ nữ trong bức ảnh là đại diện cho lực lượng ấy: những người tổ chức, vận động, hướng dẫn chị em ở khắp các bản làng tham gia kháng chiến theo cách của riêng mình.","doc":4},{"loai":"anh","src":"textures/bang_w/G15_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Người với cán bộ Hội Phụ nữ tại Việt Bắc, tháng 2/1949”, nhìn từ xa."},{"loai":"doan","tieu_de":"Tấm gương từ Tổng tuyển cử","text":"Ngày 6 tháng 1 năm 1946, trong cuộc Tổng tuyển cử đầu tiên của nước Việt Nam Dân chủ Cộng hòa, phụ nữ Việt Nam lần đầu tiên trong lịch sử được đi bầu cử và ứng cử ngang quyền với nam giới. Quốc hội khóa I có những nữ đại biểu đầu tiên trong lịch sử lập hiến, lập pháp của đất nước. Đó là nền tảng pháp lý và tinh thần để chỉ ba năm sau, khi bức ảnh này được chụp, những cán bộ Hội Phụ nữ đã có mặt bên cạnh vị Chủ tịch nước không phải với tư cách khách mời, mà với tư cách những người đang trực tiếp gánh vác một phần công việc kháng chiến, kiến quốc.","doc":5},{"loai":"ban_co_biet","text":"Câu thơ \"Nhớ người mẹ nắng cháy lưng\" trích dưới đây nằm trong bài \"Việt Bắc\" của Tố Hữu, sáng tác năm 1954 khi ông cùng đoàn cán bộ rời chiến khu về tiếp quản Thủ đô — một trong những áng thơ tiêu biểu nhất viết về tình quân dân thời kháng chiến chống Pháp.","nguon_ten":"Tố Hữu – bài thơ \"Việt Bắc\", 1954","doc":6},{"loai":"ban_co_biet","text":"Hiến pháp năm 1946 được Quốc hội khóa I thông qua ngày 9 tháng 11 năm 1946, chỉ hơn một tháng trước khi toàn quốc kháng chiến bùng nổ — là bản hiến pháp đầu tiên trong lịch sử Việt Nam ghi thành điều khoản riêng về quyền bình đẳng nam nữ.","nguon_ten":"Hiến pháp nước Việt Nam Dân chủ Cộng hòa năm 1946","doc":7},{"loai":"anh","src":"textures/bang_w/G15_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Người với cán bộ Hội Phụ nữ tại Việt Bắc, tháng 2/1949”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Khi người mẹ chiến khu bước vào thơ ca","text":"Hình ảnh những người mẹ, người chị ở hậu phương Việt Bắc không chỉ được ghi lại bằng ảnh mà còn đi vào thơ ca kháng chiến. Nhà thơ Tố Hữu, người gắn bó nhiều năm với chiến khu Việt Bắc, đã khắc họa hình ảnh ấy trong bài thơ \"Việt Bắc\" sáng tác năm 1954, khi đoàn cán bộ kháng chiến rời chiến khu về tiếp quản Thủ đô. Những câu thơ giản dị về người mẹ địu con lên rẫy, về bàn tay cần mẫn giữa nương ngô, nương sắn, đã trở thành một trong những hình ảnh tiêu biểu nhất khi hậu thế nhớ về vai trò thầm lặng của phụ nữ Việt Bắc trong suốt chín năm kháng chiến.","doc":8},{"loai":"trich","text":"Nhớ người mẹ nắng cháy lưng, Địu con lên rẫy bẻ từng bắp ngô.","nguoi":"Tố Hữu, bài thơ \"Việt Bắc\" (1954)","nguon_ten":"Tố Hữu – bài thơ \"Việt Bắc\", 1954","doc":9},{"loai":"anh","src":"textures/bang_w/G15_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Người với cán bộ Hội Phụ nữ tại Việt Bắc, tháng 2/1949”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Không chỉ là hậu phương","text":"Gọi những cán bộ, hội viên Hội Phụ nữ Việt Bắc là \"hậu phương\" đôi khi chưa nói hết vai trò của họ. Nhiều chị em trực tiếp góp sức vào các chiến dịch lớn — Việt Bắc thu đông 1947, Biên giới 1950 — bằng vai trò dân công hỏa tuyến, y tá, giao liên; một số người sau này trở thành cán bộ lãnh đạo Hội ở cấp trung ương, cấp tỉnh, tiếp tục công tác vận động phụ nữ nhiều năm sau ngày hòa bình lập lại. Bức ảnh tháng 2/1949, vì vậy, không chỉ là một khoảnh khắc đời thường của Chủ tịch Hồ Chí Minh, mà còn là một lát cắt hiếm hoi ghi lại chân dung của chính những người phụ nữ ấy — những gương mặt phần lớn không được sử sách nhắc tên, nhưng đã góp phần làm nên chiến thắng chung của cả dân tộc.\n\nỞ một khía cạnh khác, chính đội ngũ cán bộ Hội Phụ nữ cũng là cầu nối đưa các chủ trương lớn của kháng chiến — từ tăng gia sản xuất, bình dân học vụ, đến vận động nuôi quân — đến từng nếp nhà, từng bản làng xa xôi nhất. Không có mạng lưới ấy, nhiều chính sách của Chính phủ kháng chiến khó có thể chạm tới đời sống của đồng bào các dân tộc thiểu số ở vùng sâu, vùng xa quanh An toàn khu.","doc":10},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, Hội Liên hiệp Phụ nữ Việt Nam — tổ chức mà những cán bộ trong bức ảnh từng là một phần — vẫn tiếp tục hoạt động liên tục từ khi ra mắt năm 1946 cho đến nay, với hệ thống tổ chức trải khắp các tỉnh, thành, xuống tận thôn bản. Bức ảnh tháng 2/1949 cùng nhiều tư liệu khác về những năm Việt Bắc được lưu giữ, trưng bày tại các bảo tàng, khu di tích liên quan đến Chủ tịch Hồ Chí Minh, nhắc nhớ một chặng đường mà độc lập dân tộc và bình đẳng nam nữ đã cùng được đặt nền móng ngay giữa những năm tháng gian khó nhất của đất nước. Với khách tham quan hôm nay, đó là một trong những lời nhắc nhở giản dị nhưng bền vững nhất về những gương mặt phụ nữ vô danh từng góp phần làm nên chiến thắng chung của cả một dân tộc.","doc":11}],"nguon":["Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","Hiến pháp nước Việt Nam Dân chủ Cộng hòa năm 1946","Tố Hữu – bài thơ \"Việt Bắc\" (1954)","Quốc hội Việt Nam – Lịch sử Quốc hội khóa I","Hội Liên hiệp Phụ nữ Việt Nam – các dấu mốc lịch sử (hoilhpn.org.vn)"],"doc":[{"t":"\"Bất kỳ đàn ông, đàn bà\": Người và những nữ cán bộ giữa chiến khu. Tháng 2 năm 1949, ống kính vô tình ghi lại một buổi gặp gỡ giữa núi rừng: Chủ tịch Hồ Chí Minh ngồi cùng mấy cán bộ Hội Phụ nữ, không cờ hoa, không khẩu hiệu. Nhưng đằng sau khung hình bình dị ấy là một chặng đường dài, bắt đầu từ một bản Hiến pháp ghi rằng đàn bà ngang quyền đàn ông, tiếp nối bằng những đoàn thể phụ nữ ra đời ngay giữa khói lửa. Cuộc kháng chiến chín năm, hóa ra, cũng là câu chuyện của hàng vạn người mẹ, người chị chưa từng cầm súng."},{"t":"Bức ảnh giữa năm thứ ba kháng chiến. Bức ảnh được ghi chú chụp tại Việt Bắc vào tháng 2 năm 1949, khi cuộc kháng chiến toàn quốc đã bước sang năm thứ ba. Trong ảnh, Chủ tịch Hồ Chí Minh ngồi giữa một nhóm cán bộ nữ của Hội Phụ nữ, tất cả đều mặc trang phục giản dị của người hoạt động ở chiến khu — áo bà ba, khăn vấn tóc, không có gì phân biệt họ với những phụ nữ nông thôn miền núi khác, ngoài ánh mắt và tư thế của những người đang làm việc, đang báo cáo, đang trao đổi công việc với vị lãnh tụ của cuộc kháng chiến. Theo ghi chú lưu trữ đi kèm, tư liệu này từng gắn với tên một cơ sở lưu giữ ảnh mang tên \"Musée Annam\" — chi tiết cho thấy tấm ảnh đã có một hành trình lưu giữ, luân chuyển qua nhiều kho tư liệu trước khi trở thành một trong những hình ảnh đời thường hiếm hoi về Người giữa những năm kháng chiến gian khổ nhất. Không giống những bức ảnh nghi lễ, trang trọng, khung hình này gần như không có bố cục dàn dựng: người ngồi, người đứng, có người còn nhìn nghiêng, tay vẫn đang cầm giấy tờ hoặc túi vải đựng tài liệu công tác. Chính sự thiếu vắng tính trình diễn ấy lại khiến bức ảnh trở nên quý — nó ghi lại một lát cắt rất thật của đời sống chính trị kháng chiến, nơi người đứng đầu nhà nước có thể ngồi xổm hoặc ngồi bệt trên nền đất cùng những cán bộ cấp cơ sở, không khoảng cách, không nghi thức."},{"t":"Lời hiệu triệu không phân biệt nam nữ. Ngay trong Lời kêu gọi toàn quốc kháng chiến, phát đi đêm 19 tháng 12 năm 1946, Chủ tịch Hồ Chí Minh đã nói rõ: \"Bất kỳ đàn ông, đàn bà, bất kỳ người già, người trẻ, không chia tôn giáo, đảng phái, dân tộc. Hễ là người Việt Nam thì phải đứng lên đánh thực dân Pháp để cứu Tổ quốc.\" Đó không phải một câu nói ngẫu hứng. Trước đó, Hiến pháp năm 1946 — bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa, do Ban dự thảo đứng đầu là Chủ tịch Hồ Chí Minh soạn thảo và được Quốc hội khóa I thông qua ngày 9 tháng 11 năm 1946 — đã ghi thành điều khoản: \"Đàn bà ngang quyền với đàn ông về mọi phương diện.\" Từ một bản hiến văn đến một lời hiệu triệu giữa chiến tranh, quan điểm về vai trò của phụ nữ trong sự nghiệp cứu nước được đặt ra rành mạch, nhất quán ngay từ những ngày đầu lập quốc."},{"t":"Từ Phụ nữ Cứu quốc đến Hội Liên hiệp Phụ nữ. Trong Mặt trận Việt Minh, thành lập năm 1941, một trong những đoàn thể cứu quốc ra đời sớm nhất là Đoàn Phụ nữ Cứu quốc, chính thức thành lập ngày 16 tháng 6 năm 1941, tập hợp chị em phụ nữ tham gia phong trào cách mạng rồi kháng chiến. Sau ngày độc lập, tổ chức này được kiện toàn: ngày 3 tháng 10 năm 1946, Bộ trưởng Bộ Nội vụ Huỳnh Thúc Kháng ký Nghị định cho phép thành lập Hội Liên hiệp Phụ nữ Việt Nam; ngày 20 tháng 10 năm 1946, Hội làm lễ ra mắt tại Quảng trường Nhà hát Lớn Hà Nội. Khi cuộc kháng chiến toàn quốc bùng nổ hai tháng sau đó, Hội Liên hiệp Phụ nữ Việt Nam cùng cơ quan Trung ương chuyển lên Việt Bắc, tiếp tục hoạt động xuyên suốt những năm chiến khu — trong đó có buổi gặp gỡ được ghi lại trong bức ảnh tháng 2/1949 này. Từ một tổ chức mới ra mắt giữa lòng Hà Nội chỉ hai tháng trước khi kháng chiến bùng nổ, Hội phải nhanh chóng thích nghi với đời sống chiến khu: không trụ sở cố định, không phương tiện in ấn hiện đại, chủ yếu hoạt động qua mạng lưới cán bộ cơ sở len lỏi khắp các bản làng. Chính trong hoàn cảnh ấy, những buổi làm việc trực tiếp giữa lãnh đạo Hội với Chủ tịch Hồ Chí Minh — như buổi gặp được ghi lại trong bức ảnh — càng có ý nghĩa: đó là dịp để nắm bắt chủ trương từ Trung ương, đồng thời báo cáo trực tiếp những khó khăn, sáng kiến từ cơ sở lên cấp lãnh đạo cao nhất."},{"t":"Những người giữ hậu phương. Trong những năm ở Việt Bắc, phụ nữ các dân tộc Tày, Nùng, Dao, Kinh... là lực lượng đông đảo nhất của hậu phương kháng chiến. Họ tăng gia sản xuất để nuôi bộ đội và cơ quan Trung ương, góp gạo, đi dân công hỏa tuyến vận chuyển lương thực, đạn dược ra mặt trận bằng quang gánh, bằng xe đạp thồ; nhiều người làm giao liên, tham gia du kích bảo vệ làng bản, canh gác cho các cơ quan đầu não di chuyển an toàn. Chính những chị em đồng bào các dân tộc thiểu số ở An toàn khu đã cưu mang, nuôi giấu cán bộ, giữ bí mật tuyệt đối suốt nhiều năm cho một bộ máy lãnh đạo phải hoạt động ngay trong vùng địch có thể đánh chiếm. Cán bộ Hội Phụ nữ trong bức ảnh là đại diện cho lực lượng ấy: những người tổ chức, vận động, hướng dẫn chị em ở khắp các bản làng tham gia kháng chiến theo cách của riêng mình."},{"t":"Tấm gương từ Tổng tuyển cử. Ngày 6 tháng 1 năm 1946, trong cuộc Tổng tuyển cử đầu tiên của nước Việt Nam Dân chủ Cộng hòa, phụ nữ Việt Nam lần đầu tiên trong lịch sử được đi bầu cử và ứng cử ngang quyền với nam giới. Quốc hội khóa I có những nữ đại biểu đầu tiên trong lịch sử lập hiến, lập pháp của đất nước. Đó là nền tảng pháp lý và tinh thần để chỉ ba năm sau, khi bức ảnh này được chụp, những cán bộ Hội Phụ nữ đã có mặt bên cạnh vị Chủ tịch nước không phải với tư cách khách mời, mà với tư cách những người đang trực tiếp gánh vác một phần công việc kháng chiến, kiến quốc."},{"t":"Bạn có biết? Câu thơ \"Nhớ người mẹ nắng cháy lưng\" trích dưới đây nằm trong bài \"Việt Bắc\" của Tố Hữu, sáng tác năm 1954 khi ông cùng đoàn cán bộ rời chiến khu về tiếp quản Thủ đô — một trong những áng thơ tiêu biểu nhất viết về tình quân dân thời kháng chiến chống Pháp."},{"t":"Bạn có biết? Hiến pháp năm 1946 được Quốc hội khóa I thông qua ngày 9 tháng 11 năm 1946, chỉ hơn một tháng trước khi toàn quốc kháng chiến bùng nổ — là bản hiến pháp đầu tiên trong lịch sử Việt Nam ghi thành điều khoản riêng về quyền bình đẳng nam nữ."},{"t":"Khi người mẹ chiến khu bước vào thơ ca. Hình ảnh những người mẹ, người chị ở hậu phương Việt Bắc không chỉ được ghi lại bằng ảnh mà còn đi vào thơ ca kháng chiến. Nhà thơ Tố Hữu, người gắn bó nhiều năm với chiến khu Việt Bắc, đã khắc họa hình ảnh ấy trong bài thơ \"Việt Bắc\" sáng tác năm 1954, khi đoàn cán bộ kháng chiến rời chiến khu về tiếp quản Thủ đô. Những câu thơ giản dị về người mẹ địu con lên rẫy, về bàn tay cần mẫn giữa nương ngô, nương sắn, đã trở thành một trong những hình ảnh tiêu biểu nhất khi hậu thế nhớ về vai trò thầm lặng của phụ nữ Việt Bắc trong suốt chín năm kháng chiến."},{"t":"Nhớ người mẹ nắng cháy lưng, Địu con lên rẫy bẻ từng bắp ngô. — Tố Hữu, bài thơ \"Việt Bắc\" (1954)"},{"t":"Không chỉ là hậu phương. Gọi những cán bộ, hội viên Hội Phụ nữ Việt Bắc là \"hậu phương\" đôi khi chưa nói hết vai trò của họ. Nhiều chị em trực tiếp góp sức vào các chiến dịch lớn — Việt Bắc thu đông 1947, Biên giới 1950 — bằng vai trò dân công hỏa tuyến, y tá, giao liên; một số người sau này trở thành cán bộ lãnh đạo Hội ở cấp trung ương, cấp tỉnh, tiếp tục công tác vận động phụ nữ nhiều năm sau ngày hòa bình lập lại. Bức ảnh tháng 2/1949, vì vậy, không chỉ là một khoảnh khắc đời thường của Chủ tịch Hồ Chí Minh, mà còn là một lát cắt hiếm hoi ghi lại chân dung của chính những người phụ nữ ấy — những gương mặt phần lớn không được sử sách nhắc tên, nhưng đã góp phần làm nên chiến thắng chung của cả dân tộc. Ở một khía cạnh khác, chính đội ngũ cán bộ Hội Phụ nữ cũng là cầu nối đưa các chủ trương lớn của kháng chiến — từ tăng gia sản xuất, bình dân học vụ, đến vận động nuôi quân — đến từng nếp nhà, từng bản làng xa xôi nhất. Không có mạng lưới ấy, nhiều chính sách của Chính phủ kháng chiến khó có thể chạm tới đời sống của đồng bào các dân tộc thiểu số ở vùng sâu, vùng xa quanh An toàn khu."},{"t":"Dấu tích hôm nay. Ngày nay, Hội Liên hiệp Phụ nữ Việt Nam — tổ chức mà những cán bộ trong bức ảnh từng là một phần — vẫn tiếp tục hoạt động liên tục từ khi ra mắt năm 1946 cho đến nay, với hệ thống tổ chức trải khắp các tỉnh, thành, xuống tận thôn bản. Bức ảnh tháng 2/1949 cùng nhiều tư liệu khác về những năm Việt Bắc được lưu giữ, trưng bày tại các bảo tàng, khu di tích liên quan đến Chủ tịch Hồ Chí Minh, nhắc nhớ một chặng đường mà độc lập dân tộc và bình đẳng nam nữ đã cùng được đặt nền móng ngay giữa những năm tháng gian khó nhất của đất nước. Với khách tham quan hôm nay, đó là một trong những lời nhắc nhở giản dị nhưng bền vững nhất về những gương mặt phụ nữ vô danh từng góp phần làm nên chiến thắng chung của cả một dân tộc."}],"so_chu":1791},{"i":6,"tieu_de_bang":"Quan sát mặt trận Đông Khê, Chiến dịch Biên giới 1950","tieu_de":"\"Chống gậy lên non xem trận địa\": Người ở mặt trận Đông Khê","sapo":"Rạng sáng 16 tháng 9 năm 1950, một người đàn ông chống gậy trèo lên đỉnh núi Báo Đông, giữa biên giới Việt – Trung, để tận mắt theo dõi trận đánh mở màn một chiến dịch lớn. Người đó là Chủ tịch nước. Bức ảnh chụp khoảnh khắc ấy, cùng bài thơ chữ Hán Người viết ngay trong chiến dịch, đã trở thành một trong những hình ảnh khắc họa rõ nhất tinh thần của cuộc kháng chiến chống Pháp giữa lúc chuyển sang thế chủ động tiến công.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_in_dong_khe_1950.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Vì sao phải mở Chiến dịch Biên giới","text":"Đến năm 1950, thực dân Pháp tăng cường khóa chặt tuyến biên giới Việt – Trung bằng một hệ thống cứ điểm quân sự dọc Đường số 4 — từ Cao Bằng, Đông Khê, Thất Khê đến Lạng Sơn — nhằm cô lập hoàn toàn căn cứ địa Việt Bắc với thế giới bên ngoài. Trong khi đó, cục diện quốc tế đang chuyển động có lợi cho cách mạng Việt Nam: cách mạng Trung Quốc thắng lợi cuối năm 1949, rồi lần lượt Trung Quốc, Liên Xô và các nước xã hội chủ nghĩa công nhận, đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa đầu năm 1950. Tháng 6 năm 1950, Trung ương Đảng và Chính phủ quyết định mở Chiến dịch Biên giới nhằm tiêu diệt một bộ phận quan trọng sinh lực địch, khai thông đường liên lạc quốc tế, đồng thời mở rộng và củng cố căn cứ địa Việt Bắc.\n\nĐây là lần đầu tiên quân đội Việt Nam có điều kiện chuẩn bị một chiến dịch tiến công quy mô lớn với sự phối hợp của nhiều đại đoàn chủ lực, thay vì chỉ đánh nhỏ lẻ, phân tán như những năm đầu kháng chiến. Bộ Tổng tư lệnh, đứng đầu là Đại tướng Võ Nguyên Giáp, trực tiếp xây dựng kế hoạch tác chiến; còn Chủ tịch Hồ Chí Minh, với tư cách người đứng đầu Đảng và Nhà nước, theo dõi sát từng bước chuẩn bị, từ hậu cần, dân công đến tinh thần bộ đội trước giờ nổ súng.","doc":1},{"loai":"doan","tieu_de":"Người ra mặt trận","text":"Đây là chiến dịch tiến công quy mô lớn đầu tiên do bộ đội chủ lực Việt Nam chủ động hoạch định và mở màn — khác hẳn những chiến dịch trước đó vốn mang tính phản công, chống càn. Chủ tịch Hồ Chí Minh trực tiếp ra mặt trận theo dõi diễn biến, một điều hiếm khi xảy ra với một vị Chủ tịch nước giữa thời chiến. Rạng sáng ngày 16 tháng 9 năm 1950, Người được đưa lên một đài quan sát dựng trên đỉnh núi để theo dõi trận đánh mở màn vào cứ điểm Đông Khê. Cùng có mặt tại đài quan sát hôm ấy là các cán bộ chỉ huy chiến dịch và đội cận vệ bảo vệ Người. Ngày 18 tháng 9, sau hai ngày chiến đấu ác liệt, Đông Khê được giải phóng — trận mở màn thắng lợi, tạo đà cho toàn bộ chiến dịch. Việc một vị đứng đầu Nhà nước trực tiếp có mặt sát cạnh mặt trận, giữa lúc bom đạn còn chưa dứt, tự nó đã là một nguồn cổ vũ tinh thần to lớn cho cán bộ, chiến sĩ đang tham gia trận đánh mở màn đầy cam go này.","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_in_dong_khe_1950.jpg","chu_thich":"Chủ tịch Hồ Chí Minh quan sát mặt trận Đông Khê trong Chiến dịch Biên giới, năm 1950.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Đài quan sát trên núi Báo Đông","text":"Vị trí Người đứng quan sát trận đánh hôm ấy là đỉnh núi Báo Đông, thuộc xóm Bản Pò, xã Đức Long, huyện Thạch An, tỉnh Cao Bằng — một điểm cao nhìn thẳng xuống cứ điểm Đông Khê. Bức ảnh nổi tiếng ghi lại khoảnh khắc này do nhiếp ảnh gia Vũ Năng An thực hiện. Từ đài quan sát dã chiến ấy, Người theo dõi từng diễn biến của trận đánh, giữa tiếng đại bác và không khí căng thẳng của một trận mở màn có ý nghĩa quyết định. Hình ảnh vị Chủ tịch nước chống gậy, đứng lặng lẽ quan sát trận địa giữa núi rừng biên giới về sau trở thành một trong những bức ảnh được biết đến rộng rãi nhất về Người trong vai trò gắn bó trực tiếp với mặt trận.\n\nCùng có mặt tại đài quan sát hôm ấy, theo tư liệu còn lưu lại, có đồng chí Phạm Chước — trưởng đài quan sát, đồng chí Võ Viết Định — đội trưởng đội cận vệ bảo vệ Người, cùng một học viên Trường Lục quân và một số cán bộ Bộ chỉ huy chiến dịch. Không có phóng viên chiến trường đông đảo, không có buổi \"dàn dựng\" nào; bức ảnh vì vậy mang đúng chất một khoảnh khắc chiến trường thực sự, được ghi lại giữa lúc trận đánh còn đang diễn ra ác liệt phía dưới chân núi.","doc":3},{"loai":"anh","src":"textures/bang_w/G15_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quan sát mặt trận Đông Khê, Chiến dịch Biên giới 1950”, nhìn từ xa."},{"loai":"doan","tieu_de":"\"Đăng sơn\" – bài thơ viết giữa trận tiền","text":"Cũng trong những ngày ở mặt trận Biên giới, Chủ tịch Hồ Chí Minh viết bài thơ chữ Hán \"Đăng sơn\" (Lên núi), ghi lại đúng tâm thế của người vừa chống gậy lên núi xem trận địa. Bài thơ ngắn, chỉ bốn câu, nhưng cho thấy rõ khí thế của cả một đội quân đang chuyển từ thế phòng ngự sang thế chủ động tiến công. Bản dịch thơ được nhiều người biết đến sau này là bản dịch của nhà thơ Xuân Diệu.","doc":4},{"loai":"trich","text":"Chống gậy lên non xem trận địa, Vạn trùng núi đỡ vạn trùng mây. Quân ta khí mạnh nuốt Ngưu Đẩu, Thề diệt xâm lăng lũ sói cầy.","nguoi":"Chủ tịch Hồ Chí Minh, bài thơ chữ Hán \"Đăng sơn\" (bản dịch của Xuân Diệu)","nguon_ten":"Bài thơ \"Đăng sơn\", viết trong Chiến dịch Biên giới, 1950; Hồ Chí Minh Toàn tập","doc":5},{"loai":"anh","src":"textures/bang_w/G15_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quan sát mặt trận Đông Khê, Chiến dịch Biên giới 1950”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Vì sao chọn Đông Khê","text":"Bộ chỉ huy chiến dịch chọn Đông Khê làm trận mở màn không phải ngẫu nhiên. Đây là cứ điểm nằm giữa Cao Bằng và Thất Khê trên Đường số 4 — mất Đông Khê đồng nghĩa quân Pháp buộc phải lựa chọn: hoặc rút quân từ Cao Bằng theo Đường số 4 xuống, hoặc đưa quân từ Thất Khê lên ứng cứu, hoặc cả hai. Bộ đội Việt Nam đã tính trước cả hai khả năng, bố trí trận địa phục kích dọc đường rút và đường tiếp viện. Đúng như dự liệu, cả hai cánh quân Pháp sau đó đều rơi vào các trận phục kích quyết định, góp phần làm nên thắng lợi chung cuộc của toàn chiến dịch.\n\nSo với những cứ điểm lớn hơn như Cao Bằng hay Lạng Sơn, Đông Khê là mắt xích vừa đủ yếu để bộ đội Việt Nam — khi ấy còn thiếu kinh nghiệm đánh công kiên quy mô lớn — có thể đánh chắc thắng, vừa đủ quan trọng để buộc đối phương phải phản ứng, từ đó lộ ra sơ hở cho những trận phục kích tiếp theo. Đây chính là bài học \"đánh điểm diệt viện\" mà quân đội Việt Nam áp dụng thành công lần đầu ở quy mô chiến dịch trong trận này.","doc":6},{"loai":"ban_co_biet","text":"Con đường lên đài quan sát trên núi Báo Đông ngày nay đã được xây dựng, gồm 846 bậc thang dẫn du khách lên tận vị trí Người từng đứng quan sát trận đánh năm xưa.","nguon_ten":"Bảo tàng Hồ Chí Minh (baotanghochiminh.vn)","doc":7},{"loai":"anh","src":"textures/bang_w/G15_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quan sát mặt trận Đông Khê, Chiến dịch Biên giới 1950”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Cánh cửa biên giới mở ra","text":"Chiến dịch Biên giới kết thúc thắng lợi vào cuối tháng 10 năm 1950. Toàn tuyến biên giới Việt – Trung từ Cao Bằng đến Đình Lập được giải phóng, phá vỡ hoàn toàn hành lang phong tỏa của quân Pháp; con đường liên lạc, vận chuyển hàng viện trợ giữa Việt Nam với Trung Quốc và các nước xã hội chủ nghĩa được khai thông. Căn cứ địa Việt Bắc, từ chỗ bị bao vây, cô lập, giờ đã có một cửa ngõ thông ra thế giới bên ngoài. Từ sau chiến dịch này, cuộc kháng chiến chống Pháp bước sang một giai đoạn mới: quân đội Việt Nam giữ thế chủ động trên chiến trường chính Bắc Bộ, thay vì chỉ phòng ngự, giữ gìn lực lượng như những năm đầu.\n\nVới Chủ tịch Hồ Chí Minh, việc đích thân có mặt ở mặt trận Đông Khê không đơn thuần là một cử chỉ động viên tinh thần. Đó còn là cách Người trực tiếp nắm tình hình chiến sự để kịp thời góp ý về sách lược cho Bộ Tổng tư lệnh, đồng thời khẳng định với cán bộ, chiến sĩ rằng vận mệnh của chiến dịch được lãnh đạo cao nhất theo dõi sát sao từng giờ, từng ngày, chứ không chỉ qua những bản báo cáo gửi về hậu phương.","doc":8},{"loai":"ban_co_biet","text":"Núi Báo Đông ngày nay nằm trong Khu di tích Quốc gia đặc biệt Địa điểm Chiến thắng Biên giới năm 1950; năm 2004, một cụm tượng mô phỏng theo bức ảnh Chủ tịch Hồ Chí Minh quan sát mặt trận Đông Khê được dựng ngay tại đài quan sát trên đỉnh núi.","nguon_ten":"Bảo tàng Hồ Chí Minh (baotanghochiminh.vn)","doc":9},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Địa điểm Chiến thắng Biên giới năm 1950, bao gồm đài quan sát trên núi Báo Đông, nay là di tích quốc gia đặc biệt, đón khách tham quan quanh năm. Leo hết 846 bậc thang, du khách có thể đứng đúng vị trí Người từng đứng, phóng tầm mắt xuống thung lũng nơi cứ điểm Đông Khê từng bị công phá bảy mươi năm trước, và hình dung lại khoảnh khắc một vị Chủ tịch nước chống gậy lên núi, lặng lẽ dõi theo bước chân của quân đội mình giữa một trận đánh có thể làm xoay chuyển cả cục diện chiến tranh.","doc":10}],"nguon":["Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","Bảo tàng Hồ Chí Minh – Di tích núi Báo Đông (baotanghochiminh.vn)"],"doc":[{"t":"\"Chống gậy lên non xem trận địa\": Người ở mặt trận Đông Khê. Rạng sáng 16 tháng 9 năm 1950, một người đàn ông chống gậy trèo lên đỉnh núi Báo Đông, giữa biên giới Việt – Trung, để tận mắt theo dõi trận đánh mở màn một chiến dịch lớn. Người đó là Chủ tịch nước. Bức ảnh chụp khoảnh khắc ấy, cùng bài thơ chữ Hán Người viết ngay trong chiến dịch, đã trở thành một trong những hình ảnh khắc họa rõ nhất tinh thần của cuộc kháng chiến chống Pháp giữa lúc chuyển sang thế chủ động tiến công."},{"t":"Vì sao phải mở Chiến dịch Biên giới. Đến năm 1950, thực dân Pháp tăng cường khóa chặt tuyến biên giới Việt – Trung bằng một hệ thống cứ điểm quân sự dọc Đường số 4 — từ Cao Bằng, Đông Khê, Thất Khê đến Lạng Sơn — nhằm cô lập hoàn toàn căn cứ địa Việt Bắc với thế giới bên ngoài. Trong khi đó, cục diện quốc tế đang chuyển động có lợi cho cách mạng Việt Nam: cách mạng Trung Quốc thắng lợi cuối năm 1949, rồi lần lượt Trung Quốc, Liên Xô và các nước xã hội chủ nghĩa công nhận, đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa đầu năm 1950. Tháng 6 năm 1950, Trung ương Đảng và Chính phủ quyết định mở Chiến dịch Biên giới nhằm tiêu diệt một bộ phận quan trọng sinh lực địch, khai thông đường liên lạc quốc tế, đồng thời mở rộng và củng cố căn cứ địa Việt Bắc. Đây là lần đầu tiên quân đội Việt Nam có điều kiện chuẩn bị một chiến dịch tiến công quy mô lớn với sự phối hợp của nhiều đại đoàn chủ lực, thay vì chỉ đánh nhỏ lẻ, phân tán như những năm đầu kháng chiến. Bộ Tổng tư lệnh, đứng đầu là Đại tướng Võ Nguyên Giáp, trực tiếp xây dựng kế hoạch tác chiến; còn Chủ tịch Hồ Chí Minh, với tư cách người đứng đầu Đảng và Nhà nước, theo dõi sát từng bước chuẩn bị, từ hậu cần, dân công đến tinh thần bộ đội trước giờ nổ súng."},{"t":"Người ra mặt trận. Đây là chiến dịch tiến công quy mô lớn đầu tiên do bộ đội chủ lực Việt Nam chủ động hoạch định và mở màn — khác hẳn những chiến dịch trước đó vốn mang tính phản công, chống càn. Chủ tịch Hồ Chí Minh trực tiếp ra mặt trận theo dõi diễn biến, một điều hiếm khi xảy ra với một vị Chủ tịch nước giữa thời chiến. Rạng sáng ngày 16 tháng 9 năm 1950, Người được đưa lên một đài quan sát dựng trên đỉnh núi để theo dõi trận đánh mở màn vào cứ điểm Đông Khê. Cùng có mặt tại đài quan sát hôm ấy là các cán bộ chỉ huy chiến dịch và đội cận vệ bảo vệ Người. Ngày 18 tháng 9, sau hai ngày chiến đấu ác liệt, Đông Khê được giải phóng — trận mở màn thắng lợi, tạo đà cho toàn bộ chiến dịch. Việc một vị đứng đầu Nhà nước trực tiếp có mặt sát cạnh mặt trận, giữa lúc bom đạn còn chưa dứt, tự nó đã là một nguồn cổ vũ tinh thần to lớn cho cán bộ, chiến sĩ đang tham gia trận đánh mở màn đầy cam go này."},{"t":"Đài quan sát trên núi Báo Đông. Vị trí Người đứng quan sát trận đánh hôm ấy là đỉnh núi Báo Đông, thuộc xóm Bản Pò, xã Đức Long, huyện Thạch An, tỉnh Cao Bằng — một điểm cao nhìn thẳng xuống cứ điểm Đông Khê. Bức ảnh nổi tiếng ghi lại khoảnh khắc này do nhiếp ảnh gia Vũ Năng An thực hiện. Từ đài quan sát dã chiến ấy, Người theo dõi từng diễn biến của trận đánh, giữa tiếng đại bác và không khí căng thẳng của một trận mở màn có ý nghĩa quyết định. Hình ảnh vị Chủ tịch nước chống gậy, đứng lặng lẽ quan sát trận địa giữa núi rừng biên giới về sau trở thành một trong những bức ảnh được biết đến rộng rãi nhất về Người trong vai trò gắn bó trực tiếp với mặt trận. Cùng có mặt tại đài quan sát hôm ấy, theo tư liệu còn lưu lại, có đồng chí Phạm Chước — trưởng đài quan sát, đồng chí Võ Viết Định — đội trưởng đội cận vệ bảo vệ Người, cùng một học viên Trường Lục quân và một số cán bộ Bộ chỉ huy chiến dịch. Không có phóng viên chiến trường đông đảo, không có buổi \"dàn dựng\" nào; bức ảnh vì vậy mang đúng chất một khoảnh khắc chiến trường thực sự, được ghi lại giữa lúc trận đánh còn đang diễn ra ác liệt phía dưới chân núi."},{"t":"\"Đăng sơn\" – bài thơ viết giữa trận tiền. Cũng trong những ngày ở mặt trận Biên giới, Chủ tịch Hồ Chí Minh viết bài thơ chữ Hán \"Đăng sơn\" (Lên núi), ghi lại đúng tâm thế của người vừa chống gậy lên núi xem trận địa. Bài thơ ngắn, chỉ bốn câu, nhưng cho thấy rõ khí thế của cả một đội quân đang chuyển từ thế phòng ngự sang thế chủ động tiến công. Bản dịch thơ được nhiều người biết đến sau này là bản dịch của nhà thơ Xuân Diệu."},{"t":"Chống gậy lên non xem trận địa, Vạn trùng núi đỡ vạn trùng mây. Quân ta khí mạnh nuốt Ngưu Đẩu, Thề diệt xâm lăng lũ sói cầy. — Chủ tịch Hồ Chí Minh, bài thơ chữ Hán \"Đăng sơn\" (bản dịch của Xuân Diệu)"},{"t":"Vì sao chọn Đông Khê. Bộ chỉ huy chiến dịch chọn Đông Khê làm trận mở màn không phải ngẫu nhiên. Đây là cứ điểm nằm giữa Cao Bằng và Thất Khê trên Đường số 4 — mất Đông Khê đồng nghĩa quân Pháp buộc phải lựa chọn: hoặc rút quân từ Cao Bằng theo Đường số 4 xuống, hoặc đưa quân từ Thất Khê lên ứng cứu, hoặc cả hai. Bộ đội Việt Nam đã tính trước cả hai khả năng, bố trí trận địa phục kích dọc đường rút và đường tiếp viện. Đúng như dự liệu, cả hai cánh quân Pháp sau đó đều rơi vào các trận phục kích quyết định, góp phần làm nên thắng lợi chung cuộc của toàn chiến dịch. So với những cứ điểm lớn hơn như Cao Bằng hay Lạng Sơn, Đông Khê là mắt xích vừa đủ yếu để bộ đội Việt Nam — khi ấy còn thiếu kinh nghiệm đánh công kiên quy mô lớn — có thể đánh chắc thắng, vừa đủ quan trọng để buộc đối phương phải phản ứng, từ đó lộ ra sơ hở cho những trận phục kích tiếp theo. Đây chính là bài học \"đánh điểm diệt viện\" mà quân đội Việt Nam áp dụng thành công lần đầu ở quy mô chiến dịch trong trận này."},{"t":"Bạn có biết? Con đường lên đài quan sát trên núi Báo Đông ngày nay đã được xây dựng, gồm 846 bậc thang dẫn du khách lên tận vị trí Người từng đứng quan sát trận đánh năm xưa."},{"t":"Cánh cửa biên giới mở ra. Chiến dịch Biên giới kết thúc thắng lợi vào cuối tháng 10 năm 1950. Toàn tuyến biên giới Việt – Trung từ Cao Bằng đến Đình Lập được giải phóng, phá vỡ hoàn toàn hành lang phong tỏa của quân Pháp; con đường liên lạc, vận chuyển hàng viện trợ giữa Việt Nam với Trung Quốc và các nước xã hội chủ nghĩa được khai thông. Căn cứ địa Việt Bắc, từ chỗ bị bao vây, cô lập, giờ đã có một cửa ngõ thông ra thế giới bên ngoài. Từ sau chiến dịch này, cuộc kháng chiến chống Pháp bước sang một giai đoạn mới: quân đội Việt Nam giữ thế chủ động trên chiến trường chính Bắc Bộ, thay vì chỉ phòng ngự, giữ gìn lực lượng như những năm đầu. Với Chủ tịch Hồ Chí Minh, việc đích thân có mặt ở mặt trận Đông Khê không đơn thuần là một cử chỉ động viên tinh thần. Đó còn là cách Người trực tiếp nắm tình hình chiến sự để kịp thời góp ý về sách lược cho Bộ Tổng tư lệnh, đồng thời khẳng định với cán bộ, chiến sĩ rằng vận mệnh của chiến dịch được lãnh đạo cao nhất theo dõi sát sao từng giờ, từng ngày, chứ không chỉ qua những bản báo cáo gửi về hậu phương."},{"t":"Bạn có biết? Núi Báo Đông ngày nay nằm trong Khu di tích Quốc gia đặc biệt Địa điểm Chiến thắng Biên giới năm 1950; năm 2004, một cụm tượng mô phỏng theo bức ảnh Chủ tịch Hồ Chí Minh quan sát mặt trận Đông Khê được dựng ngay tại đài quan sát trên đỉnh núi."},{"t":"Dấu tích hôm nay. Địa điểm Chiến thắng Biên giới năm 1950, bao gồm đài quan sát trên núi Báo Đông, nay là di tích quốc gia đặc biệt, đón khách tham quan quanh năm. Leo hết 846 bậc thang, du khách có thể đứng đúng vị trí Người từng đứng, phóng tầm mắt xuống thung lũng nơi cứ điểm Đông Khê từng bị công phá bảy mươi năm trước, và hình dung lại khoảnh khắc một vị Chủ tịch nước chống gậy lên núi, lặng lẽ dõi theo bước chân của quân đội mình giữa một trận đánh có thể làm xoay chuyển cả cục diện chiến tranh."}],"so_chu":1548},{"i":7,"tieu_de_bang":"Đại hội II của Đảng tại Chiêm Hóa, Tuyên Quang, 1951","tieu_de":"Đại hội giữa rừng Chiêm Hóa: khi Đảng trở lại hoạt động công khai","sapo":"Tháng 2 năm 1951, giữa rừng già Chiêm Hóa, hơn hai trăm đại biểu từ khắp mọi miền đất nước lặng lẽ tề tựu về một địa điểm bí mật. Sau hơn năm năm phải ẩn mình dưới cái tên \"tự giải tán\", Đảng Cộng sản Đông Dương chuẩn bị bước ra công khai với một tên gọi mới. Không lễ đài lộng lẫy, chỉ có nhà tranh giữa rừng — nhưng những quyết định đưa ra ở đó sẽ dẫn dắt cả một cuộc kháng chiến đi đến ngày toàn thắng.","bia":{"src":"textures/ht/ht_anh_dai_hoi_dai_bieu_toan_quoc_lan_thu_hai_dang_cong.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Từ \"tự giải tán\" đến một đại hội giữa rừng","text":"Ngày 11 tháng 11 năm 1945, trước sự chống phá quyết liệt của quân Tưởng Giới Thạch và các thế lực phản động tay sai vừa tràn vào miền Bắc, Đảng Cộng sản Đông Dương tuyên bố \"tự giải tán\" — một quyết định mang tính sách lược để bảo vệ chính quyền cách mạng còn non trẻ. Trên thực tế, Đảng vẫn tồn tại và hoạt động, chỉ rút vào bí mật dưới danh nghĩa \"Hội nghiên cứu chủ nghĩa Mác ở Đông Dương\", tiếp tục lãnh đạo chính quyền và cuộc kháng chiến suốt hơn năm năm sau đó. Phải đến đầu năm 1951, khi cục diện kháng chiến đã có nhiều chuyển biến thuận lợi — sau thắng lợi của Chiến dịch Biên giới cuối năm 1950 khai thông liên lạc quốc tế — Trung ương mới quyết định triệu tập Đại hội đại biểu toàn quốc lần thứ hai, đưa Đảng trở lại hoạt động công khai.\n\nSuốt hơn năm năm hoạt động dưới vỏ bọc \"tự giải tán\", Đảng vẫn là lực lượng lãnh đạo xuyên suốt cuộc kháng chiến: từ tổ chức chính quyền, xây dựng lực lượng vũ trang, đến hoạch định các chiến dịch lớn. Việc phải chờ đến năm 1951 mới tổ chức đại hội công khai cho thấy mức độ thận trọng của Trung ương trong việc bảo vệ bí mật tuyệt đối cho bộ máy lãnh đạo, giữa lúc quân Pháp vẫn ráo riết truy lùng, đánh phá khắp vùng tự do.","doc":1},{"loai":"doan","tieu_de":"Đại hội đầu tiên họp trên đất nước mình","text":"Đại hội khai mạc ngày 11 tháng 2 và bế mạc ngày 19 tháng 2 năm 1951, tại xã Vinh Quang (nay là xã Kim Bình), huyện Chiêm Hóa, tỉnh Tuyên Quang. Tham dự có 158 đại biểu chính thức và 53 đại biểu dự khuyết, thay mặt cho hơn bảy trăm sáu mươi sáu nghìn đảng viên trong cả nước. Đây là đại hội đầu tiên của Đảng được tổ chức ngay trên đất nước mình — Đại hội lần thứ nhất, họp tháng 3 năm 1935, còn phải tổ chức tại Ma Cao (Trung Quốc) vì điều kiện hoạt động bí mật lúc bấy giờ. Việc đưa được từng ấy đại biểu từ khắp các chiến trường, các miền đất nước — có người phải đi bộ hàng tháng trời — về an toàn giữa một khu rừng ở Tuyên Quang, trong điều kiện chiến tranh và sự truy lùng gắt gao của địch, tự nó đã là một thành công lớn của công tác bảo vệ, giữ bí mật ở Việt Bắc. Nhiều đại biểu từ các chiến trường Nam Bộ, Trung Bộ xa xôi phải di chuyển ròng rã hàng tháng trời, qua nhiều vùng địch hậu, mới có thể đến được địa điểm họp giữa núi rừng Tuyên Quang.","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_dai_hoi_dai_bieu_toan_quoc_lan_thu_hai_dang_cong.jpg","chu_thich":"Đại hội đại biểu toàn quốc lần thứ II của Đảng, họp tại Chiêm Hóa, Tuyên Quang, tháng 2/1951.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Bản báo cáo chính trị và cái tên mới","text":"Tại đại hội, Chủ tịch Hồ Chí Minh đọc Báo cáo chính trị, thẳng thắn chỉ ra cả những thành tựu lẫn khuyết điểm của Đảng sau hơn hai mươi năm hoạt động, đồng thời nhấn mạnh yêu cầu phải \"nghiên cứu thật sâu, thảo luận thật kỹ những vấn đề chính\" — Người còn ví von rằng \"Đại hội ta cũng phải quân sự hóa\", cho thấy tinh thần khẩn trương của một đại hội họp giữa thời chiến, khi công tác bảo vệ, phòng không, di chuyển đại biểu đều phải tổ chức chặt chẽ như một chiến dịch quân sự thực thụ. Đồng chí Trường Chinh trình bày báo cáo \"Hoàn thành giải phóng dân tộc, phát triển dân chủ nhân dân, tiến tới chủ nghĩa xã hội\", phân tích tính chất, nhiệm vụ và động lực của cách mạng Việt Nam trong giai đoạn mới. Đại hội quyết định tách Đảng Cộng sản Đông Dương thành ba đảng cách mạng riêng ở Việt Nam, Lào và Campuchia — phù hợp với đặc điểm và yêu cầu cách mạng riêng của mỗi nước, đồng thời vẫn giữ mối quan hệ đoàn kết chiến đấu giữa ba dân tộc Đông Dương. Ở Việt Nam, Đảng ra hoạt động công khai trở lại với tên gọi mới: Đảng Lao động Việt Nam.","doc":3},{"loai":"anh","src":"textures/bang_w/G15_7_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Đại hội II của Đảng tại Chiêm Hóa, Tuyên Quang, 1951”, nhìn từ xa."},{"loai":"doan","tieu_de":"Người đứng đầu Đảng","text":"Đại hội bầu Ban Chấp hành Trung ương mới; Chủ tịch Hồ Chí Minh được bầu làm Chủ tịch Đảng, đồng chí Trường Chinh được bầu lại làm Tổng Bí thư. Ngày 3 tháng 3 năm 1951, chỉ hơn hai tuần sau khi đại hội bế mạc, Đảng Lao động Việt Nam chính thức ra mắt quốc dân giữa An toàn khu. Trong lời phát biểu tại buổi lễ, Người nêu rõ mục đích của Đảng bằng một câu nói ngắn gọn, dễ nhớ, sau này được nhắc lại nhiều lần trong các văn kiện của Đảng. Cách diễn đạt cô đọng — chỉ tám chữ — cũng là phong cách quen thuộc của Người: lý luận cách mạng được chuyển thành những câu nói dễ hiểu, dễ nhớ, để cán bộ, đảng viên ở mọi trình độ đều có thể nắm bắt và truyền đạt lại cho quần chúng.","doc":4},{"loai":"trich","text":"Mục đích của Đảng Lao động Việt Nam có thể gồm trong 8 chữ là: Đoàn kết toàn dân, phụng sự Tổ quốc.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Lời kết thúc buổi ra mắt của Đảng Lao động Việt Nam, ngày 3/3/1951 – Hồ Chí Minh Toàn tập","doc":5},{"loai":"anh","src":"textures/bang_w/G15_7_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Đại hội II của Đảng tại Chiêm Hóa, Tuyên Quang, 1951”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Đại hội giữa rừng, Mặt trận cũng thống nhất","text":"Chỉ ít ngày sau Đại hội II, cũng tại khu vực Chiêm Hóa, một sự kiện chính trị quan trọng khác diễn ra: Đại hội hợp nhất Mặt trận Việt Minh và Hội Liên Việt thành Mặt trận Liên Việt, với cụ Tôn Đức Thắng được bầu làm Chủ tịch (xem thêm chuyên đề về bức ảnh Bác với cụ Tôn Đức Thắng và Hoàng Quốc Việt). Hai sự kiện diễn ra gần như liền nhau, ở cùng một khu vực An toàn khu, cho thấy đầu năm 1951 là một thời điểm bản lề: cả bộ máy lãnh đạo Đảng lẫn khối đại đoàn kết toàn dân đều được củng cố, kiện toàn ngay giữa lúc cuộc kháng chiến bước vào giai đoạn quyết liệt hơn.\n\nViệc tổ chức liên tiếp hai sự kiện chính trị lớn — đại hội của Đảng và đại hội thống nhất mặt trận — ngay giữa một khu rừng chiến khu, trong vòng chưa đầy một tháng, cũng là minh chứng cho năng lực tổ chức, hậu cần và bảo vệ bí mật đã trưởng thành rõ rệt của bộ máy kháng chiến so với những năm đầu, khi mọi cuộc họp cấp cao đều phải diễn ra chớp nhoáng, phân tán để tránh bị phát hiện.","doc":6},{"loai":"ban_co_biet","text":"Chỉ ít tuần sau Đại hội II, ngày 11 tháng 3 năm 1951, báo Nhân Dân — cơ quan trung ương của Đảng Lao động Việt Nam — ra số đầu tiên; tờ báo tiếp tục xuất bản liên tục cho đến ngày nay.","nguon_ten":"Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia; Báo Nhân Dân","doc":7},{"loai":"anh","src":"textures/bang_w/G15_7_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Đại hội II của Đảng tại Chiêm Hóa, Tuyên Quang, 1951”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Vì sao con số 158 và 53 quan trọng","text":"Con số 158 đại biểu chính thức và 53 đại biểu dự khuyết có mặt tại Đại hội II, thay mặt cho hơn bảy trăm sáu mươi sáu nghìn đảng viên, cho thấy quy mô của Đảng đã lớn mạnh vượt bậc so với những ngày đầu thành lập năm 1930 chỉ với vài trăm đảng viên. Đó cũng là minh chứng cho sức sống của một tổ chức đã trải qua giai đoạn phải \"tự giải tán\", hoạt động bí mật suốt hơn năm năm, để rồi khi có điều kiện, lập tức chứng tỏ được quy mô, tổ chức và uy tín của mình ngay giữa núi rừng kháng chiến.","doc":8},{"loai":"ban_co_biet","text":"Đại hội lần thứ I của Đảng, họp tháng 3 năm 1935, phải tổ chức tại Ma Cao (Trung Quốc) vì điều kiện hoạt động bí mật; phải chờ mười sáu năm sau, đến Đại hội II năm 1951, Đảng mới lần đầu tổ chức được đại hội toàn quốc ngay trên đất nước mình.","nguon_ten":"Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","doc":9},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Địa điểm diễn ra Đại hội II, nay thuộc xã Kim Bình, huyện Chiêm Hóa, tỉnh Tuyên Quang, đã được xếp hạng di tích lịch sử và xây dựng thành khu lưu niệm, là một điểm đến trong hành trình về nguồn của nhiều đoàn cán bộ, đảng viên, học sinh, sinh viên. Bức ảnh chụp toàn cảnh đại hội giữa những nếp nhà tranh, dưới tán rừng già Tuyên Quang, vẫn được trưng bày như một minh chứng sống động cho một sự thật: giữa những năm tháng gian khổ nhất của cuộc kháng chiến, một đảng cầm quyền vẫn đủ sức tổ chức một kỳ đại hội quy mô toàn quốc, đặt nền móng tổ chức và tư tưởng cho con đường đi đến thắng lợi Điện Biên Phủ ba năm sau đó. Đứng giữa khu lưu niệm hôm nay, khó hình dung được rằng bảy mươi năm trước, chính khoảng rừng yên tĩnh này từng là nơi tề tựu của những người sẽ định hình đường lối cho cả một dân tộc đang trong cuộc chiến sinh tử.","doc":10}],"nguon":["Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Văn kiện Đảng toàn tập, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh – hochiminh.vn (Chủ tịch Hồ Chí Minh với Đại hội II của Đảng)"],"doc":[{"t":"Đại hội giữa rừng Chiêm Hóa: khi Đảng trở lại hoạt động công khai. Tháng 2 năm 1951, giữa rừng già Chiêm Hóa, hơn hai trăm đại biểu từ khắp mọi miền đất nước lặng lẽ tề tựu về một địa điểm bí mật. Sau hơn năm năm phải ẩn mình dưới cái tên \"tự giải tán\", Đảng Cộng sản Đông Dương chuẩn bị bước ra công khai với một tên gọi mới. Không lễ đài lộng lẫy, chỉ có nhà tranh giữa rừng — nhưng những quyết định đưa ra ở đó sẽ dẫn dắt cả một cuộc kháng chiến đi đến ngày toàn thắng."},{"t":"Từ \"tự giải tán\" đến một đại hội giữa rừng. Ngày 11 tháng 11 năm 1945, trước sự chống phá quyết liệt của quân Tưởng Giới Thạch và các thế lực phản động tay sai vừa tràn vào miền Bắc, Đảng Cộng sản Đông Dương tuyên bố \"tự giải tán\" — một quyết định mang tính sách lược để bảo vệ chính quyền cách mạng còn non trẻ. Trên thực tế, Đảng vẫn tồn tại và hoạt động, chỉ rút vào bí mật dưới danh nghĩa \"Hội nghiên cứu chủ nghĩa Mác ở Đông Dương\", tiếp tục lãnh đạo chính quyền và cuộc kháng chiến suốt hơn năm năm sau đó. Phải đến đầu năm 1951, khi cục diện kháng chiến đã có nhiều chuyển biến thuận lợi — sau thắng lợi của Chiến dịch Biên giới cuối năm 1950 khai thông liên lạc quốc tế — Trung ương mới quyết định triệu tập Đại hội đại biểu toàn quốc lần thứ hai, đưa Đảng trở lại hoạt động công khai. Suốt hơn năm năm hoạt động dưới vỏ bọc \"tự giải tán\", Đảng vẫn là lực lượng lãnh đạo xuyên suốt cuộc kháng chiến: từ tổ chức chính quyền, xây dựng lực lượng vũ trang, đến hoạch định các chiến dịch lớn. Việc phải chờ đến năm 1951 mới tổ chức đại hội công khai cho thấy mức độ thận trọng của Trung ương trong việc bảo vệ bí mật tuyệt đối cho bộ máy lãnh đạo, giữa lúc quân Pháp vẫn ráo riết truy lùng, đánh phá khắp vùng tự do."},{"t":"Đại hội đầu tiên họp trên đất nước mình. Đại hội khai mạc ngày 11 tháng 2 và bế mạc ngày 19 tháng 2 năm 1951, tại xã Vinh Quang (nay là xã Kim Bình), huyện Chiêm Hóa, tỉnh Tuyên Quang. Tham dự có 158 đại biểu chính thức và 53 đại biểu dự khuyết, thay mặt cho hơn bảy trăm sáu mươi sáu nghìn đảng viên trong cả nước. Đây là đại hội đầu tiên của Đảng được tổ chức ngay trên đất nước mình — Đại hội lần thứ nhất, họp tháng 3 năm 1935, còn phải tổ chức tại Ma Cao (Trung Quốc) vì điều kiện hoạt động bí mật lúc bấy giờ. Việc đưa được từng ấy đại biểu từ khắp các chiến trường, các miền đất nước — có người phải đi bộ hàng tháng trời — về an toàn giữa một khu rừng ở Tuyên Quang, trong điều kiện chiến tranh và sự truy lùng gắt gao của địch, tự nó đã là một thành công lớn của công tác bảo vệ, giữ bí mật ở Việt Bắc. Nhiều đại biểu từ các chiến trường Nam Bộ, Trung Bộ xa xôi phải di chuyển ròng rã hàng tháng trời, qua nhiều vùng địch hậu, mới có thể đến được địa điểm họp giữa núi rừng Tuyên Quang."},{"t":"Bản báo cáo chính trị và cái tên mới. Tại đại hội, Chủ tịch Hồ Chí Minh đọc Báo cáo chính trị, thẳng thắn chỉ ra cả những thành tựu lẫn khuyết điểm của Đảng sau hơn hai mươi năm hoạt động, đồng thời nhấn mạnh yêu cầu phải \"nghiên cứu thật sâu, thảo luận thật kỹ những vấn đề chính\" — Người còn ví von rằng \"Đại hội ta cũng phải quân sự hóa\", cho thấy tinh thần khẩn trương của một đại hội họp giữa thời chiến, khi công tác bảo vệ, phòng không, di chuyển đại biểu đều phải tổ chức chặt chẽ như một chiến dịch quân sự thực thụ. Đồng chí Trường Chinh trình bày báo cáo \"Hoàn thành giải phóng dân tộc, phát triển dân chủ nhân dân, tiến tới chủ nghĩa xã hội\", phân tích tính chất, nhiệm vụ và động lực của cách mạng Việt Nam trong giai đoạn mới. Đại hội quyết định tách Đảng Cộng sản Đông Dương thành ba đảng cách mạng riêng ở Việt Nam, Lào và Campuchia — phù hợp với đặc điểm và yêu cầu cách mạng riêng của mỗi nước, đồng thời vẫn giữ mối quan hệ đoàn kết chiến đấu giữa ba dân tộc Đông Dương. Ở Việt Nam, Đảng ra hoạt động công khai trở lại với tên gọi mới: Đảng Lao động Việt Nam."},{"t":"Người đứng đầu Đảng. Đại hội bầu Ban Chấp hành Trung ương mới; Chủ tịch Hồ Chí Minh được bầu làm Chủ tịch Đảng, đồng chí Trường Chinh được bầu lại làm Tổng Bí thư. Ngày 3 tháng 3 năm 1951, chỉ hơn hai tuần sau khi đại hội bế mạc, Đảng Lao động Việt Nam chính thức ra mắt quốc dân giữa An toàn khu. Trong lời phát biểu tại buổi lễ, Người nêu rõ mục đích của Đảng bằng một câu nói ngắn gọn, dễ nhớ, sau này được nhắc lại nhiều lần trong các văn kiện của Đảng. Cách diễn đạt cô đọng — chỉ tám chữ — cũng là phong cách quen thuộc của Người: lý luận cách mạng được chuyển thành những câu nói dễ hiểu, dễ nhớ, để cán bộ, đảng viên ở mọi trình độ đều có thể nắm bắt và truyền đạt lại cho quần chúng."},{"t":"Mục đích của Đảng Lao động Việt Nam có thể gồm trong 8 chữ là: Đoàn kết toàn dân, phụng sự Tổ quốc. — Chủ tịch Hồ Chí Minh"},{"t":"Đại hội giữa rừng, Mặt trận cũng thống nhất. Chỉ ít ngày sau Đại hội II, cũng tại khu vực Chiêm Hóa, một sự kiện chính trị quan trọng khác diễn ra: Đại hội hợp nhất Mặt trận Việt Minh và Hội Liên Việt thành Mặt trận Liên Việt, với cụ Tôn Đức Thắng được bầu làm Chủ tịch (xem thêm chuyên đề về bức ảnh Bác với cụ Tôn Đức Thắng và Hoàng Quốc Việt). Hai sự kiện diễn ra gần như liền nhau, ở cùng một khu vực An toàn khu, cho thấy đầu năm 1951 là một thời điểm bản lề: cả bộ máy lãnh đạo Đảng lẫn khối đại đoàn kết toàn dân đều được củng cố, kiện toàn ngay giữa lúc cuộc kháng chiến bước vào giai đoạn quyết liệt hơn. Việc tổ chức liên tiếp hai sự kiện chính trị lớn — đại hội của Đảng và đại hội thống nhất mặt trận — ngay giữa một khu rừng chiến khu, trong vòng chưa đầy một tháng, cũng là minh chứng cho năng lực tổ chức, hậu cần và bảo vệ bí mật đã trưởng thành rõ rệt của bộ máy kháng chiến so với những năm đầu, khi mọi cuộc họp cấp cao đều phải diễn ra chớp nhoáng, phân tán để tránh bị phát hiện."},{"t":"Bạn có biết? Chỉ ít tuần sau Đại hội II, ngày 11 tháng 3 năm 1951, báo Nhân Dân — cơ quan trung ương của Đảng Lao động Việt Nam — ra số đầu tiên; tờ báo tiếp tục xuất bản liên tục cho đến ngày nay."},{"t":"Vì sao con số 158 và 53 quan trọng. Con số 158 đại biểu chính thức và 53 đại biểu dự khuyết có mặt tại Đại hội II, thay mặt cho hơn bảy trăm sáu mươi sáu nghìn đảng viên, cho thấy quy mô của Đảng đã lớn mạnh vượt bậc so với những ngày đầu thành lập năm 1930 chỉ với vài trăm đảng viên. Đó cũng là minh chứng cho sức sống của một tổ chức đã trải qua giai đoạn phải \"tự giải tán\", hoạt động bí mật suốt hơn năm năm, để rồi khi có điều kiện, lập tức chứng tỏ được quy mô, tổ chức và uy tín của mình ngay giữa núi rừng kháng chiến."},{"t":"Bạn có biết? Đại hội lần thứ I của Đảng, họp tháng 3 năm 1935, phải tổ chức tại Ma Cao (Trung Quốc) vì điều kiện hoạt động bí mật; phải chờ mười sáu năm sau, đến Đại hội II năm 1951, Đảng mới lần đầu tổ chức được đại hội toàn quốc ngay trên đất nước mình."},{"t":"Dấu tích hôm nay. Địa điểm diễn ra Đại hội II, nay thuộc xã Kim Bình, huyện Chiêm Hóa, tỉnh Tuyên Quang, đã được xếp hạng di tích lịch sử và xây dựng thành khu lưu niệm, là một điểm đến trong hành trình về nguồn của nhiều đoàn cán bộ, đảng viên, học sinh, sinh viên. Bức ảnh chụp toàn cảnh đại hội giữa những nếp nhà tranh, dưới tán rừng già Tuyên Quang, vẫn được trưng bày như một minh chứng sống động cho một sự thật: giữa những năm tháng gian khổ nhất của cuộc kháng chiến, một đảng cầm quyền vẫn đủ sức tổ chức một kỳ đại hội quy mô toàn quốc, đặt nền móng tổ chức và tư tưởng cho con đường đi đến thắng lợi Điện Biên Phủ ba năm sau đó. Đứng giữa khu lưu niệm hôm nay, khó hình dung được rằng bảy mươi năm trước, chính khoảng rừng yên tĩnh này từng là nơi tề tựu của những người sẽ định hình đường lối cho cả một dân tộc đang trong cuộc chiến sinh tử."}],"so_chu":1561},{"i":8,"tieu_de_bang":"Họa sĩ Phan Kế An ký họa Bác tại Việt Bắc, 11/1948","tieu_de":"Ký họa giữa rừng: hơn hai mươi bức vẽ Bác Hồ từ người thật","sapo":"Một ngày cuối thu năm 1948, giữa rừng Khuôn Tát, một họa sĩ trẻ được gọi đến bên Chủ tịch Hồ Chí Minh, mang theo giấy bút. Không có người mẫu ngồi yên, không có buổi tạo dáng: Người vẫn làm việc, đi lại, trò chuyện, còn họa sĩ phải vẽ thật nhanh để bắt được dáng hình chân thực nhất. Hơn hai mươi bức tốc họa ra đời trong ít ngày ngắn ngủi ấy, và một trong số chúng đã trở thành bức ký họa Bác Hồ đầu tiên được đăng báo công khai.","bia":{"src":"textures/ht/ht_anh_painter_phan_ke_an_sketched_a_portrait_of_presid.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Người được gọi đến Khuôn Tát","text":"Cuối thu năm 1948, tại Khuôn Tát, một địa điểm trong An toàn khu Định Hóa (Thái Nguyên), họa sĩ Phan Kế An — khi ấy còn là một chàng trai ngoài hai mươi tuổi — nhận được một cơ hội hiếm có: được đến gần để ký họa Chủ tịch Hồ Chí Minh. Giữa những năm chiến khu phải giữ bí mật tuyệt đối về nơi ở và lịch làm việc của Người, việc một người ngoài được phép đến gần, quan sát và vẽ trực tiếp là điều không nhiều họa sĩ có được. Ông không có nhiều thời gian: Người vẫn làm việc, đọc tài liệu, đi lại giữa lán và vườn, còn cây bút của họa sĩ phải đuổi theo từng cử chỉ, dáng ngồi, nét mặt. Không có buổi ngồi mẫu, không có ánh đèn sân khấu — chỉ có ánh sáng tự nhiên của núi rừng và sự tập trung cao độ của người cầm bút. Chính hoàn cảnh đặc biệt ấy khiến những bức ký họa ra đời từ ít ngày ở Khuôn Tát trở thành một trong những tư liệu hình ảnh quý hiếm và chân thực nhất về Chủ tịch Hồ Chí Minh giữa những năm kháng chiến gian khổ.","doc":1},{"loai":"doan","tieu_de":"Từ dinh Khâm sai đến chiến khu Việt Bắc","text":"Phan Kế An là con trai của Phan Kế Toại, người từng giữ chức Khâm sai đại thần Bắc Kỳ dưới chính phủ Trần Trọng Kim năm 1945, và sau Cách mạng Tháng Tám trở thành Bộ trưởng Bộ Nội vụ rồi Phó Thủ tướng Chính phủ nước Việt Nam Dân chủ Cộng hòa. Sinh ra trong một gia đình quan lại có học, nhưng Phan Kế An chọn con đường của một họa sĩ dấn thân theo kháng chiến, cùng nhiều văn nghệ sĩ cùng thế hệ rời phố thị lên chiến khu, mang theo giấy, bút chì, màu nước thay cho súng đạn. Ở Việt Bắc, ông vừa vẽ tranh cổ động, minh họa báo chí, vừa tham gia các hoạt động của giới văn nghệ kháng chiến. Việc một họa sĩ trẻ xuất thân từ một gia đình từng phục vụ trong bộ máy quan lại cũ lại trở thành người trực tiếp ký họa Chủ tịch Hồ Chí Minh giữa chiến khu, tự nó cũng là một câu chuyện nhỏ phản chiếu tinh thần đại đoàn kết dân tộc mà Người luôn kêu gọi trong những năm đầu kháng chiến.","doc":2},{"loai":"doan","tieu_de":"Hơn hai mươi bức tốc họa","text":"Theo lời kể của chính họa sĩ về sau, trong ít ngày ở Khuôn Tát ông đã vẽ hơn hai mươi bức tốc họa và một bức vẽ kỹ hơn về Chủ tịch Hồ Chí Minh. Tốc họa là lối vẽ nhanh, chỉ bằng vài nét bút, đòi hỏi người vẽ phải quan sát cực nhanh và ghi lại thần thái nhân vật gần như tức thời, không có cơ hội sửa lại. Trong số những bức ấy, một bức ký họa đơn sơ bằng bút sắt đã được chọn đăng trên báo Sự Thật vào tháng 12 năm 1948 — trở thành bức ký họa Bác Hồ đầu tiên được công bố công khai trên mặt báo. Với độc giả và cán bộ, chiến sĩ ở khắp các mặt trận, đó là một trong những hình ảnh hiếm hoi giúp họ hình dung được gương mặt vị Chủ tịch nước giữa những năm chiến khu, khi ảnh chụp còn rất hạn chế và phải giữ bí mật.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_painter_phan_ke_an_sketched_a_portrait_of_presid.jpg","chu_thich":"Họa sĩ Phan Kế An ký họa Chủ tịch Hồ Chí Minh tại Việt Bắc, tháng 11/1948.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Nét vẽ giữ lại đời thường","text":"Khác với những bức chân dung được vẽ lại sau này từ trí nhớ hay theo ảnh chụp, ký họa của Phan Kế An có một giá trị riêng: chúng được vẽ trực tiếp từ người thật, ngay trong khoảnh khắc Người đang sống và làm việc bình thường. Vì thế, nét bút giữ được sự giản dị, gần gũi — dáng ngồi hơi nghiêng khi đọc tài liệu, ánh mắt khi trò chuyện, bộ quần áo kaki bạc màu quen thuộc — thay vì vẻ trang trọng, tĩnh tại thường thấy ở tranh chân dung chính thức. Nhiều nhà nghiên cứu mỹ thuật sau này xem đây là một trong những bộ ký họa có giá trị tư liệu lịch sử cao về hình ảnh đời thường của Chủ tịch Hồ Chí Minh trong giai đoạn kháng chiến chống Pháp, khi phần lớn hình ảnh chính thức về Người còn rất ít ỏi.\n\nCũng vì được vẽ ngay tại chỗ, không qua dàn dựng, những bức tốc họa còn vô tình ghi lại cả khung cảnh chung quanh: mái lán nứa, khoảnh sân đất, dáng núi phía xa — những chi tiết mà một bức ảnh chụp chính thức, thường được sắp đặt kỹ hơn, khó có thể giữ lại trọn vẹn. Với người xem hôm nay, đó là một cách hình dung không gian sống thực của Người ở chiến khu, sống động hơn nhiều so với những mô tả bằng lời.","doc":4},{"loai":"anh","src":"textures/bang_w/G15_8_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Họa sĩ Phan Kế An ký họa Bác tại Việt Bắc, 11/1948”, nhìn từ xa."},{"loai":"doan","tieu_de":"Văn nghệ sĩ giữa chiến khu","text":"Câu chuyện của Phan Kế An không phải là cá biệt. Suốt những năm kháng chiến chống Pháp, rất đông họa sĩ, nhạc sĩ, nhà văn, nhà thơ đã rời Hà Nội, rời các đô thị để lên Việt Bắc, mang nghề nghiệp của mình phục vụ kháng chiến: người vẽ tranh cổ động, người sáng tác nhạc, người viết báo, làm thơ động viên bộ đội và nhân dân. Khẩu hiệu phổ biến trong giới văn nghệ thời ấy là đưa văn hóa hòa vào cuộc kháng chiến và biến kháng chiến thành nguồn cảm hứng sáng tạo. Trong bối cảnh ấy, việc Chủ tịch Hồ Chí Minh dành thời gian, dù ít ỏi giữa bộn bề công việc, để một họa sĩ trẻ được đến gần ký họa mình, cũng là một cách Người thể hiện sự trân trọng đối với vai trò của văn nghệ sĩ trong cuộc kháng chiến toàn dân.","doc":5},{"loai":"anh","src":"textures/bang_w/G15_8_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Họa sĩ Phan Kế An ký họa Bác tại Việt Bắc, 11/1948”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một mặt trận không tiếng súng","text":"Ba năm sau, năm 1951, Chủ tịch Hồ Chí Minh có thư gửi các họa sĩ nhân dịp một triển lãm hội họa, trong đó Người khẳng định văn hóa nghệ thuật cũng là một mặt trận và những người làm nghệ thuật là chiến sĩ trên mặt trận ấy. Với những họa sĩ từng có mặt ở Việt Bắc như Phan Kế An, lời khẳng định ấy không chỉ là một câu nói mang tính cổ vũ, mà đúc kết chính trải nghiệm họ đã sống: cầm bút vẽ giữa rừng, dưới bom đạn, để ghi lại gương mặt cuộc kháng chiến và gương mặt vị lãnh tụ của dân tộc, cũng là một cách chiến đấu không kém phần thầm lặng. Nhiều tác phẩm ra đời từ Việt Bắc thời kỳ ấy — tranh cổ động, ký họa, bài hát, bài thơ — về sau trở thành một phần di sản văn hóa của cuộc kháng chiến chống Pháp, được nhắc lại trong sách vở, bảo tàng và các chương trình giáo dục lịch sử cho nhiều thế hệ sau.","doc":6},{"loai":"doan","tieu_de":"Từ ký họa đến sự nghiệp mỹ thuật cách mạng","text":"Những ngày ở Khuôn Tát chỉ là một chương trong sự nghiệp dài của Phan Kế An. Về sau, ông trở thành một trong những gương mặt tiêu biểu của nền mỹ thuật cách mạng Việt Nam, với những tác phẩm được nhiều người biết đến như bức sơn mài Nhớ một chiều Tây Bắc và tranh Gặt ở Việt Bắc, phản ánh đời sống kháng chiến và hình ảnh Việt Bắc đã in sâu vào ký ức ông từ những năm tháng ấy. Ông còn được biết đến với những bức biếm họa chính trị sắc sảo trên báo, ký dưới bút danh Phan Kích. Phan Kế An qua đời năm 2018, thọ chín mươi lăm tuổi, khép lại một cuộc đời gắn liền với cây bút vẽ và những biến động lớn của đất nước, trong đó ký ức về những ngày ký họa Bác Hồ giữa rừng Việt Bắc luôn được ông nhắc tới như một trong những kỷ niệm đáng nhớ nhất.","doc":7},{"loai":"anh","src":"textures/bang_w/G15_8_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Họa sĩ Phan Kế An ký họa Bác tại Việt Bắc, 11/1948”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Bức ảnh chụp lại khoảnh khắc Phan Kế An ký họa Chủ tịch Hồ Chí Minh, cùng một số bản ký họa còn lưu giữ được, ngày nay là những tư liệu quý được giới thiệu tại các bảo tàng và không gian trưng bày về cuộc đời hoạt động cách mạng của Người, trong đó có Bảo tàng Hồ Chí Minh và Bảo tàng Mỹ thuật Việt Nam. Với khách tham quan hôm nay, đó không chỉ là một tác phẩm mỹ thuật, mà còn là một lát cắt hiếm hoi cho thấy hình ảnh đời thường, giản dị của một vị lãnh tụ giữa những năm tháng kháng chiến gian khổ nhất — khi máy ảnh còn hiếm, và mỗi nét vẽ trực tiếp từ người thật đều trở thành chứng tích lịch sử.","doc":8},{"loai":"ban_co_biet","text":"Trong kháng chiến chống Pháp, rất nhiều họa sĩ, nhạc sĩ, nhà văn, nhà thơ đã lên Việt Bắc; khẩu hiệu của giới văn nghệ thời ấy là “kháng chiến hóa văn hóa, văn hóa hóa kháng chiến”.","nguon_ten":"Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","doc":9},{"loai":"ban_co_biet","text":"Ngoài ký họa chân dung, Phan Kế An còn ký nhiều tranh biếm họa chính trị dưới bút danh Phan Kích — khác hẳn phong cách trữ tình của những bức ký họa Bác Hồ giữa chiến khu.","nguon_ten":"Báo Dân trí; Báo Nhân Dân điện tử","doc":10},{"loai":"trich","text":"Văn hóa nghệ thuật cũng là một mặt trận. Anh chị em là chiến sĩ trên mặt trận ấy.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Thư gửi các họa sĩ nhân dịp triển lãm hội họa năm 1951","doc":11}],"nguon":["Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","Báo Nhân Dân điện tử, “Chuyện của họa sĩ đầu tiên ký họa chân dung Bác Hồ” (nhandan.vn)","Báo Dân trí, “Họa sĩ ‘đại thụ’ của nền mỹ thuật Việt Nam qua đời ở tuổi 95” (dantri.com.vn)","Bảo tàng Mỹ thuật Việt Nam","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia"],"doc":[{"t":"Ký họa giữa rừng: hơn hai mươi bức vẽ Bác Hồ từ người thật. Một ngày cuối thu năm 1948, giữa rừng Khuôn Tát, một họa sĩ trẻ được gọi đến bên Chủ tịch Hồ Chí Minh, mang theo giấy bút. Không có người mẫu ngồi yên, không có buổi tạo dáng: Người vẫn làm việc, đi lại, trò chuyện, còn họa sĩ phải vẽ thật nhanh để bắt được dáng hình chân thực nhất. Hơn hai mươi bức tốc họa ra đời trong ít ngày ngắn ngủi ấy, và một trong số chúng đã trở thành bức ký họa Bác Hồ đầu tiên được đăng báo công khai."},{"t":"Người được gọi đến Khuôn Tát. Cuối thu năm 1948, tại Khuôn Tát, một địa điểm trong An toàn khu Định Hóa (Thái Nguyên), họa sĩ Phan Kế An — khi ấy còn là một chàng trai ngoài hai mươi tuổi — nhận được một cơ hội hiếm có: được đến gần để ký họa Chủ tịch Hồ Chí Minh. Giữa những năm chiến khu phải giữ bí mật tuyệt đối về nơi ở và lịch làm việc của Người, việc một người ngoài được phép đến gần, quan sát và vẽ trực tiếp là điều không nhiều họa sĩ có được. Ông không có nhiều thời gian: Người vẫn làm việc, đọc tài liệu, đi lại giữa lán và vườn, còn cây bút của họa sĩ phải đuổi theo từng cử chỉ, dáng ngồi, nét mặt. Không có buổi ngồi mẫu, không có ánh đèn sân khấu — chỉ có ánh sáng tự nhiên của núi rừng và sự tập trung cao độ của người cầm bút. Chính hoàn cảnh đặc biệt ấy khiến những bức ký họa ra đời từ ít ngày ở Khuôn Tát trở thành một trong những tư liệu hình ảnh quý hiếm và chân thực nhất về Chủ tịch Hồ Chí Minh giữa những năm kháng chiến gian khổ."},{"t":"Từ dinh Khâm sai đến chiến khu Việt Bắc. Phan Kế An là con trai của Phan Kế Toại, người từng giữ chức Khâm sai đại thần Bắc Kỳ dưới chính phủ Trần Trọng Kim năm 1945, và sau Cách mạng Tháng Tám trở thành Bộ trưởng Bộ Nội vụ rồi Phó Thủ tướng Chính phủ nước Việt Nam Dân chủ Cộng hòa. Sinh ra trong một gia đình quan lại có học, nhưng Phan Kế An chọn con đường của một họa sĩ dấn thân theo kháng chiến, cùng nhiều văn nghệ sĩ cùng thế hệ rời phố thị lên chiến khu, mang theo giấy, bút chì, màu nước thay cho súng đạn. Ở Việt Bắc, ông vừa vẽ tranh cổ động, minh họa báo chí, vừa tham gia các hoạt động của giới văn nghệ kháng chiến. Việc một họa sĩ trẻ xuất thân từ một gia đình từng phục vụ trong bộ máy quan lại cũ lại trở thành người trực tiếp ký họa Chủ tịch Hồ Chí Minh giữa chiến khu, tự nó cũng là một câu chuyện nhỏ phản chiếu tinh thần đại đoàn kết dân tộc mà Người luôn kêu gọi trong những năm đầu kháng chiến."},{"t":"Hơn hai mươi bức tốc họa. Theo lời kể của chính họa sĩ về sau, trong ít ngày ở Khuôn Tát ông đã vẽ hơn hai mươi bức tốc họa và một bức vẽ kỹ hơn về Chủ tịch Hồ Chí Minh. Tốc họa là lối vẽ nhanh, chỉ bằng vài nét bút, đòi hỏi người vẽ phải quan sát cực nhanh và ghi lại thần thái nhân vật gần như tức thời, không có cơ hội sửa lại. Trong số những bức ấy, một bức ký họa đơn sơ bằng bút sắt đã được chọn đăng trên báo Sự Thật vào tháng 12 năm 1948 — trở thành bức ký họa Bác Hồ đầu tiên được công bố công khai trên mặt báo. Với độc giả và cán bộ, chiến sĩ ở khắp các mặt trận, đó là một trong những hình ảnh hiếm hoi giúp họ hình dung được gương mặt vị Chủ tịch nước giữa những năm chiến khu, khi ảnh chụp còn rất hạn chế và phải giữ bí mật."},{"t":"Nét vẽ giữ lại đời thường. Khác với những bức chân dung được vẽ lại sau này từ trí nhớ hay theo ảnh chụp, ký họa của Phan Kế An có một giá trị riêng: chúng được vẽ trực tiếp từ người thật, ngay trong khoảnh khắc Người đang sống và làm việc bình thường. Vì thế, nét bút giữ được sự giản dị, gần gũi — dáng ngồi hơi nghiêng khi đọc tài liệu, ánh mắt khi trò chuyện, bộ quần áo kaki bạc màu quen thuộc — thay vì vẻ trang trọng, tĩnh tại thường thấy ở tranh chân dung chính thức. Nhiều nhà nghiên cứu mỹ thuật sau này xem đây là một trong những bộ ký họa có giá trị tư liệu lịch sử cao về hình ảnh đời thường của Chủ tịch Hồ Chí Minh trong giai đoạn kháng chiến chống Pháp, khi phần lớn hình ảnh chính thức về Người còn rất ít ỏi. Cũng vì được vẽ ngay tại chỗ, không qua dàn dựng, những bức tốc họa còn vô tình ghi lại cả khung cảnh chung quanh: mái lán nứa, khoảnh sân đất, dáng núi phía xa — những chi tiết mà một bức ảnh chụp chính thức, thường được sắp đặt kỹ hơn, khó có thể giữ lại trọn vẹn. Với người xem hôm nay, đó là một cách hình dung không gian sống thực của Người ở chiến khu, sống động hơn nhiều so với những mô tả bằng lời."},{"t":"Văn nghệ sĩ giữa chiến khu. Câu chuyện của Phan Kế An không phải là cá biệt. Suốt những năm kháng chiến chống Pháp, rất đông họa sĩ, nhạc sĩ, nhà văn, nhà thơ đã rời Hà Nội, rời các đô thị để lên Việt Bắc, mang nghề nghiệp của mình phục vụ kháng chiến: người vẽ tranh cổ động, người sáng tác nhạc, người viết báo, làm thơ động viên bộ đội và nhân dân. Khẩu hiệu phổ biến trong giới văn nghệ thời ấy là đưa văn hóa hòa vào cuộc kháng chiến và biến kháng chiến thành nguồn cảm hứng sáng tạo. Trong bối cảnh ấy, việc Chủ tịch Hồ Chí Minh dành thời gian, dù ít ỏi giữa bộn bề công việc, để một họa sĩ trẻ được đến gần ký họa mình, cũng là một cách Người thể hiện sự trân trọng đối với vai trò của văn nghệ sĩ trong cuộc kháng chiến toàn dân."},{"t":"Một mặt trận không tiếng súng. Ba năm sau, năm 1951, Chủ tịch Hồ Chí Minh có thư gửi các họa sĩ nhân dịp một triển lãm hội họa, trong đó Người khẳng định văn hóa nghệ thuật cũng là một mặt trận và những người làm nghệ thuật là chiến sĩ trên mặt trận ấy. Với những họa sĩ từng có mặt ở Việt Bắc như Phan Kế An, lời khẳng định ấy không chỉ là một câu nói mang tính cổ vũ, mà đúc kết chính trải nghiệm họ đã sống: cầm bút vẽ giữa rừng, dưới bom đạn, để ghi lại gương mặt cuộc kháng chiến và gương mặt vị lãnh tụ của dân tộc, cũng là một cách chiến đấu không kém phần thầm lặng. Nhiều tác phẩm ra đời từ Việt Bắc thời kỳ ấy — tranh cổ động, ký họa, bài hát, bài thơ — về sau trở thành một phần di sản văn hóa của cuộc kháng chiến chống Pháp, được nhắc lại trong sách vở, bảo tàng và các chương trình giáo dục lịch sử cho nhiều thế hệ sau."},{"t":"Từ ký họa đến sự nghiệp mỹ thuật cách mạng. Những ngày ở Khuôn Tát chỉ là một chương trong sự nghiệp dài của Phan Kế An. Về sau, ông trở thành một trong những gương mặt tiêu biểu của nền mỹ thuật cách mạng Việt Nam, với những tác phẩm được nhiều người biết đến như bức sơn mài Nhớ một chiều Tây Bắc và tranh Gặt ở Việt Bắc, phản ánh đời sống kháng chiến và hình ảnh Việt Bắc đã in sâu vào ký ức ông từ những năm tháng ấy. Ông còn được biết đến với những bức biếm họa chính trị sắc sảo trên báo, ký dưới bút danh Phan Kích. Phan Kế An qua đời năm 2018, thọ chín mươi lăm tuổi, khép lại một cuộc đời gắn liền với cây bút vẽ và những biến động lớn của đất nước, trong đó ký ức về những ngày ký họa Bác Hồ giữa rừng Việt Bắc luôn được ông nhắc tới như một trong những kỷ niệm đáng nhớ nhất."},{"t":"Dấu tích hôm nay. Bức ảnh chụp lại khoảnh khắc Phan Kế An ký họa Chủ tịch Hồ Chí Minh, cùng một số bản ký họa còn lưu giữ được, ngày nay là những tư liệu quý được giới thiệu tại các bảo tàng và không gian trưng bày về cuộc đời hoạt động cách mạng của Người, trong đó có Bảo tàng Hồ Chí Minh và Bảo tàng Mỹ thuật Việt Nam. Với khách tham quan hôm nay, đó không chỉ là một tác phẩm mỹ thuật, mà còn là một lát cắt hiếm hoi cho thấy hình ảnh đời thường, giản dị của một vị lãnh tụ giữa những năm tháng kháng chiến gian khổ nhất — khi máy ảnh còn hiếm, và mỗi nét vẽ trực tiếp từ người thật đều trở thành chứng tích lịch sử."},{"t":"Bạn có biết? Trong kháng chiến chống Pháp, rất nhiều họa sĩ, nhạc sĩ, nhà văn, nhà thơ đã lên Việt Bắc; khẩu hiệu của giới văn nghệ thời ấy là “kháng chiến hóa văn hóa, văn hóa hóa kháng chiến”."},{"t":"Bạn có biết? Ngoài ký họa chân dung, Phan Kế An còn ký nhiều tranh biếm họa chính trị dưới bút danh Phan Kích — khác hẳn phong cách trữ tình của những bức ký họa Bác Hồ giữa chiến khu."},{"t":"Văn hóa nghệ thuật cũng là một mặt trận. Anh chị em là chiến sĩ trên mặt trận ấy. — Chủ tịch Hồ Chí Minh"}],"so_chu":1644},{"i":9,"tieu_de_bang":"An toàn khu Định Hóa, Thái Nguyên ngày nay","tieu_de":"Định Hóa hôm nay: về “Thủ đô gió ngàn” nghe núi rừng kể chuyện","sapo":"Tấm ảnh chụp năm 2007 ghi lại một góc An toàn khu Định Hóa hôm nay: đồi núi trập trùng, rừng cọ và nương chè trải dài yên ả. Ít ai hình dung được rằng suốt chín năm, giữa khung cảnh bình lặng ấy, cơ quan đầu não của cả một cuộc kháng chiến đã từng ẩn mình. Hôm nay, những mái lán năm xưa đã trở thành di tích, còn vùng đất này mang một tên gọi thân thương: Thủ đô gió ngàn.","bia":{"src":"textures/ht/ht_anh_atk_dinh_hoa.jpg","credit":"Ảnh: Viethavvh at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Bức ảnh của một vùng đất lặng lẽ","text":"Bức ảnh được chụp năm 2007 tại khu vực An toàn khu Định Hóa, tỉnh Thái Nguyên, do một cộng tác viên của Wikipedia tiếng Việt thực hiện và công bố ở chế độ phạm vi công cộng. Trong ảnh là một góc cảnh quan điển hình của vùng đất này: đồi núi thấp nối tiếp nhau, xen giữa là ruộng bậc thang, nương chè và những vạt rừng cọ đặc trưng của trung du Bắc Bộ. Không có gì trong khung hình gợi nhắc trực tiếp đến một cuộc chiến tranh đã qua, nhưng chính sự lặng lẽ, kín đáo của địa hình ấy từng là điều kiện sống còn giúp cơ quan đầu não kháng chiến tồn tại an toàn suốt gần một thập kỷ.","doc":1},{"loai":"doan","tieu_de":"Định Hóa trong chín năm kháng chiến","text":"Thời kháng chiến chống Pháp, Định Hóa là một huyện miền núi của tỉnh Thái Nguyên, giáp ranh Tuyên Quang và Bắc Kạn, địa hình chủ yếu là đồi núi thấp, thung lũng hẹp, dân cư thưa. Từ tháng 5 năm 1947, Chủ tịch Hồ Chí Minh cùng các cơ quan Trung ương Đảng, Chính phủ chọn nơi đây, cùng một số vùng lân cận thuộc Tuyên Quang, Bắc Kạn, làm An toàn khu — trung tâm chỉ đạo cuộc kháng chiến toàn quốc. Đồng bào các dân tộc Tày, Nùng, Dao, Kinh sinh sống ở đây đã một lòng che chở, nuôi giấu cán bộ, giữ bí mật tuyệt đối trước sự truy lùng của quân Pháp. Cũng bởi từng là nơi đặt cơ quan đầu não của cả nước suốt những năm tháng ấy, vùng đất này về sau được nhân dân gọi bằng cái tên đầy trân trọng: Thủ đô gió ngàn.\n\nSở dĩ Định Hóa được chọn làm trung tâm An toàn khu, bên cạnh yếu tố địa hình hiểm trở dễ phòng thủ, còn vì đây là vùng đất có truyền thống cách mạng từ trước Cách mạng Tháng Tám, với các cơ sở quần chúng đã được xây dựng từ những năm hoạt động bí mật. Đường sá thời ấy còn rất khó đi, chủ yếu là đường mòn xuyên rừng, khiến việc hành quân, càn quét quy mô lớn của quân Pháp gặp nhiều trở ngại, trong khi cán bộ, bộ đội quen địa hình lại có thể di chuyển nhanh giữa các bản làng.","doc":2},{"loai":"doan","tieu_de":"Những địa danh trong ký ức","text":"Trong địa bàn Định Hóa có nhiều địa điểm gắn liền với những năm tháng Chủ tịch Hồ Chí Minh sống và làm việc: lán Khuôn Tát, nơi Người từng ở và cũng là nơi họa sĩ Phan Kế An ký họa Người năm 1948 (xem chuyên đề Họa sĩ Phan Kế An ký họa Bác tại Việt Bắc); đồi Tỉn Keo, nơi Bộ Chính trị họp ngày 6 tháng 12 năm 1953 quyết định mở Chiến dịch Điện Biên Phủ; cùng nhiều lán trại khác rải rác quanh vùng. Từ Định Hóa, con đèo De dẫn sang Sơn Dương, Tuyên Quang, nơi có Tân Trào — địa danh gắn với những ngày Tổng khởi nghĩa Tháng Tám năm 1945. Mỗi địa điểm riêng lẻ chỉ là một căn lán nhỏ giữa rừng, nhưng khi đặt cạnh nhau, chúng vẽ nên bản đồ di chuyển của một cơ quan lãnh đạo luôn phải đổi chỗ để giữ bí mật.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_atk_dinh_hoa.jpg","chu_thich":"An toàn khu Định Hóa, Thái Nguyên, ảnh chụp năm 2007.","credit":"Ảnh: Viethavvh at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Được xếp hạng Di tích quốc gia đặc biệt","text":"Ghi nhận giá trị lịch sử đặc biệt của vùng đất này, ngày 10 tháng 5 năm 2012, Thủ tướng Chính phủ ký Quyết định số 548/QĐ-TTg xếp hạng An toàn khu Định Hóa là Di tích quốc gia đặc biệt, với 13 di tích thành phần. Trong số đó có nhiều địa danh gắn liền với Chủ tịch Hồ Chí Minh như đồi Khau Tý, đồi Tỉn Keo, Khuôn Tát, đồi Pụ Đồn, các địa điểm ghi dấu hoạt động của cơ quan Đảng, Chính phủ, Quân đội thời kháng chiến, cùng Nhà tù Chợ Chu — nơi thực dân Pháp từng giam giữ nhiều chiến sĩ cách mạng trước đó. Việc được xếp hạng ở cấp quốc gia đặc biệt khẳng định vị trí của An toàn khu Định Hóa trong hệ thống di tích quan trọng bậc nhất của đất nước.","doc":4},{"loai":"anh","src":"textures/bang_w/G15_9_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “An toàn khu Định Hóa, Thái Nguyên ngày nay”, nhìn từ xa."},{"loai":"doan","tieu_de":"Một di tích sống giữa đời thường","text":"Khác với nhiều di tích chỉ còn lại phế tích, An toàn khu Định Hóa vẫn là một vùng đất có người ở, có đồi chè, nương lúa, sinh hoạt thường nhật diễn ra ngay bên cạnh các điểm di tích. Nhiều căn lán đã được phục dựng theo đúng lối cũ: vách nứa, mái lá cọ, sàn tre, nằm lọt giữa những tán rừng và sườn đồi như nguyên trạng những năm kháng chiến. Khách đến tham quan có thể đi trên những lối mòn Người từng qua lại, đứng trước căn lán nơi ra đời quyết định lịch sử về Chiến dịch Điện Biên Phủ, để cảm nhận vì sao một vùng quê núi nhỏ bé, lặng lẽ như trong tấm ảnh, lại có thể che chở an toàn cho cả một cơ quan đầu não suốt nhiều năm giữa vòng vây của đối phương.","doc":5},{"loai":"anh","src":"textures/bang_w/G15_9_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “An toàn khu Định Hóa, Thái Nguyên ngày nay”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Đồi chè nuôi cả chiến khu lẫn đời sống hôm nay","text":"Rừng cọ, đồi chè không chỉ là cảnh quan đặc trưng của Định Hóa mà từng là nguồn sống thiết thực nuôi cơ quan kháng chiến suốt chín năm: lá cọ lợp mái lán, thân cọ, thân nứa dựng nhà, còn nương chè, nương lúa của đồng bào góp phần nuôi cán bộ, bộ đội trong những năm lương thực khan hiếm. Ngày nay, chè vẫn là cây trồng chủ lực của Định Hóa và cả tỉnh Thái Nguyên, mang lại thu nhập cho nhiều hộ dân trong vùng, đồng thời tạo nên cảnh quan đồi chè xanh mướt quen thuộc mà du khách thường bắt gặp khi ghé thăm các điểm di tích. Có thể nói, chính mảnh đất từng che chở kháng chiến hôm nay vẫn đang tiếp tục nuôi sống những người đang gìn giữ ký ức về nó.","doc":6},{"loai":"doan","tieu_de":"Thủ đô gió ngàn trong thơ ca","text":"Tên gọi Thủ đô gió ngàn và hình ảnh Việt Bắc nói chung đã đi vào văn học kháng chiến, tiêu biểu nhất là bài thơ Việt Bắc của nhà thơ Tố Hữu, sáng tác vào tháng 10 năm 1954, khi Trung ương Đảng và Chính phủ chuẩn bị rời chiến khu về tiếp quản Thủ đô Hà Nội. Bài thơ được viết theo thể lục bát, mang âm hưởng của những khúc hát giao duyên, nhưng lại nói về một cuộc chia tay lịch sử: giữa cán bộ kháng chiến với núi rừng, với đồng bào các dân tộc Việt Bắc đã cưu mang, che chở suốt chín năm. Đây cũng là một trong những tác phẩm tiêu biểu nhất của thơ ca cách mạng Việt Nam viết về tình quân dân trong kháng chiến chống Pháp.","doc":7},{"loai":"trich","text":"Mình về mình có nhớ ta / Mười lăm năm ấy thiết tha mặn nồng / Mình về mình có nhớ không / Nhìn cây nhớ núi, nhìn sông nhớ nguồn.","nguoi":"Nhà thơ Tố Hữu","nguon_ten":"Bài thơ “Việt Bắc”, tháng 10 năm 1954","doc":8},{"loai":"doan","tieu_de":"Đi tìm Thủ đô gió ngàn hôm nay","text":"Ngày nay, du khách đến Định Hóa thường bắt đầu hành trình từ trung tâm huyện, theo các tuyến đường liên xã để đến những điểm di tích chính như Khuôn Tát, Tỉn Keo, nhà trưng bày ATK. Nhiều đoàn học sinh, sinh viên, cựu chiến binh chọn nơi đây làm điểm về nguồn, tìm hiểu lịch sử ngay tại không gian nó từng diễn ra, thay vì chỉ đọc qua sách vở. Chính sự kết hợp giữa cảnh quan thiên nhiên còn khá nguyên vẹn, hệ thống di tích được bảo tồn và những câu chuyện lịch sử cụ thể gắn với từng địa điểm đã khiến An toàn khu Định Hóa trở thành một trong những địa chỉ về nguồn quan trọng nhất của cả nước, chứ không chỉ là một điểm dừng chân trong hành trình tìm hiểu về Chủ tịch Hồ Chí Minh.\n\nNhiều gia đình ở các xã trong vùng lõi di tích, hậu duệ của những người từng nuôi giấu cán bộ năm xưa, ngày nay vẫn kể lại cho con cháu và du khách nghe những câu chuyện được truyền lại từ ông bà về những năm tháng bộ đội, cán bộ ở nhờ nhà, ăn cùng mâm, ngủ cùng sàn. Những câu chuyện truyền miệng ấy, dù không phải lúc nào cũng được ghi chép đầy đủ trong sử sách, vẫn góp phần làm sống động thêm bức tranh về một vùng đất từng là hậu phương vững chắc của cả nước.","doc":9},{"loai":"anh","src":"textures/bang_w/G15_9_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “An toàn khu Định Hóa, Thái Nguyên ngày nay”, nhìn từ trên cao."},{"loai":"ban_co_biet","text":"Thuật ngữ “An toàn khu” (ATK) đã được dùng từ trước Cách mạng Tháng Tám: những năm 1941 – 1945, Trung ương Đảng có các An toàn khu ở vùng ven Hà Nội và các tỉnh lân cận.","nguon_ten":"Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","doc":10},{"loai":"ban_co_biet","text":"Ngoài An toàn khu Định Hóa, thời kháng chiến chống Pháp còn có An toàn khu Chợ Đồn (Bắc Kạn) — cho thấy hệ thống An toàn khu của Trung ương trải rộng trên nhiều tỉnh liền kề, chứ không gói gọn trong một địa điểm.","nguon_ten":"Cục Di sản văn hóa, Bộ Văn hóa, Thể thao và Du lịch (dsvh.gov.vn)","doc":11}],"nguon":["Cục Di sản văn hóa, Bộ Văn hóa, Thể thao và Du lịch — Di tích lịch sử An toàn khu (ATK) Định Hóa (dsvh.gov.vn)","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Tố Hữu, bài thơ “Việt Bắc” (tháng 10/1954)","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Khu Di tích lịch sử ATK Định Hóa (Thái Nguyên)"],"doc":[{"t":"Định Hóa hôm nay: về “Thủ đô gió ngàn” nghe núi rừng kể chuyện. Tấm ảnh chụp năm 2007 ghi lại một góc An toàn khu Định Hóa hôm nay: đồi núi trập trùng, rừng cọ và nương chè trải dài yên ả. Ít ai hình dung được rằng suốt chín năm, giữa khung cảnh bình lặng ấy, cơ quan đầu não của cả một cuộc kháng chiến đã từng ẩn mình. Hôm nay, những mái lán năm xưa đã trở thành di tích, còn vùng đất này mang một tên gọi thân thương: Thủ đô gió ngàn."},{"t":"Bức ảnh của một vùng đất lặng lẽ. Bức ảnh được chụp năm 2007 tại khu vực An toàn khu Định Hóa, tỉnh Thái Nguyên, do một cộng tác viên của Wikipedia tiếng Việt thực hiện và công bố ở chế độ phạm vi công cộng. Trong ảnh là một góc cảnh quan điển hình của vùng đất này: đồi núi thấp nối tiếp nhau, xen giữa là ruộng bậc thang, nương chè và những vạt rừng cọ đặc trưng của trung du Bắc Bộ. Không có gì trong khung hình gợi nhắc trực tiếp đến một cuộc chiến tranh đã qua, nhưng chính sự lặng lẽ, kín đáo của địa hình ấy từng là điều kiện sống còn giúp cơ quan đầu não kháng chiến tồn tại an toàn suốt gần một thập kỷ."},{"t":"Định Hóa trong chín năm kháng chiến. Thời kháng chiến chống Pháp, Định Hóa là một huyện miền núi của tỉnh Thái Nguyên, giáp ranh Tuyên Quang và Bắc Kạn, địa hình chủ yếu là đồi núi thấp, thung lũng hẹp, dân cư thưa. Từ tháng 5 năm 1947, Chủ tịch Hồ Chí Minh cùng các cơ quan Trung ương Đảng, Chính phủ chọn nơi đây, cùng một số vùng lân cận thuộc Tuyên Quang, Bắc Kạn, làm An toàn khu — trung tâm chỉ đạo cuộc kháng chiến toàn quốc. Đồng bào các dân tộc Tày, Nùng, Dao, Kinh sinh sống ở đây đã một lòng che chở, nuôi giấu cán bộ, giữ bí mật tuyệt đối trước sự truy lùng của quân Pháp. Cũng bởi từng là nơi đặt cơ quan đầu não của cả nước suốt những năm tháng ấy, vùng đất này về sau được nhân dân gọi bằng cái tên đầy trân trọng: Thủ đô gió ngàn. Sở dĩ Định Hóa được chọn làm trung tâm An toàn khu, bên cạnh yếu tố địa hình hiểm trở dễ phòng thủ, còn vì đây là vùng đất có truyền thống cách mạng từ trước Cách mạng Tháng Tám, với các cơ sở quần chúng đã được xây dựng từ những năm hoạt động bí mật. Đường sá thời ấy còn rất khó đi, chủ yếu là đường mòn xuyên rừng, khiến việc hành quân, càn quét quy mô lớn của quân Pháp gặp nhiều trở ngại, trong khi cán bộ, bộ đội quen địa hình lại có thể di chuyển nhanh giữa các bản làng."},{"t":"Những địa danh trong ký ức. Trong địa bàn Định Hóa có nhiều địa điểm gắn liền với những năm tháng Chủ tịch Hồ Chí Minh sống và làm việc: lán Khuôn Tát, nơi Người từng ở và cũng là nơi họa sĩ Phan Kế An ký họa Người năm 1948 (xem chuyên đề Họa sĩ Phan Kế An ký họa Bác tại Việt Bắc); đồi Tỉn Keo, nơi Bộ Chính trị họp ngày 6 tháng 12 năm 1953 quyết định mở Chiến dịch Điện Biên Phủ; cùng nhiều lán trại khác rải rác quanh vùng. Từ Định Hóa, con đèo De dẫn sang Sơn Dương, Tuyên Quang, nơi có Tân Trào — địa danh gắn với những ngày Tổng khởi nghĩa Tháng Tám năm 1945. Mỗi địa điểm riêng lẻ chỉ là một căn lán nhỏ giữa rừng, nhưng khi đặt cạnh nhau, chúng vẽ nên bản đồ di chuyển của một cơ quan lãnh đạo luôn phải đổi chỗ để giữ bí mật."},{"t":"Được xếp hạng Di tích quốc gia đặc biệt. Ghi nhận giá trị lịch sử đặc biệt của vùng đất này, ngày 10 tháng 5 năm 2012, Thủ tướng Chính phủ ký Quyết định số 548/QĐ-TTg xếp hạng An toàn khu Định Hóa là Di tích quốc gia đặc biệt, với 13 di tích thành phần. Trong số đó có nhiều địa danh gắn liền với Chủ tịch Hồ Chí Minh như đồi Khau Tý, đồi Tỉn Keo, Khuôn Tát, đồi Pụ Đồn, các địa điểm ghi dấu hoạt động của cơ quan Đảng, Chính phủ, Quân đội thời kháng chiến, cùng Nhà tù Chợ Chu — nơi thực dân Pháp từng giam giữ nhiều chiến sĩ cách mạng trước đó. Việc được xếp hạng ở cấp quốc gia đặc biệt khẳng định vị trí của An toàn khu Định Hóa trong hệ thống di tích quan trọng bậc nhất của đất nước."},{"t":"Một di tích sống giữa đời thường. Khác với nhiều di tích chỉ còn lại phế tích, An toàn khu Định Hóa vẫn là một vùng đất có người ở, có đồi chè, nương lúa, sinh hoạt thường nhật diễn ra ngay bên cạnh các điểm di tích. Nhiều căn lán đã được phục dựng theo đúng lối cũ: vách nứa, mái lá cọ, sàn tre, nằm lọt giữa những tán rừng và sườn đồi như nguyên trạng những năm kháng chiến. Khách đến tham quan có thể đi trên những lối mòn Người từng qua lại, đứng trước căn lán nơi ra đời quyết định lịch sử về Chiến dịch Điện Biên Phủ, để cảm nhận vì sao một vùng quê núi nhỏ bé, lặng lẽ như trong tấm ảnh, lại có thể che chở an toàn cho cả một cơ quan đầu não suốt nhiều năm giữa vòng vây của đối phương."},{"t":"Đồi chè nuôi cả chiến khu lẫn đời sống hôm nay. Rừng cọ, đồi chè không chỉ là cảnh quan đặc trưng của Định Hóa mà từng là nguồn sống thiết thực nuôi cơ quan kháng chiến suốt chín năm: lá cọ lợp mái lán, thân cọ, thân nứa dựng nhà, còn nương chè, nương lúa của đồng bào góp phần nuôi cán bộ, bộ đội trong những năm lương thực khan hiếm. Ngày nay, chè vẫn là cây trồng chủ lực của Định Hóa và cả tỉnh Thái Nguyên, mang lại thu nhập cho nhiều hộ dân trong vùng, đồng thời tạo nên cảnh quan đồi chè xanh mướt quen thuộc mà du khách thường bắt gặp khi ghé thăm các điểm di tích. Có thể nói, chính mảnh đất từng che chở kháng chiến hôm nay vẫn đang tiếp tục nuôi sống những người đang gìn giữ ký ức về nó."},{"t":"Thủ đô gió ngàn trong thơ ca. Tên gọi Thủ đô gió ngàn và hình ảnh Việt Bắc nói chung đã đi vào văn học kháng chiến, tiêu biểu nhất là bài thơ Việt Bắc của nhà thơ Tố Hữu, sáng tác vào tháng 10 năm 1954, khi Trung ương Đảng và Chính phủ chuẩn bị rời chiến khu về tiếp quản Thủ đô Hà Nội. Bài thơ được viết theo thể lục bát, mang âm hưởng của những khúc hát giao duyên, nhưng lại nói về một cuộc chia tay lịch sử: giữa cán bộ kháng chiến với núi rừng, với đồng bào các dân tộc Việt Bắc đã cưu mang, che chở suốt chín năm. Đây cũng là một trong những tác phẩm tiêu biểu nhất của thơ ca cách mạng Việt Nam viết về tình quân dân trong kháng chiến chống Pháp."},{"t":"Mình về mình có nhớ ta / Mười lăm năm ấy thiết tha mặn nồng / Mình về mình có nhớ không / Nhìn cây nhớ núi, nhìn sông nhớ nguồn. — Nhà thơ Tố Hữu"},{"t":"Đi tìm Thủ đô gió ngàn hôm nay. Ngày nay, du khách đến Định Hóa thường bắt đầu hành trình từ trung tâm huyện, theo các tuyến đường liên xã để đến những điểm di tích chính như Khuôn Tát, Tỉn Keo, nhà trưng bày ATK. Nhiều đoàn học sinh, sinh viên, cựu chiến binh chọn nơi đây làm điểm về nguồn, tìm hiểu lịch sử ngay tại không gian nó từng diễn ra, thay vì chỉ đọc qua sách vở. Chính sự kết hợp giữa cảnh quan thiên nhiên còn khá nguyên vẹn, hệ thống di tích được bảo tồn và những câu chuyện lịch sử cụ thể gắn với từng địa điểm đã khiến An toàn khu Định Hóa trở thành một trong những địa chỉ về nguồn quan trọng nhất của cả nước, chứ không chỉ là một điểm dừng chân trong hành trình tìm hiểu về Chủ tịch Hồ Chí Minh. Nhiều gia đình ở các xã trong vùng lõi di tích, hậu duệ của những người từng nuôi giấu cán bộ năm xưa, ngày nay vẫn kể lại cho con cháu và du khách nghe những câu chuyện được truyền lại từ ông bà về những năm tháng bộ đội, cán bộ ở nhờ nhà, ăn cùng mâm, ngủ cùng sàn. Những câu chuyện truyền miệng ấy, dù không phải lúc nào cũng được ghi chép đầy đủ trong sử sách, vẫn góp phần làm sống động thêm bức tranh về một vùng đất từng là hậu phương vững chắc của cả nước."},{"t":"Bạn có biết? Thuật ngữ “An toàn khu” (ATK) đã được dùng từ trước Cách mạng Tháng Tám: những năm 1941 – 1945, Trung ương Đảng có các An toàn khu ở vùng ven Hà Nội và các tỉnh lân cận."},{"t":"Bạn có biết? Ngoài An toàn khu Định Hóa, thời kháng chiến chống Pháp còn có An toàn khu Chợ Đồn (Bắc Kạn) — cho thấy hệ thống An toàn khu của Trung ương trải rộng trên nhiều tỉnh liền kề, chứ không gói gọn trong một địa điểm."}],"so_chu":1568},{"i":10,"tieu_de_bang":"An toàn khu Việt Bắc","tieu_de":"An toàn khu vận hành thế nào? Bí mật, cơ động và lòng dân","sapo":"Làm sao một Chính phủ, một Bộ Tổng tư lệnh có thể hoạt động liên tục suốt nhiều năm, ngay trong tầm với của máy bay trinh sát và những cuộc hành quân càn quét của đối phương? Câu trả lời nằm ở cách An toàn khu Việt Bắc được tổ chức: không phải một cứ điểm cố định, mà là một mạng lưới bí mật, cơ động, dựa vào lòng dân.","bia":{"src":"textures/bai/G15_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một vùng rộng, không một trung tâm cố định","text":"An toàn khu của Trung ương Đảng và Chính phủ trong kháng chiến chống Pháp không phải là một địa điểm duy nhất, mà là cả một vùng địa lý rộng, trải qua nhiều huyện miền núi: Định Hóa (Thái Nguyên), Sơn Dương, Yên Sơn, Chiêm Hóa (Tuyên Quang), Chợ Đồn (Bắc Kạn)… Các cơ quan Đảng, Chính phủ, Bộ Tổng tư lệnh, các bộ, ngành không đóng tập trung một chỗ, mà phân tán ở nhiều xóm bản, cách nhau bởi những quãng đường rừng núi. Chủ tịch Hồ Chí Minh cũng liên tục di chuyển giữa nhiều địa điểm trong vùng: Khuôn Tát, Tỉn Keo (Định Hóa), Kim Quan, Hùng Lợi (Tuyên Quang)… Tháng 2 năm 1951, ngay giữa vùng núi rừng ấy, Đại hội đại biểu toàn quốc lần thứ hai của Đảng vẫn được tổ chức tại Chiêm Hóa, Tuyên Quang, đưa Đảng ra hoạt động công khai trở lại sau nhiều năm phải rút vào bí mật (xem chuyên đề Đại hội II của Đảng tại Chiêm Hóa).","doc":1},{"loai":"doan","tieu_de":"Bí mật là nguyên tắc sống còn","text":"Nguyên tắc hàng đầu chi phối mọi hoạt động trong An toàn khu là giữ bí mật tuyệt đối. Các cơ quan thường xuyên thay đổi nơi đóng, không ở một chỗ quá lâu; lán trại dựng dưới tán rừng rậm, ven suối, sát chân đồi để tránh bị máy bay trinh sát của Pháp phát hiện từ trên cao; các lối đi được ngụy trang kỹ, có khi phải phát quang từng đoạn ngắn để không tạo thành dấu vết rõ rệt nhìn từ trên không. Cán bộ, nhân viên trong vùng chỉ được biết đúng những gì công việc của mình cần biết, hạn chế tối đa việc để lộ vị trí của các cơ quan khác. Nhờ nguyên tắc kỷ luật chặt chẽ ấy, dù quân Pháp nhiều lần mở các cuộc hành quân, thả quân dù hòng đánh úp cơ quan đầu não — như cuộc tấn công lên Việt Bắc thu đông năm 1947 — nhưng đều không đạt được mục tiêu.","doc":2},{"loai":"doan","tieu_de":"Cơ động giữa vòng vây","text":"Bên cạnh bí mật, cơ động là yếu tố sống còn thứ hai. Không một cơ quan nào ở An toàn khu ở cố định một nơi quá lâu; ngay khi có dấu hiệu bị lộ hoặc nguy cơ bị tấn công, toàn bộ người, tài liệu, phương tiện làm việc phải nhanh chóng di chuyển sang địa điểm khác, có khi chỉ trong một đêm. Với Chủ tịch Hồ Chí Minh, việc chuyển chỗ ở diễn ra thường xuyên đến mức những vật dụng cá nhân của Người luôn được giữ ở mức tối giản — một chiếc máy chữ, vài bộ quần áo, một số tài liệu cần thiết — để có thể lên đường bất cứ lúc nào (xem chuyên đề Lán Bác ở và làm việc). Chính sự cơ động ấy, kết hợp với địa hình rừng núi hiểm trở của Việt Bắc, đã khiến quân Pháp, dù nhiều lần biết đại thể khu vực Trung ương kháng chiến đóng quân, vẫn không thể xác định chính xác vị trí để tổ chức một cuộc tấn công quyết định.","doc":3},{"loai":"anh","src":"textures/bang_w/G15_10_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “An toàn khu Việt Bắc”, nhìn từ xa."},{"loai":"doan","tieu_de":"Lòng dân — bức tường không nhìn thấy được","text":"Bí mật và cơ động chỉ có thể duy trì được nhờ một điều kiện quan trọng hơn cả: sự che chở của nhân dân. Đồng bào các dân tộc Tày, Nùng, Dao, Kinh trong vùng đã nhường đất, nhường nhà để bộ đội, cán bộ dựng lán; góp gạo, góp thực phẩm nuôi quân; làm giao liên, dẫn đường qua những cánh rừng quen thuộc; canh gác, báo tin mỗi khi có người lạ hay dấu hiệu khả nghi xuất hiện trong bản. Không một tấm bản đồ quân sự nào của quân Pháp có thể vẽ lại được mạng lưới bảo vệ vô hình ấy — mạng lưới được dựng nên không phải bằng công sự, mà bằng lòng tin và sự gắn bó giữa cách mạng với nhân dân địa phương.\n\nChủ tịch Hồ Chí Minh nhiều lần căn dặn cán bộ, bộ đội đóng quân trong vùng phải tôn trọng phong tục tập quán của đồng bào, giúp đỡ dân trong sản xuất, sinh hoạt, giữ mối quan hệ gắn bó như người một nhà. Chính cách ứng xử ấy, được duy trì suốt nhiều năm, đã củng cố thêm lòng tin của đồng bào các dân tộc dành cho cách mạng, biến mối quan hệ quân dân từ chỗ chỉ dựa vào tuyên truyền thành một sự gắn bó bền chặt trong đời sống hằng ngày.","doc":4},{"loai":"anh","src":"textures/bai/G15_v2.jpg","chu_thich":"Không gian 3D tái hiện An toàn khu Việt Bắc trong gian trưng bày.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Một bộ máy nhà nước vận hành giữa rừng","text":"Không chỉ có cơ quan lãnh đạo cao nhất, cả một bộ máy nhà nước và kháng chiến thu nhỏ đã vận hành giữa núi rừng Việt Bắc suốt chín năm: các bộ, ngành của Chính phủ, Bộ Tổng tư lệnh và các cơ quan quân sự, hệ thống trường học đào tạo cán bộ, xưởng in, cơ quan báo chí, cùng Đài Tiếng nói Việt Nam — cơ quan phát thanh quốc gia khi đó cũng đặt và di chuyển nhiều lần trong vùng căn cứ. Mỗi cơ quan là một mắt xích nhỏ, đóng phân tán, nhưng khi ghép lại đã tạo thành một chính quyền kháng chiến hoàn chỉnh, đủ sức điều hành đất nước, chỉ đạo các mặt trận và duy trì đời sống tinh thần cho quân dân suốt cuộc trường kỳ kháng chiến.\n\nViệc vận hành một bộ máy như vậy giữa rừng núi, không điện, không đường nhựa, không phương tiện liên lạc hiện đại, đòi hỏi một hệ thống giao liên bằng chân, bằng ngựa thồ và bằng những lá thư viết tay chuyển qua nhiều chặng mới tới nơi. Mỗi bức điện, mỗi chỉ thị từ Chủ tịch Hồ Chí Minh hay Bộ Tổng tư lệnh gửi tới các mặt trận xa xôi vì thế đều mang theo công sức âm thầm của rất nhiều giao liên, liên lạc viên không tên tuổi.","doc":5},{"loai":"anh","src":"textures/bang_w/G15_10_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “An toàn khu Việt Bắc”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Từ những nếp lán tới Điện Biên Phủ","text":"Chính từ mạng lưới bí mật, cơ động ấy, những quyết định chiến lược quan trọng nhất của cuộc kháng chiến đã ra đời. Ngày 6 tháng 12 năm 1953, tại lán Tỉn Keo dưới chân đèo De, Bộ Chính trị do Chủ tịch Hồ Chí Minh chủ trì đã họp và quyết định mở Chiến dịch Điện Biên Phủ. Gần năm tháng sau, ngày 7 tháng 5 năm 1954, chiến dịch kết thúc thắng lợi, buộc Pháp phải ký Hiệp định Genève, chấm dứt chiến tranh. Nếu không có một An toàn khu đủ bí mật và cơ động để bảo vệ cơ quan đầu não suốt nhiều năm trước đó, những cuộc họp quyết định vận mệnh đất nước như thế khó có thể diễn ra an toàn giữa vòng vây liên tục của đối phương.","doc":6},{"loai":"doan","tieu_de":"Tháng 10 năm 1954: rời chiến khu","text":"Sau chiến thắng Điện Biên Phủ và Hiệp định Genève, tháng 10 năm 1954, Thủ đô Hà Nội được giải phóng và tiếp quản; cũng trong tháng ấy, Chủ tịch Hồ Chí Minh cùng các cơ quan Trung ương rời Việt Bắc trở về Hà Nội, khép lại chín năm vận hành một bộ máy kháng chiến giữa núi rừng. Với nhiều cán bộ từng gắn bó với An toàn khu, buổi chia tay ấy vừa là niềm vui chiến thắng, vừa mang theo nỗi lưu luyến với núi rừng và đồng bào đã cưu mang mình suốt những năm gian khổ nhất.","doc":7},{"loai":"anh","src":"textures/bang_w/G15_10_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “An toàn khu Việt Bắc”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, dấu tích của mạng lưới An toàn khu năm xưa vẫn còn hiện diện rải rác trên địa bàn nhiều huyện thuộc Thái Nguyên, Tuyên Quang, Bắc Kạn, được quy tụ trong các khu di tích như An toàn khu Định Hóa, An toàn khu Chợ Đồn, cùng nhiều điểm di tích đơn lẻ khác (xem chuyên đề An toàn khu Định Hóa, Thái Nguyên ngày nay). Việc các cơ quan từng phân tán, di chuyển liên tục khiến hệ thống di tích An toàn khu trải rộng trên một không gian lớn, khác với nhiều khu di tích chiến tranh chỉ gói gọn trong một địa điểm — cũng là minh chứng sống động cho chính nguyên tắc bí mật, cơ động đã giúp cơ quan đầu não kháng chiến tồn tại an toàn suốt chín năm.\n\nVới khách tham quan hôm nay, việc đi qua nhiều điểm di tích cách nhau vài cây số đường rừng — thay vì đứng ở một địa điểm duy nhất — cũng là một cách để cảm nhận phần nào những gì cơ quan đầu não kháng chiến từng trải qua: một cuộc sống luôn di chuyển, không bao giờ neo lại quá lâu ở một chỗ.","doc":8},{"loai":"ban_co_biet","text":"Trong kháng chiến chống Pháp, không chỉ cơ quan Đảng, Chính phủ mà cả Bộ Tổng tư lệnh, trường học, xưởng in, cơ quan báo chí và Đài Tiếng nói Việt Nam đều hoạt động trong vùng căn cứ Việt Bắc.","nguon_ten":"Đài Tiếng nói Việt Nam; Khu Di tích lịch sử ATK Định Hóa (Thái Nguyên)","doc":9},{"loai":"ban_co_biet","text":"Tên gọi “An toàn khu” được viết tắt thành ATK — cách viết tắt này vẫn được giữ làm tên gọi chính thức của các khu di tích ngày nay, như ATK Định Hóa (Thái Nguyên), ATK Chợ Đồn (Bắc Kạn), ATK Tân Trào (Tuyên Quang).","nguon_ten":"Cục Di sản văn hóa, Bộ Văn hóa, Thể thao và Du lịch (dsvh.gov.vn)","doc":10}],"nguon":["Khu Di tích lịch sử ATK Định Hóa (Thái Nguyên)","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Tố Hữu, bài thơ “Việt Bắc” (tháng 10/1954)","Đài Tiếng nói Việt Nam"],"doc":[{"t":"An toàn khu vận hành thế nào? Bí mật, cơ động và lòng dân. Làm sao một Chính phủ, một Bộ Tổng tư lệnh có thể hoạt động liên tục suốt nhiều năm, ngay trong tầm với của máy bay trinh sát và những cuộc hành quân càn quét của đối phương? Câu trả lời nằm ở cách An toàn khu Việt Bắc được tổ chức: không phải một cứ điểm cố định, mà là một mạng lưới bí mật, cơ động, dựa vào lòng dân."},{"t":"Một vùng rộng, không một trung tâm cố định. An toàn khu của Trung ương Đảng và Chính phủ trong kháng chiến chống Pháp không phải là một địa điểm duy nhất, mà là cả một vùng địa lý rộng, trải qua nhiều huyện miền núi: Định Hóa (Thái Nguyên), Sơn Dương, Yên Sơn, Chiêm Hóa (Tuyên Quang), Chợ Đồn (Bắc Kạn)… Các cơ quan Đảng, Chính phủ, Bộ Tổng tư lệnh, các bộ, ngành không đóng tập trung một chỗ, mà phân tán ở nhiều xóm bản, cách nhau bởi những quãng đường rừng núi. Chủ tịch Hồ Chí Minh cũng liên tục di chuyển giữa nhiều địa điểm trong vùng: Khuôn Tát, Tỉn Keo (Định Hóa), Kim Quan, Hùng Lợi (Tuyên Quang)… Tháng 2 năm 1951, ngay giữa vùng núi rừng ấy, Đại hội đại biểu toàn quốc lần thứ hai của Đảng vẫn được tổ chức tại Chiêm Hóa, Tuyên Quang, đưa Đảng ra hoạt động công khai trở lại sau nhiều năm phải rút vào bí mật (xem chuyên đề Đại hội II của Đảng tại Chiêm Hóa)."},{"t":"Bí mật là nguyên tắc sống còn. Nguyên tắc hàng đầu chi phối mọi hoạt động trong An toàn khu là giữ bí mật tuyệt đối. Các cơ quan thường xuyên thay đổi nơi đóng, không ở một chỗ quá lâu; lán trại dựng dưới tán rừng rậm, ven suối, sát chân đồi để tránh bị máy bay trinh sát của Pháp phát hiện từ trên cao; các lối đi được ngụy trang kỹ, có khi phải phát quang từng đoạn ngắn để không tạo thành dấu vết rõ rệt nhìn từ trên không. Cán bộ, nhân viên trong vùng chỉ được biết đúng những gì công việc của mình cần biết, hạn chế tối đa việc để lộ vị trí của các cơ quan khác. Nhờ nguyên tắc kỷ luật chặt chẽ ấy, dù quân Pháp nhiều lần mở các cuộc hành quân, thả quân dù hòng đánh úp cơ quan đầu não — như cuộc tấn công lên Việt Bắc thu đông năm 1947 — nhưng đều không đạt được mục tiêu."},{"t":"Cơ động giữa vòng vây. Bên cạnh bí mật, cơ động là yếu tố sống còn thứ hai. Không một cơ quan nào ở An toàn khu ở cố định một nơi quá lâu; ngay khi có dấu hiệu bị lộ hoặc nguy cơ bị tấn công, toàn bộ người, tài liệu, phương tiện làm việc phải nhanh chóng di chuyển sang địa điểm khác, có khi chỉ trong một đêm. Với Chủ tịch Hồ Chí Minh, việc chuyển chỗ ở diễn ra thường xuyên đến mức những vật dụng cá nhân của Người luôn được giữ ở mức tối giản — một chiếc máy chữ, vài bộ quần áo, một số tài liệu cần thiết — để có thể lên đường bất cứ lúc nào (xem chuyên đề Lán Bác ở và làm việc). Chính sự cơ động ấy, kết hợp với địa hình rừng núi hiểm trở của Việt Bắc, đã khiến quân Pháp, dù nhiều lần biết đại thể khu vực Trung ương kháng chiến đóng quân, vẫn không thể xác định chính xác vị trí để tổ chức một cuộc tấn công quyết định."},{"t":"Lòng dân — bức tường không nhìn thấy được. Bí mật và cơ động chỉ có thể duy trì được nhờ một điều kiện quan trọng hơn cả: sự che chở của nhân dân. Đồng bào các dân tộc Tày, Nùng, Dao, Kinh trong vùng đã nhường đất, nhường nhà để bộ đội, cán bộ dựng lán; góp gạo, góp thực phẩm nuôi quân; làm giao liên, dẫn đường qua những cánh rừng quen thuộc; canh gác, báo tin mỗi khi có người lạ hay dấu hiệu khả nghi xuất hiện trong bản. Không một tấm bản đồ quân sự nào của quân Pháp có thể vẽ lại được mạng lưới bảo vệ vô hình ấy — mạng lưới được dựng nên không phải bằng công sự, mà bằng lòng tin và sự gắn bó giữa cách mạng với nhân dân địa phương. Chủ tịch Hồ Chí Minh nhiều lần căn dặn cán bộ, bộ đội đóng quân trong vùng phải tôn trọng phong tục tập quán của đồng bào, giúp đỡ dân trong sản xuất, sinh hoạt, giữ mối quan hệ gắn bó như người một nhà. Chính cách ứng xử ấy, được duy trì suốt nhiều năm, đã củng cố thêm lòng tin của đồng bào các dân tộc dành cho cách mạng, biến mối quan hệ quân dân từ chỗ chỉ dựa vào tuyên truyền thành một sự gắn bó bền chặt trong đời sống hằng ngày."},{"t":"Một bộ máy nhà nước vận hành giữa rừng. Không chỉ có cơ quan lãnh đạo cao nhất, cả một bộ máy nhà nước và kháng chiến thu nhỏ đã vận hành giữa núi rừng Việt Bắc suốt chín năm: các bộ, ngành của Chính phủ, Bộ Tổng tư lệnh và các cơ quan quân sự, hệ thống trường học đào tạo cán bộ, xưởng in, cơ quan báo chí, cùng Đài Tiếng nói Việt Nam — cơ quan phát thanh quốc gia khi đó cũng đặt và di chuyển nhiều lần trong vùng căn cứ. Mỗi cơ quan là một mắt xích nhỏ, đóng phân tán, nhưng khi ghép lại đã tạo thành một chính quyền kháng chiến hoàn chỉnh, đủ sức điều hành đất nước, chỉ đạo các mặt trận và duy trì đời sống tinh thần cho quân dân suốt cuộc trường kỳ kháng chiến. Việc vận hành một bộ máy như vậy giữa rừng núi, không điện, không đường nhựa, không phương tiện liên lạc hiện đại, đòi hỏi một hệ thống giao liên bằng chân, bằng ngựa thồ và bằng những lá thư viết tay chuyển qua nhiều chặng mới tới nơi. Mỗi bức điện, mỗi chỉ thị từ Chủ tịch Hồ Chí Minh hay Bộ Tổng tư lệnh gửi tới các mặt trận xa xôi vì thế đều mang theo công sức âm thầm của rất nhiều giao liên, liên lạc viên không tên tuổi."},{"t":"Từ những nếp lán tới Điện Biên Phủ. Chính từ mạng lưới bí mật, cơ động ấy, những quyết định chiến lược quan trọng nhất của cuộc kháng chiến đã ra đời. Ngày 6 tháng 12 năm 1953, tại lán Tỉn Keo dưới chân đèo De, Bộ Chính trị do Chủ tịch Hồ Chí Minh chủ trì đã họp và quyết định mở Chiến dịch Điện Biên Phủ. Gần năm tháng sau, ngày 7 tháng 5 năm 1954, chiến dịch kết thúc thắng lợi, buộc Pháp phải ký Hiệp định Genève, chấm dứt chiến tranh. Nếu không có một An toàn khu đủ bí mật và cơ động để bảo vệ cơ quan đầu não suốt nhiều năm trước đó, những cuộc họp quyết định vận mệnh đất nước như thế khó có thể diễn ra an toàn giữa vòng vây liên tục của đối phương."},{"t":"Tháng 10 năm 1954: rời chiến khu. Sau chiến thắng Điện Biên Phủ và Hiệp định Genève, tháng 10 năm 1954, Thủ đô Hà Nội được giải phóng và tiếp quản; cũng trong tháng ấy, Chủ tịch Hồ Chí Minh cùng các cơ quan Trung ương rời Việt Bắc trở về Hà Nội, khép lại chín năm vận hành một bộ máy kháng chiến giữa núi rừng. Với nhiều cán bộ từng gắn bó với An toàn khu, buổi chia tay ấy vừa là niềm vui chiến thắng, vừa mang theo nỗi lưu luyến với núi rừng và đồng bào đã cưu mang mình suốt những năm gian khổ nhất."},{"t":"Dấu tích hôm nay. Ngày nay, dấu tích của mạng lưới An toàn khu năm xưa vẫn còn hiện diện rải rác trên địa bàn nhiều huyện thuộc Thái Nguyên, Tuyên Quang, Bắc Kạn, được quy tụ trong các khu di tích như An toàn khu Định Hóa, An toàn khu Chợ Đồn, cùng nhiều điểm di tích đơn lẻ khác (xem chuyên đề An toàn khu Định Hóa, Thái Nguyên ngày nay). Việc các cơ quan từng phân tán, di chuyển liên tục khiến hệ thống di tích An toàn khu trải rộng trên một không gian lớn, khác với nhiều khu di tích chiến tranh chỉ gói gọn trong một địa điểm — cũng là minh chứng sống động cho chính nguyên tắc bí mật, cơ động đã giúp cơ quan đầu não kháng chiến tồn tại an toàn suốt chín năm. Với khách tham quan hôm nay, việc đi qua nhiều điểm di tích cách nhau vài cây số đường rừng — thay vì đứng ở một địa điểm duy nhất — cũng là một cách để cảm nhận phần nào những gì cơ quan đầu não kháng chiến từng trải qua: một cuộc sống luôn di chuyển, không bao giờ neo lại quá lâu ở một chỗ."},{"t":"Bạn có biết? Trong kháng chiến chống Pháp, không chỉ cơ quan Đảng, Chính phủ mà cả Bộ Tổng tư lệnh, trường học, xưởng in, cơ quan báo chí và Đài Tiếng nói Việt Nam đều hoạt động trong vùng căn cứ Việt Bắc."},{"t":"Bạn có biết? Tên gọi “An toàn khu” được viết tắt thành ATK — cách viết tắt này vẫn được giữ làm tên gọi chính thức của các khu di tích ngày nay, như ATK Định Hóa (Thái Nguyên), ATK Chợ Đồn (Bắc Kạn), ATK Tân Trào (Tuyên Quang)."}],"so_chu":1593},{"i":11,"tieu_de_bang":"Lán Bác ở và làm việc","tieu_de":"Căn lán, chiếc máy chữ và những trang viết của Người","sapo":"Một căn lán nứa nhỏ, một bàn tre, một chiếc máy chữ, một ngọn đèn dầu. Trong không gian giản dị ấy, giữa núi rừng Việt Bắc, đã ra đời những văn kiện, bài báo, bức thư, và cả những vần thơ đẹp trong đời cầm bút của Chủ tịch Hồ Chí Minh.","bia":{"src":"textures/bai/G15_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một kiểu lán, nhiều địa điểm","text":"Suốt những năm ở Việt Bắc, Chủ tịch Hồ Chí Minh không ở cố định một nơi mà liên tục chuyển chỗ trong An toàn khu — Khuôn Tát, Tỉn Keo (Định Hóa, Thái Nguyên), Kim Quan, Hùng Lợi (Tuyên Quang)… — theo đúng nguyên tắc bí mật, cơ động chi phối toàn bộ hoạt động của cơ quan đầu não kháng chiến (xem chuyên đề An toàn khu Việt Bắc). Nhưng dù ở đâu, khung cảnh nơi Người sống và làm việc vẫn gần như không đổi: một căn lán nhỏ dựng bằng tre, nứa, mái lợp lá cọ, sàn kê cao hơn mặt đất để tránh ẩm thấp và thú rừng. Sự lặp lại ấy không phải ngẫu nhiên, mà xuất phát từ chính yêu cầu phải sẵn sàng dời đi bất cứ lúc nào.\n\nMỗi lần chuyển lán, việc dựng lại một căn nhà mới thường chỉ mất vài ngày, nhờ vào vật liệu sẵn có tại chỗ — tre, nứa, lá cọ — và bàn tay của bộ đội, dân công quen thuộc với lối dựng nhà sàn miền núi. Nhờ vậy, dù thay đổi chỗ ở nhiều lần trong năm, công việc điều hành kháng chiến của Người hầu như không bị gián đoạn quá vài ngày.","doc":1},{"loai":"doan","tieu_de":"Bên trong căn lán","text":"Không gian bên trong lán rất đơn sơ: một chiếc bàn tre đặt máy chữ, một ngọn đèn dầu để làm việc ban đêm, một chiếc giường tre để nghỉ ngơi. Không có tủ sách lớn, không có bàn ghế cầu kỳ — chỉ những gì thật cần thiết cho công việc và sinh hoạt hằng ngày mới được giữ lại. Trước lán, Người thường tự tay trồng và chăm một khoảnh vườn hoa nhỏ, như một thói quen giữ lại giữa những ngày tháng bộn bề việc nước. Sự giản dị ấy không phải vì thiếu thốn đến mức không thể sắm sửa gì hơn, mà là một lựa chọn sống nhất quán mà Người theo suốt cuộc đời hoạt động cách mạng, kể cả về sau khi đã là Chủ tịch nước ở Hà Nội.","doc":2},{"loai":"doan","tieu_de":"Chiếc máy chữ và những trang viết","text":"Chiếc máy chữ xách tay là vật dụng làm việc quan trọng nhất, gắn bó với Người suốt những năm ở Việt Bắc. Người thường tự tay đánh máy thư từ, chỉ thị, bài viết, thay vì đọc cho người khác chép lại. Tháng 10 năm 1947, ngay giữa những ngày đầu về Việt Bắc, Người hoàn thành tác phẩm Sửa đổi lối làm việc, ký bút danh X.Y.Z, bàn về tư cách, đạo đức và phương pháp công tác của người cán bộ cách mạng, trong đó có câu được nhắc lại rất nhiều về sau: cán bộ là cái gốc của mọi công việc. Đây là một trong những tác phẩm lý luận quan trọng của Người được viết ngay tại chiến khu, giữa bộn bề công việc chỉ đạo kháng chiến.\n\nViệc tự tay đánh máy, thay vì có người chép lại, giúp Người kiểm soát từng câu chữ trước khi văn bản được gửi đi, đồng thời cũng là cách giữ bí mật thêm một lớp: càng ít người tiếp xúc trực tiếp với nội dung chỉ thị, nguy cơ để lộ thông tin cho đối phương càng thấp. Thói quen làm việc cẩn trọng, tỉ mỉ đến từng chi tiết nhỏ ấy được nhiều người từng làm việc gần Người nhắc lại như một nét tính cách nổi bật, không chỉ trong những năm ở Việt Bắc mà xuyên suốt cả cuộc đời hoạt động cách mạng.","doc":3},{"loai":"anh","src":"textures/bang_w/G15_11_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lán Bác ở và làm việc”, nhìn từ xa."},{"loai":"doan","tieu_de":"Bút danh C.B. trên báo Nhân Dân","text":"Từ năm 1951, khi báo Nhân Dân — cơ quan ngôn luận của Đảng — ra đời tại Việt Bắc, Người thường xuyên viết bài cho báo dưới bút danh C.B., bên cạnh nhiều bút danh khác từng dùng trong suốt cuộc đời hoạt động cách mạng. Những bài báo ký C.B. thường ngắn gọn, giản dị, dễ hiểu, bàn về nhiều vấn đề thiết thực của đời sống kháng chiến: tăng gia sản xuất, tiết kiệm, chống tham ô lãng phí, xây dựng đạo đức cán bộ. Cũng như tác phẩm Sửa đổi lối làm việc trước đó, những trang viết ấy phần lớn ra đời ngay trên chiếc bàn tre nhỏ, dưới ánh đèn dầu, trong những căn lán giữa rừng.","doc":4},{"loai":"doan","tieu_de":"Người thi sĩ giữa đêm chiến khu","text":"Không chỉ viết văn kiện, bài báo, giữa những đêm làm việc khuya ở chiến khu, Người còn làm thơ. Năm 1947, bài thơ Cảnh khuya ra đời, ghi lại một đêm trăng ở Việt Bắc: tiếng suối trong như tiếng hát xa, ánh trăng lồng qua tán cổ thụ tạo thành những hình bóng như tranh vẽ — một khung cảnh đẹp, nhưng người thi sĩ trong bài thơ chưa ngủ không chỉ vì cảnh đẹp, mà vì còn lo việc nước. Năm 1948, Người viết tiếp bài thơ chữ Hán Nguyên tiêu, sau này được nhà thơ Xuân Thủy dịch sang tiếng Việt với tên gọi quen thuộc Rằm tháng giêng, kể lại một đêm rằm bàn việc quân trên sông nước Việt Bắc, khuya về thuyền chở đầy ánh trăng.\n\nCả hai bài thơ đều được sáng tác ngay tại chiến khu, trong hoặc ngay sau những đêm làm việc căng thẳng, chứ không phải trong một khoảnh khắc thảnh thơi tách biệt khỏi công việc. Điều đó lý giải vì sao thơ của Người trong giai đoạn này, dù mang vẻ đẹp cổ điển của thơ Đường, vẫn luôn khép lại bằng một câu về việc nước, việc quân — cho thấy tâm trí người viết chưa khi nào thực sự tách khỏi trách nhiệm đang gánh vác.","doc":5},{"loai":"anh","src":"textures/bai/G15_v4.jpg","chu_thich":"Không gian 3D tái hiện An toàn khu Việt Bắc trong gian trưng bày.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Một góc vườn nhỏ trước lán","text":"Giữa những năm tháng chỉ đạo kháng chiến bận rộn, việc tự tay trồng và chăm một khoảnh vườn hoa nhỏ trước lán là một chi tiết đời thường nhưng nói lên nhiều điều về nếp sống của Người: dù trong hoàn cảnh nào, vẫn dành một phần thời gian cho thiên nhiên, cho những việc nhỏ mang lại sự thư thái. Theo hồi ký của những người từng phục vụ gần Người ở Việt Bắc, thói quen ấy được Người giữ đều đặn ở hầu hết những nơi mình từng ở, kể cả khi chuyển chỗ liên tục vì lý do bí mật, cơ động.","doc":6},{"loai":"doan","tieu_de":"Nếp sống điều độ giữa chiến khu","text":"Theo hồi ký của nhiều người từng phục vụ, bảo vệ Người ở Việt Bắc, Chủ tịch Hồ Chí Minh giữ một nếp sinh hoạt khá điều độ ngay giữa hoàn cảnh chiến tranh: dậy sớm, tập thể dục, rồi mới bắt đầu công việc trong ngày — đọc báo cáo, tiếp cán bộ, soạn thảo văn kiện trên chiếc máy chữ quen thuộc. Bữa ăn cũng đơn giản như đời sống chung của cả cơ quan, không có sự khác biệt lớn so với cán bộ, chiến sĩ xung quanh. Nếp sống ấy, được duy trì bất kể phải chuyển chỗ ở bao nhiêu lần, phần nào giải thích vì sao Người có thể giữ được sự minh mẫn, bền bỉ để chỉ đạo kháng chiến suốt nhiều năm liền giữa điều kiện thiếu thốn của núi rừng.","doc":7},{"loai":"anh","src":"textures/bang_w/G15_11_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lán Bác ở và làm việc”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, tại khu di tích An toàn khu Định Hóa và các điểm liên quan ở Tuyên Quang, nhiều căn lán từng là nơi Người ở và làm việc đã được phục dựng theo đúng lối kiến trúc cũ: vách nứa, mái lá cọ, sàn tre, bài trí đơn sơ như nguyên trạng được mô tả trong hồi ký của những người từng phục vụ gần Người. Một số hiện vật liên quan, trong đó có kiểu máy chữ Người từng dùng, được giới thiệu tại Bảo tàng Hồ Chí Minh và các khu di tích lưu niệm về Người. Đứng trước một căn lán phục dựng như thế, khách tham quan hôm nay có thể hình dung phần nào cuộc sống làm việc giản dị đến mức tối giản của một vị Chủ tịch nước giữa những năm kháng chiến gian khổ nhất.","doc":8},{"loai":"doan","tieu_de":"Một biểu tượng của lối sống giản dị","text":"Trong toàn bộ không gian trưng bày về Việt Bắc, hình ảnh căn lán nhỏ nơi Người ở và làm việc thường được xem là một trong những biểu tượng rõ nét nhất cho phong cách sống của Chủ tịch Hồ Chí Minh: giản dị đến mức tối thiểu về vật chất, nhưng phong phú, bền bỉ về tinh thần làm việc và sáng tác. Chính từ những căn lán như vậy, nhiều văn kiện quan trọng, nhiều bài báo, bài thơ đã ra đời, để rồi trở thành một phần di sản tinh thần Người để lại cho các thế hệ sau.","doc":9},{"loai":"anh","src":"textures/bang_w/G15_11_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lán Bác ở và làm việc”, nhìn từ trên cao."},{"loai":"trich","text":"Tiếng suối trong như tiếng hát xa / Trăng lồng cổ thụ bóng lồng hoa / Cảnh khuya như vẽ người chưa ngủ / Chưa ngủ vì lo nỗi nước nhà.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Bài thơ “Cảnh khuya”, viết tại chiến khu Việt Bắc năm 1947","doc":10},{"loai":"ban_co_biet","text":"X.Y.Z và C.B. chỉ là hai trong rất nhiều bút danh Chủ tịch Hồ Chí Minh dùng khi viết báo, viết sách trong cuộc đời hoạt động cách mạng.","nguon_ten":"Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh (hochiminh.vn)","doc":11},{"loai":"ban_co_biet","text":"Bài thơ Nguyên tiêu (Rằm tháng giêng) được Người viết bằng chữ Hán theo thể thất ngôn tứ tuyệt cổ điển; bản dịch tiếng Việt quen thuộc “Rằm xuân lồng lộng trăng soi…” là của nhà thơ Xuân Thủy.","nguon_ten":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","doc":12}],"nguon":["Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Khu Di tích lịch sử ATK Định Hóa (Thái Nguyên)","Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh (hochiminh.vn)","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Căn lán, chiếc máy chữ và những trang viết của Người. Một căn lán nứa nhỏ, một bàn tre, một chiếc máy chữ, một ngọn đèn dầu. Trong không gian giản dị ấy, giữa núi rừng Việt Bắc, đã ra đời những văn kiện, bài báo, bức thư, và cả những vần thơ đẹp trong đời cầm bút của Chủ tịch Hồ Chí Minh."},{"t":"Một kiểu lán, nhiều địa điểm. Suốt những năm ở Việt Bắc, Chủ tịch Hồ Chí Minh không ở cố định một nơi mà liên tục chuyển chỗ trong An toàn khu — Khuôn Tát, Tỉn Keo (Định Hóa, Thái Nguyên), Kim Quan, Hùng Lợi (Tuyên Quang)… — theo đúng nguyên tắc bí mật, cơ động chi phối toàn bộ hoạt động của cơ quan đầu não kháng chiến (xem chuyên đề An toàn khu Việt Bắc). Nhưng dù ở đâu, khung cảnh nơi Người sống và làm việc vẫn gần như không đổi: một căn lán nhỏ dựng bằng tre, nứa, mái lợp lá cọ, sàn kê cao hơn mặt đất để tránh ẩm thấp và thú rừng. Sự lặp lại ấy không phải ngẫu nhiên, mà xuất phát từ chính yêu cầu phải sẵn sàng dời đi bất cứ lúc nào. Mỗi lần chuyển lán, việc dựng lại một căn nhà mới thường chỉ mất vài ngày, nhờ vào vật liệu sẵn có tại chỗ — tre, nứa, lá cọ — và bàn tay của bộ đội, dân công quen thuộc với lối dựng nhà sàn miền núi. Nhờ vậy, dù thay đổi chỗ ở nhiều lần trong năm, công việc điều hành kháng chiến của Người hầu như không bị gián đoạn quá vài ngày."},{"t":"Bên trong căn lán. Không gian bên trong lán rất đơn sơ: một chiếc bàn tre đặt máy chữ, một ngọn đèn dầu để làm việc ban đêm, một chiếc giường tre để nghỉ ngơi. Không có tủ sách lớn, không có bàn ghế cầu kỳ — chỉ những gì thật cần thiết cho công việc và sinh hoạt hằng ngày mới được giữ lại. Trước lán, Người thường tự tay trồng và chăm một khoảnh vườn hoa nhỏ, như một thói quen giữ lại giữa những ngày tháng bộn bề việc nước. Sự giản dị ấy không phải vì thiếu thốn đến mức không thể sắm sửa gì hơn, mà là một lựa chọn sống nhất quán mà Người theo suốt cuộc đời hoạt động cách mạng, kể cả về sau khi đã là Chủ tịch nước ở Hà Nội."},{"t":"Chiếc máy chữ và những trang viết. Chiếc máy chữ xách tay là vật dụng làm việc quan trọng nhất, gắn bó với Người suốt những năm ở Việt Bắc. Người thường tự tay đánh máy thư từ, chỉ thị, bài viết, thay vì đọc cho người khác chép lại. Tháng 10 năm 1947, ngay giữa những ngày đầu về Việt Bắc, Người hoàn thành tác phẩm Sửa đổi lối làm việc, ký bút danh X.Y.Z, bàn về tư cách, đạo đức và phương pháp công tác của người cán bộ cách mạng, trong đó có câu được nhắc lại rất nhiều về sau: cán bộ là cái gốc của mọi công việc. Đây là một trong những tác phẩm lý luận quan trọng của Người được viết ngay tại chiến khu, giữa bộn bề công việc chỉ đạo kháng chiến. Việc tự tay đánh máy, thay vì có người chép lại, giúp Người kiểm soát từng câu chữ trước khi văn bản được gửi đi, đồng thời cũng là cách giữ bí mật thêm một lớp: càng ít người tiếp xúc trực tiếp với nội dung chỉ thị, nguy cơ để lộ thông tin cho đối phương càng thấp. Thói quen làm việc cẩn trọng, tỉ mỉ đến từng chi tiết nhỏ ấy được nhiều người từng làm việc gần Người nhắc lại như một nét tính cách nổi bật, không chỉ trong những năm ở Việt Bắc mà xuyên suốt cả cuộc đời hoạt động cách mạng."},{"t":"Bút danh C.B. trên báo Nhân Dân. Từ năm 1951, khi báo Nhân Dân — cơ quan ngôn luận của Đảng — ra đời tại Việt Bắc, Người thường xuyên viết bài cho báo dưới bút danh C.B., bên cạnh nhiều bút danh khác từng dùng trong suốt cuộc đời hoạt động cách mạng. Những bài báo ký C.B. thường ngắn gọn, giản dị, dễ hiểu, bàn về nhiều vấn đề thiết thực của đời sống kháng chiến: tăng gia sản xuất, tiết kiệm, chống tham ô lãng phí, xây dựng đạo đức cán bộ. Cũng như tác phẩm Sửa đổi lối làm việc trước đó, những trang viết ấy phần lớn ra đời ngay trên chiếc bàn tre nhỏ, dưới ánh đèn dầu, trong những căn lán giữa rừng."},{"t":"Người thi sĩ giữa đêm chiến khu. Không chỉ viết văn kiện, bài báo, giữa những đêm làm việc khuya ở chiến khu, Người còn làm thơ. Năm 1947, bài thơ Cảnh khuya ra đời, ghi lại một đêm trăng ở Việt Bắc: tiếng suối trong như tiếng hát xa, ánh trăng lồng qua tán cổ thụ tạo thành những hình bóng như tranh vẽ — một khung cảnh đẹp, nhưng người thi sĩ trong bài thơ chưa ngủ không chỉ vì cảnh đẹp, mà vì còn lo việc nước. Năm 1948, Người viết tiếp bài thơ chữ Hán Nguyên tiêu, sau này được nhà thơ Xuân Thủy dịch sang tiếng Việt với tên gọi quen thuộc Rằm tháng giêng, kể lại một đêm rằm bàn việc quân trên sông nước Việt Bắc, khuya về thuyền chở đầy ánh trăng. Cả hai bài thơ đều được sáng tác ngay tại chiến khu, trong hoặc ngay sau những đêm làm việc căng thẳng, chứ không phải trong một khoảnh khắc thảnh thơi tách biệt khỏi công việc. Điều đó lý giải vì sao thơ của Người trong giai đoạn này, dù mang vẻ đẹp cổ điển của thơ Đường, vẫn luôn khép lại bằng một câu về việc nước, việc quân — cho thấy tâm trí người viết chưa khi nào thực sự tách khỏi trách nhiệm đang gánh vác."},{"t":"Một góc vườn nhỏ trước lán. Giữa những năm tháng chỉ đạo kháng chiến bận rộn, việc tự tay trồng và chăm một khoảnh vườn hoa nhỏ trước lán là một chi tiết đời thường nhưng nói lên nhiều điều về nếp sống của Người: dù trong hoàn cảnh nào, vẫn dành một phần thời gian cho thiên nhiên, cho những việc nhỏ mang lại sự thư thái. Theo hồi ký của những người từng phục vụ gần Người ở Việt Bắc, thói quen ấy được Người giữ đều đặn ở hầu hết những nơi mình từng ở, kể cả khi chuyển chỗ liên tục vì lý do bí mật, cơ động."},{"t":"Nếp sống điều độ giữa chiến khu. Theo hồi ký của nhiều người từng phục vụ, bảo vệ Người ở Việt Bắc, Chủ tịch Hồ Chí Minh giữ một nếp sinh hoạt khá điều độ ngay giữa hoàn cảnh chiến tranh: dậy sớm, tập thể dục, rồi mới bắt đầu công việc trong ngày — đọc báo cáo, tiếp cán bộ, soạn thảo văn kiện trên chiếc máy chữ quen thuộc. Bữa ăn cũng đơn giản như đời sống chung của cả cơ quan, không có sự khác biệt lớn so với cán bộ, chiến sĩ xung quanh. Nếp sống ấy, được duy trì bất kể phải chuyển chỗ ở bao nhiêu lần, phần nào giải thích vì sao Người có thể giữ được sự minh mẫn, bền bỉ để chỉ đạo kháng chiến suốt nhiều năm liền giữa điều kiện thiếu thốn của núi rừng."},{"t":"Dấu tích hôm nay. Ngày nay, tại khu di tích An toàn khu Định Hóa và các điểm liên quan ở Tuyên Quang, nhiều căn lán từng là nơi Người ở và làm việc đã được phục dựng theo đúng lối kiến trúc cũ: vách nứa, mái lá cọ, sàn tre, bài trí đơn sơ như nguyên trạng được mô tả trong hồi ký của những người từng phục vụ gần Người. Một số hiện vật liên quan, trong đó có kiểu máy chữ Người từng dùng, được giới thiệu tại Bảo tàng Hồ Chí Minh và các khu di tích lưu niệm về Người. Đứng trước một căn lán phục dựng như thế, khách tham quan hôm nay có thể hình dung phần nào cuộc sống làm việc giản dị đến mức tối giản của một vị Chủ tịch nước giữa những năm kháng chiến gian khổ nhất."},{"t":"Một biểu tượng của lối sống giản dị. Trong toàn bộ không gian trưng bày về Việt Bắc, hình ảnh căn lán nhỏ nơi Người ở và làm việc thường được xem là một trong những biểu tượng rõ nét nhất cho phong cách sống của Chủ tịch Hồ Chí Minh: giản dị đến mức tối thiểu về vật chất, nhưng phong phú, bền bỉ về tinh thần làm việc và sáng tác. Chính từ những căn lán như vậy, nhiều văn kiện quan trọng, nhiều bài báo, bài thơ đã ra đời, để rồi trở thành một phần di sản tinh thần Người để lại cho các thế hệ sau."},{"t":"Tiếng suối trong như tiếng hát xa / Trăng lồng cổ thụ bóng lồng hoa / Cảnh khuya như vẽ người chưa ngủ / Chưa ngủ vì lo nỗi nước nhà. — Chủ tịch Hồ Chí Minh"},{"t":"Bạn có biết? X.Y.Z và C.B. chỉ là hai trong rất nhiều bút danh Chủ tịch Hồ Chí Minh dùng khi viết báo, viết sách trong cuộc đời hoạt động cách mạng."},{"t":"Bạn có biết? Bài thơ Nguyên tiêu (Rằm tháng giêng) được Người viết bằng chữ Hán theo thể thất ngôn tứ tuyệt cổ điển; bản dịch tiếng Việt quen thuộc “Rằm xuân lồng lộng trăng soi…” là của nhà thơ Xuân Thủy."}],"so_chu":1581},{"i":12,"tieu_de_bang":"Lán họp Bộ Chính trị","tieu_de":"Căn lán nhỏ, quyết định lớn: đêm 6/12/1953 ở Tỉn Keo","sapo":"Không súng ống, không quân phục, chỉ vài chiếc bàn gỗ mộc kê sát nhau dưới mái lá cọ. Đêm 6 tháng 12 năm 1953, trong căn lán nhỏ ấy ở Tỉn Keo, một quyết định làm thay đổi cục diện cả cuộc chiến tranh Đông Dương đã được đưa ra. Vì sao Bộ Chính trị chọn đúng ngọn đồi khuất nẻo này để bàn về trận đánh lớn nhất trong lịch sử quân sự Việt Nam? Câu trả lời còn nằm trong từng vật dụng mộc mạc được gìn giữ nơi đây.","bia":{"src":"textures/bai/G15_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Tỉn Keo, dưới chân đèo De","text":"Tỉn Keo là tên một quả đồi nhỏ thuộc xã Phú Đình, huyện Định Hóa, tỉnh Thái Nguyên, nằm ngay dưới chân đèo De. Đây là một trong nhiều địa điểm Chủ tịch Hồ Chí Minh cùng cơ quan Trung ương từng dừng chân, trong khoảng thời gian Người ở An toàn khu Việt Bắc, ước chừng từ năm 1948 đến năm 1954. Đồi thấp, cây cối rậm rạp, có suối nhỏ chảy quanh chân đồi, đường vào chỉ là lối mòn xuyên rừng cọ, rừng nứa — đủ kín đáo để tránh mắt máy bay trinh sát, nhưng vẫn đủ gần các bản làng để giữ liên lạc với nhân dân và các cơ quan lân cận.\n\nCuối năm 1953, Tỉn Keo trở thành nơi diễn ra một trong những cuộc họp quan trọng bậc nhất của cả cuộc kháng chiến chống Pháp. Trước đó không lâu, ngày 20/11/1953, quân Pháp — với sự hậu thuẫn của Mỹ — cho quân nhảy dù chiếm Điện Biên Phủ, biến thung lũng lòng chảo này thành trọng điểm của kế hoạch Nava, kế hoạch được tính toán sẽ xoay chuyển cục diện chiến tranh. Câu hỏi đặt ra cho Bộ Chính trị lúc này không còn là có nên đánh Điện Biên Phủ hay không, mà là đánh vào lúc nào, đánh bằng cách nào để chắc thắng.","doc":1},{"loai":"doan","tieu_de":"Một quyết định được chuẩn bị kỹ","text":"Cuộc họp ngày 6/12/1953 không phải một cuộc bàn bạc chớp nhoáng. Trước đó, Tổng Quân ủy đã có báo cáo trình Bộ Chính trị, nêu rõ quyết tâm tiến công Điện Biên Phủ kèm phương án tác chiến cụ thể. Bộ Chính trị, dưới sự chủ trì của Chủ tịch Hồ Chí Minh, phải cân nhắc giữa hai vế. Một bên là cơ hội tiêu diệt một bộ phận lớn sinh lực địch đang co cụm giữa núi rừng Tây Bắc. Bên kia là những khó khăn chưa từng có về hậu cần, vận tải, hỏa lực khi phải đưa quân và pháo vượt hàng trăm cây số đường rừng để tiếp cận một tập đoàn cứ điểm được coi là bất khả xâm phạm.\n\nTinh thần bao trùm cuộc họp, sau này được Đại tướng Võ Nguyên Giáp thuật lại trong hồi ký, gói trong một nguyên tắc ngắn gọn mà Bác căn dặn trước khi Đại tướng ra mặt trận: phải chắc thắng mới đánh, không chắc thắng thì không đánh. Nguyên tắc ấy không phải một khẩu hiệu, mà trở thành kim chỉ nam cho mọi quyết định quân sự tiếp theo, kể cả quyết định khó khăn nhất của toàn chiến dịch diễn ra hơn một tháng sau đó.","doc":2},{"loai":"anh","src":"textures/bang_w/G15_12_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lán họp Bộ Chính trị”, nhìn từ xa."},{"loai":"doan","tieu_de":"Những vật dụng trong căn lán","text":"Không có gì phô trương trong căn lán họp ấy. Bộ bàn ghế ghép từ gỗ rừng, đẽo gọt thô mộc, không sơn không chạm khắc, đủ chỗ cho vài người ngồi quây quanh. Khi cuộc họp kéo dài đến tối, một ngọn đèn dầu nhỏ là nguồn sáng duy nhất. Ánh lửa hắt lên vách nứa, lên những gương mặt đang cúi xuống tấm bản đồ tác chiến trải ngay trên mặt bàn. Đó là đạo cụ quan trọng nhất của buổi họp, nơi từng nét bút chì đánh dấu vị trí các cứ điểm của đối phương ở lòng chảo Điện Biên.\n\nBên cạnh đó là một bộ ấm chén sành mộc mạc, dùng để tiếp nước chè xanh cho những người dự họp giữa đêm dài bàn bạc. Thứ chè ấy hái ngay từ những đồi chè quanh vùng Định Hóa — loại cây gắn liền với đời sống của cả An toàn khu (xem thêm chuyên đề “Đồi chè Thái Nguyên”). Chỉ chừng ấy vật dụng, nhưng chúng cho thấy rõ một điều: những quyết định làm thay đổi vận mệnh đất nước từng được đưa ra trong điều kiện thiếu thốn đến mức tối giản.","doc":3},{"loai":"ban_co_biet","text":"Bộ ấm chén trong lán họp Tỉn Keo được phục dựng theo đồ dùng sinh hoạt phổ biến ở An toàn khu, nơi chè xanh hái từ chính những đồi chè Định Hóa là thức uống quen thuộc của cán bộ, chiến sĩ trong những đêm họp kéo dài.","nguon_ten":"ctx_G15 (canh_3d)","doc":4},{"loai":"doan","tieu_de":"Nội dung cuộc họp","text":"Sau khi nghe báo cáo và thảo luận, Bộ Chính trị đi đến quyết định mở Chiến dịch Điện Biên Phủ, đồng thời thành lập Đảng ủy và Bộ Chỉ huy chiến dịch. Đại tướng Võ Nguyên Giáp được giao trọng trách Bí thư Đảng ủy kiêm Chỉ huy trưởng mặt trận — người trực tiếp cầm cân nảy mực cho toàn bộ chiến dịch tại thực địa. Cùng với quyết định quân sự, Bộ Chính trị cũng phát lệnh huy động sức người, sức của cả hậu phương: bộ đội hành quân, dân công gánh gạo, thồ hàng bằng xe đạp, thanh niên xung phong mở đường, kéo pháo qua đèo dốc để kịp chuẩn bị cho trận quyết chiến chiến lược.\n\nDiễn biến quân sự tiếp theo — từ việc thay đổi phương châm tác chiến cho đến 56 ngày đêm “khoét núi, ngủ hầm” và chiến thắng chiều 7/5/1954 — đã được kể trong chuyên đề “Từ Tỉn Keo đến Điện Biên Phủ”. Điều đáng nhớ ở chính căn lán này là: chỉ một cuộc họp ngắn, trong một không gian giản dị đến không ngờ, đã đặt nền cho toàn bộ chuỗi sự kiện làm nên chiến thắng lừng lẫy năm châu ấy.","doc":5},{"loai":"trich","text":"Trận này rất quan trọng, phải đánh cho thắng. Chắc thắng mới đánh, không chắc thắng không đánh.","nguoi":"Chủ tịch Hồ Chí Minh dặn Đại tướng Võ Nguyên Giáp trước khi ra mặt trận (theo hồi ký của Đại tướng)","nguon_ten":"Võ Nguyên Giáp, Điện Biên Phủ: Điểm hẹn lịch sử, NXB Quân đội nhân dân, 2000","doc":6},{"loai":"anh","src":"textures/bang_w/G15_12_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lán họp Bộ Chính trị”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một thông điệp gửi ra thế giới","text":"Chỉ mươi ngày trước cuộc họp ở Tỉn Keo, ngày 26/11/1953, Chủ tịch Hồ Chí Minh trả lời phỏng vấn báo Expressen của Thụy Điển, tuyên bố Việt Nam sẵn sàng thương lượng nếu Pháp thật sự tôn trọng nền độc lập của Việt Nam. Đặt cạnh nhau, hai sự kiện — một cuộc trả lời phỏng vấn công khai và một cuộc họp bí mật giữa rừng — cho thấy quyết định quân sự tại Tỉn Keo không tách rời một chiến lược chính trị và ngoại giao rộng lớn hơn.\n\nĐánh một trận lớn ở Điện Biên Phủ không chỉ nhằm tiêu diệt sinh lực địch, mà còn nhằm tạo thế mạnh trên bàn đàm phán mà Việt Nam đã chủ động ngỏ lời. Cách tiếp cận vừa cứng rắn trên chiến trường, vừa mềm dẻo trên mặt trận ngoại giao ấy là một trong những nét đặc trưng trong tư duy chỉ đạo kháng chiến của Chủ tịch Hồ Chí Minh, và căn lán ở Tỉn Keo chính là nơi hai đường hướng ấy gặp nhau.","doc":7},{"loai":"doan","tieu_de":"Đèo De — vị trí được chọn không ngẫu nhiên","text":"Không phải ngẫu nhiên mà cơ quan đầu não kháng chiến chọn dừng chân dưới chân đèo De. Địa thế ở đây kín đáo, có đường rút nhanh vào sâu trong núi khi cần. Nơi đây lại nằm giữa vùng dân cư trung thành với cách mạng, nơi lương thực từ nương chè, ruộng lúa của đồng bào các dân tộc nuôi sống cán bộ, bộ đội suốt những năm dài (xem thêm chuyên đề “Đồi chè Thái Nguyên”). Ngay sát khu lán ở và lán họp là một hệ thống hầm, giao thông hào đào sâu vào sườn đồi, sẵn sàng che chở mỗi khi có tiếng động cơ máy bay vọng tới (xem thêm chuyên đề “Hầm trú ẩn”).\n\nSự kết hợp giữa địa hình tự nhiên, lòng dân và các công trình phòng thủ tự tạo ấy chính là công thức để một cơ quan đầu não có thể tồn tại, làm việc liên tục suốt gần một thập kỷ giữa vùng rừng núi. Đó cũng là cách giữ được bí mật tuyệt đối trước một đối phương có ưu thế vượt trội về không quân và hỏa lực.","doc":8},{"loai":"anh","src":"textures/bang_w/G15_12_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lán họp Bộ Chính trị”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Không gian phục dựng trong gian trưng bày","text":"Trong gian trưng bày, lán họp Bộ Chính trị được tái hiện đúng theo tinh thần mộc mạc của nguyên bản: những chiếc bàn gỗ ghép lại, ngọn đèn dầu, bộ ấm chén sành — không thêm thắt, không tô vẽ. Người xem có thể hình dung khung cảnh một đêm tháng Chạp năm 1953: ánh đèn dầu run rẩy, tiếng thảo luận khe khẽ để giữ bí mật, và tấm bản đồ tác chiến là tâm điểm của mọi ánh nhìn.\n\nTại chính địa điểm Tỉn Keo ngoài đời, khu di tích cũng đã phục dựng lại lán họp theo đúng kết cấu cũ, cùng với hệ thống đường mòn, biển chỉ dẫn để khách tham quan có thể hình dung trọn vẹn không gian làm việc của Bộ Chính trị năm xưa. Hai lớp phục dựng — một trong bảo tàng số, một tại chính di tích — cùng hướng đến một mục đích: giữ cho câu chuyện về căn lán nhỏ này không bị lãng quên.","doc":9},{"loai":"ban_co_biet","text":"Cuộc họp ngày 6/12/1953 diễn ra chỉ hơn hai tuần sau khi quân Pháp nhảy dù xuống Điện Biên Phủ (20/11/1953) — cho thấy tốc độ ra quyết định của Bộ Chính trị giữa lúc chiến trường biến chuyển từng ngày.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":10},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày 10/5/2012, Thủ tướng Chính phủ ban hành Quyết định số 548/QĐ-TTg, xếp hạng Di tích lịch sử An toàn khu (ATK) Định Hóa là Di tích quốc gia đặc biệt. Trong quần thể ấy, đồi Tỉn Keo — nơi Chủ tịch Hồ Chí Minh từng ở và làm việc trong khoảng thời gian 1948–1954 — được phục dựng khá đầy đủ: nơi ở của Người, lán họp Bộ Chính trị, hệ thống hầm và giao thông hào, cùng khu vực bếp.\n\nKhách tham quan hôm nay có thể bước vào chính căn lán ấy, đứng cạnh bộ bàn ghế mộc, nhìn tấm bản đồ mô phỏng và hình dung lại đêm tháng 12 năm 1953 khi một quyết định làm nên chiến thắng Điện Biên Phủ được đặt xuống bàn nghị sự. Từ một điểm dừng chân giữa rừng, Tỉn Keo giờ đây trở thành một trong những địa chỉ đỏ quan trọng bậc nhất của hành trình về nguồn tại Việt Bắc.","doc":11}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Võ Nguyên Giáp – Điện Biên Phủ: Điểm hẹn lịch sử (hồi ký), NXB Quân đội nhân dân","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","Cục Di sản văn hóa – Di tích lịch sử An toàn khu (ATK) Định Hóa, dsvh.gov.vn","Báo Thái Nguyên điện tử, baothainguyen.vn","Khu Di tích lịch sử ATK Định Hóa (Thái Nguyên)"],"doc":[{"t":"Căn lán nhỏ, quyết định lớn: đêm 6/12/1953 ở Tỉn Keo. Không súng ống, không quân phục, chỉ vài chiếc bàn gỗ mộc kê sát nhau dưới mái lá cọ. Đêm 6 tháng 12 năm 1953, trong căn lán nhỏ ấy ở Tỉn Keo, một quyết định làm thay đổi cục diện cả cuộc chiến tranh Đông Dương đã được đưa ra. Vì sao Bộ Chính trị chọn đúng ngọn đồi khuất nẻo này để bàn về trận đánh lớn nhất trong lịch sử quân sự Việt Nam? Câu trả lời còn nằm trong từng vật dụng mộc mạc được gìn giữ nơi đây."},{"t":"Tỉn Keo, dưới chân đèo De. Tỉn Keo là tên một quả đồi nhỏ thuộc xã Phú Đình, huyện Định Hóa, tỉnh Thái Nguyên, nằm ngay dưới chân đèo De. Đây là một trong nhiều địa điểm Chủ tịch Hồ Chí Minh cùng cơ quan Trung ương từng dừng chân, trong khoảng thời gian Người ở An toàn khu Việt Bắc, ước chừng từ năm 1948 đến năm 1954. Đồi thấp, cây cối rậm rạp, có suối nhỏ chảy quanh chân đồi, đường vào chỉ là lối mòn xuyên rừng cọ, rừng nứa — đủ kín đáo để tránh mắt máy bay trinh sát, nhưng vẫn đủ gần các bản làng để giữ liên lạc với nhân dân và các cơ quan lân cận. Cuối năm 1953, Tỉn Keo trở thành nơi diễn ra một trong những cuộc họp quan trọng bậc nhất của cả cuộc kháng chiến chống Pháp. Trước đó không lâu, ngày 20/11/1953, quân Pháp — với sự hậu thuẫn của Mỹ — cho quân nhảy dù chiếm Điện Biên Phủ, biến thung lũng lòng chảo này thành trọng điểm của kế hoạch Nava, kế hoạch được tính toán sẽ xoay chuyển cục diện chiến tranh. Câu hỏi đặt ra cho Bộ Chính trị lúc này không còn là có nên đánh Điện Biên Phủ hay không, mà là đánh vào lúc nào, đánh bằng cách nào để chắc thắng."},{"t":"Một quyết định được chuẩn bị kỹ. Cuộc họp ngày 6/12/1953 không phải một cuộc bàn bạc chớp nhoáng. Trước đó, Tổng Quân ủy đã có báo cáo trình Bộ Chính trị, nêu rõ quyết tâm tiến công Điện Biên Phủ kèm phương án tác chiến cụ thể. Bộ Chính trị, dưới sự chủ trì của Chủ tịch Hồ Chí Minh, phải cân nhắc giữa hai vế. Một bên là cơ hội tiêu diệt một bộ phận lớn sinh lực địch đang co cụm giữa núi rừng Tây Bắc. Bên kia là những khó khăn chưa từng có về hậu cần, vận tải, hỏa lực khi phải đưa quân và pháo vượt hàng trăm cây số đường rừng để tiếp cận một tập đoàn cứ điểm được coi là bất khả xâm phạm. Tinh thần bao trùm cuộc họp, sau này được Đại tướng Võ Nguyên Giáp thuật lại trong hồi ký, gói trong một nguyên tắc ngắn gọn mà Bác căn dặn trước khi Đại tướng ra mặt trận: phải chắc thắng mới đánh, không chắc thắng thì không đánh. Nguyên tắc ấy không phải một khẩu hiệu, mà trở thành kim chỉ nam cho mọi quyết định quân sự tiếp theo, kể cả quyết định khó khăn nhất của toàn chiến dịch diễn ra hơn một tháng sau đó."},{"t":"Những vật dụng trong căn lán. Không có gì phô trương trong căn lán họp ấy. Bộ bàn ghế ghép từ gỗ rừng, đẽo gọt thô mộc, không sơn không chạm khắc, đủ chỗ cho vài người ngồi quây quanh. Khi cuộc họp kéo dài đến tối, một ngọn đèn dầu nhỏ là nguồn sáng duy nhất. Ánh lửa hắt lên vách nứa, lên những gương mặt đang cúi xuống tấm bản đồ tác chiến trải ngay trên mặt bàn. Đó là đạo cụ quan trọng nhất của buổi họp, nơi từng nét bút chì đánh dấu vị trí các cứ điểm của đối phương ở lòng chảo Điện Biên. Bên cạnh đó là một bộ ấm chén sành mộc mạc, dùng để tiếp nước chè xanh cho những người dự họp giữa đêm dài bàn bạc. Thứ chè ấy hái ngay từ những đồi chè quanh vùng Định Hóa — loại cây gắn liền với đời sống của cả An toàn khu (xem thêm chuyên đề “Đồi chè Thái Nguyên”). Chỉ chừng ấy vật dụng, nhưng chúng cho thấy rõ một điều: những quyết định làm thay đổi vận mệnh đất nước từng được đưa ra trong điều kiện thiếu thốn đến mức tối giản."},{"t":"Bạn có biết? Bộ ấm chén trong lán họp Tỉn Keo được phục dựng theo đồ dùng sinh hoạt phổ biến ở An toàn khu, nơi chè xanh hái từ chính những đồi chè Định Hóa là thức uống quen thuộc của cán bộ, chiến sĩ trong những đêm họp kéo dài."},{"t":"Nội dung cuộc họp. Sau khi nghe báo cáo và thảo luận, Bộ Chính trị đi đến quyết định mở Chiến dịch Điện Biên Phủ, đồng thời thành lập Đảng ủy và Bộ Chỉ huy chiến dịch. Đại tướng Võ Nguyên Giáp được giao trọng trách Bí thư Đảng ủy kiêm Chỉ huy trưởng mặt trận — người trực tiếp cầm cân nảy mực cho toàn bộ chiến dịch tại thực địa. Cùng với quyết định quân sự, Bộ Chính trị cũng phát lệnh huy động sức người, sức của cả hậu phương: bộ đội hành quân, dân công gánh gạo, thồ hàng bằng xe đạp, thanh niên xung phong mở đường, kéo pháo qua đèo dốc để kịp chuẩn bị cho trận quyết chiến chiến lược. Diễn biến quân sự tiếp theo — từ việc thay đổi phương châm tác chiến cho đến 56 ngày đêm “khoét núi, ngủ hầm” và chiến thắng chiều 7/5/1954 — đã được kể trong chuyên đề “Từ Tỉn Keo đến Điện Biên Phủ”. Điều đáng nhớ ở chính căn lán này là: chỉ một cuộc họp ngắn, trong một không gian giản dị đến không ngờ, đã đặt nền cho toàn bộ chuỗi sự kiện làm nên chiến thắng lừng lẫy năm châu ấy."},{"t":"Trận này rất quan trọng, phải đánh cho thắng. Chắc thắng mới đánh, không chắc thắng không đánh. — Chủ tịch Hồ Chí Minh dặn Đại tướng Võ Nguyên Giáp trước khi ra mặt trận (theo hồi ký của Đại tướng)"},{"t":"Một thông điệp gửi ra thế giới. Chỉ mươi ngày trước cuộc họp ở Tỉn Keo, ngày 26/11/1953, Chủ tịch Hồ Chí Minh trả lời phỏng vấn báo Expressen của Thụy Điển, tuyên bố Việt Nam sẵn sàng thương lượng nếu Pháp thật sự tôn trọng nền độc lập của Việt Nam. Đặt cạnh nhau, hai sự kiện — một cuộc trả lời phỏng vấn công khai và một cuộc họp bí mật giữa rừng — cho thấy quyết định quân sự tại Tỉn Keo không tách rời một chiến lược chính trị và ngoại giao rộng lớn hơn. Đánh một trận lớn ở Điện Biên Phủ không chỉ nhằm tiêu diệt sinh lực địch, mà còn nhằm tạo thế mạnh trên bàn đàm phán mà Việt Nam đã chủ động ngỏ lời. Cách tiếp cận vừa cứng rắn trên chiến trường, vừa mềm dẻo trên mặt trận ngoại giao ấy là một trong những nét đặc trưng trong tư duy chỉ đạo kháng chiến của Chủ tịch Hồ Chí Minh, và căn lán ở Tỉn Keo chính là nơi hai đường hướng ấy gặp nhau."},{"t":"Đèo De — vị trí được chọn không ngẫu nhiên. Không phải ngẫu nhiên mà cơ quan đầu não kháng chiến chọn dừng chân dưới chân đèo De. Địa thế ở đây kín đáo, có đường rút nhanh vào sâu trong núi khi cần. Nơi đây lại nằm giữa vùng dân cư trung thành với cách mạng, nơi lương thực từ nương chè, ruộng lúa của đồng bào các dân tộc nuôi sống cán bộ, bộ đội suốt những năm dài (xem thêm chuyên đề “Đồi chè Thái Nguyên”). Ngay sát khu lán ở và lán họp là một hệ thống hầm, giao thông hào đào sâu vào sườn đồi, sẵn sàng che chở mỗi khi có tiếng động cơ máy bay vọng tới (xem thêm chuyên đề “Hầm trú ẩn”). Sự kết hợp giữa địa hình tự nhiên, lòng dân và các công trình phòng thủ tự tạo ấy chính là công thức để một cơ quan đầu não có thể tồn tại, làm việc liên tục suốt gần một thập kỷ giữa vùng rừng núi. Đó cũng là cách giữ được bí mật tuyệt đối trước một đối phương có ưu thế vượt trội về không quân và hỏa lực."},{"t":"Không gian phục dựng trong gian trưng bày. Trong gian trưng bày, lán họp Bộ Chính trị được tái hiện đúng theo tinh thần mộc mạc của nguyên bản: những chiếc bàn gỗ ghép lại, ngọn đèn dầu, bộ ấm chén sành — không thêm thắt, không tô vẽ. Người xem có thể hình dung khung cảnh một đêm tháng Chạp năm 1953: ánh đèn dầu run rẩy, tiếng thảo luận khe khẽ để giữ bí mật, và tấm bản đồ tác chiến là tâm điểm của mọi ánh nhìn. Tại chính địa điểm Tỉn Keo ngoài đời, khu di tích cũng đã phục dựng lại lán họp theo đúng kết cấu cũ, cùng với hệ thống đường mòn, biển chỉ dẫn để khách tham quan có thể hình dung trọn vẹn không gian làm việc của Bộ Chính trị năm xưa. Hai lớp phục dựng — một trong bảo tàng số, một tại chính di tích — cùng hướng đến một mục đích: giữ cho câu chuyện về căn lán nhỏ này không bị lãng quên."},{"t":"Bạn có biết? Cuộc họp ngày 6/12/1953 diễn ra chỉ hơn hai tuần sau khi quân Pháp nhảy dù xuống Điện Biên Phủ (20/11/1953) — cho thấy tốc độ ra quyết định của Bộ Chính trị giữa lúc chiến trường biến chuyển từng ngày."},{"t":"Dấu tích hôm nay. Ngày 10/5/2012, Thủ tướng Chính phủ ban hành Quyết định số 548/QĐ-TTg, xếp hạng Di tích lịch sử An toàn khu (ATK) Định Hóa là Di tích quốc gia đặc biệt. Trong quần thể ấy, đồi Tỉn Keo — nơi Chủ tịch Hồ Chí Minh từng ở và làm việc trong khoảng thời gian 1948–1954 — được phục dựng khá đầy đủ: nơi ở của Người, lán họp Bộ Chính trị, hệ thống hầm và giao thông hào, cùng khu vực bếp. Khách tham quan hôm nay có thể bước vào chính căn lán ấy, đứng cạnh bộ bàn ghế mộc, nhìn tấm bản đồ mô phỏng và hình dung lại đêm tháng 12 năm 1953 khi một quyết định làm nên chiến thắng Điện Biên Phủ được đặt xuống bàn nghị sự. Từ một điểm dừng chân giữa rừng, Tỉn Keo giờ đây trở thành một trong những địa chỉ đỏ quan trọng bậc nhất của hành trình về nguồn tại Việt Bắc."}],"so_chu":1753},{"i":13,"tieu_de_bang":"Hầm trú ẩn","tieu_de":"Dưới lòng đồi: hầm trú ẩn và cuộc chiến với bầu trời","sapo":"Đối phương làm chủ bầu trời; cơ quan kháng chiến chỉ có rừng, có đất và đôi bàn tay đào bới. Suốt chín năm ở Việt Bắc, mỗi lán ở, lán làm việc đều phải có một căn hầm bên cạnh — tấm khiên vô hình giữ an toàn cho cả bộ máy đầu não kháng chiến. Vì sao một hố đất đào vội giữa rừng lại có thể ngăn được bom đạn từ trên không?","bia":{"src":"textures/bai/G15_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Mối đe dọa từ trên không","text":"Trong kháng chiến chống Pháp, quân đội ta chưa có không quân, trong khi đối phương thường xuyên dùng máy bay trinh sát, ném bom, bắn phá những vùng bị nghi ngờ có cơ quan kháng chiến trú đóng. Với một bộ máy lãnh đạo phải làm việc liên tục, di chuyển thường xuyên giữa núi rừng, nguy cơ bị phát hiện từ trên không luôn thường trực: một cột khói bếp, một khoảng trống trên tán rừng, một vệt đường mòn mới mở cũng có thể trở thành manh mối.\n\nMùa thu năm 1947, mối đe dọa ấy trở thành hiện thực rõ rệt nhất khi quân Pháp cho lính dù nhảy xuống Bắc Kạn, Chợ Mới, Chợ Đồn, hòng đánh úp thẳng vào cơ quan đầu não của cuộc kháng chiến (xem thêm chuyên đề “Thu – đông 1947: đòn đánh vào chiến khu thất bại”). Cuộc tập kích bất thành ấy là lời cảnh báo rõ ràng: bên cạnh việc ngụy trang lán trại, mọi nơi ở và làm việc của lãnh đạo trong An toàn khu đều bắt buộc phải có công trình phòng thủ đi kèm. Câu trả lời cho yêu cầu ấy chính là những căn hầm đào sâu vào lòng đồi.","doc":1},{"loai":"doan","tieu_de":"Một công trình phòng thủ tự tạo","text":"Không có xi măng, không có thép, những căn hầm ở An toàn khu được dựng nên hoàn toàn từ vật liệu tại chỗ. Hầm đào sâu vào sườn đồi để tận dụng lớp đất dày làm tường chắn tự nhiên; lối xuống ốp bằng cọc tre chống sạt, cửa hầm gia cố bằng những đoạn gỗ tròn đủ chắc để đỡ một lớp đất ngụy trang bên trên. Nối liền căn hầm với các lán ở, lán làm việc là một đoạn giao thông hào ngắn, đủ để di chuyển nhanh mà không phải lộ thân giữa khoảng trống.\n\nKích thước mỗi hầm không lớn, thường chỉ đủ chỗ cho vài người, bởi mục tiêu không phải để chiến đấu mà để tránh trú tạm thời. Chính sự đơn giản ấy lại là điểm mạnh: một căn hầm nhỏ, đào nhanh, ngụy trang khéo bằng cành lá rừng, khó bị máy bay trinh sát phát hiện hơn nhiều so với một công sự lớn, cố định.","doc":2},{"loai":"anh","src":"textures/bang_w/G15_13_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hầm trú ẩn”, nhìn từ xa."},{"loai":"doan","tieu_de":"Nhịp sống bên miệng hầm","text":"Với những người sống và làm việc trong An toàn khu, tiếng động cơ máy bay vọng từ xa đã trở thành một phần nhịp sống hằng ngày. Hễ nghe tiếng máy bay, mọi người trong lán nhanh chóng theo giao thông hào xuống hầm, ngồi im chờ cho đến khi tiếng động cơ khuất hẳn rồi mới trở lên tiếp tục công việc dở dang — một bức thư đang viết, một bản báo cáo đang soạn, một cuộc họp đang bàn dở.\n\nChính vì nhịp gián đoạn ấy có thể xảy đến bất cứ lúc nào, hầm luôn phải được đào ngay sát nơi ở, không thể xa quá vài bước chân. Đây cũng là lý do vì sao trong gian trưng bày, hầm trú ẩn luôn xuất hiện liền kề các không gian sinh hoạt khác của Người và của Bộ Chính trị — từ nơi ở, nơi làm việc cho đến lán họp (xem thêm chuyên đề “Lán họp Bộ Chính trị”).","doc":3},{"loai":"doan","tieu_de":"Ngụy trang và kỷ luật giữ bí mật","text":"Đào được một căn hầm chắc chắn mới chỉ là một nửa công việc; nửa còn lại là giữ cho nó — và cả khu vực xung quanh — không bị lộ. Theo nền nếp chung của An toàn khu, miệng hầm và nóc lán đều phải phủ cành lá tươi, thay mới thường xuyên để không bị úa vàng khác màu với rừng xung quanh. Lối đi giữa các lán cũng tránh mở thành đường mòn rõ rệt, mà đi theo nhiều hướng khác nhau để không tạo thành dấu vết cố định nhìn từ trên cao.\n\nKỷ luật ấy áp dụng cho tất cả, không phân biệt cấp bậc: đun nấu, đốt lửa đều phải tính toán thời điểm và cách xử lý khói (xem thêm chuyên đề “Bếp Hoàng Cầm”); việc đi lại giữa các cơ quan cũng hạn chế tối đa vào ban ngày. Nhờ sự kết hợp giữa công trình phòng thủ và kỷ luật giữ bí mật nghiêm ngặt như vậy, cả một bộ máy đầu não kháng chiến mới có thể tồn tại an toàn suốt gần một thập kỷ ngay giữa vùng rừng núi không quá xa các tuyến hành quân của đối phương.","doc":4},{"loai":"trich","text":"Năm mươi sáu ngày đêm khoét núi, ngủ hầm, mưa dầm, cơm vắt.","nguoi":"Nhà thơ Tố Hữu, bài thơ “Hoan hô chiến sĩ Điện Biên”","nguon_ten":"Tố Hữu, “Hoan hô chiến sĩ Điện Biên”, 1954","doc":5},{"loai":"anh","src":"textures/bang_w/G15_13_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hầm trú ẩn”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một mạng lưới khắp An toàn khu","text":"Hầm trú ẩn ở Tỉn Keo không phải trường hợp cá biệt. Tại Khuôn Tát, một điểm dừng chân khác của Chủ tịch Hồ Chí Minh trong vùng Định Hóa, nơi ở của Người tại đồi Nà Đình cũng gắn liền với một hệ thống hầm ngầm tương tự. Có thể nói, gần như mỗi địa điểm Người từng sống và làm việc trong An toàn khu đều có một căn hầm đi kèm — bằng chứng cho một nguyên tắc an toàn được tuân thủ nhất quán suốt nhiều năm, bất kể địa hình, bất kể thời điểm.\n\nSự lặp lại ấy, nhìn ở một góc độ khác, cũng phản ánh mức độ đe dọa thường trực mà cơ quan đầu não kháng chiến phải đối mặt. Đó không phải một vài lần hiếm hoi, mà là nguy cơ liên tục trong suốt gần một thập kỷ, buộc mọi nơi ở phải mang theo “tấm khiên” bằng đất của riêng mình.","doc":6},{"loai":"doan","tieu_de":"Hầm bên cạnh những quyết định lớn","text":"Ngay sát khu lán nơi Bộ Chính trị họp và quyết định mở Chiến dịch Điện Biên Phủ đêm 6/12/1953 (xem thêm chuyên đề “Lán họp Bộ Chính trị”), cũng có một căn hầm trú ẩn được đào sẵn. Không có tư liệu nào ghi lại cuộc họp ấy từng bị gián đoạn bởi báo động máy bay, nhưng sự hiện diện của căn hầm ngay bên cạnh cho thấy rõ: dù đang bàn việc quân cơ trọng đại đến đâu, những người có mặt trong lán vẫn luôn phải sẵn sàng cho tình huống xấu nhất.\n\nChi tiết nhỏ này giúp hình dung đầy đủ hơn về điều kiện làm việc thực sự của Bộ Chính trị giữa chiến khu. Đó không phải một căn phòng họp an toàn tuyệt đối, mà là một không gian luôn đặt cạnh phương án thoát hiểm. Mọi quyết sách lớn ở đây đều được đưa ra trong tư thế sẵn sàng ứng phó với hiểm nguy có thể ập đến bất cứ lúc nào.","doc":7},{"loai":"ban_co_biet","text":"Mùa thu năm 1947, quân Pháp nhảy dù xuống Bắc Kạn, Chợ Mới, Chợ Đồn nhằm đánh úp cơ quan đầu não kháng chiến, nhưng thất bại — một phần nhờ hệ thống hầm, hào và mạng lưới cảnh giới rộng khắp An toàn khu.","nguon_ten":"Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","doc":8},{"loai":"anh","src":"textures/ht/ht_anh_atk_dinh_hoa.jpg","chu_thich":"Cảnh quan An toàn khu Định Hóa, Thái Nguyên ngày nay — địa hình đồi thấp, rừng rậm từng che giấu cả một hệ thống lán, hầm của cơ quan đầu não kháng chiến.","credit":"Ảnh: Viethavvh at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Từ hầm nhỏ đến giao thông hào Điện Biên","text":"Kinh nghiệm đào hầm, đào hào tích lũy suốt những năm ở Việt Bắc không mất đi khi bộ đội ta bước vào Chiến dịch Điện Biên Phủ năm 1954. Ở đó, kỹ thuật ấy được nâng lên một tầm mức khác hẳn: một mạng lưới giao thông hào chằng chịt, dài tổng cộng ước tính hàng trăm ki-lô-mét, có đoạn ăn sâu tới sát hàng rào các cứ điểm. Hệ thống hào ấy cho phép bộ đội ta “vây lấn” tập đoàn cứ điểm Pháp, sống và chiến đấu ngay trong lòng đất suốt 56 ngày đêm.\n\nTừ một căn hầm nhỏ đào vội bên sườn đồi Tỉn Keo hay Khuôn Tát, đến những chiến hào bao vây Điện Biên Phủ, là cả một chặng đường trưởng thành về kỹ thuật công binh và ý chí chịu đựng gian khổ của cả một quân đội. Đó là điều không nhiều người hình dung được khi chỉ nhìn vào một hố đất giản dị giữa rừng.","doc":9},{"loai":"ban_co_biet","text":"Kỹ thuật đào hào “vây lấn” ở Điện Biên Phủ năm 1954 được xem là bước phát triển vượt bậc so với những căn hầm trú ẩn đơn giản thời kỳ đầu kháng chiến ở Việt Bắc, phản ánh sự trưởng thành nhanh chóng của quân đội ta về công binh chiến trường.","nguon_ten":"Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","doc":10},{"loai":"anh","src":"textures/bang_w/G15_13_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hầm trú ẩn”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Trong quần thể Di tích quốc gia đặc biệt An toàn khu (ATK) Định Hóa, được Thủ tướng Chính phủ xếp hạng năm 2012, hệ thống hầm và giao thông hào tại các điểm di tích như Tỉn Keo, Khuôn Tát đã được phục dựng khá đầy đủ. Nhờ vậy, khách tham quan có thể hình dung rõ cách cơ quan đầu não từng ẩn mình giữa núi rừng. Đứng trước miệng một căn hầm phục dựng, nhiều du khách mới thực sự cảm nhận được không gian chật hẹp, thấp tối mà những người từng làm việc ở đây đã quen thuộc suốt nhiều năm.\n\nTrong gian trưng bày, căn hầm được tái hiện với đầy đủ chi tiết: lối xuống ốp cọc tre, cửa gỗ tròn, giao thông hào nối sang các lán bên cạnh. Đó như một lời nhắc rằng, phía sau mỗi quyết định lớn được đưa ra giữa chiến khu, luôn có một lớp phòng vệ âm thầm, giản dị nhưng bền bỉ, đã giữ an toàn cho cả bộ máy lãnh đạo kháng chiến.","doc":11}],"nguon":["Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam","Khu Di tích lịch sử ATK Định Hóa (Thái Nguyên)","Cục Di sản văn hóa – Di tích lịch sử An toàn khu (ATK) Định Hóa, dsvh.gov.vn","Tố Hữu – bài thơ “Hoan hô chiến sĩ Điện Biên” (1954)","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia"],"doc":[{"t":"Dưới lòng đồi: hầm trú ẩn và cuộc chiến với bầu trời. Đối phương làm chủ bầu trời; cơ quan kháng chiến chỉ có rừng, có đất và đôi bàn tay đào bới. Suốt chín năm ở Việt Bắc, mỗi lán ở, lán làm việc đều phải có một căn hầm bên cạnh — tấm khiên vô hình giữ an toàn cho cả bộ máy đầu não kháng chiến. Vì sao một hố đất đào vội giữa rừng lại có thể ngăn được bom đạn từ trên không?"},{"t":"Mối đe dọa từ trên không. Trong kháng chiến chống Pháp, quân đội ta chưa có không quân, trong khi đối phương thường xuyên dùng máy bay trinh sát, ném bom, bắn phá những vùng bị nghi ngờ có cơ quan kháng chiến trú đóng. Với một bộ máy lãnh đạo phải làm việc liên tục, di chuyển thường xuyên giữa núi rừng, nguy cơ bị phát hiện từ trên không luôn thường trực: một cột khói bếp, một khoảng trống trên tán rừng, một vệt đường mòn mới mở cũng có thể trở thành manh mối. Mùa thu năm 1947, mối đe dọa ấy trở thành hiện thực rõ rệt nhất khi quân Pháp cho lính dù nhảy xuống Bắc Kạn, Chợ Mới, Chợ Đồn, hòng đánh úp thẳng vào cơ quan đầu não của cuộc kháng chiến (xem thêm chuyên đề “Thu – đông 1947: đòn đánh vào chiến khu thất bại”). Cuộc tập kích bất thành ấy là lời cảnh báo rõ ràng: bên cạnh việc ngụy trang lán trại, mọi nơi ở và làm việc của lãnh đạo trong An toàn khu đều bắt buộc phải có công trình phòng thủ đi kèm. Câu trả lời cho yêu cầu ấy chính là những căn hầm đào sâu vào lòng đồi."},{"t":"Một công trình phòng thủ tự tạo. Không có xi măng, không có thép, những căn hầm ở An toàn khu được dựng nên hoàn toàn từ vật liệu tại chỗ. Hầm đào sâu vào sườn đồi để tận dụng lớp đất dày làm tường chắn tự nhiên; lối xuống ốp bằng cọc tre chống sạt, cửa hầm gia cố bằng những đoạn gỗ tròn đủ chắc để đỡ một lớp đất ngụy trang bên trên. Nối liền căn hầm với các lán ở, lán làm việc là một đoạn giao thông hào ngắn, đủ để di chuyển nhanh mà không phải lộ thân giữa khoảng trống. Kích thước mỗi hầm không lớn, thường chỉ đủ chỗ cho vài người, bởi mục tiêu không phải để chiến đấu mà để tránh trú tạm thời. Chính sự đơn giản ấy lại là điểm mạnh: một căn hầm nhỏ, đào nhanh, ngụy trang khéo bằng cành lá rừng, khó bị máy bay trinh sát phát hiện hơn nhiều so với một công sự lớn, cố định."},{"t":"Nhịp sống bên miệng hầm. Với những người sống và làm việc trong An toàn khu, tiếng động cơ máy bay vọng từ xa đã trở thành một phần nhịp sống hằng ngày. Hễ nghe tiếng máy bay, mọi người trong lán nhanh chóng theo giao thông hào xuống hầm, ngồi im chờ cho đến khi tiếng động cơ khuất hẳn rồi mới trở lên tiếp tục công việc dở dang — một bức thư đang viết, một bản báo cáo đang soạn, một cuộc họp đang bàn dở. Chính vì nhịp gián đoạn ấy có thể xảy đến bất cứ lúc nào, hầm luôn phải được đào ngay sát nơi ở, không thể xa quá vài bước chân. Đây cũng là lý do vì sao trong gian trưng bày, hầm trú ẩn luôn xuất hiện liền kề các không gian sinh hoạt khác của Người và của Bộ Chính trị — từ nơi ở, nơi làm việc cho đến lán họp (xem thêm chuyên đề “Lán họp Bộ Chính trị”)."},{"t":"Ngụy trang và kỷ luật giữ bí mật. Đào được một căn hầm chắc chắn mới chỉ là một nửa công việc; nửa còn lại là giữ cho nó — và cả khu vực xung quanh — không bị lộ. Theo nền nếp chung của An toàn khu, miệng hầm và nóc lán đều phải phủ cành lá tươi, thay mới thường xuyên để không bị úa vàng khác màu với rừng xung quanh. Lối đi giữa các lán cũng tránh mở thành đường mòn rõ rệt, mà đi theo nhiều hướng khác nhau để không tạo thành dấu vết cố định nhìn từ trên cao. Kỷ luật ấy áp dụng cho tất cả, không phân biệt cấp bậc: đun nấu, đốt lửa đều phải tính toán thời điểm và cách xử lý khói (xem thêm chuyên đề “Bếp Hoàng Cầm”); việc đi lại giữa các cơ quan cũng hạn chế tối đa vào ban ngày. Nhờ sự kết hợp giữa công trình phòng thủ và kỷ luật giữ bí mật nghiêm ngặt như vậy, cả một bộ máy đầu não kháng chiến mới có thể tồn tại an toàn suốt gần một thập kỷ ngay giữa vùng rừng núi không quá xa các tuyến hành quân của đối phương."},{"t":"Năm mươi sáu ngày đêm khoét núi, ngủ hầm, mưa dầm, cơm vắt. — Nhà thơ Tố Hữu, bài thơ “Hoan hô chiến sĩ Điện Biên”"},{"t":"Một mạng lưới khắp An toàn khu. Hầm trú ẩn ở Tỉn Keo không phải trường hợp cá biệt. Tại Khuôn Tát, một điểm dừng chân khác của Chủ tịch Hồ Chí Minh trong vùng Định Hóa, nơi ở của Người tại đồi Nà Đình cũng gắn liền với một hệ thống hầm ngầm tương tự. Có thể nói, gần như mỗi địa điểm Người từng sống và làm việc trong An toàn khu đều có một căn hầm đi kèm — bằng chứng cho một nguyên tắc an toàn được tuân thủ nhất quán suốt nhiều năm, bất kể địa hình, bất kể thời điểm. Sự lặp lại ấy, nhìn ở một góc độ khác, cũng phản ánh mức độ đe dọa thường trực mà cơ quan đầu não kháng chiến phải đối mặt. Đó không phải một vài lần hiếm hoi, mà là nguy cơ liên tục trong suốt gần một thập kỷ, buộc mọi nơi ở phải mang theo “tấm khiên” bằng đất của riêng mình."},{"t":"Hầm bên cạnh những quyết định lớn. Ngay sát khu lán nơi Bộ Chính trị họp và quyết định mở Chiến dịch Điện Biên Phủ đêm 6/12/1953 (xem thêm chuyên đề “Lán họp Bộ Chính trị”), cũng có một căn hầm trú ẩn được đào sẵn. Không có tư liệu nào ghi lại cuộc họp ấy từng bị gián đoạn bởi báo động máy bay, nhưng sự hiện diện của căn hầm ngay bên cạnh cho thấy rõ: dù đang bàn việc quân cơ trọng đại đến đâu, những người có mặt trong lán vẫn luôn phải sẵn sàng cho tình huống xấu nhất. Chi tiết nhỏ này giúp hình dung đầy đủ hơn về điều kiện làm việc thực sự của Bộ Chính trị giữa chiến khu. Đó không phải một căn phòng họp an toàn tuyệt đối, mà là một không gian luôn đặt cạnh phương án thoát hiểm. Mọi quyết sách lớn ở đây đều được đưa ra trong tư thế sẵn sàng ứng phó với hiểm nguy có thể ập đến bất cứ lúc nào."},{"t":"Bạn có biết? Mùa thu năm 1947, quân Pháp nhảy dù xuống Bắc Kạn, Chợ Mới, Chợ Đồn nhằm đánh úp cơ quan đầu não kháng chiến, nhưng thất bại — một phần nhờ hệ thống hầm, hào và mạng lưới cảnh giới rộng khắp An toàn khu."},{"t":"Từ hầm nhỏ đến giao thông hào Điện Biên. Kinh nghiệm đào hầm, đào hào tích lũy suốt những năm ở Việt Bắc không mất đi khi bộ đội ta bước vào Chiến dịch Điện Biên Phủ năm 1954. Ở đó, kỹ thuật ấy được nâng lên một tầm mức khác hẳn: một mạng lưới giao thông hào chằng chịt, dài tổng cộng ước tính hàng trăm ki-lô-mét, có đoạn ăn sâu tới sát hàng rào các cứ điểm. Hệ thống hào ấy cho phép bộ đội ta “vây lấn” tập đoàn cứ điểm Pháp, sống và chiến đấu ngay trong lòng đất suốt 56 ngày đêm. Từ một căn hầm nhỏ đào vội bên sườn đồi Tỉn Keo hay Khuôn Tát, đến những chiến hào bao vây Điện Biên Phủ, là cả một chặng đường trưởng thành về kỹ thuật công binh và ý chí chịu đựng gian khổ của cả một quân đội. Đó là điều không nhiều người hình dung được khi chỉ nhìn vào một hố đất giản dị giữa rừng."},{"t":"Bạn có biết? Kỹ thuật đào hào “vây lấn” ở Điện Biên Phủ năm 1954 được xem là bước phát triển vượt bậc so với những căn hầm trú ẩn đơn giản thời kỳ đầu kháng chiến ở Việt Bắc, phản ánh sự trưởng thành nhanh chóng của quân đội ta về công binh chiến trường."},{"t":"Dấu tích hôm nay. Trong quần thể Di tích quốc gia đặc biệt An toàn khu (ATK) Định Hóa, được Thủ tướng Chính phủ xếp hạng năm 2012, hệ thống hầm và giao thông hào tại các điểm di tích như Tỉn Keo, Khuôn Tát đã được phục dựng khá đầy đủ. Nhờ vậy, khách tham quan có thể hình dung rõ cách cơ quan đầu não từng ẩn mình giữa núi rừng. Đứng trước miệng một căn hầm phục dựng, nhiều du khách mới thực sự cảm nhận được không gian chật hẹp, thấp tối mà những người từng làm việc ở đây đã quen thuộc suốt nhiều năm. Trong gian trưng bày, căn hầm được tái hiện với đầy đủ chi tiết: lối xuống ốp cọc tre, cửa gỗ tròn, giao thông hào nối sang các lán bên cạnh. Đó như một lời nhắc rằng, phía sau mỗi quyết định lớn được đưa ra giữa chiến khu, luôn có một lớp phòng vệ âm thầm, giản dị nhưng bền bỉ, đã giữ an toàn cho cả bộ máy lãnh đạo kháng chiến."}],"so_chu":1610},{"i":14,"tieu_de_bang":"Bếp Hoàng Cầm","tieu_de":"Bếp Hoàng Cầm: sáng kiến của một anh nuôi giữ bí mật cho cả đoàn quân","sapo":"Một cột khói mỏng bốc thẳng lên tán rừng cũng đủ để máy bay trinh sát lần ra cả một đơn vị đang trú quân. Giữa khó khăn tưởng chừng không lời giải ấy, một người lính cấp dưỡng bình dị đã nghĩ ra cách “giấu khói” xuống lòng đất. Chiếc bếp mang tên anh — bếp Hoàng Cầm — theo bước quân đi suốt hai cuộc kháng chiến.","bia":{"src":"textures/bai/G15_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Bài toán khói bếp giữa rừng","text":"Trong kháng chiến, nấu ăn giữa rừng là việc phải làm mỗi ngày, nhưng cũng là việc đầy nguy hiểm. Một cột khói bốc thẳng lên khỏi tán cây có thể làm lộ ngay vị trí đóng quân trước mắt máy bay trinh sát của đối phương; còn nếu chờ đến tối mới nhóm lửa, ánh lửa bập bùng giữa đêm rừng lại càng dễ bị phát hiện từ trên cao. Với những đơn vị đóng quân đông người, nhu cầu có bữa cơm nóng mỗi ngày không thể bỏ qua, nhưng cách nấu truyền thống lại đồng nghĩa với việc tự giăng một lá cờ hiệu cho đối phương.\n\nNgười đảm nhận việc bếp núc trong quân đội — mà bộ đội vẫn trìu mến gọi là “anh nuôi” — vì thế phải tìm ra một giải pháp: làm sao để hàng trăm, hàng nghìn người vẫn có cơm ăn, nước uống đều đặn, mà khói lửa không trở thành thứ tố cáo vị trí của cả đơn vị. Đây không phải một yêu cầu kỹ thuật đơn thuần, mà là một bài toán sống còn, ảnh hưởng trực tiếp đến an toàn của cả một đội hình chiến đấu.","doc":1},{"loai":"doan","tieu_de":"Hậu cần giữa muôn vàn thiếu thốn","text":"Bài toán khói bếp chỉ là một trong vô số khó khăn mà công tác hậu cần kháng chiến phải giải quyết giữa núi rừng Việt Bắc. Gạo, muối, thực phẩm phần lớn dựa vào đóng góp của đồng bào các dân tộc quanh vùng và những vạt nương do chính các đơn vị tăng gia; phương tiện vận chuyển chỉ có đôi vai, đôi quang gánh và những chiếc xe đạp thồ hàng vượt đường rừng. Trong bối cảnh ấy, mỗi sáng kiến giúp tiết kiệm công sức, giảm rủi ro bị lộ đều có giá trị lớn hơn nhiều so với quy mô nhỏ bé của nó.\n\nBếp Hoàng Cầm ra đời chính từ tinh thần ấy: không chờ đợi trang thiết bị hiện đại từ bên ngoài, mà tận dụng tối đa những gì sẵn có — đất, cành lá, sức người — để giải quyết một nhu cầu thiết yếu hằng ngày. Đó cũng là cách nhiều sáng kiến khác trong kháng chiến đã ra đời: từ nhu cầu thực tế của người lính bình thường, chứ không phải từ phòng nghiên cứu hay bản vẽ kỹ thuật.","doc":2},{"loai":"doan","tieu_de":"Người anh nuôi tên Hoàng Cầm","text":"Người tìm ra lời giải cho bài toán ấy là Hoàng Cầm, tiểu đội trưởng nuôi quân của Đại đoàn 308. Trong Chiến dịch Hòa Bình, diễn ra khoảng năm 1951 – 1952, giữa hoàn cảnh phải nấu ăn cho bộ đội ngay trong vùng địch thường xuyên trinh sát bằng đường không, ông đã mày mò thiết kế một kiểu bếp mới, sau này được đặt tên theo chính người sáng chế ra nó.\n\nKhông có bằng sáng chế, không có công bố khoa học, sáng kiến của một người lính cấp dưỡng bình dị ấy ra đời từ nhu cầu thực tế của chiến trường và được kiểm chứng ngay bằng hiệu quả sử dụng. Chỉ trong thời gian ngắn, kiểu bếp mang tên Hoàng Cầm đã được phổ biến rộng rãi trong toàn quân, trở thành một trong những sáng kiến hậu cần tiêu biểu nhất của quân đội ta trong suốt cuộc kháng chiến chống Pháp.","doc":3},{"loai":"anh","src":"textures/bang_w/G15_14_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bếp Hoàng Cầm”, nhìn từ xa."},{"loai":"doan","tieu_de":"Cấu tạo của một chiếc bếp không khói","text":"Điểm mấu chốt trong thiết kế của bếp Hoàng Cầm là hệ thống rãnh dẫn khói đào ngầm dưới mặt đất. Buồng đốt được đào sâu xuống lòng đất thay vì đặt nổi trên mặt bằng như bếp thông thường; từ buồng đốt, nhiều rãnh nhỏ tỏa ra các hướng, được phủ lớp đất ẩm và cành lá bên trên. Khi lửa cháy, khói không thoát thẳng lên trời mà len theo các rãnh, bị chia nhỏ thành nhiều luồng, nguội dần trong lòng đất trước khi len ra mặt đất ở nhiều điểm cách xa nhau.\n\nKết quả là thay vì một cột khói đặc, dễ nhận diện, khói thoát ra chỉ như một lớp sương mỏng là là mặt đất, tan nhanh trong không khí và gần như không thể phát hiện được từ trên cao. Ánh lửa trong buồng đốt cũng bị lớp đất che khuất hoàn toàn, nên bếp có thể đỏ lửa cả ngày lẫn đêm mà không tạo ra dấu hiệu bất thường nào lộ ra bên ngoài.","doc":4},{"loai":"ban_co_biet","text":"Do đặc điểm khói tỏa là là mặt đất, dễ tản ra nhiều hướng, một chiếc bếp Hoàng Cầm được thiết kế tốt gần như không thể bị phát hiện từ máy bay trinh sát bay ở độ cao thông thường, kể cả khi đang đỏ lửa giữa ban ngày.","nguon_ten":"Báo Quân đội nhân dân","doc":5},{"loai":"anh","src":"textures/bang_w/G15_14_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bếp Hoàng Cầm”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Bếp Hoàng Cầm trên chiến trường Điện Biên Phủ","text":"Đến Chiến dịch Điện Biên Phủ năm 1954, bếp Hoàng Cầm đã trở thành vật dụng quen thuộc, được đào ngay gần hầm, gần trận địa pháo, gần các tuyến giao thông hào bao vây tập đoàn cứ điểm Pháp (xem thêm chuyên đề “Hầm trú ẩn”). Giữa 56 ngày đêm bám trụ trong lòng đất, việc vẫn có được bữa cơm nóng nhờ những chiếc bếp không khói này góp phần không nhỏ vào sức bền của bộ đội trên một chiến trường kéo dài và khốc liệt bậc nhất trong lịch sử kháng chiến.\n\nKhông cường điệu khi nói rằng, phía sau mỗi đợt xung phong, mỗi đêm đào hào dưới mưa bom, vẫn có những chiếc bếp lặng lẽ cháy trong lòng đất, giữ cho đoàn quân đủ sức chiến đấu bền bỉ. Đó là một mắt xích hậu cần nhỏ nhưng không thể thiếu trong chiến thắng chung của cả chiến dịch.","doc":6},{"loai":"anh","src":"textures/bang_w/G15_14_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bếp Hoàng Cầm”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Theo bước quân đi: từ Điện Biên đến Trường Sơn","text":"Câu chuyện của bếp Hoàng Cầm không dừng lại ở Điện Biên Phủ năm 1954. Trong cuộc kháng chiến chống Mỹ sau này, kiểu bếp không khói ấy tiếp tục theo bước những đoàn quân hành quân trên tuyến đường Trường Sơn và nhiều chiến trường khác, nơi yêu cầu giữ bí mật trước máy bay trinh sát và pháo đài bay của đối phương còn khắt khe hơn nhiều so với thời chống Pháp.\n\nTrải qua hai cuộc kháng chiến, từ một sáng kiến cá nhân của một anh nuôi ở Đại đoàn 308, bếp Hoàng Cầm trở thành một phần trong “vốn kinh nghiệm chiến trường” chung của cả quân đội. Kinh nghiệm ấy được truyền dạy qua nhiều thế hệ bộ đội, từ những cán bộ hậu cần dày dạn cho đến các chiến sĩ trẻ mới nhập ngũ.","doc":7},{"loai":"ban_co_biet","text":"Trải qua hai cuộc kháng chiến chống Pháp và chống Mỹ, bếp Hoàng Cầm vẫn giữ nguyên nguyên lý ban đầu — rãnh dẫn khói ngầm dưới đất — và đến nay vẫn được nhắc đến như biểu tượng cho trí sáng tạo của những người lính hậu cần bình dị.","nguon_ten":"Báo Quân đội nhân dân","doc":8},{"loai":"doan","tieu_de":"Những vật dụng bên bếp","text":"Trong không gian phục dựng, cạnh bếp Hoàng Cầm còn có một chiếc thùng gỗ dùng đựng nước sinh hoạt và một chiếc giỏ đan bằng tre nứa — những vật dụng quen thuộc của anh nuôi ở chiến khu. Chúng dùng để đựng gạo, rau, hay các loại thực phẩm kiếm được từ rừng và từ sự đóng góp của đồng bào quanh vùng. Cách bố trí đơn giản ấy — bếp, thùng nước, giỏ đựng — tái hiện đúng một góc bếp dã chiến điển hình giữa An toàn khu Việt Bắc.\n\nNhìn vào cả cụm vật dụng nhỏ bé này, người xem có thể hình dung phần nào công việc thầm lặng nhưng vất vả của những người lính cấp dưỡng: dậy sớm, kiếm củi, gánh nước, giữ lửa. Tất cả đều phải tính toán để không lộ dấu vết, để bữa cơm nóng vẫn đến tay đồng đội đúng giờ mà không đánh đổi bằng sự an toàn của cả đơn vị.","doc":9},{"loai":"doan","tieu_de":"Một sáng kiến còn sống mãi","text":"Ngày nay, bếp Hoàng Cầm không chỉ được nhắc tới trong sách sử mà còn được phục dựng tại nhiều bảo tàng và khu di tích kháng chiến trên cả nước, trong đó có các điểm trưng bày về An toàn khu Việt Bắc và Bảo tàng Lịch sử Quân sự Việt Nam. Với nhiều thế hệ, đây không đơn thuần là một chiếc bếp, mà là hiện thân cho một triết lý chiến tranh nhân dân: mọi khó khăn đều có thể vượt qua bằng sự sáng tạo bắt nguồn từ chính đời sống chiến trường.\n\nTừ một nhu cầu rất đời thường — làm sao để có bữa cơm nóng mà không lộ vị trí — một người lính cấp dưỡng vô danh với phần đông công chúng đã để lại một di sản kỹ thuật quân sự tồn tại qua nhiều thập kỷ. Trong gian trưng bày về Việt Bắc, bếp Hoàng Cầm vì thế xứng đáng có một vị trí riêng, bên cạnh những lán ở, lán họp của các nhà lãnh đạo kháng chiến.\n\nTrong nhiều cuộc trò chuyện với cựu chiến binh, cái tên Hoàng Cầm vẫn được nhắc đến với sự trân trọng đặc biệt — không phải vì một chiến công nơi trận tiền, mà vì một đóng góp thầm lặng giúp hàng vạn người lính có bữa cơm nóng giữa những năm tháng gian khổ nhất. Đó là minh chứng cho một điều giản dị: trong chiến tranh nhân dân, sáng kiến có thể đến từ bất cứ ai, ở bất cứ vị trí nào, miễn là bắt nguồn từ việc quan sát kỹ và giải quyết đúng khó khăn trước mắt.","doc":10}],"nguon":["Báo Nhân Dân – Bếp Hoàng Cầm (chuyên đề Điện Biên Phủ)","Báo Quân đội nhân dân","Bảo tàng Lịch sử Quân sự Việt Nam","Sách giáo khoa Lịch sử 12, NXB Giáo dục Việt Nam"],"doc":[{"t":"Bếp Hoàng Cầm: sáng kiến của một anh nuôi giữ bí mật cho cả đoàn quân. Một cột khói mỏng bốc thẳng lên tán rừng cũng đủ để máy bay trinh sát lần ra cả một đơn vị đang trú quân. Giữa khó khăn tưởng chừng không lời giải ấy, một người lính cấp dưỡng bình dị đã nghĩ ra cách “giấu khói” xuống lòng đất. Chiếc bếp mang tên anh — bếp Hoàng Cầm — theo bước quân đi suốt hai cuộc kháng chiến."},{"t":"Bài toán khói bếp giữa rừng. Trong kháng chiến, nấu ăn giữa rừng là việc phải làm mỗi ngày, nhưng cũng là việc đầy nguy hiểm. Một cột khói bốc thẳng lên khỏi tán cây có thể làm lộ ngay vị trí đóng quân trước mắt máy bay trinh sát của đối phương; còn nếu chờ đến tối mới nhóm lửa, ánh lửa bập bùng giữa đêm rừng lại càng dễ bị phát hiện từ trên cao. Với những đơn vị đóng quân đông người, nhu cầu có bữa cơm nóng mỗi ngày không thể bỏ qua, nhưng cách nấu truyền thống lại đồng nghĩa với việc tự giăng một lá cờ hiệu cho đối phương. Người đảm nhận việc bếp núc trong quân đội — mà bộ đội vẫn trìu mến gọi là “anh nuôi” — vì thế phải tìm ra một giải pháp: làm sao để hàng trăm, hàng nghìn người vẫn có cơm ăn, nước uống đều đặn, mà khói lửa không trở thành thứ tố cáo vị trí của cả đơn vị. Đây không phải một yêu cầu kỹ thuật đơn thuần, mà là một bài toán sống còn, ảnh hưởng trực tiếp đến an toàn của cả một đội hình chiến đấu."},{"t":"Hậu cần giữa muôn vàn thiếu thốn. Bài toán khói bếp chỉ là một trong vô số khó khăn mà công tác hậu cần kháng chiến phải giải quyết giữa núi rừng Việt Bắc. Gạo, muối, thực phẩm phần lớn dựa vào đóng góp của đồng bào các dân tộc quanh vùng và những vạt nương do chính các đơn vị tăng gia; phương tiện vận chuyển chỉ có đôi vai, đôi quang gánh và những chiếc xe đạp thồ hàng vượt đường rừng. Trong bối cảnh ấy, mỗi sáng kiến giúp tiết kiệm công sức, giảm rủi ro bị lộ đều có giá trị lớn hơn nhiều so với quy mô nhỏ bé của nó. Bếp Hoàng Cầm ra đời chính từ tinh thần ấy: không chờ đợi trang thiết bị hiện đại từ bên ngoài, mà tận dụng tối đa những gì sẵn có — đất, cành lá, sức người — để giải quyết một nhu cầu thiết yếu hằng ngày. Đó cũng là cách nhiều sáng kiến khác trong kháng chiến đã ra đời: từ nhu cầu thực tế của người lính bình thường, chứ không phải từ phòng nghiên cứu hay bản vẽ kỹ thuật."},{"t":"Người anh nuôi tên Hoàng Cầm. Người tìm ra lời giải cho bài toán ấy là Hoàng Cầm, tiểu đội trưởng nuôi quân của Đại đoàn 308. Trong Chiến dịch Hòa Bình, diễn ra khoảng năm 1951 – 1952, giữa hoàn cảnh phải nấu ăn cho bộ đội ngay trong vùng địch thường xuyên trinh sát bằng đường không, ông đã mày mò thiết kế một kiểu bếp mới, sau này được đặt tên theo chính người sáng chế ra nó. Không có bằng sáng chế, không có công bố khoa học, sáng kiến của một người lính cấp dưỡng bình dị ấy ra đời từ nhu cầu thực tế của chiến trường và được kiểm chứng ngay bằng hiệu quả sử dụng. Chỉ trong thời gian ngắn, kiểu bếp mang tên Hoàng Cầm đã được phổ biến rộng rãi trong toàn quân, trở thành một trong những sáng kiến hậu cần tiêu biểu nhất của quân đội ta trong suốt cuộc kháng chiến chống Pháp."},{"t":"Cấu tạo của một chiếc bếp không khói. Điểm mấu chốt trong thiết kế của bếp Hoàng Cầm là hệ thống rãnh dẫn khói đào ngầm dưới mặt đất. Buồng đốt được đào sâu xuống lòng đất thay vì đặt nổi trên mặt bằng như bếp thông thường; từ buồng đốt, nhiều rãnh nhỏ tỏa ra các hướng, được phủ lớp đất ẩm và cành lá bên trên. Khi lửa cháy, khói không thoát thẳng lên trời mà len theo các rãnh, bị chia nhỏ thành nhiều luồng, nguội dần trong lòng đất trước khi len ra mặt đất ở nhiều điểm cách xa nhau. Kết quả là thay vì một cột khói đặc, dễ nhận diện, khói thoát ra chỉ như một lớp sương mỏng là là mặt đất, tan nhanh trong không khí và gần như không thể phát hiện được từ trên cao. Ánh lửa trong buồng đốt cũng bị lớp đất che khuất hoàn toàn, nên bếp có thể đỏ lửa cả ngày lẫn đêm mà không tạo ra dấu hiệu bất thường nào lộ ra bên ngoài."},{"t":"Bạn có biết? Do đặc điểm khói tỏa là là mặt đất, dễ tản ra nhiều hướng, một chiếc bếp Hoàng Cầm được thiết kế tốt gần như không thể bị phát hiện từ máy bay trinh sát bay ở độ cao thông thường, kể cả khi đang đỏ lửa giữa ban ngày."},{"t":"Bếp Hoàng Cầm trên chiến trường Điện Biên Phủ. Đến Chiến dịch Điện Biên Phủ năm 1954, bếp Hoàng Cầm đã trở thành vật dụng quen thuộc, được đào ngay gần hầm, gần trận địa pháo, gần các tuyến giao thông hào bao vây tập đoàn cứ điểm Pháp (xem thêm chuyên đề “Hầm trú ẩn”). Giữa 56 ngày đêm bám trụ trong lòng đất, việc vẫn có được bữa cơm nóng nhờ những chiếc bếp không khói này góp phần không nhỏ vào sức bền của bộ đội trên một chiến trường kéo dài và khốc liệt bậc nhất trong lịch sử kháng chiến. Không cường điệu khi nói rằng, phía sau mỗi đợt xung phong, mỗi đêm đào hào dưới mưa bom, vẫn có những chiếc bếp lặng lẽ cháy trong lòng đất, giữ cho đoàn quân đủ sức chiến đấu bền bỉ. Đó là một mắt xích hậu cần nhỏ nhưng không thể thiếu trong chiến thắng chung của cả chiến dịch."},{"t":"Theo bước quân đi: từ Điện Biên đến Trường Sơn. Câu chuyện của bếp Hoàng Cầm không dừng lại ở Điện Biên Phủ năm 1954. Trong cuộc kháng chiến chống Mỹ sau này, kiểu bếp không khói ấy tiếp tục theo bước những đoàn quân hành quân trên tuyến đường Trường Sơn và nhiều chiến trường khác, nơi yêu cầu giữ bí mật trước máy bay trinh sát và pháo đài bay của đối phương còn khắt khe hơn nhiều so với thời chống Pháp. Trải qua hai cuộc kháng chiến, từ một sáng kiến cá nhân của một anh nuôi ở Đại đoàn 308, bếp Hoàng Cầm trở thành một phần trong “vốn kinh nghiệm chiến trường” chung của cả quân đội. Kinh nghiệm ấy được truyền dạy qua nhiều thế hệ bộ đội, từ những cán bộ hậu cần dày dạn cho đến các chiến sĩ trẻ mới nhập ngũ."},{"t":"Bạn có biết? Trải qua hai cuộc kháng chiến chống Pháp và chống Mỹ, bếp Hoàng Cầm vẫn giữ nguyên nguyên lý ban đầu — rãnh dẫn khói ngầm dưới đất — và đến nay vẫn được nhắc đến như biểu tượng cho trí sáng tạo của những người lính hậu cần bình dị."},{"t":"Những vật dụng bên bếp. Trong không gian phục dựng, cạnh bếp Hoàng Cầm còn có một chiếc thùng gỗ dùng đựng nước sinh hoạt và một chiếc giỏ đan bằng tre nứa — những vật dụng quen thuộc của anh nuôi ở chiến khu. Chúng dùng để đựng gạo, rau, hay các loại thực phẩm kiếm được từ rừng và từ sự đóng góp của đồng bào quanh vùng. Cách bố trí đơn giản ấy — bếp, thùng nước, giỏ đựng — tái hiện đúng một góc bếp dã chiến điển hình giữa An toàn khu Việt Bắc. Nhìn vào cả cụm vật dụng nhỏ bé này, người xem có thể hình dung phần nào công việc thầm lặng nhưng vất vả của những người lính cấp dưỡng: dậy sớm, kiếm củi, gánh nước, giữ lửa. Tất cả đều phải tính toán để không lộ dấu vết, để bữa cơm nóng vẫn đến tay đồng đội đúng giờ mà không đánh đổi bằng sự an toàn của cả đơn vị."},{"t":"Một sáng kiến còn sống mãi. Ngày nay, bếp Hoàng Cầm không chỉ được nhắc tới trong sách sử mà còn được phục dựng tại nhiều bảo tàng và khu di tích kháng chiến trên cả nước, trong đó có các điểm trưng bày về An toàn khu Việt Bắc và Bảo tàng Lịch sử Quân sự Việt Nam. Với nhiều thế hệ, đây không đơn thuần là một chiếc bếp, mà là hiện thân cho một triết lý chiến tranh nhân dân: mọi khó khăn đều có thể vượt qua bằng sự sáng tạo bắt nguồn từ chính đời sống chiến trường. Từ một nhu cầu rất đời thường — làm sao để có bữa cơm nóng mà không lộ vị trí — một người lính cấp dưỡng vô danh với phần đông công chúng đã để lại một di sản kỹ thuật quân sự tồn tại qua nhiều thập kỷ. Trong gian trưng bày về Việt Bắc, bếp Hoàng Cầm vì thế xứng đáng có một vị trí riêng, bên cạnh những lán ở, lán họp của các nhà lãnh đạo kháng chiến. Trong nhiều cuộc trò chuyện với cựu chiến binh, cái tên Hoàng Cầm vẫn được nhắc đến với sự trân trọng đặc biệt — không phải vì một chiến công nơi trận tiền, mà vì một đóng góp thầm lặng giúp hàng vạn người lính có bữa cơm nóng giữa những năm tháng gian khổ nhất. Đó là minh chứng cho một điều giản dị: trong chiến tranh nhân dân, sáng kiến có thể đến từ bất cứ ai, ở bất cứ vị trí nào, miễn là bắt nguồn từ việc quan sát kỹ và giải quyết đúng khó khăn trước mắt."}],"so_chu":1642},{"i":15,"tieu_de_bang":"Đồi chè Thái Nguyên","tieu_de":"Rừng cọ, đồi chè: núi rừng Việt Bắc che chở và nuôi dưỡng kháng chiến","sapo":"Không một khẩu súng nào canh gác cho cơ quan đầu não kháng chiến tốt hơn chính những cánh rừng cọ, những đồi chè xanh ngát của Định Hóa. Núi rừng Việt Bắc không chỉ là phông nền cho câu chuyện chín năm kháng chiến — mà là một phần sống còn của câu chuyện ấy: vừa che mắt kẻ thù, vừa nuôi sống cả một bộ máy lãnh đạo. Vì sao một vùng trung du bình dị lại trở thành “thủ đô kháng chiến” vững chắc đến vậy?","bia":{"src":"textures/bai/G15_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Vùng đất của cọ và chè","text":"Thái Nguyên từ lâu đã nổi tiếng với cây chè; những nương chè xanh trải dài trên các sườn đồi thấp là hình ảnh quen thuộc của vùng trung du, miền núi phía Bắc. Ở Định Hóa và các vùng lân cận thuộc Tuyên Quang, Bắc Kạn, xen giữa những nương chè ấy là rừng cọ, rừng nứa, rừng tre trải rộng theo các sườn đồi nối tiếp nhau. Chính những loại cây tưởng như bình thường ấy lại làm nên diện mạo vật chất của cả An toàn khu: lá cọ dùng lợp mái lán, thân nứa và thân tre dùng dựng vách, làm sàn, đóng bàn ghế, giường nằm cho hầu hết các cơ quan Trung ương đóng trong vùng.\n\nKhông có một viên gạch, một tấm tôn nào được chở từ nơi khác đến; toàn bộ hạ tầng của cơ quan đầu não kháng chiến — từ nơi ở của Chủ tịch Hồ Chí Minh cho đến các lán làm việc của Bộ Chính trị — đều dựng lên từ chính vật liệu của núi rừng nơi đây. Sự giản dị ấy, nhìn ở khía cạnh khác, cũng chính là bí quyết giúp mọi công trình có thể dựng nhanh, tháo dỡ nhanh, di chuyển gọn nhẹ mỗi khi cần đổi địa điểm để giữ bí mật.","doc":1},{"loai":"doan","tieu_de":"Rừng che bộ đội","text":"Tán rừng rậm rạp của Định Hóa và các vùng lân cận là tấm lưới ngụy trang tự nhiên khổng lồ, che khuất tầm quan sát của máy bay trinh sát đối phương. Địa hình đồi núi trùng điệp tạo nên vô số thung lũng kín đáo, đủ để bố trí các cơ quan đóng quân phân tán mà vẫn giữ được liên lạc, lại có nhiều ngả đường rừng để cơ động, đổi chỗ khi cần thiết. Một cơ quan có thể chuyển từ đồi này sang đồi khác chỉ trong một đêm, gần như không để lại dấu vết trên mặt đất.\n\nChính địa thế ấy giải thích vì sao, suốt gần một thập kỷ, hàng loạt cơ quan Trung ương và cả nơi ở, nơi làm việc của Chủ tịch Hồ Chí Minh có thể tồn tại an toàn giữa một vùng không quá xa các tuyến hành quân, các thị trấn do đối phương kiểm soát. Núi rừng không phải là nơi lẩn trốn thụ động, mà là một phần chủ động trong chiến lược phòng thủ và cơ động của cả An toàn khu.\n\nHiệu quả của tấm lá chắn tự nhiên ấy đã được kiểm chứng ngay từ rất sớm. Mùa thu – đông năm 1947, quân Pháp huy động một lực lượng lớn, có cả lính dù, mở cuộc tấn công quy mô nhằm đánh úp cơ quan đầu não kháng chiến ngay giữa An toàn khu. Chính núi rừng trùng điệp cùng mạng lưới hầm, hào, đường cơ động đã giúp các cơ quan Trung ương kịp thời phân tán, bảo toàn lực lượng (xem thêm chuyên đề “Thu – đông 1947: đòn đánh vào chiến khu thất bại”). Thất bại của đối phương trong chiến dịch ấy là minh chứng rõ ràng nhất cho giá trị phòng thủ của địa hình Việt Bắc.","doc":2},{"loai":"anh","src":"textures/bang_w/G15_15_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Đồi chè Thái Nguyên”, nhìn từ xa."},{"loai":"trich","text":"Nhớ khi giặc đến giặc lùng, Rừng cây núi đá ta cùng đánh Tây. Núi giăng thành lũy sắt dày, Rừng che bộ đội, rừng vây quân thù.","nguoi":"Nhà thơ Tố Hữu, bài thơ “Việt Bắc”","nguon_ten":"Tố Hữu, “Việt Bắc”, 1954","doc":3},{"loai":"doan","tieu_de":"Đồng bào các dân tộc và hậu phương tại chỗ","text":"Rừng và đồi chỉ có thể che chở nếu có lòng người đi cùng. Suốt những năm kháng chiến, đồng bào các dân tộc Tày, Nùng, Dao và nhiều dân tộc khác sinh sống ở Định Hóa cùng các huyện lân cận vừa trồng lúa, trồng ngô trên những thửa ruộng bậc thang nhỏ hẹp, vừa chăm sóc nương chè. Họ cũng tham gia bảo vệ bí mật cho các cơ quan đóng gần bản làng mình. Lương thực, thực phẩm mà cán bộ, bộ đội có được phần lớn đến từ chính sự đóng góp âm thầm ấy của người dân địa phương.\n\nMối quan hệ giữa cơ quan kháng chiến và dân bản không chỉ là một chiều nuôi dưỡng, mà còn là sự tin cậy hai chiều: người dân biết rõ có “cán bộ trên rừng” nhưng luôn giữ kín, không để lộ dù chỉ một lời với người lạ. Chính lòng dân bền chặt ấy, cùng với địa hình hiểm trở, đã biến cả một vùng trung du thành “thủ đô kháng chiến” khó công phá bậc nhất trong cuộc chiến tranh.","doc":4},{"loai":"anh","src":"textures/bang_w/G15_15_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Đồi chè Thái Nguyên”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Mùa vụ nương chè và nhịp sống chiến khu","text":"Nương chè ở Định Hóa không tách rời khỏi nhịp sống của cả An toàn khu. Những vụ hái chè theo mùa, xen giữa vụ lúa, vụ ngô, tạo thành nguồn thu nhập và nguồn thực phẩm bổ sung cho cả người dân lẫn các đơn vị đóng quân gần đó. Không hiếm khi, chè xanh hái từ chính những sườn đồi quanh vùng trở thành thức uống quen thuộc trong những buổi họp kéo dài của cán bộ lãnh đạo, kể cả trong những cuộc họp quan trọng bậc nhất của cuộc kháng chiến.\n\nBộ ấm chén giản dị trong lán họp Bộ Chính trị tại Tỉn Keo, nơi Bác cùng các đồng chí bàn định mở Chiến dịch Điện Biên Phủ đêm 6/12/1953, cũng được rót đầy thứ chè xanh ấy (xem thêm chuyên đề “Lán họp Bộ Chính trị”). Một chi tiết nhỏ, nhưng cho thấy rõ: đời sống vật chất bình dị của vùng đất này đã len vào tận những thời khắc mang tính bước ngoặt của lịch sử.","doc":5},{"loai":"doan","tieu_de":"Lá cọ và những vật dụng đời thường","text":"Không chỉ dùng để lợp mái lán, lá cọ ở Định Hóa còn được người dân địa phương chế tác thành nhiều vật dụng đời thường: nón lá che nắng che mưa, áo tơi khoác lên vai mỗi khi ra đồng giữa những cơn mưa rừng bất chợt. Với những cán bộ, chiến sĩ từ nơi khác đến, chiếc nón, chiếc áo tơi lá cọ nhanh chóng trở thành vật dụng quen thuộc không kém gì đối với người dân bản địa.\n\nSự gắn bó giữa con người và cây cối nơi đây sâu đến mức: nhiều năm sau khi cuộc kháng chiến kết thúc, hình ảnh rừng cọ, đồi chè Định Hóa vẫn luôn được nhắc đến. Người ta nhắc tới chúng cùng với ký ức về những năm tháng “nếm mật nằm gai” của cả dân tộc. Đó là minh chứng cho việc thiên nhiên, khi được con người biết tận dụng đúng cách, có thể trở thành đồng minh bền bỉ nhất trong những hoàn cảnh gian khó nhất.","doc":6},{"loai":"ban_co_biet","text":"Lá cọ không chỉ dùng để lợp lán: người dân Việt Bắc còn dùng lá cọ làm nón, làm áo tơi che mưa — những vật dụng quen thuộc của vùng trung du, miền núi phía Bắc suốt nhiều thế hệ.","nguon_ten":"Khu Di tích lịch sử ATK Định Hóa (Thái Nguyên)","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_atk_dinh_hoa.jpg","chu_thich":"An toàn khu Định Hóa, Thái Nguyên ngày nay — đồi chè và rừng cọ vẫn là cảnh sắc đặc trưng của vùng đất từng là “thủ đô kháng chiến”.","credit":"Ảnh: Viethavvh at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Cảnh sắc hôm nay","text":"Ngày nay, bên cạnh các di tích lán trại, hầm hào được phục dựng, những nương chè, rừng cọ vẫn là cảnh sắc đặc trưng của Định Hóa và nhiều vùng quê Việt Bắc khác. Đứng giữa một đồi chè, nhìn về phía những dãy núi xa mờ sương, du khách hôm nay có thể phần nào hình dung vì sao cả một cơ quan đầu não kháng chiến từng có thể ẩn mình an toàn ở đây suốt nhiều năm: núi rừng che chở, còn lòng người nuôi dưỡng.\n\nNgày 10/5/2012, Thủ tướng Chính phủ đã xếp hạng Di tích lịch sử An toàn khu (ATK) Định Hóa là Di tích quốc gia đặc biệt. Đó là một sự ghi nhận không chỉ cho những lán, hầm cụ thể, mà cho cả một không gian tự nhiên và văn hóa rộng lớn hơn, nơi thiên nhiên và con người cùng góp phần làm nên chiến thắng.","doc":8},{"loai":"ban_co_biet","text":"Cùng với các điểm di tích như Tỉn Keo, Khuôn Tát, cảnh quan đồi chè và rừng cọ của Định Hóa nằm trong tổng thể Di tích quốc gia đặc biệt An toàn khu (ATK) Định Hóa, được Thủ tướng Chính phủ xếp hạng theo Quyết định số 548/QĐ-TTg ngày 10/5/2012.","nguon_ten":"Cục Di sản văn hóa – dsvh.gov.vn","doc":9},{"loai":"anh","src":"textures/bang_w/G15_15_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Đồi chè Thái Nguyên”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Núi rừng che chở, lòng dân nuôi dưỡng","text":"Nhìn lại cả chín năm kháng chiến ở Việt Bắc, khó có thể tách rời câu chuyện về những quyết định lịch sử — từ lán họp Bộ Chính trị đến những chiến dịch lớn — khỏi câu chuyện về chính vùng đất đã cưu mang chúng. Rừng cọ cho mái lán, đồi chè cho bát nước chè giữa đêm họp dài, và trên hết là những người dân âm thầm góp gạo, góp công, giữ kín từng lời. Tất cả hợp lại thành một “thủ đô kháng chiến” không tường thành, không công sự kiên cố, nhưng vững chắc đến mức không một cuộc càn quét nào của đối phương có thể chạm tới.\n\nĐó là lý do vì sao, cho đến hôm nay, khi nhắc đến Việt Bắc, người ta vẫn dùng hai chữ đầy tự hào: “quê hương cách mạng” — nơi núi rừng và lòng người đã cùng nhau viết nên một chương quan trọng bậc nhất trong lịch sử dân tộc.","doc":10}],"nguon":["Khu Di tích lịch sử ATK Định Hóa (Thái Nguyên)","Cục Di sản văn hóa – Di tích lịch sử An toàn khu (ATK) Định Hóa, dsvh.gov.vn","Tố Hữu – bài thơ “Việt Bắc” (1954)","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia"],"doc":[{"t":"Rừng cọ, đồi chè: núi rừng Việt Bắc che chở và nuôi dưỡng kháng chiến. Không một khẩu súng nào canh gác cho cơ quan đầu não kháng chiến tốt hơn chính những cánh rừng cọ, những đồi chè xanh ngát của Định Hóa. Núi rừng Việt Bắc không chỉ là phông nền cho câu chuyện chín năm kháng chiến — mà là một phần sống còn của câu chuyện ấy: vừa che mắt kẻ thù, vừa nuôi sống cả một bộ máy lãnh đạo. Vì sao một vùng trung du bình dị lại trở thành “thủ đô kháng chiến” vững chắc đến vậy?"},{"t":"Vùng đất của cọ và chè. Thái Nguyên từ lâu đã nổi tiếng với cây chè; những nương chè xanh trải dài trên các sườn đồi thấp là hình ảnh quen thuộc của vùng trung du, miền núi phía Bắc. Ở Định Hóa và các vùng lân cận thuộc Tuyên Quang, Bắc Kạn, xen giữa những nương chè ấy là rừng cọ, rừng nứa, rừng tre trải rộng theo các sườn đồi nối tiếp nhau. Chính những loại cây tưởng như bình thường ấy lại làm nên diện mạo vật chất của cả An toàn khu: lá cọ dùng lợp mái lán, thân nứa và thân tre dùng dựng vách, làm sàn, đóng bàn ghế, giường nằm cho hầu hết các cơ quan Trung ương đóng trong vùng. Không có một viên gạch, một tấm tôn nào được chở từ nơi khác đến; toàn bộ hạ tầng của cơ quan đầu não kháng chiến — từ nơi ở của Chủ tịch Hồ Chí Minh cho đến các lán làm việc của Bộ Chính trị — đều dựng lên từ chính vật liệu của núi rừng nơi đây. Sự giản dị ấy, nhìn ở khía cạnh khác, cũng chính là bí quyết giúp mọi công trình có thể dựng nhanh, tháo dỡ nhanh, di chuyển gọn nhẹ mỗi khi cần đổi địa điểm để giữ bí mật."},{"t":"Rừng che bộ đội. Tán rừng rậm rạp của Định Hóa và các vùng lân cận là tấm lưới ngụy trang tự nhiên khổng lồ, che khuất tầm quan sát của máy bay trinh sát đối phương. Địa hình đồi núi trùng điệp tạo nên vô số thung lũng kín đáo, đủ để bố trí các cơ quan đóng quân phân tán mà vẫn giữ được liên lạc, lại có nhiều ngả đường rừng để cơ động, đổi chỗ khi cần thiết. Một cơ quan có thể chuyển từ đồi này sang đồi khác chỉ trong một đêm, gần như không để lại dấu vết trên mặt đất. Chính địa thế ấy giải thích vì sao, suốt gần một thập kỷ, hàng loạt cơ quan Trung ương và cả nơi ở, nơi làm việc của Chủ tịch Hồ Chí Minh có thể tồn tại an toàn giữa một vùng không quá xa các tuyến hành quân, các thị trấn do đối phương kiểm soát. Núi rừng không phải là nơi lẩn trốn thụ động, mà là một phần chủ động trong chiến lược phòng thủ và cơ động của cả An toàn khu. Hiệu quả của tấm lá chắn tự nhiên ấy đã được kiểm chứng ngay từ rất sớm. Mùa thu – đông năm 1947, quân Pháp huy động một lực lượng lớn, có cả lính dù, mở cuộc tấn công quy mô nhằm đánh úp cơ quan đầu não kháng chiến ngay giữa An toàn khu. Chính núi rừng trùng điệp cùng mạng lưới hầm, hào, đường cơ động đã giúp các cơ quan Trung ương kịp thời phân tán, bảo toàn lực lượng (xem thêm chuyên đề “Thu – đông 1947: đòn đánh vào chiến khu thất bại”). Thất bại của đối phương trong chiến dịch ấy là minh chứng rõ ràng nhất cho giá trị phòng thủ của địa hình Việt Bắc."},{"t":"Nhớ khi giặc đến giặc lùng, Rừng cây núi đá ta cùng đánh Tây. Núi giăng thành lũy sắt dày, Rừng che bộ đội, rừng vây quân thù. — Nhà thơ Tố Hữu, bài thơ “Việt Bắc”"},{"t":"Đồng bào các dân tộc và hậu phương tại chỗ. Rừng và đồi chỉ có thể che chở nếu có lòng người đi cùng. Suốt những năm kháng chiến, đồng bào các dân tộc Tày, Nùng, Dao và nhiều dân tộc khác sinh sống ở Định Hóa cùng các huyện lân cận vừa trồng lúa, trồng ngô trên những thửa ruộng bậc thang nhỏ hẹp, vừa chăm sóc nương chè. Họ cũng tham gia bảo vệ bí mật cho các cơ quan đóng gần bản làng mình. Lương thực, thực phẩm mà cán bộ, bộ đội có được phần lớn đến từ chính sự đóng góp âm thầm ấy của người dân địa phương. Mối quan hệ giữa cơ quan kháng chiến và dân bản không chỉ là một chiều nuôi dưỡng, mà còn là sự tin cậy hai chiều: người dân biết rõ có “cán bộ trên rừng” nhưng luôn giữ kín, không để lộ dù chỉ một lời với người lạ. Chính lòng dân bền chặt ấy, cùng với địa hình hiểm trở, đã biến cả một vùng trung du thành “thủ đô kháng chiến” khó công phá bậc nhất trong cuộc chiến tranh."},{"t":"Mùa vụ nương chè và nhịp sống chiến khu. Nương chè ở Định Hóa không tách rời khỏi nhịp sống của cả An toàn khu. Những vụ hái chè theo mùa, xen giữa vụ lúa, vụ ngô, tạo thành nguồn thu nhập và nguồn thực phẩm bổ sung cho cả người dân lẫn các đơn vị đóng quân gần đó. Không hiếm khi, chè xanh hái từ chính những sườn đồi quanh vùng trở thành thức uống quen thuộc trong những buổi họp kéo dài của cán bộ lãnh đạo, kể cả trong những cuộc họp quan trọng bậc nhất của cuộc kháng chiến. Bộ ấm chén giản dị trong lán họp Bộ Chính trị tại Tỉn Keo, nơi Bác cùng các đồng chí bàn định mở Chiến dịch Điện Biên Phủ đêm 6/12/1953, cũng được rót đầy thứ chè xanh ấy (xem thêm chuyên đề “Lán họp Bộ Chính trị”). Một chi tiết nhỏ, nhưng cho thấy rõ: đời sống vật chất bình dị của vùng đất này đã len vào tận những thời khắc mang tính bước ngoặt của lịch sử."},{"t":"Lá cọ và những vật dụng đời thường. Không chỉ dùng để lợp mái lán, lá cọ ở Định Hóa còn được người dân địa phương chế tác thành nhiều vật dụng đời thường: nón lá che nắng che mưa, áo tơi khoác lên vai mỗi khi ra đồng giữa những cơn mưa rừng bất chợt. Với những cán bộ, chiến sĩ từ nơi khác đến, chiếc nón, chiếc áo tơi lá cọ nhanh chóng trở thành vật dụng quen thuộc không kém gì đối với người dân bản địa. Sự gắn bó giữa con người và cây cối nơi đây sâu đến mức: nhiều năm sau khi cuộc kháng chiến kết thúc, hình ảnh rừng cọ, đồi chè Định Hóa vẫn luôn được nhắc đến. Người ta nhắc tới chúng cùng với ký ức về những năm tháng “nếm mật nằm gai” của cả dân tộc. Đó là minh chứng cho việc thiên nhiên, khi được con người biết tận dụng đúng cách, có thể trở thành đồng minh bền bỉ nhất trong những hoàn cảnh gian khó nhất."},{"t":"Bạn có biết? Lá cọ không chỉ dùng để lợp lán: người dân Việt Bắc còn dùng lá cọ làm nón, làm áo tơi che mưa — những vật dụng quen thuộc của vùng trung du, miền núi phía Bắc suốt nhiều thế hệ."},{"t":"Cảnh sắc hôm nay. Ngày nay, bên cạnh các di tích lán trại, hầm hào được phục dựng, những nương chè, rừng cọ vẫn là cảnh sắc đặc trưng của Định Hóa và nhiều vùng quê Việt Bắc khác. Đứng giữa một đồi chè, nhìn về phía những dãy núi xa mờ sương, du khách hôm nay có thể phần nào hình dung vì sao cả một cơ quan đầu não kháng chiến từng có thể ẩn mình an toàn ở đây suốt nhiều năm: núi rừng che chở, còn lòng người nuôi dưỡng. Ngày 10/5/2012, Thủ tướng Chính phủ đã xếp hạng Di tích lịch sử An toàn khu (ATK) Định Hóa là Di tích quốc gia đặc biệt. Đó là một sự ghi nhận không chỉ cho những lán, hầm cụ thể, mà cho cả một không gian tự nhiên và văn hóa rộng lớn hơn, nơi thiên nhiên và con người cùng góp phần làm nên chiến thắng."},{"t":"Bạn có biết? Cùng với các điểm di tích như Tỉn Keo, Khuôn Tát, cảnh quan đồi chè và rừng cọ của Định Hóa nằm trong tổng thể Di tích quốc gia đặc biệt An toàn khu (ATK) Định Hóa, được Thủ tướng Chính phủ xếp hạng theo Quyết định số 548/QĐ-TTg ngày 10/5/2012."},{"t":"Núi rừng che chở, lòng dân nuôi dưỡng. Nhìn lại cả chín năm kháng chiến ở Việt Bắc, khó có thể tách rời câu chuyện về những quyết định lịch sử — từ lán họp Bộ Chính trị đến những chiến dịch lớn — khỏi câu chuyện về chính vùng đất đã cưu mang chúng. Rừng cọ cho mái lán, đồi chè cho bát nước chè giữa đêm họp dài, và trên hết là những người dân âm thầm góp gạo, góp công, giữ kín từng lời. Tất cả hợp lại thành một “thủ đô kháng chiến” không tường thành, không công sự kiên cố, nhưng vững chắc đến mức không một cuộc càn quét nào của đối phương có thể chạm tới. Đó là lý do vì sao, cho đến hôm nay, khi nhắc đến Việt Bắc, người ta vẫn dùng hai chữ đầy tự hào: “quê hương cách mạng” — nơi núi rừng và lòng người đã cùng nhau viết nên một chương quan trọng bậc nhất trong lịch sử dân tộc."}],"so_chu":1596}],"do_vat":[{"id":"table@-7.1,-19.6","x":-7.13,"y":3.18,"z":-19.63,"loai":"table","ten":"Bàn tre làm việc","tieu_de":"Nơi ra đời “Sửa đổi lối làm việc”","text":"Trong không gian phục dựng của lán Việt Bắc, chiếc bàn tre nhỏ kê sát vách nứa là hình ảnh gợi nhớ rõ nhất một góc làm việc của Chủ tịch Hồ Chí Minh những năm kháng chiến chống Pháp. Mặt bàn ghép bằng những thanh tre già chẻ đều, không sơn không chạm, bốn chân đóng chắc vừa đủ để đặt một chồng công văn, vài tờ báo, một cây bút và lọ mực. Đây là kiểu bàn ghế phổ biến khắp An toàn khu (ATK) Định Hóa, Sơn Dương, Chiêm Hóa – nơi tre nứa mọc sẵn trong rừng trở thành vật liệu chính cho hầu như mọi vật dụng, từ giường nằm, ghế ngồi đến máng nước, gáo múc. Sự giản dị của chiếc bàn không chỉ vì thiếu thốn, mà còn vì yêu cầu ngặt nghèo của bí mật quân sự: đồ đạc phải gọn nhẹ, dễ tháo dỡ, dễ mang đi, để cơ quan đầu não có thể rời địa điểm trong vài giờ nếu có tin báo động máy bay hay nguy cơ địch càn quét.\n\nTừ tháng 5 năm 1947, Chủ tịch Hồ Chí Minh cùng các cơ quan Trung ương liên tục chuyển qua nhiều địa điểm trong An toàn khu – Khuôn Tát, Tỉn Keo, Nà Lừa, Kim Quan… – mỗi nơi chỉ ở một thời gian ngắn rồi lại dời đi. Ở đâu Người cũng giữ một nếp sinh hoạt gần như không đổi: dậy sớm, tập thể dục, rồi ngồi vào bàn làm việc trước khi các cán bộ giúp việc thức giấc. Bàn tre là nơi Người đọc báo cáo từ các mặt trận, xem lại bản tin, viết thư gửi cán bộ, chiến sĩ, đồng bào, và soạn thảo những văn kiện quan trọng của Đảng, Chính phủ. Nhiều cán bộ từng phục vụ bên Người kể lại rằng thói quen làm việc khoa học, đúng giờ giấc được giữ nghiêm ngặt ngay giữa hoàn cảnh chiến tranh gian khổ, như một cách Người tự rèn mình và làm gương cho cấp dưới.\n\nChính trên những chiếc bàn tre như thế này, tháng 10 năm 1947, Chủ tịch Hồ Chí Minh hoàn thành tác phẩm “Sửa đổi lối làm việc”, ký bút danh X.Y.Z. Cuốn sách nhỏ bàn sâu về tư cách, đạo đức và phương pháp làm việc của người cán bộ cách mạng, phê phán bệnh quan liêu, chủ quan, hẹp hòi, đồng thời nêu yêu cầu về “phê bình và tự phê bình”. Trong tác phẩm có câu được nhắc lại qua nhiều thế hệ sau: “Cán bộ là cái gốc của mọi công việc”, hàm ý muốn công việc cách mạng thành công, trước hết phải có đội ngũ cán bộ vừa có đức vừa có tài, gần dân, trọng dân. Ra đời giữa núi rừng Việt Bắc, khi cuộc kháng chiến còn ở giai đoạn cầm cự gian khó, tác phẩm cho thấy Người không chỉ lo việc quân sự, ngoại giao mà còn dành tâm sức xây dựng nền móng tổ chức, con người cho một Đảng cầm quyền lâu dài.\n\n“Sửa đổi lối làm việc” về sau được đưa vào Hồ Chí Minh Toàn tập, trở thành một trong những tài liệu giáo dục cán bộ, đảng viên được trích dẫn thường xuyên nhất, đặc biệt trong các đợt sinh hoạt chính trị về xây dựng, chỉnh đốn Đảng. Chiếc bàn tre trong gian trưng bày hôm nay là hiện vật phục dựng, không phải nguyên bản – bởi lán trại Việt Bắc thời chiến tranh làm bằng tre nứa, mái lá cọ, khó tồn tại nguyên vẹn qua nhiều chục năm mưa nắng. Nhưng hình dáng mộc mạc của nó được dựng lại đúng theo mô tả tại các khu di tích lịch sử An toàn khu Định Hóa, Tân Trào, nơi những căn lán được phục dựng, bảo tồn để du khách hôm nay có thể hình dung không gian làm việc thanh bạch của một vị Chủ tịch nước giữa những năm tháng kháng chiến gian lao.","nguon":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011; Khu di tích lịch sử An toàn khu Định Hóa","doc":[{"t":"Nơi ra đời “Sửa đổi lối làm việc”. Trong không gian phục dựng của lán Việt Bắc, chiếc bàn tre nhỏ kê sát vách nứa là hình ảnh gợi nhớ rõ nhất một góc làm việc của Chủ tịch Hồ Chí Minh những năm kháng chiến chống Pháp. Mặt bàn ghép bằng những thanh tre già chẻ đều, không sơn không chạm, bốn chân đóng chắc vừa đủ để đặt một chồng công văn, vài tờ báo, một cây bút và lọ mực. Đây là kiểu bàn ghế phổ biến khắp An toàn khu (ATK) Định Hóa, Sơn Dương, Chiêm Hóa – nơi tre nứa mọc sẵn trong rừng trở thành vật liệu chính cho hầu như mọi vật dụng, từ giường nằm, ghế ngồi đến máng nước, gáo múc. Sự giản dị của chiếc bàn không chỉ vì thiếu thốn, mà còn vì yêu cầu ngặt nghèo của bí mật quân sự: đồ đạc phải gọn nhẹ, dễ tháo dỡ, dễ mang đi, để cơ quan đầu não có thể rời địa điểm trong vài giờ nếu có tin báo động máy bay hay nguy cơ địch càn quét."},{"t":"Từ tháng 5 năm 1947, Chủ tịch Hồ Chí Minh cùng các cơ quan Trung ương liên tục chuyển qua nhiều địa điểm trong An toàn khu – Khuôn Tát, Tỉn Keo, Nà Lừa, Kim Quan… – mỗi nơi chỉ ở một thời gian ngắn rồi lại dời đi. Ở đâu Người cũng giữ một nếp sinh hoạt gần như không đổi: dậy sớm, tập thể dục, rồi ngồi vào bàn làm việc trước khi các cán bộ giúp việc thức giấc. Bàn tre là nơi Người đọc báo cáo từ các mặt trận, xem lại bản tin, viết thư gửi cán bộ, chiến sĩ, đồng bào, và soạn thảo những văn kiện quan trọng của Đảng, Chính phủ. Nhiều cán bộ từng phục vụ bên Người kể lại rằng thói quen làm việc khoa học, đúng giờ giấc được giữ nghiêm ngặt ngay giữa hoàn cảnh chiến tranh gian khổ, như một cách Người tự rèn mình và làm gương cho cấp dưới."},{"t":"Chính trên những chiếc bàn tre như thế này, tháng 10 năm 1947, Chủ tịch Hồ Chí Minh hoàn thành tác phẩm “Sửa đổi lối làm việc”, ký bút danh X.Y.Z. Cuốn sách nhỏ bàn sâu về tư cách, đạo đức và phương pháp làm việc của người cán bộ cách mạng, phê phán bệnh quan liêu, chủ quan, hẹp hòi, đồng thời nêu yêu cầu về “phê bình và tự phê bình”. Trong tác phẩm có câu được nhắc lại qua nhiều thế hệ sau: “Cán bộ là cái gốc của mọi công việc”, hàm ý muốn công việc cách mạng thành công, trước hết phải có đội ngũ cán bộ vừa có đức vừa có tài, gần dân, trọng dân. Ra đời giữa núi rừng Việt Bắc, khi cuộc kháng chiến còn ở giai đoạn cầm cự gian khó, tác phẩm cho thấy Người không chỉ lo việc quân sự, ngoại giao mà còn dành tâm sức xây dựng nền móng tổ chức, con người cho một Đảng cầm quyền lâu dài."},{"t":"“Sửa đổi lối làm việc” về sau được đưa vào Hồ Chí Minh Toàn tập, trở thành một trong những tài liệu giáo dục cán bộ, đảng viên được trích dẫn thường xuyên nhất, đặc biệt trong các đợt sinh hoạt chính trị về xây dựng, chỉnh đốn Đảng. Chiếc bàn tre trong gian trưng bày hôm nay là hiện vật phục dựng, không phải nguyên bản – bởi lán trại Việt Bắc thời chiến tranh làm bằng tre nứa, mái lá cọ, khó tồn tại nguyên vẹn qua nhiều chục năm mưa nắng. Nhưng hình dáng mộc mạc của nó được dựng lại đúng theo mô tả tại các khu di tích lịch sử An toàn khu Định Hóa, Tân Trào, nơi những căn lán được phục dựng, bảo tồn để du khách hôm nay có thể hình dung không gian làm việc thanh bạch của một vị Chủ tịch nước giữa những năm tháng kháng chiến gian lao."},{"t":"Bạn có biết? Suốt cuộc đời hoạt động cách mạng, Người từng dùng nhiều bút danh khác nhau tùy giai đoạn và tờ báo, trong đó X.Y.Z là bút danh ký dưới tác phẩm “Sửa đổi lối làm việc” năm 1947 (Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia)."}],"ban_co_biet":"Suốt cuộc đời hoạt động cách mạng, Người từng dùng nhiều bút danh khác nhau tùy giai đoạn và tờ báo, trong đó X.Y.Z là bút danh ký dưới tác phẩm “Sửa đổi lối làm việc” năm 1947 (Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia)."},{"id":"typewriter@-7.2,-19.6","x":-7.23,"y":3.84,"z":-19.61,"loai":"typewriter","ten":"Chiếc máy chữ","tieu_de":"Người bạn đồng hành thầm lặng ở chiến khu","text":"Đặt cạnh bàn làm việc trong lán phục dựng là một chiếc máy chữ xách tay kiểu cũ, thân kim loại sơn đen, các phím tròn nhỏ như đã mòn cạnh vì bàn tay gõ hàng nghìn con chữ. Giữa núi rừng Việt Bắc, một chiếc máy chữ là tài sản quý và hiếm: phải mang theo từ vùng xuôi lên, bảo quản kỹ trong những chuyến hành quân di chuyển liên miên, tránh ẩm mốc, tránh rơi vỡ khi băng rừng, lội suối. Với một cơ quan kháng chiến thường xuyên phải di dời để giữ bí mật, mỗi vật dụng mang theo đều được cân nhắc theo nguyên tắc gọn nhẹ, và chiếc máy chữ là một trong số ít ngoại lệ được giữ lại bên mình vì tính thiết yếu của nó đối với công việc viết lách, soạn thảo văn bản hằng ngày.\n\nNhiều người từng làm việc gần Chủ tịch Hồ Chí Minh kể rằng Người có thói quen tự tay đánh máy phần lớn thư từ, bài viết, không nhờ cậy thư ký chép lại hay đánh máy hộ, kể cả khi tuổi đã cao. Cách làm việc ấy vừa xuất phát từ tính cách giản dị, không muốn phiền người khác vì việc riêng, vừa vì Người muốn tự mình chỉnh sửa câu chữ đến khi ưng ý mới thôi. Dưới mái lán nứa, tiếng lách cách của bàn phím máy chữ vang lên đều đặn mỗi khi có báo cáo cần trả lời gấp, có chỉ thị cần gửi kịp thời tới các chiến trường, hay đơn giản là một lá thư gửi bộ đội, thiếu nhi, đồng bào ở hậu phương.\n\nChiếc máy chữ gắn liền với một chặng quan trọng trong sự nghiệp báo chí cách mạng của Người: từ năm 1951, khi báo Nhân Dân – cơ quan ngôn luận của Đảng – chính thức ra đời tại chiến khu Việt Bắc, Chủ tịch Hồ Chí Minh thường xuyên viết bài cộng tác dưới bút danh C.B. Các bài báo ký C.B. có văn phong đặc trưng: câu ngắn, ý rõ, lập luận chặt chẽ nhưng gần gũi, dễ hiểu với cả những người ít chữ nghĩa nhất, đúng với quan điểm viết báo Người vẫn nhắc nhở: viết cho ai đọc, đọc rồi có làm được không. Nhiều bài trong số đó bàn về thi đua sản xuất, chống tham ô lãng phí, cổ vũ tinh thần kháng chiến, trở thành công cụ tuyên truyền sắc bén ngay giữa những ngày gian khổ nhất.\n\nSuốt cuộc đời hoạt động cách mạng, Người sử dụng nhiều bút danh khác nhau tùy từng giai đoạn, từng tờ báo, từ Nguyễn Ái Quốc thời kỳ ở Pháp, đến Trần Lực, T.L., C.B., X.Y.Z trong nước những năm kháng chiến. Cách viết báo ngắn gọn, thiết thực mà Người theo đuổi trở thành một trường phái ảnh hưởng lâu dài tới báo chí cách mạng Việt Nam, được các thế hệ nhà báo sau này xem là mẫu mực về việc dùng chữ nghĩa phục vụ quần chúng thay vì phô diễn câu chữ cầu kỳ.\n\nChiếc máy chữ trưng bày trong không gian 3D của gian Việt Bắc là mô hình phục dựng theo kiểu máy chữ xách tay phổ biến giữa thế kỷ hai mươi, giúp hình dung lại người bạn đồng hành thầm lặng ấy trong những năm tháng Chủ tịch Hồ Chí Minh sống và làm việc giữa rừng. Một số hiện vật liên quan đến việc viết lách, làm báo của Người – bản thảo, bút tích, dụng cụ làm việc – hiện được lưu giữ, trưng bày tại Bảo tàng Hồ Chí Minh (Hà Nội) và các khu di tích Phủ Chủ tịch, An toàn khu Định Hóa.","nguon":"Bảo tàng Hồ Chí Minh; Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","doc":[{"t":"Người bạn đồng hành thầm lặng ở chiến khu. Đặt cạnh bàn làm việc trong lán phục dựng là một chiếc máy chữ xách tay kiểu cũ, thân kim loại sơn đen, các phím tròn nhỏ như đã mòn cạnh vì bàn tay gõ hàng nghìn con chữ. Giữa núi rừng Việt Bắc, một chiếc máy chữ là tài sản quý và hiếm: phải mang theo từ vùng xuôi lên, bảo quản kỹ trong những chuyến hành quân di chuyển liên miên, tránh ẩm mốc, tránh rơi vỡ khi băng rừng, lội suối. Với một cơ quan kháng chiến thường xuyên phải di dời để giữ bí mật, mỗi vật dụng mang theo đều được cân nhắc theo nguyên tắc gọn nhẹ, và chiếc máy chữ là một trong số ít ngoại lệ được giữ lại bên mình vì tính thiết yếu của nó đối với công việc viết lách, soạn thảo văn bản hằng ngày."},{"t":"Nhiều người từng làm việc gần Chủ tịch Hồ Chí Minh kể rằng Người có thói quen tự tay đánh máy phần lớn thư từ, bài viết, không nhờ cậy thư ký chép lại hay đánh máy hộ, kể cả khi tuổi đã cao. Cách làm việc ấy vừa xuất phát từ tính cách giản dị, không muốn phiền người khác vì việc riêng, vừa vì Người muốn tự mình chỉnh sửa câu chữ đến khi ưng ý mới thôi. Dưới mái lán nứa, tiếng lách cách của bàn phím máy chữ vang lên đều đặn mỗi khi có báo cáo cần trả lời gấp, có chỉ thị cần gửi kịp thời tới các chiến trường, hay đơn giản là một lá thư gửi bộ đội, thiếu nhi, đồng bào ở hậu phương."},{"t":"Chiếc máy chữ gắn liền với một chặng quan trọng trong sự nghiệp báo chí cách mạng của Người: từ năm 1951, khi báo Nhân Dân – cơ quan ngôn luận của Đảng – chính thức ra đời tại chiến khu Việt Bắc, Chủ tịch Hồ Chí Minh thường xuyên viết bài cộng tác dưới bút danh C.B. Các bài báo ký C.B. có văn phong đặc trưng: câu ngắn, ý rõ, lập luận chặt chẽ nhưng gần gũi, dễ hiểu với cả những người ít chữ nghĩa nhất, đúng với quan điểm viết báo Người vẫn nhắc nhở: viết cho ai đọc, đọc rồi có làm được không. Nhiều bài trong số đó bàn về thi đua sản xuất, chống tham ô lãng phí, cổ vũ tinh thần kháng chiến, trở thành công cụ tuyên truyền sắc bén ngay giữa những ngày gian khổ nhất."},{"t":"Suốt cuộc đời hoạt động cách mạng, Người sử dụng nhiều bút danh khác nhau tùy từng giai đoạn, từng tờ báo, từ Nguyễn Ái Quốc thời kỳ ở Pháp, đến Trần Lực, T.L., C.B., X.Y.Z trong nước những năm kháng chiến. Cách viết báo ngắn gọn, thiết thực mà Người theo đuổi trở thành một trường phái ảnh hưởng lâu dài tới báo chí cách mạng Việt Nam, được các thế hệ nhà báo sau này xem là mẫu mực về việc dùng chữ nghĩa phục vụ quần chúng thay vì phô diễn câu chữ cầu kỳ."},{"t":"Chiếc máy chữ trưng bày trong không gian 3D của gian Việt Bắc là mô hình phục dựng theo kiểu máy chữ xách tay phổ biến giữa thế kỷ hai mươi, giúp hình dung lại người bạn đồng hành thầm lặng ấy trong những năm tháng Chủ tịch Hồ Chí Minh sống và làm việc giữa rừng. Một số hiện vật liên quan đến việc viết lách, làm báo của Người – bản thảo, bút tích, dụng cụ làm việc – hiện được lưu giữ, trưng bày tại Bảo tàng Hồ Chí Minh (Hà Nội) và các khu di tích Phủ Chủ tịch, An toàn khu Định Hóa."}]},{"id":"vintage_oil_lamp@-6.8,-19.8","x":-6.77,"y":3.84,"z":-19.75,"loai":"vintage_oil_lamp","ten":"Đèn dầu","tieu_de":"“Cảnh khuya như vẽ người chưa ngủ”","text":"Chiếc đèn dầu nhỏ đặt bên góc bàn làm việc là vật dụng chiếu sáng quen thuộc trong mọi lán trại kháng chiến ở Việt Bắc, nơi chưa hề có điện lưới và ánh sáng ban đêm chỉ trông vào ngọn lửa dầu hỏa leo lét trong bầu đèn thủy tinh. Loại đèn này – dân gian quen gọi là đèn Hoa Kỳ hay đèn tọa đăng – có cấu tạo đơn giản: bầu đựng dầu bằng kim loại hoặc thủy tinh, bấc vải xe tròn, chao đèn bằng kính trong để che gió mà vẫn giữ được ánh sáng. Giữa núi rừng thâm u, mỗi khi trời sập tối, ngọn đèn dầu trở thành trung tâm của cả căn lán: nơi cán bộ tụ họp đọc tài liệu, nơi bộ đội hành quân ghé chân sưởi ấm, và cũng là nơi một vị Chủ tịch nước ngồi lặng lẽ làm việc khi mọi người đã yên giấc.\n\nTheo lời kể của nhiều cán bộ, chiến sĩ từng phục vụ bên Người, Chủ tịch Hồ Chí Minh có thói quen thức khuya làm việc, đọc báo cáo, suy nghĩ về tình hình chiến sự và vận nước dưới ánh đèn dầu, trong khi anh em cần vụ, bảo vệ đã chìm vào giấc ngủ từ lâu. Ánh sáng đèn dầu tuy yếu ớt nhưng đều đặn hiện diện trong hầu hết những đêm như thế, trở thành một phần không thể tách rời khỏi hình ảnh Người giữa những năm tháng kháng chiến gian khổ, khi mọi quyết sách lớn nhỏ của đất nước đều được cân nhắc trong không gian tĩnh lặng, thiếu thốn đến vậy.\n\nChính trong một đêm như thế, tại chiến khu Việt Bắc năm 1947, Người viết bài thơ chữ Hán được dịch ra tiếng Việt với tên gọi “Cảnh khuya”: “Tiếng suối trong như tiếng hát xa / Trăng lồng cổ thụ bóng lồng hoa / Cảnh khuya như vẽ người chưa ngủ / Chưa ngủ vì lo nỗi nước nhà”. Bài thơ ngắn bốn câu vừa tả một đêm trăng núi rừng đẹp như tranh vẽ, vừa hé lộ tâm trạng thao thức của một người đứng đầu đất nước giữa những năm đầu kháng chiến còn nhiều gian nan, khi vận mệnh dân tộc là điều canh cánh không rời.\n\nCùng thời gian ở Việt Bắc, đầu năm 1948, Người còn viết bài thơ “Nguyên tiêu” (Rằm tháng Giêng), cũng tả cảnh đêm trăng trên sông nước giữa lúc bàn việc quân, với câu mở đầu quen thuộc “Kim dạ nguyên tiêu nguyệt chính viên”. Hai bài thơ ra đời cách nhau không xa, cùng một mạch cảm xúc: giữa khung cảnh thiên nhiên tĩnh lặng, đẹp đẽ của núi rừng Việt Bắc, nỗi lo việc nước vẫn thường trực trong tâm trí Người, không lúc nào ngơi nghỉ, kể cả những đêm trăng thanh gió mát hiếm hoi giữa bộn bề công việc kháng chiến.\n\n“Cảnh khuya” và “Nguyên tiêu” về sau được đưa vào chương trình giáo dục phổ thông, trở thành hai trong số những bài thơ được nhiều thế hệ học sinh Việt Nam thuộc lòng. Bản gốc chữ Hán cùng các bản dịch, chú giải hiện được lưu giữ trong Hồ Chí Minh Toàn tập và tại Bảo tàng Hồ Chí Minh; còn chiếc đèn dầu trong gian trưng bày là hiện vật phục dựng, gợi lại thứ ánh sáng khiêm nhường đã soi cho biết bao trang viết, bài thơ ra đời giữa những đêm chiến khu như thế.","nguon":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011","doc":[{"t":"“Cảnh khuya như vẽ người chưa ngủ”. Chiếc đèn dầu nhỏ đặt bên góc bàn làm việc là vật dụng chiếu sáng quen thuộc trong mọi lán trại kháng chiến ở Việt Bắc, nơi chưa hề có điện lưới và ánh sáng ban đêm chỉ trông vào ngọn lửa dầu hỏa leo lét trong bầu đèn thủy tinh. Loại đèn này – dân gian quen gọi là đèn Hoa Kỳ hay đèn tọa đăng – có cấu tạo đơn giản: bầu đựng dầu bằng kim loại hoặc thủy tinh, bấc vải xe tròn, chao đèn bằng kính trong để che gió mà vẫn giữ được ánh sáng. Giữa núi rừng thâm u, mỗi khi trời sập tối, ngọn đèn dầu trở thành trung tâm của cả căn lán: nơi cán bộ tụ họp đọc tài liệu, nơi bộ đội hành quân ghé chân sưởi ấm, và cũng là nơi một vị Chủ tịch nước ngồi lặng lẽ làm việc khi mọi người đã yên giấc."},{"t":"Theo lời kể của nhiều cán bộ, chiến sĩ từng phục vụ bên Người, Chủ tịch Hồ Chí Minh có thói quen thức khuya làm việc, đọc báo cáo, suy nghĩ về tình hình chiến sự và vận nước dưới ánh đèn dầu, trong khi anh em cần vụ, bảo vệ đã chìm vào giấc ngủ từ lâu. Ánh sáng đèn dầu tuy yếu ớt nhưng đều đặn hiện diện trong hầu hết những đêm như thế, trở thành một phần không thể tách rời khỏi hình ảnh Người giữa những năm tháng kháng chiến gian khổ, khi mọi quyết sách lớn nhỏ của đất nước đều được cân nhắc trong không gian tĩnh lặng, thiếu thốn đến vậy."},{"t":"Chính trong một đêm như thế, tại chiến khu Việt Bắc năm 1947, Người viết bài thơ chữ Hán được dịch ra tiếng Việt với tên gọi “Cảnh khuya”: “Tiếng suối trong như tiếng hát xa / Trăng lồng cổ thụ bóng lồng hoa / Cảnh khuya như vẽ người chưa ngủ / Chưa ngủ vì lo nỗi nước nhà”. Bài thơ ngắn bốn câu vừa tả một đêm trăng núi rừng đẹp như tranh vẽ, vừa hé lộ tâm trạng thao thức của một người đứng đầu đất nước giữa những năm đầu kháng chiến còn nhiều gian nan, khi vận mệnh dân tộc là điều canh cánh không rời."},{"t":"Cùng thời gian ở Việt Bắc, đầu năm 1948, Người còn viết bài thơ “Nguyên tiêu” (Rằm tháng Giêng), cũng tả cảnh đêm trăng trên sông nước giữa lúc bàn việc quân, với câu mở đầu quen thuộc “Kim dạ nguyên tiêu nguyệt chính viên”. Hai bài thơ ra đời cách nhau không xa, cùng một mạch cảm xúc: giữa khung cảnh thiên nhiên tĩnh lặng, đẹp đẽ của núi rừng Việt Bắc, nỗi lo việc nước vẫn thường trực trong tâm trí Người, không lúc nào ngơi nghỉ, kể cả những đêm trăng thanh gió mát hiếm hoi giữa bộn bề công việc kháng chiến."},{"t":"“Cảnh khuya” và “Nguyên tiêu” về sau được đưa vào chương trình giáo dục phổ thông, trở thành hai trong số những bài thơ được nhiều thế hệ học sinh Việt Nam thuộc lòng. Bản gốc chữ Hán cùng các bản dịch, chú giải hiện được lưu giữ trong Hồ Chí Minh Toàn tập và tại Bảo tàng Hồ Chí Minh; còn chiếc đèn dầu trong gian trưng bày là hiện vật phục dựng, gợi lại thứ ánh sáng khiêm nhường đã soi cho biết bao trang viết, bài thơ ra đời giữa những đêm chiến khu như thế."},{"t":"Bạn có biết? “Cảnh khuya” và “Nguyên tiêu” đều được Người làm bằng chữ Hán theo thể thất ngôn tứ tuyệt Đường luật, sau mới được dịch sang tiếng Việt để phổ biến rộng rãi (Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia)."}],"ban_co_biet":"“Cảnh khuya” và “Nguyên tiêu” đều được Người làm bằng chữ Hán theo thể thất ngôn tứ tuyệt Đường luật, sau mới được dịch sang tiếng Việt để phổ biến rộng rãi (Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia)."},{"id":"table@11.1,-24.3","x":11.06,"y":3.38,"z":-24.29,"loai":"table","ten":"Bàn họp Bộ Chính trị","tieu_de":"Ngày 6/12/1953: quyết định mở Chiến dịch Điện Biên Phủ","text":"Bộ bàn ghế mộc trong lán họp phục dựng gợi lại không gian giản dị nơi diễn ra một trong những quyết định quân sự quan trọng bậc nhất của cuộc kháng chiến chống Pháp. Chỉ là vài tấm ván ghép thô, không phủ khăn, không trang trí, đặt giữa một căn lán nứa nhỏ nép mình dưới chân đèo De, thuộc xã Phú Đình, huyện Định Hóa, tỉnh Thái Nguyên – nơi cơ quan đầu não kháng chiến từng đóng trong những năm 1953 – 1954. Trên mặt bàn mộc ấy, thay vì giấy tờ hành chính thông thường, là những tấm bản đồ tác chiến, báo cáo tình hình chiến trường, được xem như nơi cân nhắc cho một quyết định có thể làm thay đổi cả cục diện chiến tranh.\n\nCuối năm 1953, sau nhiều chiến dịch từ Việt Bắc, Biên giới đến Hòa Bình, Tây Bắc, tương quan lực lượng trên chiến trường Đông Dương đã có những chuyển biến quan trọng. Thực dân Pháp, với sự hậu thuẫn của Mỹ, xây dựng Điện Biên Phủ thành một tập đoàn cứ điểm mạnh, coi đó là pháo đài khó xâm phạm giữa lòng Tây Bắc. Trước tình hình ấy, Trung ương Đảng và Chủ tịch Hồ Chí Minh phải cân nhắc một quyết định chiến lược: có nên tập trung lực lượng chủ lực mở một chiến dịch quy mô lớn nhằm vào chính tập đoàn cứ điểm này, trong bối cảnh đường vận chuyển hậu cần từ hậu phương lên Tây Bắc dài và khó khăn bậc nhất từ trước tới nay.\n\nNgày 6 tháng 12 năm 1953, tại lán Tỉn Keo, Bộ Chính trị họp dưới sự chủ trì của Chủ tịch Hồ Chí Minh, chính thức thông qua chủ trương mở Chiến dịch Điện Biên Phủ. Đảng ủy và Bộ Chỉ huy chiến dịch được thành lập ngay trong cuộc họp này, do Đại tướng Võ Nguyên Giáp làm Bí thư Đảng ủy kiêm Chỉ huy trưởng chiến dịch. Trước khi lên đường ra mặt trận, Đại tướng còn được Người giao toàn quyền quyết định tại chỗ, với lời dặn dò được nhiều tài liệu, hồi ký ghi lại: trận này quan hệ đến vận mệnh của cả dân tộc, cần phải đánh cho thắng, chắc thắng mới đánh, không chắc thắng không đánh.\n\nChưa đầy năm tháng sau cuộc họp lịch sử ấy, ngày 7 tháng 5 năm 1954, Chiến dịch Điện Biên Phủ toàn thắng, tập đoàn cứ điểm mạnh nhất Đông Dương của quân Pháp sụp đổ hoàn toàn. Chiến thắng này buộc chính phủ Pháp phải ngồi vào bàn đàm phán, dẫn tới Hiệp định Genève được ký kết ngày 21 tháng 7 năm 1954, chấm dứt cuộc chiến tranh xâm lược của thực dân Pháp tại Đông Dương. Từ một quyết định được đưa ra quanh chiếc bàn mộc giữa rừng, cả cục diện chiến tranh Đông Dương đã rẽ sang một hướng khác, mở đường cho miền Bắc bước vào thời kỳ hòa bình, xây dựng.\n\nLán Tỉn Keo cùng bộ bàn ghế họp Bộ Chính trị năm xưa nay được phục dựng, bảo tồn trong Khu di tích lịch sử An toàn khu (ATK) Định Hóa, tỉnh Thái Nguyên – một trong những điểm đến quan trọng để tìm hiểu về những ngày tháng cơ quan đầu não kháng chiến sống và làm việc giữa núi rừng Việt Bắc. Bộ bàn trong không gian trưng bày 3D là hiện vật phục dựng theo đúng hình dáng mộc mạc ấy, giúp người xem hình dung lại khung cảnh của một cuộc họp đã đi vào lịch sử.","nguon":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia; Khu di tích lịch sử An toàn khu Định Hóa","doc":[{"t":"Ngày 6/12/1953: quyết định mở Chiến dịch Điện Biên Phủ. Bộ bàn ghế mộc trong lán họp phục dựng gợi lại không gian giản dị nơi diễn ra một trong những quyết định quân sự quan trọng bậc nhất của cuộc kháng chiến chống Pháp. Chỉ là vài tấm ván ghép thô, không phủ khăn, không trang trí, đặt giữa một căn lán nứa nhỏ nép mình dưới chân đèo De, thuộc xã Phú Đình, huyện Định Hóa, tỉnh Thái Nguyên – nơi cơ quan đầu não kháng chiến từng đóng trong những năm 1953 – 1954. Trên mặt bàn mộc ấy, thay vì giấy tờ hành chính thông thường, là những tấm bản đồ tác chiến, báo cáo tình hình chiến trường, được xem như nơi cân nhắc cho một quyết định có thể làm thay đổi cả cục diện chiến tranh."},{"t":"Cuối năm 1953, sau nhiều chiến dịch từ Việt Bắc, Biên giới đến Hòa Bình, Tây Bắc, tương quan lực lượng trên chiến trường Đông Dương đã có những chuyển biến quan trọng. Thực dân Pháp, với sự hậu thuẫn của Mỹ, xây dựng Điện Biên Phủ thành một tập đoàn cứ điểm mạnh, coi đó là pháo đài khó xâm phạm giữa lòng Tây Bắc. Trước tình hình ấy, Trung ương Đảng và Chủ tịch Hồ Chí Minh phải cân nhắc một quyết định chiến lược: có nên tập trung lực lượng chủ lực mở một chiến dịch quy mô lớn nhằm vào chính tập đoàn cứ điểm này, trong bối cảnh đường vận chuyển hậu cần từ hậu phương lên Tây Bắc dài và khó khăn bậc nhất từ trước tới nay."},{"t":"Ngày 6 tháng 12 năm 1953, tại lán Tỉn Keo, Bộ Chính trị họp dưới sự chủ trì của Chủ tịch Hồ Chí Minh, chính thức thông qua chủ trương mở Chiến dịch Điện Biên Phủ. Đảng ủy và Bộ Chỉ huy chiến dịch được thành lập ngay trong cuộc họp này, do Đại tướng Võ Nguyên Giáp làm Bí thư Đảng ủy kiêm Chỉ huy trưởng chiến dịch. Trước khi lên đường ra mặt trận, Đại tướng còn được Người giao toàn quyền quyết định tại chỗ, với lời dặn dò được nhiều tài liệu, hồi ký ghi lại: trận này quan hệ đến vận mệnh của cả dân tộc, cần phải đánh cho thắng, chắc thắng mới đánh, không chắc thắng không đánh."},{"t":"Chưa đầy năm tháng sau cuộc họp lịch sử ấy, ngày 7 tháng 5 năm 1954, Chiến dịch Điện Biên Phủ toàn thắng, tập đoàn cứ điểm mạnh nhất Đông Dương của quân Pháp sụp đổ hoàn toàn. Chiến thắng này buộc chính phủ Pháp phải ngồi vào bàn đàm phán, dẫn tới Hiệp định Genève được ký kết ngày 21 tháng 7 năm 1954, chấm dứt cuộc chiến tranh xâm lược của thực dân Pháp tại Đông Dương. Từ một quyết định được đưa ra quanh chiếc bàn mộc giữa rừng, cả cục diện chiến tranh Đông Dương đã rẽ sang một hướng khác, mở đường cho miền Bắc bước vào thời kỳ hòa bình, xây dựng."},{"t":"Lán Tỉn Keo cùng bộ bàn ghế họp Bộ Chính trị năm xưa nay được phục dựng, bảo tồn trong Khu di tích lịch sử An toàn khu (ATK) Định Hóa, tỉnh Thái Nguyên – một trong những điểm đến quan trọng để tìm hiểu về những ngày tháng cơ quan đầu não kháng chiến sống và làm việc giữa núi rừng Việt Bắc. Bộ bàn trong không gian trưng bày 3D là hiện vật phục dựng theo đúng hình dáng mộc mạc ấy, giúp người xem hình dung lại khung cảnh của một cuộc họp đã đi vào lịch sử."},{"t":"Bạn có biết? Đảng ủy và Bộ Chỉ huy Chiến dịch Điện Biên Phủ, do Đại tướng Võ Nguyên Giáp đứng đầu, được thành lập ngay trong cuộc họp Bộ Chính trị ngày 6/12/1953 tại Tỉn Keo (Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia)."}],"ban_co_biet":"Đảng ủy và Bộ Chỉ huy Chiến dịch Điện Biên Phủ, do Đại tướng Võ Nguyên Giáp đứng đầu, được thành lập ngay trong cuộc họp Bộ Chính trị ngày 6/12/1953 tại Tỉn Keo (Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia)."},{"id":"table@9.2,-24.7","x":9.15,"y":3.38,"z":-24.68,"loai":"table","ten":"Bàn họp gỗ mộc","tieu_de":"Lời dặn “chắc thắng mới đánh”","text":"Cách bàn họp chính không xa, chiếc bàn gỗ mộc thứ hai trong không gian phục dựng gợi lại nơi những cuộc trao đổi, dặn dò riêng giữa Chủ tịch Hồ Chí Minh với các tướng lĩnh trước khi họ lên đường ra mặt trận. Không cầu kỳ hơn chiếc bàn họp chính là bao, bàn chỉ được ghép bằng vài tấm gỗ xẻ tại chỗ, đặt trong một góc lán nhỏ đủ cho vài người ngồi trò chuyện, nhưng lại là nơi chứng kiến một trong những lời dặn dò nổi tiếng nhất của Người trong kháng chiến chống Pháp.\n\nTrước khi Chiến dịch Điện Biên Phủ mở màn, phương án tác chiến ban đầu được xây dựng theo hướng đánh nhanh, giải quyết nhanh, dự kiến dùng bộ binh, pháo binh tiến công đồng loạt để nhanh chóng tiêu diệt tập đoàn cứ điểm trong một thời gian ngắn. Đây là phương án được chuẩn bị công phu, huy động lớn về hỏa lực và nhân lực, nhưng tiềm ẩn rủi ro cao trước một đối phương đã có thời gian củng cố công sự kiên cố trên địa hình lòng chảo hiểm trở.\n\nTheo hồi ký của Đại tướng Võ Nguyên Giáp, trước khi ông rời Việt Bắc ra mặt trận, Chủ tịch Hồ Chí Minh đã dặn dò: “Trận này rất quan trọng, phải đánh cho thắng. Chắc thắng mới đánh, không chắc thắng không đánh”. Lời dặn ngắn gọn nhưng đặt lên vai vị Tổng Tư lệnh một trách nhiệm nặng nề: được toàn quyền quyết định tại mặt trận, nhưng điều kiện tiên quyết luôn là sự chắc chắn của thắng lợi, không được đem sinh mạng bộ đội ra đánh cược cho một chiến thắng chưa vững chắc.\n\nRa tới mặt trận, sau nhiều ngày quan sát thực địa và cân nhắc, ngày 26 tháng 1 năm 1954, Đại tướng Võ Nguyên Giáp đưa ra một quyết định khó khăn: chuyển toàn bộ phương châm tác chiến từ đánh nhanh, giải quyết nhanh sang đánh chắc, tiến chắc, tức bao vây, xây dựng trận địa vững chắc, tiến công từng bước, đánh chắc thắng từng cứ điểm một trước khi tổng công kích. Quyết định này đã được báo cáo và được Bộ Chính trị, Chủ tịch Hồ Chí Minh đồng ý, đúng theo tinh thần lời dặn chắc thắng mới đánh trước đó.\n\nSự thay đổi phương châm ấy khiến chiến dịch kéo dài hơn dự kiến ban đầu – từ chỗ định đánh nhanh trong vài ngày đêm chuyển sang chuẩn bị hàng tháng trời để kéo pháo vào trận địa, đào hào vây lấn từng bước – nhưng đã tránh được những tổn thất có thể rất lớn nếu tiến công vội vàng vào một hệ thống công sự đã được củng cố kiên cố. Quyết định ấy về sau được giới nghiên cứu quân sự đánh giá là một trong những bước ngoặt quan trọng nhất, góp phần quyết định vào chiến thắng toàn vẹn ngày 7 tháng 5 năm 1954. Câu chuyện về chiếc bàn nhỏ nơi lời dặn dò ấy được nói ra, cùng với quyết định lịch sử ngoài mặt trận, đến nay vẫn được nhắc lại trong các tài liệu quân sự, trong hồi ký của chính Đại tướng Võ Nguyên Giáp, như một bài học về sự thận trọng, về niềm tin trao đi cùng trách nhiệm nặng nề, giữa những thời khắc quyết định vận mệnh dân tộc. Bàn họp phục dựng trong gian trưng bày, vì thế, không chỉ là một vật dụng mô phỏng không gian sinh hoạt, mà còn là điểm gợi nhắc một quyết định chỉ huy táo bạo đã làm nên khác biệt giữa thắng và bại trên chiến trường Điện Biên Phủ, một câu chuyện thường được kể lại tại các khu di tích và trong giáo trình lịch sử quân sự như minh chứng cho bản lĩnh cầm quân thận trọng mà quyết đoán.","nguon":"Võ Nguyên Giáp – Điện Biên Phủ: Điểm hẹn lịch sử (hồi ký), NXB Quân đội nhân dân; Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":[{"t":"Lời dặn “chắc thắng mới đánh”. Cách bàn họp chính không xa, chiếc bàn gỗ mộc thứ hai trong không gian phục dựng gợi lại nơi những cuộc trao đổi, dặn dò riêng giữa Chủ tịch Hồ Chí Minh với các tướng lĩnh trước khi họ lên đường ra mặt trận. Không cầu kỳ hơn chiếc bàn họp chính là bao, bàn chỉ được ghép bằng vài tấm gỗ xẻ tại chỗ, đặt trong một góc lán nhỏ đủ cho vài người ngồi trò chuyện, nhưng lại là nơi chứng kiến một trong những lời dặn dò nổi tiếng nhất của Người trong kháng chiến chống Pháp."},{"t":"Trước khi Chiến dịch Điện Biên Phủ mở màn, phương án tác chiến ban đầu được xây dựng theo hướng đánh nhanh, giải quyết nhanh, dự kiến dùng bộ binh, pháo binh tiến công đồng loạt để nhanh chóng tiêu diệt tập đoàn cứ điểm trong một thời gian ngắn. Đây là phương án được chuẩn bị công phu, huy động lớn về hỏa lực và nhân lực, nhưng tiềm ẩn rủi ro cao trước một đối phương đã có thời gian củng cố công sự kiên cố trên địa hình lòng chảo hiểm trở."},{"t":"Theo hồi ký của Đại tướng Võ Nguyên Giáp, trước khi ông rời Việt Bắc ra mặt trận, Chủ tịch Hồ Chí Minh đã dặn dò: “Trận này rất quan trọng, phải đánh cho thắng. Chắc thắng mới đánh, không chắc thắng không đánh”. Lời dặn ngắn gọn nhưng đặt lên vai vị Tổng Tư lệnh một trách nhiệm nặng nề: được toàn quyền quyết định tại mặt trận, nhưng điều kiện tiên quyết luôn là sự chắc chắn của thắng lợi, không được đem sinh mạng bộ đội ra đánh cược cho một chiến thắng chưa vững chắc."},{"t":"Ra tới mặt trận, sau nhiều ngày quan sát thực địa và cân nhắc, ngày 26 tháng 1 năm 1954, Đại tướng Võ Nguyên Giáp đưa ra một quyết định khó khăn: chuyển toàn bộ phương châm tác chiến từ đánh nhanh, giải quyết nhanh sang đánh chắc, tiến chắc, tức bao vây, xây dựng trận địa vững chắc, tiến công từng bước, đánh chắc thắng từng cứ điểm một trước khi tổng công kích. Quyết định này đã được báo cáo và được Bộ Chính trị, Chủ tịch Hồ Chí Minh đồng ý, đúng theo tinh thần lời dặn chắc thắng mới đánh trước đó."},{"t":"Sự thay đổi phương châm ấy khiến chiến dịch kéo dài hơn dự kiến ban đầu – từ chỗ định đánh nhanh trong vài ngày đêm chuyển sang chuẩn bị hàng tháng trời để kéo pháo vào trận địa, đào hào vây lấn từng bước – nhưng đã tránh được những tổn thất có thể rất lớn nếu tiến công vội vàng vào một hệ thống công sự đã được củng cố kiên cố. Quyết định ấy về sau được giới nghiên cứu quân sự đánh giá là một trong những bước ngoặt quan trọng nhất, góp phần quyết định vào chiến thắng toàn vẹn ngày 7 tháng 5 năm 1954. Câu chuyện về chiếc bàn nhỏ nơi lời dặn dò ấy được nói ra, cùng với quyết định lịch sử ngoài mặt trận, đến nay vẫn được nhắc lại trong các tài liệu quân sự, trong hồi ký của chính Đại tướng Võ Nguyên Giáp, như một bài học về sự thận trọng, về niềm tin trao đi cùng trách nhiệm nặng nề, giữa những thời khắc quyết định vận mệnh dân tộc. Bàn họp phục dựng trong gian trưng bày, vì thế, không chỉ là một vật dụng mô phỏng không gian sinh hoạt, mà còn là điểm gợi nhắc một quyết định chỉ huy táo bạo đã làm nên khác biệt giữa thắng và bại trên chiến trường Điện Biên Phủ, một câu chuyện thường được kể lại tại các khu di tích và trong giáo trình lịch sử quân sự như minh chứng cho bản lĩnh cầm quân thận trọng mà quyết đoán."}]},{"id":"vintage_oil_lamp@12.2,-24.1","x":12.19,"y":4.14,"z":-24.07,"loai":"vintage_oil_lamp","ten":"Đèn dầu lán họp","tieu_de":"Quyết định quân sự, thông điệp hòa bình","text":"Một chiếc đèn dầu khác, cùng kiểu dáng mộc mạc, được đặt trong góc lán họp Bộ Chính trị ở Tỉn Keo, nơi ánh sáng của nó không chỉ soi những tấm bản đồ quân sự mà còn soi cả những trang điện tín, thư từ được chuyển về từ xa. Trong hoàn cảnh liên lạc khó khăn của chiến khu, mọi thông tin từ bên ngoài – kể cả những bức điện quan trọng liên quan tới dư luận quốc tế – đều phải chờ đến tối mới có thời gian được đọc kỹ, cân nhắc dưới ánh đèn dầu tù mù như thế.\n\nSong song với việc chuẩn bị cho trận đánh lớn nhất của cuộc kháng chiến, Chủ tịch Hồ Chí Minh và Trung ương Đảng vẫn luôn theo dõi sát diễn biến chính trị, ngoại giao quốc tế, ý thức rõ rằng một cuộc chiến tranh không chỉ được quyết định trên chiến trường mà còn trên bàn đàm phán và trong dư luận thế giới. Đây là thời điểm mà xu hướng muốn chấm dứt chiến tranh Đông Dương bằng thương lượng đã bắt đầu xuất hiện rõ nét hơn trong chính giới nhiều nước phương Tây, tạo ra một cánh cửa ngoại giao mà phía Việt Nam Dân chủ Cộng hòa chủ động tận dụng.\n\nNgày 26 tháng 11 năm 1953 – chỉ ít ngày trước cuộc họp quyết định mở Chiến dịch Điện Biên Phủ – Chủ tịch Hồ Chí Minh trả lời phỏng vấn báo Expressen của Thụy Điển, khẳng định lập trường của Việt Nam sẵn sàng thương lượng hòa bình nếu thực dân Pháp thật sự tôn trọng độc lập của Việt Nam. Câu trả lời được đăng tải trên báo chí quốc tế, cho thấy rõ chủ trương nhất quán: kiên quyết kháng chiến đến cùng để bảo vệ độc lập dân tộc, nhưng luôn để ngỏ con đường hòa bình nếu đối phương thực tâm chấm dứt chiến tranh xâm lược trên cơ sở tôn trọng chủ quyền Việt Nam.\n\nDiễn biến sau đó cho thấy hai hướng đi quân sự và ngoại giao đã gặp nhau đúng lúc: chiến thắng Điện Biên Phủ ngày 7 tháng 5 năm 1954 giáng một đòn quyết định vào ý chí xâm lược của Pháp, tạo áp lực trực tiếp lên bàn Hội nghị Genève đang họp bàn về Đông Dương. Hiệp định Genève được ký kết ngày 21 tháng 7 năm 1954, công nhận độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của Việt Nam, Lào, Campuchia, chính thức chấm dứt cuộc chiến tranh của thực dân Pháp tại Đông Dương.\n\nChiếc đèn dầu nhỏ trong lán họp, vì thế, mang một ý nghĩa kép: nó từng soi sáng cho những quyết định quân sự táo bạo, cũng từng soi sáng cho những trang thông điệp hòa bình được cân nhắc từng câu chữ. Hiện vật trưng bày là mô hình phục dựng, nhưng câu chuyện đằng sau nó – về sự kết hợp nhuần nhuyễn giữa đấu tranh quân sự và đấu tranh ngoại giao dưới sự chỉ đạo của Chủ tịch Hồ Chí Minh – vẫn được ghi lại trong nhiều công trình nghiên cứu lịch sử ngoại giao Việt Nam thời kỳ kháng chiến chống Pháp.","nguon":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia, 2011; Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":[{"t":"Quyết định quân sự, thông điệp hòa bình. Một chiếc đèn dầu khác, cùng kiểu dáng mộc mạc, được đặt trong góc lán họp Bộ Chính trị ở Tỉn Keo, nơi ánh sáng của nó không chỉ soi những tấm bản đồ quân sự mà còn soi cả những trang điện tín, thư từ được chuyển về từ xa. Trong hoàn cảnh liên lạc khó khăn của chiến khu, mọi thông tin từ bên ngoài – kể cả những bức điện quan trọng liên quan tới dư luận quốc tế – đều phải chờ đến tối mới có thời gian được đọc kỹ, cân nhắc dưới ánh đèn dầu tù mù như thế."},{"t":"Song song với việc chuẩn bị cho trận đánh lớn nhất của cuộc kháng chiến, Chủ tịch Hồ Chí Minh và Trung ương Đảng vẫn luôn theo dõi sát diễn biến chính trị, ngoại giao quốc tế, ý thức rõ rằng một cuộc chiến tranh không chỉ được quyết định trên chiến trường mà còn trên bàn đàm phán và trong dư luận thế giới. Đây là thời điểm mà xu hướng muốn chấm dứt chiến tranh Đông Dương bằng thương lượng đã bắt đầu xuất hiện rõ nét hơn trong chính giới nhiều nước phương Tây, tạo ra một cánh cửa ngoại giao mà phía Việt Nam Dân chủ Cộng hòa chủ động tận dụng."},{"t":"Ngày 26 tháng 11 năm 1953 – chỉ ít ngày trước cuộc họp quyết định mở Chiến dịch Điện Biên Phủ – Chủ tịch Hồ Chí Minh trả lời phỏng vấn báo Expressen của Thụy Điển, khẳng định lập trường của Việt Nam sẵn sàng thương lượng hòa bình nếu thực dân Pháp thật sự tôn trọng độc lập của Việt Nam. Câu trả lời được đăng tải trên báo chí quốc tế, cho thấy rõ chủ trương nhất quán: kiên quyết kháng chiến đến cùng để bảo vệ độc lập dân tộc, nhưng luôn để ngỏ con đường hòa bình nếu đối phương thực tâm chấm dứt chiến tranh xâm lược trên cơ sở tôn trọng chủ quyền Việt Nam."},{"t":"Diễn biến sau đó cho thấy hai hướng đi quân sự và ngoại giao đã gặp nhau đúng lúc: chiến thắng Điện Biên Phủ ngày 7 tháng 5 năm 1954 giáng một đòn quyết định vào ý chí xâm lược của Pháp, tạo áp lực trực tiếp lên bàn Hội nghị Genève đang họp bàn về Đông Dương. Hiệp định Genève được ký kết ngày 21 tháng 7 năm 1954, công nhận độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của Việt Nam, Lào, Campuchia, chính thức chấm dứt cuộc chiến tranh của thực dân Pháp tại Đông Dương."},{"t":"Chiếc đèn dầu nhỏ trong lán họp, vì thế, mang một ý nghĩa kép: nó từng soi sáng cho những quyết định quân sự táo bạo, cũng từng soi sáng cho những trang thông điệp hòa bình được cân nhắc từng câu chữ. Hiện vật trưng bày là mô hình phục dựng, nhưng câu chuyện đằng sau nó – về sự kết hợp nhuần nhuyễn giữa đấu tranh quân sự và đấu tranh ngoại giao dưới sự chỉ đạo của Chủ tịch Hồ Chí Minh – vẫn được ghi lại trong nhiều công trình nghiên cứu lịch sử ngoại giao Việt Nam thời kỳ kháng chiến chống Pháp."}]},{"id":"tea_set_01@10.0,-24.5","x":9.98,"y":4.14,"z":-24.51,"loai":"tea_set_01","ten":"Bộ ấm chén","tieu_de":"Chén trà trên đất chè Thái Nguyên","text":"Bộ ấm chén sành nhỏ đặt cạnh bàn họp là vật dụng minh họa, tái hiện một nét sinh hoạt quen thuộc trong các buổi làm việc, hội họp giữa núi rừng Việt Bắc: chén trà nóng mời khách, mời cán bộ trước khi vào việc. Ấm nhỏ, chén hạt mít không men bóng bẩy, kiểu gốm mộc mạc vẫn được các gia đình miền núi, trung du phía Bắc sử dụng phổ biến suốt nhiều thế hệ, khác hẳn những bộ trà cầu kỳ, cao sang của thành thị.\n\nUống chè xanh, chè mạn là tập quán sinh hoạt lâu đời của cư dân vùng trung du, miền núi phía Bắc, đặc biệt gắn liền với vùng đất Thái Nguyên – nơi từ lâu đã nổi tiếng với những nương chè trải khắp các sườn đồi, cho ra loại trà có hương vị đặc trưng được nhiều vùng miền ưa chuộng. Với người dân nơi đây, ấm nước chè luôn sẵn sàng trên bếp, và mời khách một chén trà nóng là cách thể hiện sự hiếu khách, thân tình đơn giản nhất, không phân biệt sang hèn.\n\nTrong những năm cơ quan đầu não kháng chiến đóng tại An toàn khu Định Hóa, sinh hoạt của cán bộ, bộ đội gắn bó mật thiết với đời sống của đồng bào các dân tộc địa phương. Trước hay sau mỗi buổi họp bàn việc quân, việc nước trong những căn lán đơn sơ, chén trà nóng rót ra không chỉ để giải khát mà còn là khoảng lặng ấm áp giữa bộn bề công việc, gắn kết tình quân dân giữa những người cùng chung chí hướng kháng chiến, kiến quốc giữa hoàn cảnh thiếu thốn trăm bề.\n\nĐịnh Hóa, nơi đặt phần lớn các cơ quan Trung ương suốt chín năm kháng chiến, nằm giữa lòng tỉnh Thái Nguyên – vùng đất chè lâu đời của miền Bắc. Sự trùng hợp giữa một vùng căn cứ địa cách mạng và một vùng chè nổi tiếng không phải ngẫu nhiên: chính địa hình đồi núi, cây cối rậm rạp thuận lợi cho việc giữ bí mật, ngụy trang cũng là điều kiện tự nhiên cho cây chè phát triển, tạo nên một vùng đất vừa che chở cách mạng vừa nuôi dưỡng một nghề truyền thống gắn bó với đời sống người dân đến tận hôm nay.\n\nBộ ấm chén trong gian trưng bày, như đã nói, là vật dụng minh họa chứ không phải hiện vật gốc gắn với một sự kiện cụ thể nào của Chủ tịch Hồ Chí Minh. Nhưng đặt cạnh bàn họp Bộ Chính trị, nó góp phần dựng lại không khí giản dị, đời thường của những buổi làm việc giữa chiến khu – nơi các quyết sách lớn của đất nước được bàn định trong một không gian gần gũi, ấm áp tình người, chứ không xa cách, quan cách như người ta có thể tưởng tượng về một cơ quan đầu não thời chiến. Ngày nay, Thái Nguyên vẫn giữ vị trí là một trong những vùng chè lớn nhất cả nước, với vùng chè đặc sản Tân Cương được nhiều người biết đến; khách tham quan Khu di tích An toàn khu Định Hóa, bên cạnh tìm hiểu những địa điểm Chủ tịch Hồ Chí Minh từng sống và làm việc, cũng có dịp ghé những đồi chè xanh mướt trải dài quanh vùng – hình ảnh song hành giữa ký ức kháng chiến và đời sống lao động bình dị vẫn tiếp diễn đến hôm nay.","nguon":"Khu Di tích lịch sử ATK Định Hóa (Thái Nguyên)","doc":[{"t":"Chén trà trên đất chè Thái Nguyên. Bộ ấm chén sành nhỏ đặt cạnh bàn họp là vật dụng minh họa, tái hiện một nét sinh hoạt quen thuộc trong các buổi làm việc, hội họp giữa núi rừng Việt Bắc: chén trà nóng mời khách, mời cán bộ trước khi vào việc. Ấm nhỏ, chén hạt mít không men bóng bẩy, kiểu gốm mộc mạc vẫn được các gia đình miền núi, trung du phía Bắc sử dụng phổ biến suốt nhiều thế hệ, khác hẳn những bộ trà cầu kỳ, cao sang của thành thị."},{"t":"Uống chè xanh, chè mạn là tập quán sinh hoạt lâu đời của cư dân vùng trung du, miền núi phía Bắc, đặc biệt gắn liền với vùng đất Thái Nguyên – nơi từ lâu đã nổi tiếng với những nương chè trải khắp các sườn đồi, cho ra loại trà có hương vị đặc trưng được nhiều vùng miền ưa chuộng. Với người dân nơi đây, ấm nước chè luôn sẵn sàng trên bếp, và mời khách một chén trà nóng là cách thể hiện sự hiếu khách, thân tình đơn giản nhất, không phân biệt sang hèn."},{"t":"Trong những năm cơ quan đầu não kháng chiến đóng tại An toàn khu Định Hóa, sinh hoạt của cán bộ, bộ đội gắn bó mật thiết với đời sống của đồng bào các dân tộc địa phương. Trước hay sau mỗi buổi họp bàn việc quân, việc nước trong những căn lán đơn sơ, chén trà nóng rót ra không chỉ để giải khát mà còn là khoảng lặng ấm áp giữa bộn bề công việc, gắn kết tình quân dân giữa những người cùng chung chí hướng kháng chiến, kiến quốc giữa hoàn cảnh thiếu thốn trăm bề."},{"t":"Định Hóa, nơi đặt phần lớn các cơ quan Trung ương suốt chín năm kháng chiến, nằm giữa lòng tỉnh Thái Nguyên – vùng đất chè lâu đời của miền Bắc. Sự trùng hợp giữa một vùng căn cứ địa cách mạng và một vùng chè nổi tiếng không phải ngẫu nhiên: chính địa hình đồi núi, cây cối rậm rạp thuận lợi cho việc giữ bí mật, ngụy trang cũng là điều kiện tự nhiên cho cây chè phát triển, tạo nên một vùng đất vừa che chở cách mạng vừa nuôi dưỡng một nghề truyền thống gắn bó với đời sống người dân đến tận hôm nay."},{"t":"Bộ ấm chén trong gian trưng bày, như đã nói, là vật dụng minh họa chứ không phải hiện vật gốc gắn với một sự kiện cụ thể nào của Chủ tịch Hồ Chí Minh. Nhưng đặt cạnh bàn họp Bộ Chính trị, nó góp phần dựng lại không khí giản dị, đời thường của những buổi làm việc giữa chiến khu – nơi các quyết sách lớn của đất nước được bàn định trong một không gian gần gũi, ấm áp tình người, chứ không xa cách, quan cách như người ta có thể tưởng tượng về một cơ quan đầu não thời chiến. Ngày nay, Thái Nguyên vẫn giữ vị trí là một trong những vùng chè lớn nhất cả nước, với vùng chè đặc sản Tân Cương được nhiều người biết đến; khách tham quan Khu di tích An toàn khu Định Hóa, bên cạnh tìm hiểu những địa điểm Chủ tịch Hồ Chí Minh từng sống và làm việc, cũng có dịp ghé những đồi chè xanh mướt trải dài quanh vùng – hình ảnh song hành giữa ký ức kháng chiến và đời sống lao động bình dị vẫn tiếp diễn đến hôm nay."}]},{"id":"hearth@-17.5,-7.0","x":-17.5,"y":0.33,"z":-7,"loai":"hearth","ten":"Bếp Hoàng Cầm","tieu_de":"Bếp giấu khói của anh nuôi Hoàng Cầm","text":"Khác hẳn hình dung thông thường về một cái bếp, bếp Hoàng Cầm trong không gian phục dựng là một hố đào sâu xuống lòng đất, quanh miệng hố là hệ thống rãnh nhỏ chạy tỏa ra nhiều hướng, phủ đất mỏng và cành lá ngụy trang phía trên. Khi nhóm lửa, thay vì bốc thẳng lên cao thành cột khói dễ bị phát hiện từ xa, khói bếp theo các đường rãnh ngầm len lỏi, tản mỏng ra một vùng rộng quanh miệng hố rồi tan biến, chỉ còn lại một lớp hơi mờ là là sát mặt đất như sương sớm, khó lòng nhận ra ngay cả khi quan sát từ trên không.\n\nTrong chiến tranh, việc nấu ăn giữa rừng luôn tiềm ẩn nguy hiểm: một cột khói bốc lên bất cẩn có thể tố cáo vị trí đóng quân, dẫn máy bay hay pháo binh đối phương tới oanh tạc. Đối với một đội quân phải nuôi hàng vạn cán bộ, chiến sĩ giữa núi rừng, bài toán vừa nấu chín được cơm vừa không để lộ khói trở thành một yêu cầu sống còn, đặc biệt trong giai đoạn chiến tranh có sự tham gia ngày càng nhiều của không quân đối phương.\n\nKiểu bếp giấu khói này là sáng kiến của anh nuôi Hoàng Cầm, thuộc Đại đoàn 308, ra đời trong Chiến dịch Hòa Bình những năm 1951 – 1952. Từ quan sát thực tế và nhu cầu cấp thiết của đơn vị, người chiến sĩ nuôi quân bình dị ấy đã nghĩ ra cách đào rãnh dẫn khói tỏa rộng trong lòng đất thay vì để khói bốc thẳng lên trời, một giải pháp đơn giản nhưng hiệu quả bất ngờ, giúp bộ đội có thể nấu ăn an toàn ngay gần tiền tuyến mà không lo bị lộ.\n\nTừ một sáng kiến của một đơn vị, cách làm bếp không khói nhanh chóng được phổ biến rộng rãi trong toàn quân, trở thành kỹ thuật hậu cần tiêu chuẩn ở khắp các chiến trường, kể cả trong Chiến dịch Điện Biên Phủ năm 1954, nơi hàng vạn bộ đội, dân công phải ăn ở ngay trong các chiến hào, lán trại giữa vòng vây quân địch. Về sau, bếp Hoàng Cầm còn tiếp tục được sử dụng suốt cuộc kháng chiến chống Mỹ, trở thành một trong những hình ảnh tiêu biểu của hậu cần chiến trường Việt Nam, gắn liền với tên tuổi người lính nuôi quân đã sáng tạo ra nó.\n\nNgày nay, mô hình bếp Hoàng Cầm được phục dựng tại nhiều khu di tích lịch sử, bảo tàng quân sự trên cả nước, trong đó có Khu di tích lịch sử An toàn khu Định Hóa và các điểm di tích liên quan đến Chiến dịch Điện Biên Phủ, giúp thế hệ hôm nay hình dung phần nào sự sáng tạo, kiên cường của hậu phương và hậu cần kháng chiến – những yếu tố âm thầm nhưng không thể thiếu để làm nên chiến thắng. Bên cạnh giá trị quân sự, câu chuyện bếp Hoàng Cầm còn thường được kể lại như một minh chứng sinh động cho tinh thần sáng tạo bắt nguồn từ chính những người lính bình thường nhất trong quân đội, không chỉ từ cấp chỉ huy hay các nhà khoa học quân sự – một sáng kiến nhỏ, nảy sinh từ nhu cầu thiết thực của một bếp ăn đơn vị, đã trở thành giải pháp kỹ thuật được áp dụng xuyên suốt hai cuộc kháng chiến.","nguon":"Báo Quân đội nhân dân","doc":[{"t":"Bếp giấu khói của anh nuôi Hoàng Cầm. Khác hẳn hình dung thông thường về một cái bếp, bếp Hoàng Cầm trong không gian phục dựng là một hố đào sâu xuống lòng đất, quanh miệng hố là hệ thống rãnh nhỏ chạy tỏa ra nhiều hướng, phủ đất mỏng và cành lá ngụy trang phía trên. Khi nhóm lửa, thay vì bốc thẳng lên cao thành cột khói dễ bị phát hiện từ xa, khói bếp theo các đường rãnh ngầm len lỏi, tản mỏng ra một vùng rộng quanh miệng hố rồi tan biến, chỉ còn lại một lớp hơi mờ là là sát mặt đất như sương sớm, khó lòng nhận ra ngay cả khi quan sát từ trên không."},{"t":"Trong chiến tranh, việc nấu ăn giữa rừng luôn tiềm ẩn nguy hiểm: một cột khói bốc lên bất cẩn có thể tố cáo vị trí đóng quân, dẫn máy bay hay pháo binh đối phương tới oanh tạc. Đối với một đội quân phải nuôi hàng vạn cán bộ, chiến sĩ giữa núi rừng, bài toán vừa nấu chín được cơm vừa không để lộ khói trở thành một yêu cầu sống còn, đặc biệt trong giai đoạn chiến tranh có sự tham gia ngày càng nhiều của không quân đối phương."},{"t":"Kiểu bếp giấu khói này là sáng kiến của anh nuôi Hoàng Cầm, thuộc Đại đoàn 308, ra đời trong Chiến dịch Hòa Bình những năm 1951 – 1952. Từ quan sát thực tế và nhu cầu cấp thiết của đơn vị, người chiến sĩ nuôi quân bình dị ấy đã nghĩ ra cách đào rãnh dẫn khói tỏa rộng trong lòng đất thay vì để khói bốc thẳng lên trời, một giải pháp đơn giản nhưng hiệu quả bất ngờ, giúp bộ đội có thể nấu ăn an toàn ngay gần tiền tuyến mà không lo bị lộ."},{"t":"Từ một sáng kiến của một đơn vị, cách làm bếp không khói nhanh chóng được phổ biến rộng rãi trong toàn quân, trở thành kỹ thuật hậu cần tiêu chuẩn ở khắp các chiến trường, kể cả trong Chiến dịch Điện Biên Phủ năm 1954, nơi hàng vạn bộ đội, dân công phải ăn ở ngay trong các chiến hào, lán trại giữa vòng vây quân địch. Về sau, bếp Hoàng Cầm còn tiếp tục được sử dụng suốt cuộc kháng chiến chống Mỹ, trở thành một trong những hình ảnh tiêu biểu của hậu cần chiến trường Việt Nam, gắn liền với tên tuổi người lính nuôi quân đã sáng tạo ra nó."},{"t":"Ngày nay, mô hình bếp Hoàng Cầm được phục dựng tại nhiều khu di tích lịch sử, bảo tàng quân sự trên cả nước, trong đó có Khu di tích lịch sử An toàn khu Định Hóa và các điểm di tích liên quan đến Chiến dịch Điện Biên Phủ, giúp thế hệ hôm nay hình dung phần nào sự sáng tạo, kiên cường của hậu phương và hậu cần kháng chiến – những yếu tố âm thầm nhưng không thể thiếu để làm nên chiến thắng. Bên cạnh giá trị quân sự, câu chuyện bếp Hoàng Cầm còn thường được kể lại như một minh chứng sinh động cho tinh thần sáng tạo bắt nguồn từ chính những người lính bình thường nhất trong quân đội, không chỉ từ cấp chỉ huy hay các nhà khoa học quân sự – một sáng kiến nhỏ, nảy sinh từ nhu cầu thiết thực của một bếp ăn đơn vị, đã trở thành giải pháp kỹ thuật được áp dụng xuyên suốt hai cuộc kháng chiến."},{"t":"Bạn có biết? Bếp được đặt theo tên chính người sáng chế ra nó – anh nuôi Hoàng Cầm, Đại đoàn 308 – một trường hợp hiếm hoi trong lịch sử hậu cần quân đội Việt Nam khi tên một loại bếp gắn liền với tên người phát minh (Báo Quân đội nhân dân)."}],"ban_co_biet":"Bếp được đặt theo tên chính người sáng chế ra nó – anh nuôi Hoàng Cầm, Đại đoàn 308 – một trường hợp hiếm hoi trong lịch sử hậu cần quân đội Việt Nam khi tên một loại bếp gắn liền với tên người phát minh (Báo Quân đội nhân dân)."},{"id":"wicker_basket_01@-18.5,-6.2","x":-18.5,"y":0.33,"z":-6.2,"loai":"wicker_basket_01","ten":"Giỏ đan","tieu_de":"Gánh gạo nuôi quân","text":"Chiếc giỏ đan bằng tre, đặt bên bếp Hoàng Cầm trong không gian phục dựng, là vật dụng minh họa cho một phần đời sống hậu cần thầm lặng nhưng không kém phần quan trọng của cuộc kháng chiến chín năm: việc vận chuyển lương thực, thực phẩm từ các bản làng đến nơi đóng quân của bộ đội, cơ quan. Giỏ được đan nan tre chéo nhau, có quai xách hoặc quai đeo vai, kiểu dáng quen thuộc trong đời sống thường nhật của đồng bào các dân tộc Tày, Nùng, Dao… sinh sống tại vùng núi Việt Bắc từ bao đời.\n\nỞ những vùng địa hình hiểm trở, đường sá đi lại khó khăn như Định Hóa, Sơn Dương, Chiêm Hóa, phương tiện vận chuyển chủ yếu vẫn là sức người: gánh trên vai bằng đòn gánh, gùi sau lưng, hoặc xách tay từng giỏ nhỏ len lỏi qua những con đường mòn, vượt suối, trèo đèo. Không có ô tô, không có đường lớn, mọi thứ từ hạt gạo, mớ rau, cân muối đến vũ khí, đạn dược, tài liệu đều phải trông cậy vào đôi vai, đôi chân của những người dân công, đồng bào địa phương.\n\nSuốt chín năm cơ quan đầu não kháng chiến đứng chân tại An toàn khu Việt Bắc, đồng bào các dân tộc nơi đây vừa duy trì sản xuất, vừa tự nguyện đóng góp lương thực, thực phẩm nuôi cán bộ, bộ đội. Từng gùi thóc, giỏ ngô, bó rau rừng được người dân mang đến các trạm giao liên, các cơ quan đóng trong bản làng, âm thầm góp phần bảo đảm hậu cần cho một bộ máy kháng chiến quy mô lớn hoạt động giữa núi rừng, xa cách hoàn toàn với các trung tâm sản xuất, cung ứng lớn ở vùng đồng bằng.\n\nSự đùm bọc, che chở của đồng bào Việt Bắc đối với cách mạng trong suốt những năm tháng ấy đã biến vùng núi rừng nghèo khó này thành một hậu phương vững chắc đúng nghĩa, nơi mỗi người dân, dù không cầm súng ra trận, vẫn có phần đóng góp cụ thể của mình vào thắng lợi chung. Đây cũng là lý do An toàn khu Định Hóa được xem là một trong những chiếc nôi của cuộc kháng chiến chống Pháp, nơi lòng dân và ý Đảng gắn bó chặt chẽ suốt một chặng đường dài gian khổ.\n\nChiếc giỏ đan trong gian trưng bày, vì vậy, tuy chỉ là vật dụng minh họa, không gắn với một sự kiện hay nhân vật cụ thể nào, nhưng lại mang ý nghĩa biểu tượng cho sự đóng góp thầm lặng của hàng vạn người dân bình thường. Tại Khu di tích lịch sử An toàn khu Định Hóa hôm nay, nhiều hiện vật tương tự – gùi, giỏ, đòn gánh của đồng bào thời kháng chiến – vẫn được sưu tầm, trưng bày, như một lời nhắc về vai trò không thể thay thế của hậu phương trong mọi cuộc chiến tranh nhân dân. Đặt cạnh bếp Hoàng Cầm trong không gian phục dựng, chiếc giỏ đan còn gợi lên một liên tưởng gần gũi: một bên là sáng kiến quân sự để giữ bí mật bếp núc giữa rừng, một bên là công sức bền bỉ của người dân để có gạo, có rau đưa vào chính những chiếc bếp ấy – hai hiện vật nhỏ bé kể chung một câu chuyện lớn hơn về cách một dân tộc thiếu thốn phương tiện hiện đại đã tổ chức được một hậu phương kháng chiến vận hành bền bỉ suốt gần một thập niên giữa núi rừng hiểm trở.","nguon":"Khu Di tích lịch sử ATK Định Hóa (Thái Nguyên)","doc":[{"t":"Gánh gạo nuôi quân. Chiếc giỏ đan bằng tre, đặt bên bếp Hoàng Cầm trong không gian phục dựng, là vật dụng minh họa cho một phần đời sống hậu cần thầm lặng nhưng không kém phần quan trọng của cuộc kháng chiến chín năm: việc vận chuyển lương thực, thực phẩm từ các bản làng đến nơi đóng quân của bộ đội, cơ quan. Giỏ được đan nan tre chéo nhau, có quai xách hoặc quai đeo vai, kiểu dáng quen thuộc trong đời sống thường nhật của đồng bào các dân tộc Tày, Nùng, Dao… sinh sống tại vùng núi Việt Bắc từ bao đời."},{"t":"Ở những vùng địa hình hiểm trở, đường sá đi lại khó khăn như Định Hóa, Sơn Dương, Chiêm Hóa, phương tiện vận chuyển chủ yếu vẫn là sức người: gánh trên vai bằng đòn gánh, gùi sau lưng, hoặc xách tay từng giỏ nhỏ len lỏi qua những con đường mòn, vượt suối, trèo đèo. Không có ô tô, không có đường lớn, mọi thứ từ hạt gạo, mớ rau, cân muối đến vũ khí, đạn dược, tài liệu đều phải trông cậy vào đôi vai, đôi chân của những người dân công, đồng bào địa phương."},{"t":"Suốt chín năm cơ quan đầu não kháng chiến đứng chân tại An toàn khu Việt Bắc, đồng bào các dân tộc nơi đây vừa duy trì sản xuất, vừa tự nguyện đóng góp lương thực, thực phẩm nuôi cán bộ, bộ đội. Từng gùi thóc, giỏ ngô, bó rau rừng được người dân mang đến các trạm giao liên, các cơ quan đóng trong bản làng, âm thầm góp phần bảo đảm hậu cần cho một bộ máy kháng chiến quy mô lớn hoạt động giữa núi rừng, xa cách hoàn toàn với các trung tâm sản xuất, cung ứng lớn ở vùng đồng bằng."},{"t":"Sự đùm bọc, che chở của đồng bào Việt Bắc đối với cách mạng trong suốt những năm tháng ấy đã biến vùng núi rừng nghèo khó này thành một hậu phương vững chắc đúng nghĩa, nơi mỗi người dân, dù không cầm súng ra trận, vẫn có phần đóng góp cụ thể của mình vào thắng lợi chung. Đây cũng là lý do An toàn khu Định Hóa được xem là một trong những chiếc nôi của cuộc kháng chiến chống Pháp, nơi lòng dân và ý Đảng gắn bó chặt chẽ suốt một chặng đường dài gian khổ."},{"t":"Chiếc giỏ đan trong gian trưng bày, vì vậy, tuy chỉ là vật dụng minh họa, không gắn với một sự kiện hay nhân vật cụ thể nào, nhưng lại mang ý nghĩa biểu tượng cho sự đóng góp thầm lặng của hàng vạn người dân bình thường. Tại Khu di tích lịch sử An toàn khu Định Hóa hôm nay, nhiều hiện vật tương tự – gùi, giỏ, đòn gánh của đồng bào thời kháng chiến – vẫn được sưu tầm, trưng bày, như một lời nhắc về vai trò không thể thay thế của hậu phương trong mọi cuộc chiến tranh nhân dân. Đặt cạnh bếp Hoàng Cầm trong không gian phục dựng, chiếc giỏ đan còn gợi lên một liên tưởng gần gũi: một bên là sáng kiến quân sự để giữ bí mật bếp núc giữa rừng, một bên là công sức bền bỉ của người dân để có gạo, có rau đưa vào chính những chiếc bếp ấy – hai hiện vật nhỏ bé kể chung một câu chuyện lớn hơn về cách một dân tộc thiếu thốn phương tiện hiện đại đã tổ chức được một hậu phương kháng chiến vận hành bền bỉ suốt gần một thập niên giữa núi rừng hiểm trở."}]}]};
